include("1_HBMapmakerUtilities");

-- Soft deploy: false. Local tuning: true (LekmapPangaeaFractal.lua overrides).
if _lek_mapgen_logs == nil then
	_lek_mapgen_logs = false;
end
-- Per-channel toggles (PangaeaFractal sets the table). Nil table = all channels on when master on.
if _lek_mapgen_log_channels == nil then
	_lek_mapgen_log_channels = nil;
end

function LekMapgenLogsEnabled()
	return _lek_mapgen_logs == true;
end

function LekMapgenChannelEnabled(channel)
	if not LekMapgenLogsEnabled() then
		return false;
	end
	local t = _lek_mapgen_log_channels;
	if type(t) ~= "table" then
		return true;
	end
	local key = channel or "other";
	local v = t[key];
	if v == nil then
		return t.other == true;
	end
	return v == true;
end

function LekMapgenInferChannel(msg)
	local s;
	if type(msg) == "table" then
		s = tostring(msg[1] or "");
	else
		s = tostring(msg or "");
	end
	if string.find(s, "LekIslandTile", 1, true) or string.find(s, "LekIslandFootprint", 1, true) then
		return "islands_tiles";
	end
	if string.find(s, "LekIsland", 1, true) then
		return "islands";
	end
	if string.find(s, "LEK_STRAT", 1, true) or string.find(s, "LEK_RESOURCE_SETTING", 1, true) then
		return "strategics";
	end
	if string.find(s, "LekBench6", 1, true) then
		return "bench";
	end
	if string.find(s, "LekMapGen", 1, true) then
		return "mapgen";
	end
	if string.find(s, "LekPangaea", 1, true) then
		return "pangaea";
	end
	if string.find(s, "LekGlobalSix", 1, true)
		or string.find(s, "ChooseLocations", 1, true)
		or string.find(s, "StartSpacing", 1, true)
		or string.find(s, "forceGeom", 1, true) then
		return "starts";
	end
	return "other";
end

function LekMapgenAllowMsg(msg)
	return LekMapgenChannelEnabled(LekMapgenInferChannel(msg));
end

function LekMapgenDiagLogPath()
	if not (os and os.getenv) then
		return nil;
	end
	local home = os.getenv("HOME") or "";
	if home ~= "" then
		return home .. "/Library/Application Support/Sid Meier's Civilization 5/Logs/LekmapStartSpacing6P.log";
	end
	local user = os.getenv("USER") or "";
	if user ~= "" then
		return "/Users/" .. user .. "/Library/Application Support/Sid Meier's Civilization 5/Logs/LekmapStartSpacing6P.log";
	end
	return nil;
end

function LekMapgenDiagLogAppend(lineOrLines)
	if not LekMapgenAllowMsg(lineOrLines) then
		return;
	end
	local path = LekMapgenDiagLogPath();
	if not path or not (io and io.open) then
		return;
	end
	pcall(function()
		local f = io.open(path, "a");
		if not f then
			return;
		end
		if type(lineOrLines) == "table" then
			for _, line in ipairs(lineOrLines) do
				f:write(line);
				f:write("\n");
			end
		else
			f:write(tostring(lineOrLines));
			f:write("\n");
		end
		f:close();
	end);
end

if _lek_mapgen_log_verbosity == nil then
	_lek_mapgen_log_verbosity = 1;
end

if _lek_mapgen_world_is_small == nil then
	_lek_mapgen_world_is_small = false;
end
if _lek_mapgen_tuple_benchmark_mode == nil then
	_lek_mapgen_tuple_benchmark_mode = false;
end
if _lek_strat_audit_log_each_hit == nil then
	_lek_strat_audit_log_each_hit = false;
end

function LekMapgenTupleBenchmarkMode()
	return _lek_mapgen_tuple_benchmark_mode == true;
end

function LekMapgenEmitBench6OneLine(line)
	if not LekMapgenTupleBenchmarkMode() or not LekMapgenChannelEnabled("bench") then
		return;
	end
	print(line);
	pcall(function()
		LekMapgenDiagLogAppend(line);
	end);
end

function LekMapgenFormatBench6SummaryLine(startDb)
	if not LekMapgenTupleBenchmarkMode() or startDb == nil then
		return nil;
	end
	local rid = tostring(_lek_run_id or "na");
	local la = tostring(_lek_map_layout_attempt or 1);
	local maxL = tonumber(_lek_global_six_regen_max_layouts) or 11;
	local outer = tostring(_lek_pangaea_outer_attempt or "?");
	local po = (_lek_pangaea_max_outer_failed == true) and "1" or "0";
	local tup = tostring(_lek_bench_tuple_ok or "?");
	local why = tostring(_lek_bench_tuple_why or "");
	local leaf = tostring(_lek_bench_tuple_leaf or "?");
	local fc = tostring(_lek_bench_tuple_fail_complete or "?");
	local tier = tostring(_lek_bench_tuple_tier or "");
	local leg = (tier == "legacy_after_tuple_fail" or tier == "legacy_menu_skip_tuple") and "1" or "0";
	local rlx = tostring(_lek_bench_tuple_relax or "");
	if rlx == "" then
		rlx = "na";
	end
	local iso = tostring(_lek_bench_islands_dt or "?");
	local fdt = tostring(_lek_bench_fractal_world_dt or "?");
	local gpt = tostring(_lek_bench_generate_plot_types_lua_total_dt or "?");
	local mn = tostring(_lek_bench_spacing_min_nearest or "?");
	local an = tostring(_lek_bench_spacing_avg_nearest or "?");
	local m2 = tostring(_lek_bench_spacing_median_second or "?");
	local x2 = tostring(_lek_bench_spacing_max_second or "?");
	local mc = tostring(_lek_bench_spacing_min_center or "?");
	local cc = tostring(_lek_bench_spacing_coastal_n or "?");
	local sa = tostring(_lek_bench_spacing_salt_adj_n or "?");
	local rpair = tostring(_lek_bench_regional_lux_repair_cleared or 0);
	local rsht = "0";
	if startDb._lek_regional_lux_shortfall_after_fallback and #startDb._lek_regional_lux_shortfall_after_fallback > 0 then
		rsht = tostring(#startDb._lek_regional_lux_shortfall_after_fallback);
	end
	local csd = tostring(startDb.iNumCityStatesDiscarded or 0);
	local one_map = (startDb._lek_global_six_one_map_placement_mode == true) and "1" or "0";
	local regenReq = (_lek_global_six_request_map_regen == true) and "1" or "0";
	local regenWhy = tostring(_lek_global_six_request_map_regen_reason or "na");
	local scs = tostring(_lek_bench_short_circuit_stage or "na");
	return "### LekBench6 runId=" .. rid
		.. " layout=" .. la .. "/" .. tostring(maxL)
		.. " pangaeaOuter=" .. outer
		.. " pangaeaOuterFail=" .. po
		.. " one_map=" .. one_map
		.. " regenReq=" .. regenReq
		.. " regenReason=" .. regenWhy
		.. " shortCircuitStage=" .. scs
		.. " tuple_ok=" .. tup
		.. " why=" .. why
		.. " failComplete=" .. fc
		.. " leafEvals=" .. leaf
		.. " relax_phase=" .. rlx
		.. " placement_tier=" .. tier
		.. " legacy_path=" .. leg
		.. " dt_islands=" .. iso
		.. " dt_fractalWorld=" .. fdt
		.. " dt_generatePlotTypesLua=" .. gpt
		.. " spacing_minNearest=" .. mn
		.. " spacing_avgNearest=" .. an
		.. " spacing_medianSecondNearest=" .. m2
		.. " spacing_maxSecondNearest=" .. x2
		.. " spacing_minCenter=" .. mc
		.. " coastal_starts=" .. cc
		.. " salt_adj_majors=" .. sa
		.. " lux_regional_repair_batches=" .. rpair
		.. " lux_regional_shortfall_queued=" .. tostring(_lek_bench_lux_regional_shortfall_queued or 0)
		.. " lux_regional_shortfall_after_repair=" .. rsht
		.. " cs_discarded=" .. csd
		.. " hex_ok=" .. tostring(_lek_bench_hex_ok or "?")
		.. " hex_rot=" .. tostring(_lek_bench_hex_rot or "?")
		.. " hex_ringR=" .. tostring(_lek_bench_hex_ringR or "?")
		.. " feas_bn=" .. tostring(_lek_bench_feas_bn or "?")
		.. " feas_xmin=" .. tostring(_lek_bench_feas_xmin or "?")
		.. " feas_h2max=" .. tostring(_lek_bench_feas_h2max or "?")
		.. " feas_margmin=" .. tostring(_lek_bench_feas_margmin or "?")
		.. " feas_k=" .. tostring(_lek_bench_feas_k or "?");
end

function LekMapgenVerbosity()
	local v = tonumber(_lek_mapgen_log_verbosity);
	if v == nil then
		return 2;
	end
	v = math.floor(v);
	if v < 1 then
		v = 1;
	elseif v > 3 then
		v = 3;
	end
	return v;
end

function LekMapgenLogAtLeast(minLevel)
	if not LekMapgenLogsEnabled() then
		return false;
	end
	return LekMapgenVerbosity() >= minLevel;
end

function LekPlacementProbeAt(minLevel, msg)
	if not LekMapgenLogAtLeast(minLevel) or not LekMapgenAllowMsg(msg) then
		return;
	end
	print(msg);
	pcall(function()
		LekMapgenDiagLogAppend(msg);
	end);
end

function LekMapgenPrintAndDiagFile(msg)
	if not LekMapgenAllowMsg(msg) then
		return;
	end
	print(msg);
	pcall(function()
		LekMapgenDiagLogAppend(msg);
	end);
end

-- Optional print-only path (master + channel inferred from first arg when string).
function LekMapgenPrint(...)
	if not LekMapgenLogsEnabled() then
		return;
	end
	local first = select(1, ...);
	if first ~= nil and not LekMapgenAllowMsg(first) then
		return;
	end
	print(...);
end

function LekPlacementProbeLog(msg)
	LekPlacementProbeAt(2, msg);
end

function LekMapgenDiagAt(minLevel, lineOrLines)
	if not LekMapgenLogAtLeast(minLevel) then
		return;
	end
	LekMapgenDiagLogAppend(lineOrLines);
end

function LekMapgenFileTrace(...)
	if not LekMapgenLogsEnabled() or LekMapgenTupleBenchmarkMode() then
		return;
	end
	local n = select("#", ...);
	if n == 0 then
		return;
	end
	local parts = {};
	for i = 1, n do
		parts[i] = tostring(select(i, ...));
	end
	local line = table.concat(parts, " ");
	if not LekMapgenAllowMsg(line) then
		return;
	end
	pcall(function()
		LekMapgenDiagLogAppend(line);
	end);
end

function LekAllowLuxuryIndex(allowed_luxuries, resId)
	if resId ~= nil and allowed_luxuries ~= nil then
		allowed_luxuries[resId] = true;
	end
end

function LekSafeMajorPlayer(pid)
	if type(pid) ~= "number" then
		return nil;
	end
	local ok, pl = pcall(function()
		return Players[pid];
	end);
	if ok then
		return pl;
	end
	return nil;
end

local function LekSafeGetDisableStartBiasOption()
	local ok, v = pcall(function()
		return Game.GetCustomOption("GAMEOPTION_DISABLE_START_BIAS");
	end);
	if ok then
		return v;
	end
	return nil;
end

local function LekHBPlotListLen(plot_list)
	if plot_list == nil then
		return 0;
	end
	local n = #(plot_list);
	if n > 0 then
		return n;
	end
	return table.maxn(plot_list) or 0;
end

local function LekStratIsBalanceAuditPass(pass)
	-- Place labels are strat_balance_{iron|horse}_{primary|fallback}:region=N
	-- (older path also used strat_balance_region=N). Must match all of these or trim
	-- treats balance majors as extras and deletes them down to the cap.
	return type(pass) == "string" and string.sub(pass, 1, 13) == "strat_balance";
end

-- Legacy: post-place major trim. Unused for volume (freqs own density). Kept for optional experiments.
local LEK_RS5_MAX_NON_BALANCE_MAJOR_PER_TYPE = 4;

------------------------------------------------------------------------------
-- Strategic audit (horse/iron/oil/uranium/coal/aluminum): active when self.resource_setting == 5.
-- Call sites set self._lek_strat_audit_context to a short pass label before placing.
------------------------------------------------------------------------------
AssignStartingPlots = AssignStartingPlots or {};
function AssignStartingPlots.LekStratAuditReset(self)
	if (self.resource_setting or 0) ~= 5 then
		self._lek_strat_audit = nil;
		self._lek_strat_audit_context = nil;
		return;
	end
	self._lek_strat_audit = { entries = {} };
	self._lek_strat_audit_context = nil;
end

function AssignStartingPlots.LekStratAuditEnsure(self)
	if (self.resource_setting or 0) ~= 5 then
		return false;
	end
	if self._lek_strat_audit == nil then
		self._lek_strat_audit = { entries = {} };
	end
	return true;
end

function AssignStartingPlots.LekStratAuditResName(self, resId)
	if resId == self.horse_ID then return "horse"; end
	if resId == self.iron_ID then return "iron"; end
	if resId == self.oil_ID then return "oil"; end
	if resId == self.uranium_ID then return "uranium"; end
	if resId == self.coal_ID then return "coal"; end
	if resId == self.aluminum_ID then return "aluminum"; end
	return nil;
end

function AssignStartingPlots.LekStratAuditClassifyHorseIronSize(self, resId, qty)
	-- Kept for trim path; oil/uranium/coal/alum use ClassifyStrategicSize.
	if type(qty) ~= "number" then
		return "?";
	end
	if resId == self.horse_ID then
		return (qty >= 4) and "major" or "small";
	end
	if resId == self.iron_ID then
		return (qty >= 5) and "major" or "small";
	end
	return "?";
end

function AssignStartingPlots.LekStratAuditClassifyStrategicSize(self, resId, qty, pass)
	if type(qty) ~= "number" then
		return "?";
	end
	local p = tostring(pass or "");
	if resId == self.horse_ID then
		return (qty >= 4) and "major" or "small";
	end
	if resId == self.iron_ID then
		return (qty >= 5) and "major" or "small";
	end
	if resId == self.oil_ID then
		if string.sub(p, 1, 8) == "sea_oil:" then
			return "sea";
		end
		return (qty >= 5) and "major" or "small";
	end
	if resId == self.coal_ID then
		-- Major qty ~7, small ~3.
		return (qty >= 5) and "major" or "small";
	end
	if resId == self.aluminum_ID then
		-- Major qty ~8, small ~3.
		return (qty >= 5) and "major" or "small";
	end
	if resId == self.uranium_ID then
		-- Major and small qty are often both 2 (or balance uses 1); classify by pass / label.
		if string.sub(p, 1, 12) == "small_strat:" then
			return "small";
		end
		if string.find(p, ":small:", 1, true) or string.find(p, "_small", 1, true) then
			return "small";
		end
		if string.find(p, ":major:", 1, true) or string.find(p, "_major", 1, true) then
			return "major";
		end
		if string.sub(p, 1, 13) == "strat_balance"
			or string.sub(p, 1, 9) == "backfill:"
			or string.sub(p, 1, 16) == "guaranteed_band:"
			or string.sub(p, 1, 6) == "major:"
			or string.sub(p, 1, 10) == "cs_center:" then
			return "major";
		end
		if qty < 2 then
			return "small";
		end
		return "major";
	end
	return "?";
end

function AssignStartingPlots.LekStratAuditRecordHorseIron(self, resId, qty, plot, x, y)
	-- Name historical; records horse/iron/oil/uranium/coal/aluminum.
	if not AssignStartingPlots.LekStratAuditEnsure(self) then
		return;
	end
	local resName = AssignStartingPlots.LekStratAuditResName(self, resId);
	if resName == nil then
		return;
	end
	local p = plot;
	if p == nil and type(x) == "number" and type(y) == "number" then
		p = Map.GetPlot(x, y);
	end
	local tt, ft, pt = -1, -1, -1;
	if p then
		tt = p:GetTerrainType();
		ft = p:GetFeatureType();
		pt = p:GetPlotType();
	end
	local pass = tostring(self._lek_strat_audit_context or "unknown_pass");
	local sz = AssignStartingPlots.LekStratAuditClassifyStrategicSize(self, resId, qty, pass);
	local dStart = -1;
	if type(x) == "number" and type(y) == "number" then
		local d = self:LekStratMinDistanceToAnyMajorStart(x, y);
		if type(d) == "number" and d < 999999 then
			dStart = d;
		end
	end
	local ent = {
		pass = pass,
		res = resName,
		qty = qty,
		sz = sz,
		tt = tt,
		ft = ft,
		pt = pt,
		x = x,
		y = y,
		dStart = dStart,
	};
	local t = self._lek_strat_audit.entries;
	t[#t + 1] = ent;
	if _lek_strat_audit_log_each_hit == true and #t <= 4000 then
		LekMapgenPrintAndDiagFile("### LEK_STRAT_HIT runId=" .. tostring(_lek_run_id or "na")
			.. " pass=" .. pass
			.. " res=" .. resName
			.. " qty=" .. tostring(qty)
			.. " sz=" .. sz
			.. " x=" .. tostring(x) .. " y=" .. tostring(y)
			.. " dStart=" .. tostring(dStart)
			.. " tt=" .. tostring(tt) .. " ft=" .. tostring(ft) .. " pt=" .. tostring(pt));
	end
end

function AssignStartingPlots.LekStratAuditClassifyPassBucket(pass)
	-- player = NormalizeStartLocation / BalanceAndAssign (per-start).
	-- global = PlaceStrategicAndBonusResources biome/frequency passes + sea oil + CS extras.
	-- rescan = post-process map wipe (labels collapsed; not separable).
	local p = tostring(pass or "");
	if string.sub(p, 1, 13) == "strat_balance"
		or string.sub(p, 1, 12) == "extra_small:"
		or string.sub(p, 1, 11) == "hammer_poor"
		or string.sub(p, 1, 16) == "guaranteed_band:" then
		return "player";
	end
	if string.sub(p, 1, 6) == "major:"
		or string.sub(p, 1, 12) == "small_strat:"
		or string.sub(p, 1, 9) == "backfill:"
		or string.sub(p, 1, 8) == "sea_oil:"
		or string.sub(p, 1, 10) == "cs_center:"
		or string.sub(p, 1, 10) == "cs_modern:" then
		return "global";
	end
	if string.sub(p, 1, 10) == "final_map_" or p == "map_scan" then
		return "rescan";
	end
	return "other";
end

local function LekStratAuditEmptyCounts()
	return {
		horse_major = 0, horse_small = 0,
		iron_major = 0, iron_small = 0,
		oil_major = 0, oil_small = 0, oil_sea = 0,
		uran_major = 0, uran_small = 0,
		coal_major = 0, coal_small = 0,
		alum_major = 0, alum_small = 0,
		nodes = 0,
	};
end

function AssignStartingPlots.LekStratAuditPrintSpacingForRes(self, stageTag, resName)
	-- Nearest-neighbor + close-pair counts for clump baseline (uranium primary use).
	if not self._lek_strat_audit or not self._lek_strat_audit.entries then
		return;
	end
	local pts = {};
	for _, e in ipairs(self._lek_strat_audit.entries) do
		if e.res == resName and type(e.x) == "number" and type(e.y) == "number" then
			pts[#pts + 1] = e;
		end
	end
	local n = #pts;
	if n <= 0 then
		return;
	end
	local sumNN, minNN, maxNN = 0, 999999, 0;
	local pairsLe2, pairsLe3 = 0, 0;
	local nnCount = 0;
	for i = 1, n do
		local best = 999999;
		for j = 1, n do
			if i ~= j then
				local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, pts[i].x, pts[i].y, pts[j].x, pts[j].y);
				if type(d) == "number" then
					if d < best then
						best = d;
					end
					if i < j then
						if d <= 2 then
							pairsLe2 = pairsLe2 + 1;
						end
						if d <= 3 then
							pairsLe3 = pairsLe3 + 1;
						end
					end
				end
			end
		end
		if best < 999999 then
			nnCount = nnCount + 1;
			sumNN = sumNN + best;
			if best < minNN then
				minNN = best;
			end
			if best > maxNN then
				maxNN = best;
			end
		end
	end
	local meanNN = (nnCount > 0) and (sumNN / nnCount) or -1;
	LekMapgenPrintAndDiagFile("### LEK_STRAT_OU_SPACING runId=" .. tostring(_lek_run_id or "na")
		.. " stage=" .. tostring(stageTag or "na")
		.. " res=" .. resName
		.. " nodes=" .. tostring(n)
		.. " nn_mean=" .. string.format("%.2f", meanNN)
		.. " nn_min=" .. tostring((minNN < 999999) and minNN or -1)
		.. " nn_max=" .. tostring(maxNN)
		.. " pairs_dLe2=" .. tostring(pairsLe2)
		.. " pairs_dLe3=" .. tostring(pairsLe3));
end

function AssignStartingPlots:LekStratAuditPrintSummary(stageTag)
	if (self.resource_setting or 0) ~= 5 or not self._lek_strat_audit or not self._lek_strat_audit.entries then
		return;
	end
	local rid = tostring(_lek_run_id or "na");
	local tot = LekStratAuditEmptyCounts();
	local byPass = {};
	local byBucket = {
		player = LekStratAuditEmptyCounts(),
		global = LekStratAuditEmptyCounts(),
		rescan = LekStratAuditEmptyCounts(),
		other = LekStratAuditEmptyCounts(),
	};
	local function bump(dst, key)
		dst[key] = (dst[key] or 0) + 1;
	end
	for _, e in ipairs(self._lek_strat_audit.entries) do
		local p = e.pass;
		byPass[p] = byPass[p] or LekStratAuditEmptyCounts();
		local b = byPass[p];
		local bucket = AssignStartingPlots.LekStratAuditClassifyPassBucket(p);
		local bk = byBucket[bucket] or byBucket.other;
		b.nodes = b.nodes + 1;
		bk.nodes = bk.nodes + 1;
		tot.nodes = tot.nodes + 1;
		local key = nil;
		if e.res == "horse" and e.sz == "major" then key = "horse_major";
		elseif e.res == "horse" and e.sz == "small" then key = "horse_small";
		elseif e.res == "iron" and e.sz == "major" then key = "iron_major";
		elseif e.res == "iron" and e.sz == "small" then key = "iron_small";
		elseif e.res == "oil" and e.sz == "major" then key = "oil_major";
		elseif e.res == "oil" and e.sz == "small" then key = "oil_small";
		elseif e.res == "oil" and e.sz == "sea" then key = "oil_sea";
		elseif e.res == "uranium" and e.sz == "major" then key = "uran_major";
		elseif e.res == "uranium" and e.sz == "small" then key = "uran_small";
		elseif e.res == "coal" and e.sz == "major" then key = "coal_major";
		elseif e.res == "coal" and e.sz == "small" then key = "coal_small";
		elseif e.res == "aluminum" and e.sz == "major" then key = "alum_major";
		elseif e.res == "aluminum" and e.sz == "small" then key = "alum_small";
		end
		if key then
			bump(b, key);
			bump(bk, key);
			bump(tot, key);
		end
	end
	local keys = {};
	for k in pairs(byPass) do
		keys[#keys + 1] = k;
	end
	table.sort(keys);
	LekMapgenPrintAndDiagFile("### LEK_STRAT_SUMMARY runId=" .. rid .. " stage=" .. tostring(stageTag or "na")
		.. " resource_setting=5 entries=" .. tostring(#self._lek_strat_audit.entries));
	LekMapgenPrintAndDiagFile("### LEK_STRAT_TOTAL runId=" .. rid .. " stage=" .. tostring(stageTag or "na")
		.. " horse_majorN=" .. tostring(tot.horse_major)
		.. " horse_smallN=" .. tostring(tot.horse_small)
		.. " iron_majorN=" .. tostring(tot.iron_major)
		.. " iron_smallN=" .. tostring(tot.iron_small)
		.. " horse_nodes=" .. tostring(tot.horse_major + tot.horse_small)
		.. " iron_nodes=" .. tostring(tot.iron_major + tot.iron_small));
	LekMapgenPrintAndDiagFile("### LEK_STRAT_OU_TOTAL runId=" .. rid .. " stage=" .. tostring(stageTag or "na")
		.. " oil_majorN=" .. tostring(tot.oil_major)
		.. " oil_smallN=" .. tostring(tot.oil_small)
		.. " oil_seaN=" .. tostring(tot.oil_sea)
		.. " uran_majorN=" .. tostring(tot.uran_major)
		.. " uran_smallN=" .. tostring(tot.uran_small)
		.. " oil_nodes=" .. tostring(tot.oil_major + tot.oil_small + tot.oil_sea)
		.. " uran_nodes=" .. tostring(tot.uran_major + tot.uran_small)
		.. " oil_units=" .. tostring(self.amounts_of_resources_placed and (self.amounts_of_resources_placed[self.oil_ID + 1] or 0) or 0)
		.. " uran_units=" .. tostring(self.amounts_of_resources_placed and (self.amounts_of_resources_placed[self.uranium_ID + 1] or 0) or 0));
	LekMapgenPrintAndDiagFile("### LEK_STRAT_CA_TOTAL runId=" .. rid .. " stage=" .. tostring(stageTag or "na")
		.. " coal_majorN=" .. tostring(tot.coal_major)
		.. " coal_smallN=" .. tostring(tot.coal_small)
		.. " alum_majorN=" .. tostring(tot.alum_major)
		.. " alum_smallN=" .. tostring(tot.alum_small)
		.. " coal_nodes=" .. tostring(tot.coal_major + tot.coal_small)
		.. " alum_nodes=" .. tostring(tot.alum_major + tot.alum_small)
		.. " coal_units=" .. tostring(self.amounts_of_resources_placed and (self.amounts_of_resources_placed[self.coal_ID + 1] or 0) or 0)
		.. " alum_units=" .. tostring(self.amounts_of_resources_placed and (self.amounts_of_resources_placed[self.aluminum_ID + 1] or 0) or 0));
	for _, bucketName in ipairs({ "player", "global", "rescan", "other" }) do
		local bk = byBucket[bucketName];
		if bk.nodes > 0 then
			LekMapgenPrintAndDiagFile("### LEK_STRAT_BUCKET runId=" .. rid
				.. " stage=" .. tostring(stageTag or "na")
				.. " bucket=" .. bucketName
				.. " horse_majorN=" .. tostring(bk.horse_major)
				.. " horse_smallN=" .. tostring(bk.horse_small)
				.. " iron_majorN=" .. tostring(bk.iron_major)
				.. " iron_smallN=" .. tostring(bk.iron_small)
				.. " nodes=" .. tostring(bk.nodes));
			local ouNodes = bk.oil_major + bk.oil_small + bk.oil_sea + bk.uran_major + bk.uran_small;
			if ouNodes > 0 then
				LekMapgenPrintAndDiagFile("### LEK_STRAT_OU_BUCKET runId=" .. rid
					.. " stage=" .. tostring(stageTag or "na")
					.. " bucket=" .. bucketName
					.. " oil_majorN=" .. tostring(bk.oil_major)
					.. " oil_smallN=" .. tostring(bk.oil_small)
					.. " oil_seaN=" .. tostring(bk.oil_sea)
					.. " uran_majorN=" .. tostring(bk.uran_major)
					.. " uran_smallN=" .. tostring(bk.uran_small)
					.. " nodes=" .. tostring(ouNodes));
			end
			local caNodes = bk.coal_major + bk.coal_small + bk.alum_major + bk.alum_small;
			if caNodes > 0 then
				LekMapgenPrintAndDiagFile("### LEK_STRAT_CA_BUCKET runId=" .. rid
					.. " stage=" .. tostring(stageTag or "na")
					.. " bucket=" .. bucketName
					.. " coal_majorN=" .. tostring(bk.coal_major)
					.. " coal_smallN=" .. tostring(bk.coal_small)
					.. " alum_majorN=" .. tostring(bk.alum_major)
					.. " alum_smallN=" .. tostring(bk.alum_small)
					.. " nodes=" .. tostring(caNodes));
			end
		end
	end
	AssignStartingPlots.LekStratAuditPrintSpacingForRes(self, stageTag, "uranium");
	AssignStartingPlots.LekStratAuditPrintSpacingForRes(self, stageTag, "oil");
	for _, k in ipairs(keys) do
		local b = byPass[k];
		LekMapgenPrintAndDiagFile("### LEK_STRAT_PHASE runId=" .. rid
			.. " pass=" .. k
			.. " bucket=" .. AssignStartingPlots.LekStratAuditClassifyPassBucket(k)
			.. " horse_majorN=" .. tostring(b.horse_major)
			.. " horse_smallN=" .. tostring(b.horse_small)
			.. " iron_majorN=" .. tostring(b.iron_major)
			.. " iron_smallN=" .. tostring(b.iron_small)
			.. " oil_majorN=" .. tostring(b.oil_major)
			.. " oil_smallN=" .. tostring(b.oil_small)
			.. " oil_seaN=" .. tostring(b.oil_sea)
			.. " uran_majorN=" .. tostring(b.uran_major)
			.. " uran_smallN=" .. tostring(b.uran_small)
			.. " coal_majorN=" .. tostring(b.coal_major)
			.. " coal_smallN=" .. tostring(b.coal_small)
			.. " alum_majorN=" .. tostring(b.alum_major)
			.. " alum_smallN=" .. tostring(b.alum_small));
	end
end

function AssignStartingPlots:LekStratMinDistanceToAnyMajorStart(x, y)
	local best = 999999;
	local n = self.iNumCivs or 0;
	for r = 1, n do
		local sp = self.startingPlots[r];
		if sp and type(sp[1]) == "number" and type(sp[2]) == "number" then
			local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, sp[1], sp[2], x, y);
			if type(d) == "number" and d < best then
				best = d;
			end
		end
	end
	return best;
end

function AssignStartingPlots:LekStratDecrementPlacedAmounts(resId, qty)
	if not self.amounts_of_resources_placed or type(resId) ~= "number" or type(qty) ~= "number" then
		return;
	end
	local i = resId + 1;
	self.amounts_of_resources_placed[i] = math.max(0, (self.amounts_of_resources_placed[i] or 0) - qty);
end

function AssignStartingPlots:LekStratTrimNonBalanceMajorHorseIron(maxExtraPerType)
	if maxExtraPerType == nil then
		maxExtraPerType = 4;
	end
	if not self._lek_strat_audit or not self._lek_strat_audit.entries then
		return;
	end
	local function trimOneKind(resName, resId)
		local byKey = {};
		for _, e in ipairs(self._lek_strat_audit.entries) do
			if e.res == resName and e.sz == "major" and not LekStratIsBalanceAuditPass(e.pass)
				and type(e.x) == "number" and type(e.y) == "number" then
				local key = tostring(e.x) .. "_" .. tostring(e.y);
				byKey[key] = { x = e.x, y = e.y, resId = resId };
			end
		end
		local list = {};
		for _, row in pairs(byKey) do
			row.d = self:LekStratMinDistanceToAnyMajorStart(row.x, row.y);
			list[#list + 1] = row;
		end
		if #list <= maxExtraPerType then
			return;
		end
		table.sort(list, function(a, b)
			return (a.d or 0) > (b.d or 0);
		end);
		for i = 1, #list - maxExtraPerType do
			local row = list[i];
			local plot = Map.GetPlot(row.x, row.y);
			if plot and plot:GetResourceType(-1) == row.resId and plot.GetNumResource then
				local q = plot:GetNumResource();
				if type(q) == "number" then
					local sz = AssignStartingPlots.LekStratAuditClassifyHorseIronSize(self, row.resId, q);
					if sz == "major" then
						plot:SetResourceType(-1);
						self:LekStratDecrementPlacedAmounts(row.resId, q);
					end
				end
			end
		end
	end
	trimOneKind("horse", self.horse_ID);
	trimOneKind("iron", self.iron_ID);
end

function AssignStartingPlots:LekStratStripSmallIronOnHillsFromMap()
	-- Legacy hygiene. Unused when placers enforce flat-only small iron (extras + RS5 small_strat).
	local iW, iH = Map.GetGridSize();
	for y = 0, iH - 1 do
		for x = 0, iW - 1 do
			local plot = Map.GetPlot(x, y);
			if plot:GetPlotType() == PlotTypes.PLOT_HILLS and plot:GetResourceType(-1) == self.iron_ID and plot.GetNumResource then
				local q = plot:GetNumResource();
				if type(q) == "number" and q < 5 then
					plot:SetResourceType(-1);
					self:LekStratDecrementPlacedAmounts(self.iron_ID, q);
				end
			end
		end
	end
end

function AssignStartingPlots.LekStratAuditRescanHorseIronFromMap(self, passLabel)
	-- Name historical; rescans horse/iron/oil/uranium/coal/aluminum.
	if not AssignStartingPlots.LekStratAuditEnsure(self) then
		return;
	end
	self._lek_strat_audit.entries = {};
	local iW, iH = Map.GetGridSize();
	for y = 0, iH - 1 do
		for x = 0, iW - 1 do
			local plot = Map.GetPlot(x, y);
			local rt = plot:GetResourceType(-1);
			if (rt == self.horse_ID or rt == self.iron_ID or rt == self.oil_ID or rt == self.uranium_ID
				or rt == self.coal_ID or rt == self.aluminum_ID)
				and plot.GetNumResource then
				local qty = plot:GetNumResource();
				if type(qty) ~= "number" then
					qty = 0;
				end
				self._lek_strat_audit_context = passLabel or "map_scan";
				AssignStartingPlots.LekStratAuditRecordHorseIron(self, rt, qty, plot, x, y);
			end
		end
	end
	self._lek_strat_audit_context = nil;
end

function AssignStartingPlots:LekStratPostProcessForResourceSettingFive()
	-- Volume = freqs only (no trim). Small iron flat = place-time (extras + small_strat); no strip.
	AssignStartingPlots.LekStratAuditReset(self);
	AssignStartingPlots.LekStratAuditRescanHorseIronFromMap(self, "final_map_after_rs5_tune");
end

-- TEST ONLY (see LekmapPangaeaFractal.lua `_lek_strat_extra_balance_smalls`).
-- After OG AddStrategicBalanceResources majors: place 1 small iron + 1 small horse in r4-5
-- and again in r6-7. Horse uses OG flat primary; small iron uses flat-only (not OG hills primary).
function AssignStartingPlots.LekStratExtraBalanceSmallsEnabled()
	return _lek_strat_extra_balance_smalls == true;
end

-- TEST ONLY (see LekmapPangaeaFractal.lua `_lek_strat_skip_global_horse_iron`).
function AssignStartingPlots.LekStratSkipGlobalHorseIronEnabled()
	return _lek_strat_skip_global_horse_iron == true;
end

-- RS5 oil/uranium balance recipe: band guarantees (see `_lek_strat_ou_bands`).
function AssignStartingPlots.LekStratOuBandsEnabled()
	return _lek_strat_ou_bands == true;
end

function AssignStartingPlots:LekStratBuildHorseIronListsForRingBand(x, y, dMin, dMax, ironFlatOnly)
	-- Horse: OG balance-style flat primary. Iron: OG hills primary unless ironFlatOnly (extra smalls).
	-- Primary when ripple_radius < dMax; fallback on outer ring of the band (+ flat iron fallbacks when not flat-only).
	local iW, iH = Map.GetGridSize();
	local wrapX = Map:IsWrapX();
	local wrapY = Map:IsWrapY();
	local odd = self.firstRingYIsOdd;
	local even = self.firstRingYIsEven;
	local iron_list, horse_list, iron_fallback, horse_fallback = {}, {}, {}, {};
	local function pushIron(plotIndex, ripple_radius)
		if ripple_radius < dMax then
			table.insert(iron_list, plotIndex);
		else
			table.insert(iron_fallback, plotIndex);
		end
	end
	for ripple_radius = dMin, dMax do
		local currentX = x - ripple_radius;
		local currentY = y;
		for direction_index = 1, 6 do
			for plot_to_handle = 1, ripple_radius do
				local plot_adjustments;
				if currentY / 2 > math.floor(currentY / 2) then
					plot_adjustments = odd[direction_index];
				else
					plot_adjustments = even[direction_index];
				end
				local nextX = currentX + plot_adjustments[1];
				local nextY = currentY + plot_adjustments[2];
				if wrapX == false and (nextX < 0 or nextX >= iW) then
				elseif wrapY == false and (nextY < 0 or nextY >= iH) then
				else
					local realX = nextX;
					local realY = nextY;
					if wrapX then
						realX = realX % iW;
					end
					if wrapY then
						realY = realY % iH;
					end
					local plot = Map.GetPlot(realX, realY);
					local plotType = plot:GetPlotType();
					local terrainType = plot:GetTerrainType();
					local featureType = plot:GetFeatureType();
					local plotIndex = realY * iW + realX + 1;
					if plotType == PlotTypes.PLOT_HILLS then
						if not ironFlatOnly then
							pushIron(plotIndex, ripple_radius);
						end
						if terrainType ~= TerrainTypes.TERRAIN_SNOW and featureType == FeatureTypes.NO_FEATURE then
							table.insert(horse_fallback, plotIndex);
						end
					elseif plotType == PlotTypes.PLOT_LAND then
						if featureType == FeatureTypes.NO_FEATURE then
							if terrainType == TerrainTypes.TERRAIN_TUNDRA or terrainType == TerrainTypes.TERRAIN_DESERT then
								if ironFlatOnly then
									pushIron(plotIndex, ripple_radius);
								else
									table.insert(iron_fallback, plotIndex);
								end
								table.insert(horse_fallback, plotIndex);
							elseif terrainType == TerrainTypes.TERRAIN_PLAINS or terrainType == TerrainTypes.TERRAIN_GRASS then
								if ripple_radius < dMax then
									table.insert(horse_list, plotIndex);
								else
									table.insert(horse_fallback, plotIndex);
								end
								if ironFlatOnly then
									pushIron(plotIndex, ripple_radius);
								else
									table.insert(iron_fallback, plotIndex);
								end
							end
						elseif featureType == FeatureTypes.FEATURE_MARSH then
							if ironFlatOnly then
								pushIron(plotIndex, ripple_radius);
							else
								table.insert(iron_fallback, plotIndex);
							end
						elseif featureType == FeatureTypes.FEATURE_FLOOD_PLAINS then
							table.insert(horse_fallback, plotIndex);
						elseif featureType == FeatureTypes.FEATURE_JUNGLE or featureType == FeatureTypes.FEATURE_FOREST then
							if ironFlatOnly then
								pushIron(plotIndex, ripple_radius);
							else
								table.insert(iron_fallback, plotIndex);
							end
						end
					end
					currentX, currentY = nextX, nextY;
				end
			end
		end
	end
	return iron_list, iron_fallback, horse_list, horse_fallback;
end

function AssignStartingPlots:LekStratPlaceOneWithPrimaryFallback(resId, qty, primary_list, fallback_list, auditLabel, impact_table_number, min_radius, max_radius)
	-- Optional strategic/luxury/… impact: impact_table_number (-1 ignore), min/max radius.
	local impactTbl = impact_table_number;
	if impactTbl == nil then
		impactTbl = -1;
	end
	local minR = min_radius or 0;
	local maxR = max_radius or 0;
	local prevCtx = self._lek_strat_audit_context;
	local resName = AssignStartingPlots.LekStratAuditResName(self, resId) or ("id" .. tostring(resId));
	local pN = table.maxn(primary_list or {});
	local fN = table.maxn(fallback_list or {});
	local listUsed = "none";
	local placed = false;
	if pN > 0 then
		if self.resource_setting == 5 then
			self._lek_strat_audit_context = auditLabel .. ":list=primary";
		end
		local shuf = GetShuffledCopyOfTable(primary_list);
		if self:PlaceSpecificNumberOfResources(resId, qty, 1, 1, impactTbl, minR, maxR, shuf) == 0 then
			placed = true;
			listUsed = "primary";
		end
	end
	if not placed and fN > 0 then
		if self.resource_setting == 5 then
			self._lek_strat_audit_context = auditLabel .. ":list=fallback";
		end
		local shuf = GetShuffledCopyOfTable(fallback_list);
		if self:PlaceSpecificNumberOfResources(resId, qty, 1, 1, impactTbl, minR, maxR, shuf) == 0 then
			placed = true;
			listUsed = "fallback";
		end
	end
	LekMapgenPrintAndDiagFile("### LEK_STRAT_PLACE runId=" .. tostring(_lek_run_id or "na")
		.. " label=" .. tostring(auditLabel)
		.. " res=" .. resName
		.. " qty=" .. tostring(qty)
		.. " ok=" .. tostring(placed)
		.. " listUsed=" .. listUsed
		.. " primaryN=" .. tostring(pN)
		.. " fallbackN=" .. tostring(fN));
	self._lek_strat_audit_context = prevCtx;
	return placed;
end

function AssignStartingPlots:LekStratPlaceExtraBalanceSmallsForRegion(region_number)
	local start_point_data = self.startingPlots[region_number];
	if start_point_data == nil then
		return;
	end
	local x, y = start_point_data[1], start_point_data[2];
	local _, horse_small, _, iron_small = self:GetSmallStrategicResourceQuantityValues();
	LekMapgenPrintAndDiagFile("### LEK_STRAT_EXTRA_SMALLS region_begin runId=" .. tostring(_lek_run_id or "na")
		.. " region=" .. tostring(region_number)
		.. " startX=" .. tostring(x) .. " startY=" .. tostring(y)
		.. " iron_small_qty=" .. tostring(iron_small)
		.. " horse_small_qty=" .. tostring(horse_small));
	local bands = { {4, 5, "r4-5"}, {6, 7, "r6-7"} };
	local okN = 0;
	for _, band in ipairs(bands) do
		local dMin, dMax, tag = band[1], band[2], band[3];
		local iron_list, iron_fallback, horse_list, horse_fallback =
			self:LekStratBuildHorseIronListsForRingBand(x, y, dMin, dMax, true);
		LekMapgenPrintAndDiagFile("### LEK_STRAT_EXTRA_SMALLS band_lists runId=" .. tostring(_lek_run_id or "na")
			.. " region=" .. tostring(region_number) .. " band=" .. tag
			.. " iron_primaryN=" .. tostring(table.maxn(iron_list))
			.. " iron_fallbackN=" .. tostring(table.maxn(iron_fallback))
			.. " horse_primaryN=" .. tostring(table.maxn(horse_list))
			.. " horse_fallbackN=" .. tostring(table.maxn(horse_fallback)));
		if self:LekStratPlaceOneWithPrimaryFallback(
			self.iron_ID, iron_small, iron_list, iron_fallback,
			"extra_small:" .. tag .. "_iron:region=" .. tostring(region_number)) then
			okN = okN + 1;
		end
		if self:LekStratPlaceOneWithPrimaryFallback(
			self.horse_ID, horse_small, horse_list, horse_fallback,
			"extra_small:" .. tag .. "_horse:region=" .. tostring(region_number)) then
			okN = okN + 1;
		end
	end
	LekMapgenPrintAndDiagFile("### LEK_STRAT_EXTRA_SMALLS region_done runId=" .. tostring(_lek_run_id or "na")
		.. " region=" .. tostring(region_number)
		.. " placed=" .. tostring(okN) .. "/4");
end

function AssignStartingPlots:LekStratBuildOilListsForRingBand(x, y, dMin, dMax)
	-- Primary = OG oil_list terrain (desert/tundra/snow/marsh). Fallback = plains/grass/forest/jungle/flood.
	local iW, iH = Map.GetGridSize();
	local wrapX = Map:IsWrapX();
	local wrapY = Map:IsWrapY();
	local odd = self.firstRingYIsOdd;
	local even = self.firstRingYIsEven;
	local oil_list, oil_fallback = {}, {};
	for ripple_radius = dMin, dMax do
		local currentX = x - ripple_radius;
		local currentY = y;
		for direction_index = 1, 6 do
			for plot_to_handle = 1, ripple_radius do
				local plot_adjustments;
				if currentY / 2 > math.floor(currentY / 2) then
					plot_adjustments = odd[direction_index];
				else
					plot_adjustments = even[direction_index];
				end
				local nextX = currentX + plot_adjustments[1];
				local nextY = currentY + plot_adjustments[2];
				if wrapX == false and (nextX < 0 or nextX >= iW) then
				elseif wrapY == false and (nextY < 0 or nextY >= iH) then
				else
					local realX = nextX;
					local realY = nextY;
					if wrapX then
						realX = realX % iW;
					end
					if wrapY then
						realY = realY % iH;
					end
					local plot = Map.GetPlot(realX, realY);
					local plotType = plot:GetPlotType();
					local terrainType = plot:GetTerrainType();
					local featureType = plot:GetFeatureType();
					local plotIndex = realY * iW + realX + 1;
					if plotType == PlotTypes.PLOT_LAND then
						if featureType == FeatureTypes.NO_FEATURE then
							if terrainType == TerrainTypes.TERRAIN_TUNDRA
								or terrainType == TerrainTypes.TERRAIN_DESERT
								or terrainType == TerrainTypes.TERRAIN_SNOW then
								if ripple_radius < dMax then
									table.insert(oil_list, plotIndex);
								else
									table.insert(oil_fallback, plotIndex);
								end
							elseif terrainType == TerrainTypes.TERRAIN_PLAINS or terrainType == TerrainTypes.TERRAIN_GRASS then
								table.insert(oil_fallback, plotIndex);
							end
						elseif featureType == FeatureTypes.FEATURE_MARSH then
							if ripple_radius < dMax then
								table.insert(oil_list, plotIndex);
							else
								table.insert(oil_fallback, plotIndex);
							end
						elseif featureType == FeatureTypes.FEATURE_FLOOD_PLAINS
							or featureType == FeatureTypes.FEATURE_JUNGLE
							or featureType == FeatureTypes.FEATURE_FOREST then
							table.insert(oil_fallback, plotIndex);
						end
					end
					currentX, currentY = nextX, nextY;
				end
			end
		end
	end
	return oil_list, oil_fallback;
end

function AssignStartingPlots:LekStratBuildUranListsForRingBand(x, y, dMin, dMax)
	-- Primary: marsh/jungle/forest + tundra/desert/snow land. Fallback: grass/plains + hills land.
	local iW, iH = Map.GetGridSize();
	local wrapX = Map:IsWrapX();
	local wrapY = Map:IsWrapY();
	local odd = self.firstRingYIsOdd;
	local even = self.firstRingYIsEven;
	local uran_list, uran_fallback = {}, {};
	for ripple_radius = dMin, dMax do
		local currentX = x - ripple_radius;
		local currentY = y;
		for direction_index = 1, 6 do
			for plot_to_handle = 1, ripple_radius do
				local plot_adjustments;
				if currentY / 2 > math.floor(currentY / 2) then
					plot_adjustments = odd[direction_index];
				else
					plot_adjustments = even[direction_index];
				end
				local nextX = currentX + plot_adjustments[1];
				local nextY = currentY + plot_adjustments[2];
				if wrapX == false and (nextX < 0 or nextX >= iW) then
				elseif wrapY == false and (nextY < 0 or nextY >= iH) then
				else
					local realX = nextX;
					local realY = nextY;
					if wrapX then
						realX = realX % iW;
					end
					if wrapY then
						realY = realY % iH;
					end
					local plot = Map.GetPlot(realX, realY);
					local plotType = plot:GetPlotType();
					local terrainType = plot:GetTerrainType();
					local featureType = plot:GetFeatureType();
					local plotIndex = realY * iW + realX + 1;
					if plotType == PlotTypes.PLOT_LAND or plotType == PlotTypes.PLOT_HILLS then
						if featureType ~= FeatureTypes.FEATURE_FLOOD_PLAINS and featureType ~= FeatureTypes.FEATURE_OASIS then
							local primary = false;
							if featureType == FeatureTypes.FEATURE_MARSH
								or featureType == FeatureTypes.FEATURE_JUNGLE
								or featureType == FeatureTypes.FEATURE_FOREST then
								primary = true;
							elseif featureType == FeatureTypes.NO_FEATURE
								and (terrainType == TerrainTypes.TERRAIN_TUNDRA
									or terrainType == TerrainTypes.TERRAIN_DESERT
									or terrainType == TerrainTypes.TERRAIN_SNOW) then
								primary = true;
							end
							if primary and ripple_radius < dMax then
								table.insert(uran_list, plotIndex);
							elseif primary then
								table.insert(uran_fallback, plotIndex);
							else
								table.insert(uran_fallback, plotIndex);
							end
						end
					end
					currentX, currentY = nextX, nextY;
				end
			end
		end
	end
	return uran_list, uran_fallback;
end

function AssignStartingPlots:LekStratPickMajorOrMinorQty(majorQty, minorQty)
	if Map.Rand(2, "LekStrat OU major/minor coin - Lua") == 0 then
		return majorQty, "major";
	end
	return minorQty, "small";
end

function AssignStartingPlots:LekStratPlaceOuBandsForRegion(region_number)
	local start_point_data = self.startingPlots[region_number];
	if start_point_data == nil then
		return;
	end
	local x, y = start_point_data[1], start_point_data[2];
	local uran_major, horse_major, oil_major, iron_major = self:GetMajorStrategicResourceQuantityValues();
	local uran_small, horse_small, oil_small, iron_small = self:GetSmallStrategicResourceQuantityValues();
	LekMapgenPrintAndDiagFile("### LEK_STRAT_OU_BANDS region_begin runId=" .. tostring(_lek_run_id or "na")
		.. " region=" .. tostring(region_number)
		.. " startX=" .. tostring(x) .. " startY=" .. tostring(y)
		.. " oil_major_qty=" .. tostring(oil_major) .. " oil_small_qty=" .. tostring(oil_small)
		.. " uran_major_qty=" .. tostring(uran_major) .. " uran_small_qty=" .. tostring(uran_small));

	local oilOk, uranOk = 0, 0;
	-- Oil: 1 major r1-3; 1 major/minor r4-5; 1 major/minor r6-7.
	do
		local oil_list, oil_fallback = self:LekStratBuildOilListsForRingBand(x, y, 1, 3);
		if self:LekStratPlaceOneWithPrimaryFallback(
			self.oil_ID, oil_major, oil_list, oil_fallback,
			"guaranteed_band:oil_r1-3_major:region=" .. tostring(region_number)) then
			oilOk = oilOk + 1;
		end
	end
	do
		local qty, szTag = self:LekStratPickMajorOrMinorQty(oil_major, oil_small);
		local oil_list, oil_fallback = self:LekStratBuildOilListsForRingBand(x, y, 4, 5);
		if self:LekStratPlaceOneWithPrimaryFallback(
			self.oil_ID, qty, oil_list, oil_fallback,
			"guaranteed_band:oil_r4-5_" .. szTag .. ":region=" .. tostring(region_number)) then
			oilOk = oilOk + 1;
		end
	end
	do
		local qty, szTag = self:LekStratPickMajorOrMinorQty(oil_major, oil_small);
		local oil_list, oil_fallback = self:LekStratBuildOilListsForRingBand(x, y, 6, 7);
		if self:LekStratPlaceOneWithPrimaryFallback(
			self.oil_ID, qty, oil_list, oil_fallback,
			"guaranteed_band:oil_r6-7_" .. szTag .. ":region=" .. tostring(region_number)) then
			oilOk = oilOk + 1;
		end
	end

	-- Uranium: 1 deposit r3-5 (50/50 major/minor) + 1 r6-8 (qty=1). Avoid r1-2 for the close node.
	-- Uranium-only impact layer (9) so deadzone does not block coal/alum/other strategics.
	local uran_band_impact_min, uran_band_impact_max = 4, 6;
	do
		local qty, szTag = self:LekStratPickMajorOrMinorQty(uran_major, uran_small);
		local uran_list, uran_fallback = self:LekStratBuildUranListsForRingBand(x, y, 3, 5);
		if self:LekStratPlaceOneWithPrimaryFallback(
			self.uranium_ID, qty, uran_list, uran_fallback,
			"guaranteed_band:uran_r3-5_" .. szTag .. ":region=" .. tostring(region_number),
			9, uran_band_impact_min, uran_band_impact_max) then
			uranOk = uranOk + 1;
		end
	end
	do
		local uran_band_qty = 1;
		local uran_list, uran_fallback = self:LekStratBuildUranListsForRingBand(x, y, 6, 8);
		if self:LekStratPlaceOneWithPrimaryFallback(
			self.uranium_ID, uran_band_qty, uran_list, uran_fallback,
			"guaranteed_band:uran_r6-8_qty1:region=" .. tostring(region_number),
			9, uran_band_impact_min, uran_band_impact_max) then
			uranOk = uranOk + 1;
		end
	end

	LekMapgenPrintAndDiagFile("### LEK_STRAT_OU_BANDS region_done runId=" .. tostring(_lek_run_id or "na")
		.. " region=" .. tostring(region_number)
		.. " oil_placed=" .. tostring(oilOk) .. "/3"
		.. " uran_placed=" .. tostring(uranOk) .. "/2");
end

-- Lekmap: stubs for natural wonder custom eligibility/placement (called when XML method number != -1)
function NWCustomEligibility(x, y, method_number) return false; end
function NWCustomPlacement(x, y, row_number, method_number) end

------------------------------------------------------------------------------
-- NOTE FOR MODDERS: There is a detailed Reference at the end of the file.
------------------------------------------------------------------------------

--                             FOREWORD

-- Jon wanted a lot of changes to terrain composition for Civ5. These have
-- had the effect of making different parts of each randomly generated maps
-- more distinct, more unique, but it has also necessitated a complete
-- overhaul of where civs are placed on the map and how resources are
-- distributed. The new placements are much more precise, both for civs 
-- and resources. As such, any modifications to terrain or resource types 
-- will no longer be "plug and play" in the XML. Terrain modders will have 
-- to work with this file as well as the XML, to integrate their mods in to
-- the new system.

-- Some civs will be purposely placed in difficult terrain, depending on what
-- a given map instance has to offer. Civs placed in tough environments will
-- receive specific amounts of assistance, primarily in the form of Bonus food
-- from Wheat, Cows, Deer, Bananas, or Fish. This part of the new system is 
-- very precisely calibrated and balanced, so be aware that any changes or 
-- additions to how resources are placed near start points will have a 
-- dramatic effect on the game, and could pose challenges of a sort that were
-- not present in the sphere of Civ4 modding.
--
-- Lekmap naming (capital / rings near start): regional luxury bundle and
-- second-lux cascade are luxuries only. Strategics (iron, horses, …) use
-- other passes and are not part of the "capital goodies" counter. Capital
-- goodies = fish plus LekResourceIsBonus tiles (wheat, sheep, stone, …) in
-- LekCountCapitalGoodiesBudgetNearStart; coastal fish uses goodies_cap=3 for
-- that combined budget. AttemptToPlaceBonusResourceAtPlot uses a separate
-- per-call maxCapitalGoodiesLeft counter for legacy ring placement.

-- The Luxury resources are also carefully calibrated. In a given game, some
-- will be clustered near a small number of civs (perhaps even a monopoly 
-- given to one). Some will be placed only near City States, requiring civs 
-- to go through a City State, one way or another, to obtain any instances of
-- that luxury type. Some will be left up to fate, appearing randomly in 
-- whatever is their normal habitat. Yet others may be oversupplied or perhaps
-- even absent from a given game. Which luxuries fall in to which category 
-- will be scrambled, to keep players guessing, and to help further the sense
-- of curiosity when exploring a new map in a new game.

-- Bob Thomas  -  April 16, 2010

-- There is a Reference section at the end of the file.

------------------------------------------------------------------------------
------------------------------------------------------------------------------
AssignStartingPlots = AssignStartingPlots or {};
------------------------------------------------------------------------------

-- WARNING: There must not be any recalculation of AreaIDs at any time during
-- the execution of any operations in or attached to this table. Recalculating
-- will invalidate all data based on AreaID relationships with plots, which
-- will destroy Regional definitions for all but the Rectangular method. A fix
-- for scrambled AreaID data is theoretically possible, but I have not spent
-- development resources and time on this, directing attention to other tasks.

------------------------------------------------------------------------------
function AssignStartingPlots.Create()
	-- There are three methods of dividing the map in to regions.
	-- OneLandmass, Continents, Oceanic. Default method is Continents.
	--
	-- Standard start plot finding uses a regional division method, then
	-- assigns one civ per region. Regions with lowest average fertility
	-- get their assignment first, to avoid the poor getting poorer.
	--
	-- Default methods for civ and city state placement both rely on having
	-- regional division data. If the desired process for a given map script
	-- would not define regions of this type, replace the start finder
	-- with your custom method.
	--
	-- Note that this operation relies on inclusion of the Mapmaker Utilities.
	local iW, iH = Map.GetGridSize();
	local feature_atoll;
	for thisFeature in GameInfo.Features() do
		if thisFeature.Type == "FEATURE_ATOLL" then
			feature_atoll = thisFeature.ID;
		end
	end

	-- Main data table ("self dot" table).
	--
	-- Scripters have the opportunity to replace member methods without
	-- having to replace the entire process.
	local findStarts = {

		-- Core Process member methods
		__Init = AssignStartingPlots.__Init,
		__InitLuxuryWeights = AssignStartingPlots.__InitLuxuryWeights,
		__CustomInit = AssignStartingPlots.__CustomInit,
		ApplyHexAdjustment = AssignStartingPlots.ApplyHexAdjustment,
		GenerateRegions = AssignStartingPlots.GenerateRegions,
		ChooseLocations = AssignStartingPlots.ChooseLocations,
		LekGlobalSixChooseLocations = AssignStartingPlots.LekGlobalSixChooseLocations,
		LekGlobalSix_ForceApplyExpectedPlayerStarts = AssignStartingPlots.LekGlobalSix_ForceApplyExpectedPlayerStarts,
		LekGlobalSix_LogForceBiasAssignmentAudit = AssignStartingPlots.LekGlobalSix_LogForceBiasAssignmentAudit,
		LekGlobalSix_OK_RunAll = AssignStartingPlots.LekGlobalSix_OK_RunAll,
		LekGlobalSix_GatherRawFindStartStyleCandidateIndices = AssignStartingPlots.LekGlobalSix_GatherRawFindStartStyleCandidateIndices,
		LekGlobalSix_GatherTupleStyleCandidateIndices = AssignStartingPlots.LekGlobalSix_GatherTupleStyleCandidateIndices,
		LekGlobalSix_CountRawFindStartStyleCandidates = AssignStartingPlots.LekGlobalSix_CountRawFindStartStyleCandidates,
		LekGlobalSix_CountEvaluateMeetsMinInRawPool = AssignStartingPlots.LekGlobalSix_CountEvaluateMeetsMinInRawPool,
		LekGlobalSix_ApplyDistanceRipplesForStartOnly = AssignStartingPlots.LekGlobalSix_ApplyDistanceRipplesForStartOnly,
		LekGlobalSix_LogRippleOrderedSampleDryRun = AssignStartingPlots.LekGlobalSix_LogRippleOrderedSampleDryRun,
		LekGlobalSix_RunTupleSearch = AssignStartingPlots.LekGlobalSix_RunTupleSearch,
		LekGlobalSix_OK_LogDiagnostics = AssignStartingPlots.LekGlobalSix_OK_LogDiagnostics,
		BalanceAndAssign = AssignStartingPlots.BalanceAndAssign,
