-- MOD SAPHT: First call after create, example args from SmallContinents:
-- 	local args = {
-- 		method = RegionalMethod, -- (==2)
-- method == 1 on fractal map
-- 		start_locations = starts,
-- 		resources = res,
-- 		CoastLux = CoastLux,
-- 		NoCoastInland = OnlyCoastal,
-- 		BalancedCoastal = BalancedCoastal,
-- 		MixedBias = MixedBias;
-- 		};

function AssignStartingPlots:GenerateRegions(args)
	if not LekMapgenTupleBenchmarkMode() then
		print("Map Generation - Dividing the map in to Regions");
	end
	-- This function stores its data in the instance (self) data table.
	--
	-- The "Three Methods" of regional division:
	-- 1. Biggest Landmass: All civs start on the biggest landmass.
	-- 2. Continental: Civs are assigned to continents. Any continents with more than one civ are divided.
	-- 3. Rectangular: Civs start within a given rectangle that spans the whole map, without regard to landmass sizes.
	--                 This method is primarily applied to Archipelago and other maps with lots of tiny islands.
	-- 4. Rectangular: Civs start within a given rectangle defined by arguments passed in on the function call.
	--                 Arguments required for this method: iWestX, iSouthY, iWidth, iHeight
	local args = args or {};
	local iW, iH = Map.GetGridSize();
	self.method = args.method or self.method; -- Continental method is default.
	self.start_locations = args.start_locations or 2; -- Each map script has to pass in parameter for Resource setting chosen by user.
	self.resource_setting = args.resources or 5;
	LekMapgenPrintAndDiagFile("### LEK_RESOURCE_SETTING runId=" .. tostring(_lek_run_id or "na")
		.. " args.resources=" .. tostring(args.resources)
		.. " resolved_resource_setting=" .. tostring(self.resource_setting));
	AssignStartingPlots.LekStratAuditReset(self);
	self.CoastLux = args.CoastLux or false;
	self.AllowInlandSea = args.AllowInlandSea or 1;
	self.NoCoastInland = args.NoCoastInland;
	self.BalancedCoastal = args.BalancedCoastal;
	self.BalancedCoastalExactTwo = (args.BalancedCoastalExactTwo == true);
	self.ForceAllInlandPlayerSpawns = (args.ForceAllInlandPlayerSpawns == true);
	self._lek_tuple_force_two_coastal_majors = (args.BalancedCoastalExactTwo == true);
	self.MixedBias = args.MixedBias;
	self._lek_ignore_all_start_bias = (args.IgnoreAllStartBias == true);

	-- Determine number of civilizations and city states present in this game.
	self.iNumCivs, self.iNumCityStates, self.player_ID_list, self.bTeamGame, self.teams_with_major_civs, self.number_civs_per_team = GetPlayerAndTeamInfo()
	self.iNumCityStatesUnassigned = self.iNumCityStates;
	if not LekMapgenTupleBenchmarkMode() then
		print("-"); print("Civs:", self.iNumCivs); print("City States:", self.iNumCityStates);
	end

	if self.method == 1 then -- Biggest Landmass
		-- Identify the biggest landmass.
		local biggest_area = Map.FindBiggestArea(False);
		local iAreaID = biggest_area:GetID();
		-- We'll need all eight data fields returned in the results table from the boundary finder:
		local landmass_data = ObtainLandmassBoundaries(iAreaID);
		local iWestX = landmass_data[1];
		local iSouthY = landmass_data[2];
		local iEastX = landmass_data[3];
		local iNorthY = landmass_data[4];
		local iWidth = landmass_data[5];
		local iHeight = landmass_data[6];
		local wrapsX = landmass_data[7];
		local wrapsY = landmass_data[8];
		
		-- Obtain "Start Placement Fertility" of the landmass. (This measurement is customized for start placement).
		-- This call returns a table recording fertility of all plots within a rectangle that contains the landmass,
		-- with a zero value for any plots not part of the landmass -- plus a fertility sum and plot count.
		local fert_table, fertCount, plotCount = self:MeasureStartPlacementFertilityOfLandmass(iAreaID, 
		                                         iWestX, iEastX, iSouthY, iNorthY, wrapsX, wrapsY);
		-- Now divide this landmass in to regions, one per civ.
		-- The regional divider requires three arguments:
		-- 1. Number of divisions. (For "Biggest Landmass" this means number of civs in the game).
		-- 2. Fertility table. (This was obtained from the last call.)
		-- 3. Rectangle table. This table includes seven data fields:
		-- westX, southY, width, height, AreaID, fertilityCount, plotCount
		-- This is why we got the fertCount and plotCount from the fertility function.
		--
		-- Assemble the Rectangle data table:
		local rect_table = {iWestX, iSouthY, iWidth, iHeight, iAreaID, fertCount, plotCount};
		-- The data from this call is processed in to self.regionData during the process.
		self:DivideIntoRegions(self.iNumCivs, fert_table, rect_table)
		-- The regions have been defined.
	
	elseif self.method == 3 or self.method == 4 then -- Rectangular
		-- Obtain the boundaries of the rectangle to be processed.
		-- If no coords were passed via the args table, default to processing the entire map.
		-- Note that it matters if method 3 or 4 is designated, because the difference affects
		-- how city states are placed, whether they look for any uninhabited lands outside the rectangle.
		self.inhabited_WestX = args.iWestX or 0;
		self.inhabited_SouthY = args.iSouthY or 0;
		self.inhabited_Width = args.iWidth or iW;
		self.inhabited_Height = args.iHeight or iH;

		-- Obtain "Start Placement Fertility" inside the rectangle.
		-- Data returned is: fertility table, sum of all fertility, plot count.
		local fert_table, fertCount, plotCount = self:MeasureStartPlacementFertilityInRectangle(self.inhabited_WestX, 
		                                         self.inhabited_SouthY, self.inhabited_Width, self.inhabited_Height)
		-- Assemble the Rectangle data table:
		local rect_table = {self.inhabited_WestX, self.inhabited_SouthY, self.inhabited_Width, 
		                    self.inhabited_Height, -1, fertCount, plotCount}; -- AreaID -1 means ignore area IDs.
		-- Divide the rectangle.
		self:DivideIntoRegions(self.iNumCivs, fert_table, rect_table)
		-- The regions have been defined.
	
	else -- Continental.
		--[[ Loop through all plots on the map, measuring fertility of each land 
		     plot, identifying its AreaID, building a list of landmass AreaIDs, and
		     tallying the Start Placement Fertility for each landmass. ]]--

		-- region_data: [WestX, EastX, SouthY, NorthY, 
		-- numLandPlotsinRegion, numCoastalPlotsinRegion,
		-- numOceanPlotsinRegion, iRegionNetYield, 
		-- iNumLandAreas, iNumPlotsinRegion]
		local best_areas = {};
		local globalFertilityOfLands = {};

		-- Obtain info on all landmasses for comparision purposes.
		local iGlobalFertilityOfLands = 0;
		local iNumLandPlots = 0;
		local iNumLandAreas = 0;
		local land_area_IDs = {};
		local land_area_plots = {};
		local land_area_fert = {};
		-- Cycle through all plots in the world, checking their Start Placement Fertility and AreaID.
		for x = 0, iW - 1 do
			for y = 0, iH - 1 do
				local i = y * iW + x + 1;
				local plot = Map.GetPlot(x, y);
				if not plot:IsWater() then -- Land plot, process it.
					iNumLandPlots = iNumLandPlots + 1;
					local iArea = plot:GetArea();
					local plotFertility = self:MeasureStartPlacementFertilityOfPlot(x, y, true); -- Check for coastal land is enabled.
					iGlobalFertilityOfLands = iGlobalFertilityOfLands + plotFertility;
					--
					if TestMembership(land_area_IDs, iArea) == false then -- This plot is the first detected in its AreaID.
						iNumLandAreas = iNumLandAreas + 1;
						table.insert(land_area_IDs, iArea);
						land_area_plots[iArea] = 1;
						land_area_fert[iArea] = plotFertility;
					else -- This AreaID already known.
						land_area_plots[iArea] = land_area_plots[iArea] + 1;
						land_area_fert[iArea] = land_area_fert[iArea] + plotFertility;
					end
				end
			end
		end
		
		--[[ Debug printout
		print("* * * * * * * * * *");
		for area_loop, AreaID in ipairs(land_area_IDs) do
			print("Area ID " .. AreaID .. " is land.");
		end ]]--
		print("* * * * * * * * * *");
		for AreaID, fert in pairs(land_area_fert) do
			print("Area ID " .. AreaID .. " has fertility of " .. fert);
		end
		print("* * * * * * * * * *");
		--		
		
		-- Sort areas, achieving a list of AreaIDs with best areas first.
		--
		-- Fertility data in land_area_fert is stored with areaID index keys.
		-- Need to generate a version of this table with indices of 1 to n, where n is number of land areas.
		local interim_table = {};
		for loop_index, data_entry in pairs(land_area_fert) do
			table.insert(interim_table, data_entry);
		end
		
		--[[for AreaID, fert in ipairs(interim_table) do
			print("Interim Table ID " .. AreaID .. " has fertility of " .. fert);
		end
		print("* * * * * * * * * *"); ]]--
		
		-- Sort the fertility values stored in the interim table. Sort order in Lua is lowest to highest.
		table.sort(interim_table);

		for AreaID, fert in ipairs(interim_table) do
			print("Interim Table ID " .. AreaID .. " has fertility of " .. fert);
		end
		print("* * * * * * * * * *");

		-- If less players than landmasses, we will ignore the extra landmasses.
		local iNumRelevantLandAreas = math.min(iNumLandAreas, self.iNumCivs);
		-- Now re-match the AreaID numbers with their corresponding fertility values
		-- by comparing the original fertility table with the sorted interim table.
		-- During this comparison, best_areas will be constructed from sorted AreaIDs, richest stored first.
		local best_areas = {};
		-- Currently, the best yields are at the end of the interim table. We need to step backward from there.
		local end_of_interim_table = table.maxn(interim_table);
		-- We may not need all entries in the table. Process only iNumRelevantLandAreas worth of table entries.
		local fertility_value_list = {};
		local fertility_value_tie = false;
		for tableConstructionLoop = end_of_interim_table, (end_of_interim_table - iNumRelevantLandAreas + 1), -1 do
			if TestMembership(fertility_value_list, interim_table[tableConstructionLoop]) == true then
				fertility_value_tie = true;
				print("*** WARNING: Fertility Value Tie exists! ***");
			else
				table.insert(fertility_value_list, interim_table[tableConstructionLoop]);
			end
		end

		if fertility_value_tie == false then -- No ties, so no need of special handling for ties.
			for areaTestLoop = end_of_interim_table, (end_of_interim_table - iNumRelevantLandAreas + 1), -1 do
				for loop_index, AreaID in ipairs(land_area_IDs) do
					if interim_table[areaTestLoop] == land_area_fert[land_area_IDs[loop_index]] then
						table.insert(best_areas, AreaID);
						break
					end
				end
			end
		else -- Ties exist! Special handling required to protect against a shortfall in the number of defined regions.
			local iNumUniqueFertValues = table.maxn(fertility_value_list);
			for fertLoop = 1, iNumUniqueFertValues do
				for AreaID, fert in pairs(land_area_fert) do
					if fert == fertility_value_list[fertLoop] then
						-- Add ties only if there is room!
						local best_areas_length = table.maxn(best_areas);
						if best_areas_length < iNumRelevantLandAreas then
							table.insert(best_areas, AreaID);
						else
							break
						end
					end
				end
			end
		end
				
		-- Debug printout
		print("-"); print("--- Continental Division, Initial Readout ---"); print("-");
		print("- Global Fertility:", iGlobalFertilityOfLands);
		print("- Total Land Plots:", iNumLandPlots);
		print("- Total Areas:", iNumLandAreas);
		print("- Relevant Areas:", iNumRelevantLandAreas); print("-");
		--

		-- Debug printout
		print("* * * * * * * * * *");
		for area_loop, AreaID in ipairs(best_areas) do
			print("Area ID " .. AreaID .. " has fertility of " .. land_area_fert[AreaID]);
		end
		print("* * * * * * * * * *");
		--

		-- Assign continents to receive start plots. Record number of civs assigned to each landmass.
		local inhabitedAreaIDs = {};
		local numberOfCivsPerArea = table.fill(0, iNumRelevantLandAreas); -- Indexed in synch with best_areas. Use same index to match values from each table.
		for civToAssign = 1, self.iNumCivs do
			local bestRemainingArea;
			local bestRemainingFertility = 0;
			local bestAreaTableIndex;
			-- Loop through areas, find the one with the best remaining fertility (civs added 
			-- to a landmass reduces its fertility rating for subsequent civs).
			--
			print("- - Searching landmasses in order to place Civ #", civToAssign); print("-");
			for area_loop, AreaID in ipairs(best_areas) do
				local thisLandmassCurrentFertility = land_area_fert[AreaID] / (1 + numberOfCivsPerArea[area_loop]);
				if thisLandmassCurrentFertility > bestRemainingFertility then
					bestRemainingArea = AreaID;
					bestRemainingFertility = thisLandmassCurrentFertility;
					bestAreaTableIndex = area_loop;
					--
					print("- Found new candidate landmass with Area ID#:", bestRemainingArea, " with fertility of ", bestRemainingFertility);
				end
			end
			-- Record results for this pass. (A landmass has been assigned to receive one more start point than it previously had).
			numberOfCivsPerArea[bestAreaTableIndex] = numberOfCivsPerArea[bestAreaTableIndex] + 1;
			if TestMembership(inhabitedAreaIDs, bestRemainingArea) == false then
				table.insert(inhabitedAreaIDs, bestRemainingArea);
			end
			print("Civ #", civToAssign, "has been assigned to Area#", bestRemainingArea); print("-");
		end
		print("-"); print("--- End of Initial Readout ---"); print("-");
		
		print("*** Number of Civs per Landmass - Table Readout ***");
		PrintContentsOfTable(numberOfCivsPerArea)
		print("--- End of Civs per Landmass readout ***"); print("-"); print("-");
				
		-- Loop through the list of inhabited landmasses, dividing each landmass in to regions.
		-- Note that it is OK to divide a continent with one civ on it: this will assign the whole
		-- of the landmass to a single region, and is the easiest method of recording such a region.
		local iNumInhabitedLandmasses = table.maxn(inhabitedAreaIDs);
		for loop, currentLandmassID in ipairs(inhabitedAreaIDs) do
			-- Obtain the boundaries of and data for this landmass.
			local landmass_data = ObtainLandmassBoundaries(currentLandmassID);
			local iWestX = landmass_data[1];
			local iSouthY = landmass_data[2];
			local iEastX = landmass_data[3];
			local iNorthY = landmass_data[4];
			local iWidth = landmass_data[5];
			local iHeight = landmass_data[6];
			local wrapsX = landmass_data[7];
			local wrapsY = landmass_data[8];
			-- Obtain "Start Placement Fertility" of the current landmass. (Necessary to do this
			-- again because the fert_table can't be built prior to finding boundaries, and we had
			-- to ID the proper landmasses via fertility to be able to figure out their boundaries.
			local fert_table, fertCount, plotCount = self:MeasureStartPlacementFertilityOfLandmass(currentLandmassID, 
		  	                                         iWestX, iEastX, iSouthY, iNorthY, wrapsX, wrapsY);
			-- Assemble the rectangle data for this landmass.
			local rect_table = {iWestX, iSouthY, iWidth, iHeight, currentLandmassID, fertCount, plotCount};
			-- Divide this landmass in to number of regions equal to civs assigned here.
			iNumCivsOnThisLandmass = numberOfCivsPerArea[loop];
			if iNumCivsOnThisLandmass > 0 and iNumCivsOnThisLandmass <= 22 then -- valid number of civs.
			
				-- Debug printout for regional division inputs.
				print("-"); print("- Region #: ", loop);
				print("- Civs on this landmass: ", iNumCivsOnThisLandmass);
				print("- Area ID#: ", currentLandmassID);
				print("- Fertility: ", fertCount);
				print("- Plot Count: ", plotCount); print("-");
				--
			
				self:DivideIntoRegions(iNumCivsOnThisLandmass, fert_table, rect_table)
			else
				print("Invalid number of civs assigned to a landmass: ", iNumCivsOnThisLandmass);
			end
		end
		--
		-- The regions have been defined.
	end
	
	-- Entry point for easier overrides.
	self:CustomOverride()
	
	-- Printout is for debugging only. Deactivate otherwise.
	-- local tempRegionData = self.regionData;
	-- for i, data in ipairs(tempRegionData) do
	-- 	print("-");
	-- 	print("Data for Start Region #", i);
	-- 	print("WestX:  ", data[1]);
	-- 	print("SouthY: ", data[2]);
	-- 	print("Width:  ", data[3]);
	-- 	print("Height: ", data[4]);
	-- 	print("AreaID: ", data[5]);
	-- 	print("Fertility:", data[6]);
	-- 	print("Plots:  ", data[7]);
	-- 	print("Fert/Plot:", data[8]);
	-- 	print("-");
	-- end
	--
end
------------------------------------------------------------------------------
-- Start of functions tied to ChooseLocations()
------------------------------------------------------------------------------
function AssignStartingPlots:MeasureTerrainInRegions()
	local iW, iH = Map.GetGridSize();
	-- This function stores its data in the instance (self) data table.
	for region_loop, region_data_table in ipairs(self.regionData) do
		local iWestX = region_data_table[1];
		local iSouthY = region_data_table[2];
		local iWidth = region_data_table[3];
		local iHeight = region_data_table[4];
		local iAreaID = region_data_table[5];
		
		local totalPlots, areaPlots = 0, 0;
		local waterCount, flatlandsCount, hillsCount, peaksCount = 0, 0, 0, 0;
		local lakeCount, coastCount, oceanCount, iceCount = 0, 0, 0, 0;
		local grassCount, plainsCount, desertCount, tundraCount, snowCount = 0, 0, 0, 0, 0; -- counts flatlands only!
		local forestCount, jungleCount, marshCount, riverCount, floodplainCount, oasisCount = 0, 0, 0, 0, 0, 0;
		local coastalLandCount, nextToCoastCount = 0, 0;

		-- Iterate through the region's plots, getting plotType, terrainType, featureType and river status.
		for region_loop_y = 0, iHeight - 1 do
			for region_loop_x = 0, iWidth - 1 do
				totalPlots = totalPlots + 1;
				local x = (region_loop_x + iWestX) % iW;
				local y = (region_loop_y + iSouthY) % iH;
				local plot = Map.GetPlot(x, y);
				local area_of_plot = plot:GetArea();
				-- get plot info
				local plotType = plot:GetPlotType()
				local terrainType = plot:GetTerrainType()
				local featureType = plot:GetFeatureType()
				
				-- Mountain and Ocean plot types get their own AreaIDs, but we are going to measure them anyway.
				if plotType == PlotTypes.PLOT_MOUNTAIN then
					peaksCount = peaksCount + 1; -- and that's it for Mountain plots. No other stats.
				elseif plotType == PlotTypes.PLOT_OCEAN then
					waterCount = waterCount + 1;
					if terrainType == TerrainTypes.TERRAIN_COAST then
						if plot:IsLake() then
							lakeCount = lakeCount + 1;
						else
							coastCount = coastCount + 1;
						end
					else
						oceanCount = oceanCount + 1;
					end
					if featureType == FeatureTypes.FEATURE_ICE then
						iceCount = iceCount + 1;
					end

				else
					-- Hills and Flatlands, check plot for region membership. Only process this plot if it is a member.
					if (area_of_plot == iAreaID) or (iAreaID == -1) then
						areaPlots = areaPlots + 1;

						-- set up coastalLand and nextToCoast index
						local i = iW * y + x + 1;
			
						-- Record plot data
						if plotType == PlotTypes.PLOT_HILLS then
							hillsCount = hillsCount + 1;

							if self.plotDataIsCoastal[i] then
								coastalLandCount = coastalLandCount + 1;
							elseif self.plotDataIsNextToCoast[i] then
								nextToCoastCount = nextToCoastCount + 1;
							end

							if plot:IsRiverSide() then
								riverCount = riverCount + 1;
							end

							-- Feature check checking for all types, in case features are not obeying standard allowances.
							if featureType == FeatureTypes.FEATURE_FOREST then
								forestCount = forestCount + 1;
							elseif featureType == FeatureTypes.FEATURE_JUNGLE then
								jungleCount = jungleCount + 1;
							elseif featureType == FeatureTypes.FEATURE_MARSH then
								marshCount = marshCount + 1;
							elseif featureType == FeatureTypes.FEATURE_FLOOD_PLAINS then
								floodplainCount = floodplainCount + 1;
							elseif featureType == FeatureTypes.FEATURE_OASIS then
								oasisCount = oasisCount + 1;
							end
								
						else -- Flatlands plot
							flatlandsCount = flatlandsCount + 1;
	
							if self.plotDataIsCoastal[i] then
								coastalLandCount = coastalLandCount + 1;
							elseif self.plotDataIsNextToCoast[i] then
								nextToCoastCount = nextToCoastCount + 1;
							end

							if plot:IsRiverSide() then
								riverCount = riverCount + 1;
							end
				
							if terrainType == TerrainTypes.TERRAIN_GRASS then
								grassCount = grassCount + 1;
							elseif terrainType == TerrainTypes.TERRAIN_PLAINS then
								plainsCount = plainsCount + 1;
							elseif terrainType == TerrainTypes.TERRAIN_DESERT then
								desertCount = desertCount + 1;
							elseif terrainType == TerrainTypes.TERRAIN_TUNDRA then
								tundraCount = tundraCount + 1;
							elseif terrainType == TerrainTypes.TERRAIN_SNOW then
								snowCount = snowCount + 1;
							end
				
							-- Feature check checking for all types, in case features are not obeying standard allowances.
							if featureType == FeatureTypes.FEATURE_FOREST then
								forestCount = forestCount + 1;
							elseif featureType == FeatureTypes.FEATURE_JUNGLE then
								jungleCount = jungleCount + 1;
							elseif featureType == FeatureTypes.FEATURE_MARSH then
								marshCount = marshCount + 1;
							elseif featureType == FeatureTypes.FEATURE_FLOOD_PLAINS then
								floodplainCount = floodplainCount + 1;
							elseif featureType == FeatureTypes.FEATURE_OASIS then
								oasisCount = oasisCount + 1;
							end
						end
					end
				end
			end
		end
			
		-- Assemble in to an array the recorded data for this region: 23 variables.
		local regionCounts = {
			totalPlots, areaPlots,
			waterCount, flatlandsCount, hillsCount, peaksCount,
			lakeCount, coastCount, oceanCount, iceCount,
			grassCount, plainsCount, desertCount, tundraCount, snowCount,
			forestCount, jungleCount, marshCount, riverCount, floodplainCount, oasisCount,
			coastalLandCount, nextToCoastCount
			}
		--[[ Table Key:
		
		1) totalPlots
		2) areaPlots                 13) desertCount
		3) waterCount                14) tundraCount
		4) flatlandsCount            15) snowCount
		5) hillsCount                16) forestCount
		6) peaksCount                17) jungleCount
		7) lakeCount                 18) marshCount
		8) coastCount                19) riverCount
		9) oceanCount                20) floodplainCount
		10) iceCount                 21) oasisCount
		11) grassCount               22) coastalLandCount
		12) plainsCount              23) nextToCoastCount   ]]--
			
		-- Add array to the data table.
		table.insert(self.regionTerrainCounts, regionCounts);
		
		--Activate printout only for debugging.
		print("-");
		print("--- Region Terrain Measurements for Region #", region_loop, "---");
		print("Total Plots: ", totalPlots);
		print("Area Plots: ", areaPlots);
		print("-");
		print("Mountains: ", peaksCount, " - Cannot belong to a landmass AreaID.");
		print("Total Water Plots: ", waterCount, " - Cannot belong to a landmass AreaID.");
		print("-");
		print("Lake Plots: ", lakeCount);
		print("Coast Plots: ", coastCount, " - Does not include Lakes.");
		print("Ocean Plots: ", oceanCount);
		print("Icebergs: ", iceCount);
		print("-");
		print("Flatlands: ", flatlandsCount);
		print("Hills: ", hillsCount);
		print("-");
		print("Grass Plots: ", grassCount);
		print("Plains Plots: ", plainsCount);
		print("Desert Plots: ", desertCount);
		print("Tundra Plots: ", tundraCount);
		print("Snow Plots: ", snowCount);
		print("-");
		print("Forest Plots: ", forestCount);
		print("Jungle Plots: ", jungleCount);
		print("Marsh Plots: ", marshCount);
		print("Flood Plains: ", floodplainCount);
		print("Oases: ", oasisCount);
		print("-");
		print("Plots Along Rivers: ", riverCount);
		print("Plots Along Oceans: ", coastalLandCount);
		print("Plots Next To Plots Along Oceans: ", nextToCoastCount);
		print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -");
		
	end
end
------------------------------------------------------------------------------
function AssignStartingPlots:DetermineRegionTypes()
	-- Determine region type and conditions. Use self.regionTypes to store the results
	--
	-- REGION TYPES
	-- 0. Undefined
	-- 1. Tundra
	-- 2. Jungle
	-- 3. Forest
	-- 4. Desert
	-- 5. Hills
	-- 6. Plains
	-- 7. Grassland
	-- 8. Hybrid
	-- 9. Marsh

	-- Main loop
	for this_region, terrainCounts in ipairs(self.regionTerrainCounts) do
		-- Set each region to "Undefined Type" as default.
		-- If all efforts fail at determining what type of region this should be, region type will remain Undefined.
		--local totalPlots = terrainCounts[1];
		local totalPlots = terrainCounts[1] ;
		local areaPlots = terrainCounts[2];
		local waterCount = terrainCounts[3];
		local flatlandsCount = terrainCounts[4];
		local hillsCount = terrainCounts[5];
		local peaksCount = terrainCounts[6];
		local lakeCount = terrainCounts[7];
		local coastCount = terrainCounts[8];
		local oceanCount = terrainCounts[9];
		local iceCount = terrainCounts[10];
		local grassCount = terrainCounts[11];
		local plainsCount = terrainCounts[12];
		local desertCount = terrainCounts[13];
		local tundraCount = terrainCounts[14];
		local snowCount = terrainCounts[15];
		local forestCount = terrainCounts[16];
		local jungleCount = terrainCounts[17];
		local marshCount = terrainCounts[18];
		local riverCount = terrainCounts[19];
		local floodplainCount = terrainCounts[20];
		local oasisCount = terrainCounts[21];
		local coastalLandCount = terrainCounts[22];
		local nextToCoastCount = terrainCounts[23];

		print("----------------------------------------------- REGION TYPE CHECKS START -----------------------------------------------");
		print("--- Region Terrain Measurements for Region #", this_region, "---");
		print("Total Plots: ", totalPlots);
		print("Area Plots: ", areaPlots);
		print("-");
		print("Mountains: ", peaksCount, " - Cannot belong to a landmass AreaID.");
		print("Total Water Plots: ", waterCount, " - Cannot belong to a landmass AreaID.");
		print("-");
		print("Lake Plots: ", lakeCount);
		print("Coast Plots: ", coastCount, " - Does not include Lakes.");
		print("Ocean Plots: ", oceanCount);
		print("Icebergs: ", iceCount);
		print("-");
		print("Flatlands: ", flatlandsCount);
		print("Hills: ", hillsCount);
		print("-");
		print("Grass Plots: ", grassCount);
		print("Plains Plots: ", plainsCount);
		print("Desert Plots: ", desertCount);
		print("Tundra Plots: ", tundraCount);
		print("Snow Plots: ", snowCount);
		print("-");
		print("Forest Plots: ", forestCount);
		print("Jungle Plots: ", jungleCount);
		print("Marsh Plots: ", marshCount);
		print("Flood Plains: ", floodplainCount);
		print("Oases: ", oasisCount);
		print("-");
		print("Plots Along Rivers: ", riverCount);
		print("Plots Along Oceans: ", coastalLandCount);
		print("Plots Next To Plots Along Oceans: ", nextToCoastCount);
		print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -");

		-- If Rectangular regional division, then water plots would be included in area plots.
		-- Let's recalculate area plots based only on flatland and hills plots.
		if self.method == 3 or self.method == 4 then
			areaPlots = flatlandsCount + hillsCount;
		end

		-- Tundra check first.
		if (tundraCount + snowCount) >= areaPlots * 0.10 then
			table.insert(self.regionTypes, 1);
			print("-");
			print("Region #", this_region, " has been defined as a Tundra Region.");
		
		-- Jungle check.
		elseif (jungleCount >= areaPlots * 0.12) then
			table.insert(self.regionTypes, 2);
			print("-");
			print("Region #", this_region, " has been defined as a Jungle Region.");
		elseif (jungleCount >= areaPlots * 0.10) and (jungleCount + forestCount >= areaPlots * 0.24) then
			table.insert(self.regionTypes, 2);
			print("-");
			print("Region #", this_region, " has been defined as a Jungle Region.");
		
		-- Forest check.
		elseif (forestCount >= areaPlots * 0.21) then
			table.insert(self.regionTypes, 3);
			print("-");
			print("Region #", this_region, " has been defined as a Forest Region.");
		elseif (forestCount >= areaPlots * 0.8) and (jungleCount + forestCount >= areaPlots * 0.3) then
			table.insert(self.regionTypes, 3);
			print("-");
			print("Region #", this_region, " has been defined as a Forest Region.");
		
		-- Desert check.
		elseif (desertCount >= areaPlots * 0.15) then
			table.insert(self.regionTypes, 4);
			print("-");
			print("Region #", this_region, " has been defined as a Desert Region.");
			
		-- Wetlands check.
		elseif ((marshCount) >= areaPlots * 0.11) or (marshCount >= 6) then
			table.insert(self.regionTypes, 9);
			print("-");
			print("Region #", this_region, " has been defined as a Wetlands Region.");
		-- Hills check.
		elseif (hillsCount >= areaPlots * 0.37) then
			table.insert(self.regionTypes, 5);
			print("-");
			print("Region #", this_region, " has been defined as a Hills Region.");
			
		-- Grass check.
		elseif (grassCount >= areaPlots * 0.20) and (grassCount * 0.7 > plainsCount) then
			table.insert(self.regionTypes, 7);
			print("-");
			print("Region #", this_region, " has been defined as a Grassland Region.");
		
		-- Plains check.
		elseif (plainsCount >= areaPlots * 0.27) and (plainsCount * 0.8 > grassCount) then
			table.insert(self.regionTypes, 6);
			print("-");
			print("Region #", this_region, " has been defined as a Plains Region.");
		-- Hybrid check.
		elseif ((grassCount + plainsCount + desertCount + tundraCount + snowCount + hillsCount + peaksCount) > areaPlots * 0.8) then
			table.insert(self.regionTypes, 8);
			print("-");
			print("Region #", this_region, " has been defined as a Hybrid Region.");

		else -- Undefined Region (most likely due to operating on a mod that adds new terrain types.)
			table.insert(self.regionTypes, 0);
			print("-");
			print("Region #", this_region, " has been defined as an Undefined Region.");
		
		end
	end

	--[[
	-- Main loop
	for this_region, terrainCounts in ipairs(self.regionTerrainCounts) do
		-- Set each region to "Undefined Type" as default.
		-- If all efforts fail at determining what type of region this should be, region type will remain Undefined.
		--local totalPlots = terrainCounts[1];
		local totalPlots = terrainCounts[1] ;
		local areaPlots = terrainCounts[2];
		local waterCount = terrainCounts[3];
		local flatlandsCount = terrainCounts[4];
		local hillsCount = terrainCounts[5];
		local peaksCount = terrainCounts[6];
		local lakeCount = terrainCounts[7];
		local coastCount = terrainCounts[8];
		local oceanCount = terrainCounts[9];
		local iceCount = terrainCounts[10];
		local grassCount = terrainCounts[11];
		local plainsCount = terrainCounts[12];
		local desertCount = terrainCounts[13];
		local tundraCount = terrainCounts[14];
		local snowCount = terrainCounts[15];
		local forestCount = terrainCounts[16];
		local jungleCount = terrainCounts[17];
		local marshCount = terrainCounts[18];
		local riverCount = terrainCounts[19];
		local floodplainCount = terrainCounts[20];
		local oasisCount = terrainCounts[21];
		local coastalLandCount = terrainCounts[22];
		local nextToCoastCount = terrainCounts[23];

		print("----------------------------------------------- REGION TYPE CHECKS START -----------------------------------------------");
		print("--- Region Terrain Measurements for Region #", this_region, "---");
		print("Total Plots: ", totalPlots);
		print("Area Plots: ", areaPlots);
		print("-");
		print("Mountains: ", peaksCount, " - Cannot belong to a landmass AreaID.");
		print("Total Water Plots: ", waterCount, " - Cannot belong to a landmass AreaID.");
		print("-");
		print("Lake Plots: ", lakeCount);
		print("Coast Plots: ", coastCount, " - Does not include Lakes.");
		print("Ocean Plots: ", oceanCount);
		print("Icebergs: ", iceCount);
		print("-");
		print("Flatlands: ", flatlandsCount);
		print("Hills: ", hillsCount);
		print("-");
		print("Grass Plots: ", grassCount);
		print("Plains Plots: ", plainsCount);
		print("Desert Plots: ", desertCount);
		print("Tundra Plots: ", tundraCount);
		print("Snow Plots: ", snowCount);
		print("-");
		print("Forest Plots: ", forestCount);
		print("Jungle Plots: ", jungleCount);
		print("Marsh Plots: ", marshCount);
		print("Flood Plains: ", floodplainCount);
		print("Oases: ", oasisCount);
		print("-");
		print("Plots Along Rivers: ", riverCount);
		print("Plots Along Oceans: ", coastalLandCount);
		print("Plots Next To Plots Along Oceans: ", nextToCoastCount);
		print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -");

		-- If Rectangular regional division, then water plots would be included in area plots.
		-- Let's recalculate area plots based only on flatland and hills plots.
		if self.method == 3 or self.method == 4 then
			areaPlots = flatlandsCount + hillsCount;
		end

		
			 MOD.Barathor: 
			 Totally revamped this entire function.
			 With the old method, very dominant conditions could be missed, resulting in mislabeled regions.
			 Now, a large decrementing value is added on to the base percentage requirements to filter out very dominant conditions first. 
		
	
		local found_region   = false
		-- MOD.Barathor: These are the minimum values
		local desert_percent 	= 0.30
		local tundra_percent 	= 0.30
		local jungle_percent 	= 0.30
		local forest_percent 	= 0.30
		local hills_percent  	= 0.30
		local wetlands_percent  = 0.30
		local plains_percent 	= 0.30
		local grass_percent  	= 0.30

		-- MOD.Barathor: This variable will decrement until a region is assigned; starts off very high.
		local adjustment     = 0.50
		
		-- MOD.Barathor: Decided to disable this part.
		
		-- MOD.Barathor: An additional value is applied to region types already chosen, to very slightly lessen the chances of choosing it again.
		for loop, region in ipairs(self.regionTypes) do
			if region == 4 then
				desert_percent = desert_percent + 0.05
			elseif region == 1 then
				tundra_percent = tundra_percent + 0.05
			elseif region == 2 then
				jungle_percent = jungle_percent + 0.05
			elseif region == 3 then
				forest_percent = forest_percent + 0.05
			elseif region == 5 then
				hills_percent = hills_percent + 0.05
			elseif region == 6 then
				plains_percent = plains_percent + 0.05
			elseif region == 7 then
				grass_percent = grass_percent + 0.05
			end
		end
		
		
		-- MOD.Barathor: Reordered condition checks and modified what some checks include.
		while found_region == false do
			-- Desert check.
			if (desertCount >= areaPlots * (desert_percent + adjustment)) then
				table.insert(self.regionTypes, 4)
				print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - -")
				print("Region #", this_region, " has been defined as a DESERT Region.")
				found_region = true
				
			-- Tundra check.
			elseif (tundraCount >= areaPlots * (tundra_percent + adjustment)) then
				table.insert(self.regionTypes, 1)
				print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - -")
				print("Region #", this_region, " has been defined as a TUNDRA Region.")
				found_region = true
				
			-- Jungle check.
			elseif (jungleCount >= areaPlots * (jungle_percent + adjustment)) then 
				table.insert(self.regionTypes, 2)
				print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - -")
				print("Region #", this_region, " has been defined as a JUNGLE Region.")
				found_region = true
				
			-- Forest check. 
			elseif (forestCount >= areaPlots * (forest_percent + adjustment)) and (tundraCount < areaPlots * tundra_percent) then
				table.insert(self.regionTypes, 3)
				print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - -")
				print("Region #", this_region, " has been defined as a FOREST Region.")
				found_region = true

			-- Wetlands check.
			elseif ((marshCount + floodplainCount) >= areaPlots * (wetlands_percent + adjustment)) or (floodplainCount >= 10) or (marshCount >= 8) then
				table.insert(self.regionTypes, 9);
				print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - -");
				print("Region #", this_region, " has been defined as a Wetlands Region.");
				found_region = true
			
			else
				if adjustment <= 0 then
					-- Plains check.
					if (plainsCount >= areaPlots * plains_percent) and (plainsCount * 0.8 > grassCount) then
						table.insert(self.regionTypes, 6)
						print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - -")
						print("Region #", this_region, " has been defined as a PLAINS Region.")
						found_region = true
					-- Grass check.
					elseif (grassCount >= areaPlots * grass_percent) and (grassCount * 0.8 > plainsCount) then
						table.insert(self.regionTypes, 7)
						print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - -")
						print("Region #", this_region, " has been defined as a GRASSLAND Region.")
						found_region = true
					
					-- Hills check.
					elseif (hillsCount >= areaPlots * hills_percent) then
						table.insert(self.regionTypes, 5)
						print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - -")
						print("Region #", this_region, " has been defined as a HILLS Region.")
						found_region = true

					else
						-- Hybrid: No conditions dominate or other mods have included new terrain/feature/plot types which aren't recognized here.
						table.insert(self.regionTypes, 8)
						print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - -")
						print("Region #", this_region, " has been defined as a HYBRID Region.")
						found_region = true
					end
				end
				adjustment = adjustment - 0.01
			end
		end
		
		-- MOD.Barathor: New data for very useful debug printouts.
		print("Threshold Values:")
		print(string.format("Desert: %.2f - Tundra: %.2f - Jungle: %.2f - Forest: %.2f - Hills: %.2f - Plains: %.2f - Grass: %.2f", desert_percent, tundra_percent, jungle_percent, forest_percent, hills_percent, plains_percent, grass_percent))		
		print("Region Values:")
		print(string.format("Desert: %.2f - Tundra: %.2f - Jungle: %.2f - Forest: %.2f - Hills: %.2f - Plains: %.2f - Grass: %.2f", desertCount / areaPlots, tundraCount / areaPlots, jungleCount / areaPlots, forestCount / areaPlots, hillsCount / areaPlots, plainsCount / areaPlots, grassCount / areaPlots))
		print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - -")	
	end
	]]
	--[[
		-- Tundra check first.
		if (tundraCount + snowCount) >= areaPlots * 0.15 then
			table.insert(self.regionTypes, 1);
			print("-");
			print("Region #", this_region, " has been defined as a Tundra Region.");
		
		-- Jungle check.
		elseif (jungleCount >= areaPlots * 0.17) then
			table.insert(self.regionTypes, 2);
			print("-");
			print("Region #", this_region, " has been defined as a Jungle Region.");
		elseif (jungleCount >= areaPlots * 0.15) and (jungleCount + forestCount >= areaPlots * 0.32) then
			table.insert(self.regionTypes, 2);
			print("-");
			print("Region #", this_region, " has been defined as a Jungle Region.");
		
		-- Forest check.
		elseif (forestCount >= areaPlots * 0.24) then
			table.insert(self.regionTypes, 3);
			print("-");
			print("Region #", this_region, " has been defined as a Forest Region.");
		elseif (forestCount >= areaPlots * 0.18) and (jungleCount + forestCount >= areaPlots * 0.32) then
			table.insert(self.regionTypes, 3);
			print("-");
			print("Region #", this_region, " has been defined as a Forest Region.");
		
		-- Desert check.
		elseif (desertCount >= areaPlots * 0.15) then
			table.insert(self.regionTypes, 4);
			print("-");
			print("Region #", this_region, " has been defined as a Desert Region.");
			
		-- Hills check.
		elseif (hillsCount >= areaPlots * 0.47) then
			table.insert(self.regionTypes, 5);
			print("-");
			print("Region #", this_region, " has been defined as a Hills Region.");
		
		-- Wetlands check.
		elseif ((marshCount + floodplainCount) >= areaPlots * 0.12) or (floodplainCount >= 8) or (marshCount >= 6) then
			table.insert(self.regionTypes, 9);
			print("-");
			print("Region #", this_region, " has been defined as a Wetlands Region.");

		-- Grass check.
		elseif (grassCount >= areaPlots * 0.25) and (grassCount * 0.7 > plainsCount) then
			table.insert(self.regionTypes, 7);
			print("-");
			print("Region #", this_region, " has been defined as a Grassland Region.");
		
		-- Plains check.
		elseif (plainsCount >= areaPlots * 0.35) and (plainsCount * 0.8 > grassCount) then
			table.insert(self.regionTypes, 6);
			print("-");
			print("Region #", this_region, " has been defined as a Plains Region.");
		-- Hybrid check.
		elseif ((grassCount + plainsCount + desertCount + tundraCount + snowCount + hillsCount + peaksCount) > areaPlots * 0.8) then
			table.insert(self.regionTypes, 8);
			print("-");
			print("Region #", this_region, " has been defined as a Hybrid Region.");

		else -- Undefined Region (most likely due to operating on a mod that adds new terrain types.)
			table.insert(self.regionTypes, 0);
			print("-");
			print("Region #", this_region, " has been defined as an Undefined Region.");
		
		end
	end
	--]]

end
------------------------------------------------------------------------------
function AssignStartingPlots:PlaceImpactAndRipples(x, y)
	-- This function operates upon the "impact and ripple" data overlays. This
	-- is the core version, which operates on start points. Resources and city 
	-- states have their own data layers, using this same design principle.
	-- Execution of this function handles a single start point (x, y).
	--[[ The purpose of the overlay is to strongly discourage placement of new
	     start points near already-placed start points. Each start placed makes
	     an "impact" on the map, and this impact "ripples" outward in rings, each
	     ring weaker in bias than the previous ring. ... Civ4 attempted to adjust
	     the minimum distance between civs according to a formula that factored
	     map size and number of civs in the game, but the formula was chock full 
	     of faulty assumptions, resulting in an accurate calibration rate of less
	     than ten percent. The failure of this approach is the primary reason 
	     that an all-new positioner was written for Civ5. ... Rather than repeat
	     the mistakes of the old system, in part or in whole, I have opted to go 
	     with a flat 9-tile impact crater for all map sizes and number of civs.
	     The new system will place civs at least 9 tiles away from other civs
	     whenever and wherever a reasonable candidate plot exists at this range. 
	     If a start must be found within that range, it will attempt to balance
	     quality of the location against proximity to another civ, with the bias
	     becoming very heavy inside 7 plots, and all but prohibitive inside 5.
	     The only starts that should see any Civs crowding together are those 
	     with impossible conditions such as cramming more than a dozen civs on 
	     to Tiny or Duel sized maps. ... The Impact and Ripple is aimed mostly
	     at assisting with Rectangular Method regional division on islands maps,
	     as the primary method of spacing civs is the Center Bias factor. The 
	     Impact and Ripple is a second layer of protection, for those rare cases
	     when regional shapes are severely distorted, with little to no land in
	     the region center, and the start having to be placed near the edge, and
	     for cases of extremely thin regional dimension.   ]]--
	-- To establish a bias of 9, we Impact the overlay and Ripple outward 8 times.
	-- Value of 0 in a plot means no influence from existing Impacts in that plot.
	-- Value of 99 means an Impact occurred in that plot and it IS a start point.
	-- Values > 0 and < 99 are "ripples", meaning that plot is near a start point.
	local iW, iH = Map.GetGridSize();
	local wrapX = Map:IsWrapX();
	local wrapY = Map:IsWrapY();
	local impact_value = 99;

	local ripple_decider = LekMapGetCustomOption(6);
	local ripple_values = {97, 95, 92, 88, 83, 77, 70, 62, 51, 41, 30, 18};	
	if ripple_decider == 1 then
		local ripple_values = {97, 95, 92, 89, 69, 57, 24, 15};
	end
	if ripple_decider == 2 then	
		local ripple_values = {97, 95, 92, 88, 83, 77, 70, 62, 51, 41, 30, 18};
	end
	if ripple_decider == 3 then	
		local ripple_values = {99, 98, 97, 89, 88, 83, 77, 70, 62, 51, 41, 30, 18, 12};
	end
	
	--local ripple_values = {99, 99, 99, 99, 99, 99};

	local odd = self.firstRingYIsOdd;
	local even = self.firstRingYIsEven;
	local nextX, nextY, plot_adjustments;
	local plot = Map.GetPlot(x, y);

	-- Start points need to impact the resource layers, so let's handle that first.
	self:PlaceResourceImpact(x, y, 1, 0) -- Strategic layer, at impact site only.
	self:PlaceResourceImpact(x, y, 2, 3) -- Luxury layer, set all plots within this civ start as off limits.
	self:PlaceResourceImpact(x, y, 3, 3) -- Bonus layer
	self:PlaceResourceImpact(x, y, 4, 3) -- Fish layer
	if plot:IsCoastalLand() then
		if self._lek_collide_coastals then
			self:PlaceResourceImpactCoastalMod(x, y, 5, 3, 4) -- MOD: SAPHT 10 range city state coastal
		else
			self:PlaceResourceImpact(x, y, 5, 5) -- Add CS layer with radius of 6 tiles
		end
	else
		self:PlaceResourceImpact(x, y, 5, 5) -- Add CS layer with radius of 6 tiles
	end

	self:PlaceResourceImpact(x, y, 6, 4) -- Natural Wonders layer, set a minimum distance of 5 plots (4 ripples) away.
	-- Now the main data layer, for start points themselves, and the City State data layer.
	-- Place Impact!
	local impactPlotIndex = y * iW + x + 1;
	self.distanceData[impactPlotIndex] = impact_value;
	self.playerCollisionData[impactPlotIndex] = true;
	self.cityStateData[impactPlotIndex] = 1;

	-- self.playerCoastalCollisionData[impactPlotIndex] = true
	-- Place Ripples
	for ripple_radius, ripple_value in ipairs(ripple_values) do
		-- Moving clockwise around the ring, the first direction to travel will be Northeast.
		-- This matches the direction-based data in the odd and even tables. Each
		-- subsequent change in direction will correctly match with these tables, too.
		--
		-- Locate the plot within this ripple ring that is due West of the Impact Plot.
		local currentX = x - ripple_radius;
		local currentY = y;
		-- Now loop through the six directions, moving ripple_radius number of times
		-- per direction. At each plot in the ring, add the ripple_value for that ring 
		-- to the plot's entry in the distance data table.
		for direction_index = 1, 6 do
			for plot_to_handle = 1, ripple_radius do
				-- Must account for hex factor.
			 	if currentY / 2 > math.floor(currentY / 2) then -- Current Y is odd. Use odd table.
					plot_adjustments = odd[direction_index];
				else -- Current Y is even. Use plot adjustments from even table.
					plot_adjustments = even[direction_index];
				end
				-- Identify the next plot in the ring.
				nextX = currentX + plot_adjustments[1];
				nextY = currentY + plot_adjustments[2];
				-- Make sure the plot exists
				if wrapX == false and (nextX < 0 or nextX >= iW) then -- X is out of bounds.
					-- Do not add ripple data to this plot.
				elseif wrapY == false and (nextY < 0 or nextY >= iH) then -- Y is out of bounds.
					-- Do not add ripple data to this plot.
				else -- Plot is in bounds, process it.
					-- Handle any world wrap.
					local realX = nextX;
					local realY = nextY;
					if wrapX then
						realX = realX % iW;
					end
					if wrapY then
						realY = realY % iH;
					end
					-- Record ripple data for this plot.
					local ringPlotIndex = realY * iW + realX + 1;
					if self.distanceData[ringPlotIndex] > 0 then -- This plot is already in range of at least one other civ!
						-- First choose the greater of the two, existing value or current ripple.
						local stronger_value = math.max(self.distanceData[ringPlotIndex], ripple_value);
						-- Now increase it by 1.2x to reflect that multiple civs are in range of this plot.
						local overlap_value = math.min(97, math.floor(stronger_value * 1.4));
						self.distanceData[ringPlotIndex] = overlap_value;
					else
						self.distanceData[ringPlotIndex] = ripple_value;
					end
					-- Now impact the City State layer if appropriate.
					if ripple_radius <= 6 then
						self.cityStateData[ringPlotIndex] = 1;
					end
				end
				currentX, currentY = nextX, nextY;
			end
		end
	end
end
------------------------------------------------------------------------------
function AssignStartingPlots:LekGlobalSix_ApplyDistanceRipplesForStartOnly(x, y)
	local iW, iH = Map.GetGridSize();
	local gridMax = iW * iH;
	if gridMax < 1 then
		return;
	end
	local wrapX = Map:IsWrapX();
	local wrapY = Map:IsWrapY();
	local impact_value = 99;
	local ripple_decider = 0;
	local okOpt, optVal = pcall(function()
		return LekMapGetCustomOption(6);
	end);
	if okOpt and type(optVal) == "number" then
		ripple_decider = optVal;
	end
	local ripple_values = {97, 95, 92, 88, 83, 77, 70, 62, 51, 41, 30, 18};
	if ripple_decider == 1 then
		ripple_values = {97, 95, 92, 89, 69, 57, 24, 15};
	elseif ripple_decider == 2 then
		ripple_values = {97, 95, 92, 88, 83, 77, 70, 62, 51, 41, 30, 18};
	elseif ripple_decider == 3 then
		ripple_values = {99, 98, 97, 89, 88, 83, 77, 70, 62, 51, 41, 30, 18, 12};
	end
	local odd = self.firstRingYIsOdd;
	local even = self.firstRingYIsEven;
	local nextX, nextY, plot_adjustments;
	local impactPlotIndex = y * iW + x + 1;
	if impactPlotIndex < 1 or impactPlotIndex > gridMax then
		return;
	end
	self.distanceData[impactPlotIndex] = impact_value;
	self.playerCollisionData[impactPlotIndex] = true;
	self.cityStateData[impactPlotIndex] = 1;
	for ripple_radius, ripple_value in ipairs(ripple_values) do
		local currentX = x - ripple_radius;
		local currentY = y;
		for direction_index = 1, 6 do
			for plot_to_handle = 1, ripple_radius do
				if currentY / 2 > math.floor(currentY / 2) then
					plot_adjustments = odd[direction_index];
				else
					plot_adjustments = even[direction_index];
				end
				nextX = currentX + plot_adjustments[1];
				nextY = currentY + plot_adjustments[2];
				if wrapX == false and (nextX < 0 or nextX >= iW) then
				elseif wrapY == false and (nextY < 0 or nextY >= iH) then
				else
					local realX = nextX;
					local realY = nextY;
					if wrapX then
						realX = realX % iW;
					end
					if wrapY then
						realY = realY % iH;
					end
					local ringPlotIndex = realY * iW + realX + 1;
					if ringPlotIndex >= 1 and ringPlotIndex <= gridMax then
						local prev = self.distanceData[ringPlotIndex] or 0;
						if prev > 0 then
							local stronger_value = math.max(prev, ripple_value);
							local overlap_value = math.min(97, math.floor(stronger_value * 1.4));
							self.distanceData[ringPlotIndex] = overlap_value;
						else
							self.distanceData[ringPlotIndex] = ripple_value;
						end
						if ripple_radius <= 6 then
							self.cityStateData[ringPlotIndex] = 1;
						end
					end
				end
				currentX, currentY = nextX, nextY;
			end
		end
	end
end
------------------------------------------------------------------------------
function AssignStartingPlots:MeasureSinglePlot(x, y, region_type, distance_from_city)
	local data = table.fill(false, 5);
	-- Note that "Food" is not strictly about tile yield.
	-- Different regions get their food in different ways.
	-- Tundra, Jungle, Forest, Desert, Plains regions will 
	-- get Bonus resource support to cover food shortages.
	--
	-- Data table entries hold results; all begin as false:
	-- [1] "Food"
	-- [2] "Prod"
	-- [3] "Good"
	-- [4] "Junk"
	-- [5] "Count Double" (For hills on city plot as production and snow as junk)
	local iW, iH = Map.GetGridSize();
	local plot = Map.GetPlot(x, y);
	local plotType = plot:GetPlotType()
	local terrainType = plot:GetTerrainType()
	local featureType = plot:GetFeatureType()
	
	if plotType == PlotTypes.PLOT_MOUNTAIN then -- Mountains are Junk
		data[4] = true;
		return data
	elseif plotType == PlotTypes.PLOT_OCEAN then
		if featureType == FeatureTypes.FEATURE_ICE then -- Icebergs are Junk.
			data[4] = true;
		elseif plot:IsLake() then -- Lakes are Food, not good.
			data[1] = true;
		elseif terrainType == TerrainTypes.TERRAIN_COAST then 
			data[1] = true;
			if self.method == 3 or self.method == 4 then -- Shallow water is Good for Archipelago-type maps.
				data[3] = true;
			end
		end
		-- Other water plots are ignored.
		return data
	end

	if featureType == FeatureTypes.FEATURE_JUNGLE and distance_from_city ~= 0 then -- Jungles are Food except in Grass regions and only Good in Jungle regions.
		if plotType == PlotTypes.PLOT_HILLS then -- Jungle hill count as Prod but not Good.
			data[2] = true;
		end
		if region_type ~= 7 then -- Region type is not Grass.
			data[1] = true;
			if region_type == 2 then -- Region type is jungle
				data[3] = true;
			end
		end
		return data
	elseif featureType == FeatureTypes.FEATURE_FOREST and distance_from_city ~= 0 then -- Forests are Prod, Good.
		data[2] = true;
		if plotType == PlotTypes.PLOT_HILLS then
			data[3] = true;
		else
			-- tile under forest is a flat land tile so must be food
			if terrainType ~= TerrainTypes.TERRAIN_TUNDRA then -- must be flat plains or grassland
				data[1] = true;
			end
		end

		return data
	elseif featureType == FeatureTypes.FEATURE_OASIS then -- Oases are Food, Good.
		data[1] = true;
		data[3] = true;
		return data
	elseif featureType == FeatureTypes.FEATURE_FLOOD_PLAINS then -- Flood Plains are Food, Good.
		data[1] = true;
		data[3] = true;
		return data
	elseif featureType == FeatureTypes.FEATURE_MARSH and distance_from_city ~= 0 then -- Marsh are ignored.
		
		-- marsh is good for wetlands region types
		if region_type == 9 then
			data[3] = true;
		else
			data[4] = true;
		end

		return data
	end

	if plotType == PlotTypes.PLOT_HILLS then -- Hills with no features are Prod, Good.
		data[2] = true;
		data[3] = true;
		return data
	end
	
	-- If we have reached this point in the process, the plot is flatlands.
	if terrainType == TerrainTypes.TERRAIN_SNOW then -- Snow are Junk.
		data[4] = true;
		data[5] = true;
		return data
		
	elseif terrainType == TerrainTypes.TERRAIN_DESERT then -- Non-Oasis, non-FloodPlain flat deserts are Junk (desert regions too).
		data[4] = true;
		return data

	elseif terrainType == TerrainTypes.TERRAIN_TUNDRA then -- Naked Tundra are Junk, except in Tundra Regions where they are Food
		if region_type == 1 then
			data[3] = true;
		else
			data[4] = true;
		end
		return data

	elseif terrainType == TerrainTypes.TERRAIN_PLAINS then -- Plains are Good for all region types, but Food in only non-Grassland.
		data[3] = true;
		if region_type == 1 or region_type == 4 or region_type == 5 or region_type == 6 or region_type == 8 then
			data[1] = true;
		end
		return data

	elseif terrainType == TerrainTypes.TERRAIN_GRASS then -- Grass is Food, Good for all region types.
		data[1] = true;
		data[3] = true;
		return data
	end

	-- If we have arrived here, the plot has non-standard terrain.
	print("Encountered non-standard terrain.");
	return data
end
------------------------------------------------------------------------------
function AssignStartingPlots:EvaluateCandidatePlot(plotIndex, region_type)
	-- Lekmap: exclude polarMerge + fjordPeninsula reserved plots; snow in EvaluateCandidatePlot below
	if _polar_merge_excluded_plots and _polar_merge_excluded_plots[plotIndex] then
		return 0, false;
	end
	if _fjord_peninsula_excluded_plots and _fjord_peninsula_excluded_plots[plotIndex] then
		return 0, false;
	end
	local iW, iH = Map.GetGridSize();
	local x = (plotIndex - 1) % iW;
	local y = (plotIndex - x - 1) / iW;
	local distFromEdge = math.min(y, iH - 1 - y);
	if distFromEdge < 8 then
		return 0, false;
	end
	local plot = Map.GetPlot(x, y);
	if plot and plot:GetTerrainType() == TerrainTypes.TERRAIN_SNOW then
		return 0, false;
	end
	--[[ Lekmap: map-center distance (was used for optional finalScore penalties; global OK will own geometry.)
	local centerX = math.floor(iW / 2);
	local centerY = math.floor(iH / 2);
	local dCenter = nil;
	if Map.PlotDistance then
		dCenter = Map.PlotDistance(x, y, centerX, centerY);
	elseif PlotDistance then
		dCenter = PlotDistance(x, y, centerX, centerY);
	end
	local tooCloseToCenter = (dCenter ~= nil and dCenter < 8);
	--]]
	local goodSoFar = true;
	local isEvenY = true;
	if y / 2 > math.floor(y / 2) then
		isEvenY = false;
	end
	local wrapX = Map:IsWrapX();
	local wrapY = Map:IsWrapY();
	local distance_bias = self.distanceData[plotIndex];
	local adjacentMountainCount = 0;
	local foodTotal, prodTotal, goodTotal, junkTotal, riverTotal, coastScore = 0, 0, 0, 0, 0, 0;
	local search_table = {};
	
	-- Check candidate plot to see if it's adjacent to saltwater.
	if self.plotDataIsCoastal[plotIndex] == true then
		coastScore = 40;
	end
		
	-- Check candidate plot for hills and river
	local innerRingScore = 0;
	local result = self:MeasureSinglePlot(x, y, region_type, 0)
	if result[2] then
		innerRingScore = innerRingScore + 4;
		if result[5] then
			innerRingScore = innerRingScore + 4;
		end
	end
	if result[3] then
		goodTotal = goodTotal + 1;
		if result[5] then
			goodTotal = goodTotal + 1;
		end
	end
	if plot:IsRiverSide() or plot:IsFreshWater() then
		riverTotal = riverTotal + 4;
	end
		
	-- Evaluate First Ring
	if isEvenY then
		search_table = self.firstRingYIsEven;
	else
		search_table = self.firstRingYIsOdd;
	end

	for loop, plot_adjustments in ipairs(search_table) do
		local searchX, searchY;
		if wrapX then
			searchX = (x + plot_adjustments[1]) % iW;
		else
			searchX = x + plot_adjustments[1];
		end
		if wrapY then
			searchY = (y + plot_adjustments[2]) % iH;
		else
			searchY = y + plot_adjustments[2];
		end
		--
		if searchX < 0 or searchX >= iW or searchY < 0 or searchY >= iH then
			-- This plot does not exist. It's off the map edge.
			junkTotal = junkTotal + 1;
		else
			local searchPlot = Map.GetPlot(searchX, searchY);
			local result = self:MeasureSinglePlot(searchX, searchY, region_type, 1)
			if result[4] then
				junkTotal = junkTotal + 1;
				if searchPlot:GetPlotType() == PlotTypes.PLOT_MOUNTAIN and adjacentMountainCount == 0 then
					--junkTotal = junkTotal - 1;
					adjacentMountainCount = adjacentMountainCount + 1;
				elseif result[5] then
					junkTotal = junkTotal + 1;
				end
			else
				if result[1] then
					foodTotal = foodTotal + 1;
					if result[5] then
						foodTotal = foodTotal + 1;
					end
				end
				if result[2] then
					prodTotal = prodTotal + 1;
					if result[5] then
						prodTotal = prodTotal + 1;
					end
				end
				if result[3] then
					goodTotal = goodTotal + 1;
					if result[5] then
						goodTotal = goodTotal + 1;
					end
				end
				if searchPlot:IsRiverSide() or plot:IsFreshWater() then
					riverTotal = riverTotal + 2;
				end
			end
		end
	end

	-- Now check the results from the first ring against the established targets.
	if foodTotal < self.minFoodInner then
		goodSoFar = false;
	elseif prodTotal < self.minProdInner then
		goodSoFar = false;
	elseif goodTotal < self.minGoodInner then
		goodSoFar = false;
	end

	-- Set up the "score" for this candidate. Inner ring results weigh the heaviest.
	local weightedFoodInner = {0, 8, 14, 19, 22, 24, 25};
	local foodResultInner = weightedFoodInner[foodTotal + 1];
	local weightedProdInner = {0, 10, 16, 20, 20, 12, 0};
	local prodResultInner = weightedProdInner[prodTotal + 1];
	local goodResultInner = goodTotal * 2;
	innerRingScore = innerRingScore + foodResultInner + prodResultInner + goodResultInner + riverTotal - (junkTotal * 3);
	
	-- Evaluate Second Ring
	if isEvenY then
		search_table = self.secondRingYIsEven;
	else
		search_table = self.secondRingYIsOdd;
	end

	for loop, plot_adjustments in ipairs(search_table) do
		local searchX, searchY;
		if wrapX then
			searchX = (x + plot_adjustments[1]) % iW;
		else
			searchX = x + plot_adjustments[1];
		end
		if wrapY then
			searchY = (y + plot_adjustments[2]) % iH;
		else
			searchY = y + plot_adjustments[2];
		end
		if searchX < 0 or searchX >= iW or searchY < 0 or searchY >= iH then
			-- This plot does not exist. It's off the map edge.
			junkTotal = junkTotal + 1;
		else
			local result = self:MeasureSinglePlot(searchX, searchY, region_type, 2)
			if result[4] then
				junkTotal = junkTotal + 1;
				if result[5] then
					junkTotal = junkTotal + 1;
				end
			else
				if result[1] then
					foodTotal = foodTotal + 1;
					if result[5] then
						foodTotal = foodTotal + 1;
					end
				end
				if result[2] then
					prodTotal = prodTotal + 1;
					if result[5] then
						prodTotal = prodTotal + 1;
					end
				end
				if result[3] then
					goodTotal = goodTotal + 1;
					if result[5] then
						goodTotal = goodTotal + 1;
					end
				end
				local searchPlot = Map.GetPlot(searchX, searchY);
				if searchPlot:IsRiverSide() or plot:IsFreshWater() then
					riverTotal = riverTotal + 2;
				end
			end
		end
	end

	-- Check the results from the second ring against the established targets.
	if foodTotal < self.minFoodMiddle then
		goodSoFar = false;
	elseif prodTotal < self.minProdMiddle then
		goodSoFar = false;
	elseif goodTotal < self.minGoodMiddle then
		goodSoFar = false;
	end
	
	-- Update up the "score" for this candidate. Middle ring results weigh significantly.
	local weightedFoodMiddle = {0, 2, 5, 10, 20, 25, 28, 30, 32, 34, 35}; -- 35 for any further values.
	local foodResultMiddle = 35;
	if foodTotal < 10 then
		foodResultMiddle = weightedFoodMiddle[foodTotal + 1];
	end
	local weightedProdMiddle = {0, 10, 20, 25, 30, 35}; -- 35 for any further values.
	local effectiveProdTotal = prodTotal;
	if foodTotal * 2 < prodTotal then
		effectiveProdTotal = math.ceil(foodTotal / 2);
	end
	local prodResultMiddle = 35;
	if effectiveProdTotal < 5 then
		prodResultMiddle = weightedProdMiddle[effectiveProdTotal + 1];
	end
	local goodResultMiddle = goodTotal * 2;
	local middleRingScore = foodResultMiddle + prodResultMiddle + goodResultMiddle + riverTotal - (junkTotal * 3);
	
	-- Evaluate Third Ring
	if isEvenY then
		search_table = self.thirdRingYIsEven;
	else
		search_table = self.thirdRingYIsOdd;
	end

	for loop, plot_adjustments in ipairs(search_table) do
		local searchX, searchY;
		if wrapX then
			searchX = (x + plot_adjustments[1]) % iW;
		else
			searchX = x + plot_adjustments[1];
		end
		if wrapY then
			searchY = (y + plot_adjustments[2]) % iH;
		else
			searchY = y + plot_adjustments[2];
		end
		if searchX < 0 or searchX >= iW or searchY < 0 or searchY >= iH then
			-- This plot does not exist. It's off the map edge.
			junkTotal = junkTotal + 1;
		else
			local result = self:MeasureSinglePlot(searchX, searchY, region_type, 3)
			if result[4] then
				junkTotal = junkTotal + 1;
				if result[5] then
					junkTotal = junkTotal + 1;
				end
			else
				if result[1] then
					foodTotal = foodTotal + 1;
					if result[5] then
						foodTotal = foodTotal + 1;
					end
				end
				if result[2] then
					prodTotal = prodTotal + 1;
					if result[5] then
						prodTotal = prodTotal + 1;
					end
				end
				if result[3] then
					goodTotal = goodTotal + 1;
					if result[5] then
						goodTotal = goodTotal + 1;
					end
				end
				local searchPlot = Map.GetPlot(searchX, searchY);
				if searchPlot:IsRiverSide() or plot:IsFreshWater() then
					riverTotal = riverTotal + 2;
				end
			end
		end
	end

	-- Check the results from the third ring against the established targets.
	if foodTotal < self.minFoodOuter then
		goodSoFar = false;
	elseif prodTotal < self.minProdOuter then
		goodSoFar = false;
	elseif goodTotal < self.minGoodOuter then
		goodSoFar = false;
	end
	if junkTotal > self.maxJunk then
		goodSoFar = false;
	end

	-- Tally the final "score" for this candidate.
	local outerRingScore = foodTotal + prodTotal + goodTotal + riverTotal - (junkTotal * 2);
	local finalScore = innerRingScore + middleRingScore + outerRingScore + coastScore;

	--[[ Lekmap placement cleanup (spec v0.3): optional finalScore steering disabled so ranking
	    does not fight future global OK() hard checks (map-centre d in 9..18, inland salt). Re-enable
	    for local experiments only.
	local saltSeaAdj = 0;
	do
		local adjDirs = {
			DirectionTypes.DIRECTION_NORTHEAST,
			DirectionTypes.DIRECTION_EAST,
			DirectionTypes.DIRECTION_SOUTHEAST,
			DirectionTypes.DIRECTION_SOUTHWEST,
			DirectionTypes.DIRECTION_WEST,
			DirectionTypes.DIRECTION_NORTHWEST
		};
		for _, di in ipairs(adjDirs) do
			local np = Map.PlotDirection(x, y, di);
			if np and np:IsWater() and not np:IsLake() then
				saltSeaAdj = saltSeaAdj + 1;
			end
		end
	end
	finalScore = finalScore - saltSeaAdj * 3;

	if tooCloseToCenter then
		finalScore = finalScore - 10000;
	end
	if dCenter ~= nil then
		if dCenter > 21 then
			finalScore = finalScore - 12000;
		elseif dCenter > 18 then
			finalScore = finalScore - 5500;
		end
	end
	--]]

	-- Check Impact and Ripple data to see if candidate is near an already-placed start point.
	if distance_bias > 0 then
		-- This candidate is near an already placed start. This invalidates its 
		-- eligibility for first-pass placement; but it may still qualify as a 
		-- fallback site, so we will reduce its Score according to the bias factor.
		goodSoFar = false;
		finalScore = finalScore - math.floor(finalScore * distance_bias / 100);
	end

	--[[ Debug
	print(".");
	print("Plot:", x, y, " Food:", foodTotal, "Prod: ", prodTotal, "Good:", goodTotal, "Junk:", 
	       junkTotal, "River:", riverTotal, "Score:", finalScore);
	print("Plot:", x, y, " Coastal:", self.plotDataIsCoastal[plotIndex], "Distance Bias:", distance_bias);
	]]--
	
	return finalScore, goodSoFar
end
------------------------------------------------------------------------------
function AssignStartingPlots:IterateThroughCandidatePlotList(plot_list, region_type)
	-- Iterates through a list of candidate plots.
	-- Each plot is identified by its global plot index.
	-- This function assumes all candidate plots can have a city built on them.
	-- Any plots not allowed to have a city should be weeded out when building the candidate list.
	local found_eligible = false;
	local bestPlotScore = -math.huge;
	local bestPlotIndex;
	local found_fallback = false;
	local bestFallbackScore = -math.huge;
	local bestFallbackIndex;
	-- Process list of candidate plots.
	for loop, plotIndex in ipairs(plot_list) do
		local score, meets_minimums = self:EvaluateCandidatePlot(plotIndex, region_type)
		-- Test current plot against best known plot.
		if meets_minimums == true then
			found_eligible = true;
			if score > bestPlotScore then
				bestPlotScore = score;
				bestPlotIndex = plotIndex;
			end
		else
			found_fallback = true;
			if score > bestFallbackScore then
				bestFallbackScore = score;
				bestFallbackIndex = plotIndex;
			end
		end
	end
	-- returns table containing six variables: boolean, integer, integer, boolean, integer, integer
	local election_results = {found_eligible, bestPlotScore, bestPlotIndex, found_fallback, bestFallbackScore, bestFallbackIndex};
	return election_results
end
------------------------------------------------------------------------------
-- Vanilla HB-style scan with center/middle/outer tier bookkeeping (same plot set as full rectangle).
-- Global-six tuple search uses LekGlobalSix_GatherTupleStyleCandidateIndices + map-centre ring sort instead.
function AssignStartingPlots:LekGlobalSix_GatherRawFindStartStyleCandidateIndices(region_number, NoCoast)
	local region_data_table = self.regionData[region_number];
	if not region_data_table then
		return {};
	end
	local iW, iH = Map.GetGridSize();
	local iWestX = region_data_table[1];
	local iSouthY = region_data_table[2];
	local iWidth = region_data_table[3];
	local iHeight = region_data_table[4];
	local iAreaID = region_data_table[5];
	local fCenterWidth = (self.centerBias / 100) * iWidth;
	local iNonCenterWidth = math.floor((iWidth - fCenterWidth) / 2);
	local iCenterWidth = iWidth - (iNonCenterWidth * 2);
	local iCenterWestX = (iWestX + iNonCenterWidth) % iW;
	local iCenterTestWestX = (iWestX + iNonCenterWidth);
	local iCenterTestEastX = (iCenterWestX + iCenterWidth - 1);
	local fCenterHeight = (self.centerBias / 100) * iHeight;
	local iNonCenterHeight = math.floor((iHeight - fCenterHeight) / 2);
	local iCenterHeight = iHeight - (iNonCenterHeight * 2);
	local iCenterSouthY = (iSouthY + iNonCenterHeight) % iH;
	local iCenterTestSouthY = (iSouthY + iNonCenterHeight);
	local iCenterTestNorthY = (iCenterTestSouthY + iCenterHeight - 1);
	local fMiddleWidth = (self.middleBias / 100) * iWidth;
	local iOuterWidth = math.floor((iWidth - fMiddleWidth) / 2);
	local iMiddleWidth = iWidth - (iOuterWidth * 2);
	local iMiddleWestX = (iWestX + iOuterWidth) % iW;
	local iMiddleTestWestX = (iWestX + iOuterWidth);
	local iMiddleTestEastX = (iMiddleTestWestX + iMiddleWidth - 1);
	local fMiddleHeight = (self.middleBias / 100) * iHeight;
	local iOuterHeight = math.floor((iHeight - fMiddleHeight) / 2);
	local iMiddleHeight = iHeight - (iOuterHeight * 2);
	local iMiddleSouthY = (iSouthY + iOuterHeight) % iH;
	local iMiddleTestSouthY = (iSouthY + iOuterHeight);
	local iMiddleTestNorthY = (iMiddleTestSouthY + iMiddleHeight - 1);
	local seen = {};
	for region_y = 0, iHeight - 1 do
		for region_x = 0, iWidth - 1 do
			local x = (region_x + iWestX) % iW;
			local y = (region_y + iSouthY) % iH;
			local plotIndex = y * iW + x + 1;
			local plot = Map.GetPlot(x, y);
			if plot then
				local plotType = plot:GetPlotType();
				if plotType == PlotTypes.PLOT_HILLS or plotType == PlotTypes.PLOT_LAND then
					if self.plotDataIsNextToCoast[plotIndex] == true then
					elseif self.plotDataIsThreeFromCoast[plotIndex] == true then
					else
						local area_of_plot = plot:GetArea();
						if area_of_plot == iAreaID or iAreaID == -1 then
							local test_x = region_x + iWestX;
							local test_y = region_y + iSouthY;
							local function tryMark()
								if NoCoast == true and self.plotDataIsCoastal[plotIndex] == true then
									return;
								end
								if self.plotDataIsCoastal[plotIndex] == true then
									if not (self.AllowInlandSea == 1 or plot:IsCoastalLand(300)) then
										return;
									end
								end
								seen[plotIndex] = true;
							end
							if (test_x >= iCenterTestWestX and test_x <= iCenterTestEastX) and
							   (test_y >= iCenterTestSouthY and test_y <= iCenterTestNorthY) then
								tryMark();
							elseif (test_x >= iMiddleTestWestX and test_x <= iMiddleTestEastX) and
							       (test_y >= iMiddleTestSouthY and test_y <= iMiddleTestNorthY) then
								tryMark();
							else
								tryMark();
							end
						end
					end
				end
			end
		end
	end
	local list = {};
	for pi in pairs(seen) do
		list[#list + 1] = pi;
	end
	table.sort(list);
	return list;
end

-- Global-six tuple path: same land/area/coast filters as GatherRawFindStartStyleCandidateIndices
-- but scans the full region rectangle without center/middle/outer tier scheduling (spec: ideal map-centre
-- ring ordering is applied in GatherSearchCandidatesOrdered, not HB FindStart donuts).
function AssignStartingPlots:LekGlobalSix_GatherTupleStyleCandidateIndices(region_number, NoCoast)
	local region_data_table = self.regionData[region_number];
	if not region_data_table then
		return {};
	end
	local iW, iH = Map.GetGridSize();
	local iWestX = region_data_table[1];
	local iSouthY = region_data_table[2];
	local iWidth = region_data_table[3];
	local iHeight = region_data_table[4];
	local iAreaID = region_data_table[5];
	local seen = {};
	for region_y = 0, iHeight - 1 do
		for region_x = 0, iWidth - 1 do
			local x = (region_x + iWestX) % iW;
			local y = (region_y + iSouthY) % iH;
			local plotIndex = y * iW + x + 1;
			local plot = Map.GetPlot(x, y);
			if plot then
				local plotType = plot:GetPlotType();
				if plotType == PlotTypes.PLOT_HILLS or plotType == PlotTypes.PLOT_LAND then
					if self.plotDataIsNextToCoast[plotIndex] == true then
					elseif self.plotDataIsThreeFromCoast[plotIndex] == true then
					else
						local area_of_plot = plot:GetArea();
						if area_of_plot == iAreaID or iAreaID == -1 then
							if not (NoCoast == true and self.plotDataIsCoastal[plotIndex] == true) then
								if self.plotDataIsCoastal[plotIndex] == true then
									if self.AllowInlandSea == 1 or plot:IsCoastalLand(300) then
										seen[plotIndex] = true;
									end
								else
									seen[plotIndex] = true;
								end
							end
						end
					end
				end
			end
		end
	end
	local list = {};
	for pi in pairs(seen) do
		list[#list + 1] = pi;
	end
	table.sort(list);
	return list;
end

function AssignStartingPlots:LekGlobalSix_CountRawFindStartStyleCandidates(region_number, NoCoast)
	return #AssignStartingPlots.LekGlobalSix_GatherTupleStyleCandidateIndices(self, region_number, NoCoast);
end

function AssignStartingPlots:LekGlobalSix_CountEvaluateMeetsMinInRawPool(region_number, NoCoast)
	local list = AssignStartingPlots.LekGlobalSix_GatherTupleStyleCandidateIndices(self, region_number, NoCoast);
	local rawCount = #list;
	local rt = self.regionTypes[region_number];
	if not rt or rawCount == 0 then
		return 0, rawCount;
	end
	local pass = 0;
	for i = 1, rawCount do
		local plotIndex = list[i];
		local savedDD = self.distanceData[plotIndex];
		self.distanceData[plotIndex] = 0;
		local score, meetsMin = self:EvaluateCandidatePlot(plotIndex, rt);
		self.distanceData[plotIndex] = savedDD;
		if meetsMin then
			pass = pass + 1;
		end
	end
	return pass, rawCount;
end
------------------------------------------------------------------------------
function AssignStartingPlots:LekGlobalSix_LogRippleOrderedSampleDryRun()
	if self.iNumCivs ~= 6 then
		return;
	end
	local rid = tostring(_lek_run_id or "na");
	local iW, iH = Map.GetGridSize();
	local gridCells = iW * iH;
	local snapDD = {};
	local snapPC = {};
	local snapCS = {};
	for i = 1, gridCells do
		snapDD[i] = self.distanceData[i];
		snapPC[i] = self.playerCollisionData[i];
		snapCS[i] = self.cityStateData[i];
	end
	local snapSP = {};
	for r = 1, 6 do
		local t = self.startingPlots[r];
		snapSP[r] = t and { t[1], t[2], t[3] } or nil;
	end
	for r = 1, 6 do
		self.startingPlots[r] = nil;
	end
	local function restoreAll()
		for i = 1, gridCells do
			self.distanceData[i] = snapDD[i];
			self.playerCollisionData[i] = snapPC[i];
			self.cityStateData[i] = snapCS[i];
		end
		for r = 1, 6 do
			self.startingPlots[r] = snapSP[r];
		end
	end
	local pickLine = {};
	local failPick = nil;
	for r = 1, 6 do
		local list = AssignStartingPlots.LekGlobalSix_GatherTupleStyleCandidateIndices(self, r, false);
		local rt = self.regionTypes[r];
		if not rt then
			failPick = "nil_regionType_r=" .. tostring(r);
			break;
		end
		local elig = {};
		for i = 1, #list do
			local plotIndex = list[i];
			local bias = self.distanceData[plotIndex];
			if not (bias and bias > 0) then
				local score, meetsMin = self:EvaluateCandidatePlot(plotIndex, rt);
				if meetsMin then
					elig[#elig + 1] = plotIndex;
				end
			end
		end
		if #elig == 0 then
			failPick = "no_eligible_plot_r=" .. tostring(r);
			break;
		end
		local pickIdx = 1 + Map.Rand(#elig, "LekGlobalSixRippleDryRun");
		local plotIndex = elig[pickIdx];
		local x = (plotIndex - 1) % iW;
		local y = (plotIndex - x - 1) / iW;
		self.startingPlots[r] = { x, y, 0 };
		pickLine[#pickLine + 1] = string.format("%d@%d,%d", r, x, y);
		self:LekGlobalSix_ApplyDistanceRipplesForStartOnly(x, y);
	end
	if failPick then
		restoreAll();
		LekPlacementProbeAt(2, "### LekGlobalSix rippleOrderDryRun runId=" .. rid ..
			" mode=rippleOnlyNoResourceImpact status=in_order_pick_failed " .. failPick);
		return;
	end
	local R = AssignStartingPlots.LekGlobalSix_OK_RunAll(self);
	restoreAll();
	LekPlacementProbeAt(2, "### LekGlobalSix rippleOrderDryRun runId=" .. rid ..
		" mode=rippleOnlyNoResourceImpact status=complete order=r123456 randomAmongEligPerRegion=1" ..
		" picks=" .. table.concat(pickLine, ";") ..
		" first_fail=" .. tostring(R.first_fail or "none") ..
		" all_hard_pass=" .. (R.all_hard_pass and "1" or "0"));
end
------------------------------------------------------------------------------
function AssignStartingPlots:LekErrorIfLegacyForbidForcedCorner(region_number, where)
	if self._lek_legacy_forbid_forced_start_placement ~= true then
		return;
	end
	local rid = tostring(_lek_run_id or "na");
	LekPlacementProbeLog("### LekGlobalSix FATAL runId=" .. rid ..
		" legacy_forced_SW_corner_blocked region=" .. tostring(region_number) ..
		" where=" .. tostring(where));
	error("Lekmap: start placement for region " .. tostring(region_number) .. " failed (" .. tostring(where) ..
		"). Tuple solver already rejected this map; legacy HB would force the region rectangle SW corner. " ..
		"Typical causes: no plot meets min inner/middle food-prod-good thresholds after ripples, coastal count too low for a coastal-bias region, " ..
		"or areaID mismatch. Regenerate, use Capital Precision Fast (Legacy-only), or relax/disable start bias.");
end
------------------------------------------------------------------------------
function AssignStartingPlots:FindStart(region_number, NoCoast)
	
	print("No Coast: ", NoCoast);
	
	-- This function attempts to choose a start position for a single region.
	-- This function returns two boolean flags, indicating the success level of the operation.
	local bSuccessFlag = false; -- Returns true when a start is placed, false when process fails.
	local bForcedPlacementFlag = false; -- Returns true if this region had no eligible starts and one was forced to occur.

	-- Obtain data needed to process this region.
	local iW, iH = Map.GetGridSize();
	local region_data_table = self.regionData[region_number];
	local iWestX = region_data_table[1];
	local iSouthY = region_data_table[2];
	local iWidth = region_data_table[3];
	local iHeight = region_data_table[4];
	local iAreaID = region_data_table[5];
	local iMembershipEastX = iWestX + iWidth - 1;
	local iMembershipNorthY = iSouthY + iHeight - 1;
	--
	local terrainCounts = self.regionTerrainCounts[region_number];
	--
	local region_type = self.regionTypes[region_number];
	-- Done setting up region data.
	-- Set up contingency.
	local fallback_plots = {};
	
	-- Establish scope of center bias.
	local fCenterWidth = (self.centerBias / 100) * iWidth;
	local iNonCenterWidth = math.floor((iWidth - fCenterWidth) / 2)
	local iCenterWidth = iWidth - (iNonCenterWidth * 2);
	local iCenterWestX = (iWestX + iNonCenterWidth) % iW; -- Modulo math to synch coordinate to actual map in case of world wrap.
	local iCenterTestWestX = (iWestX + iNonCenterWidth); -- "Test" values ignore world wrap for easier membership testing.
	local iCenterTestEastX = (iCenterWestX + iCenterWidth - 1);

	local fCenterHeight = (self.centerBias / 100) * iHeight;
	local iNonCenterHeight = math.floor((iHeight - fCenterHeight) / 2)
	local iCenterHeight = iHeight - (iNonCenterHeight * 2);
	local iCenterSouthY = (iSouthY + iNonCenterHeight) % iH;
	local iCenterTestSouthY = (iSouthY + iNonCenterHeight);
	local iCenterTestNorthY = (iCenterTestSouthY + iCenterHeight - 1);

	-- Establish scope of "middle donut", outside the center but inside the outer.
	local fMiddleWidth = (self.middleBias / 100) * iWidth;
	local iOuterWidth = math.floor((iWidth - fMiddleWidth) / 2)
	local iMiddleWidth = iWidth - (iOuterWidth * 2);
	local iMiddleWestX = (iWestX + iOuterWidth) % iW;
	local iMiddleTestWestX = (iWestX + iOuterWidth);
	local iMiddleTestEastX = (iMiddleTestWestX + iMiddleWidth - 1);

	local fMiddleHeight = (self.middleBias / 100) * iHeight;
	local iOuterHeight = math.floor((iHeight - fMiddleHeight) / 2)
	local iMiddleHeight = iHeight - (iOuterHeight * 2);
	local iMiddleSouthY = (iSouthY + iOuterHeight) % iH;
	local iMiddleTestSouthY = (iSouthY + iOuterHeight);
	local iMiddleTestNorthY = (iMiddleTestSouthY + iMiddleHeight - 1); 

	-- Assemble candidates lists.
	local two_plots_from_ocean = {};
	local three_plots_from_ocean = {};
	local center_candidates = {};
	local center_river = {};
	local center_coastal = {};
	local center_inland_dry = {};
	local middle_candidates = {};
	local middle_river = {};
	local middle_coastal = {};
	local middle_inland_dry = {};
	local outer_plots = {};
	
	-- Identify candidate plots.
	for region_y = 0, iHeight - 1 do -- When handling global plot indices, process Y first.
		for region_x = 0, iWidth - 1 do
			local x = (region_x + iWestX) % iW; -- Actual coords, adjusted for world wrap, if any.
			local y = (region_y + iSouthY) % iH; --
			local plotIndex = y * iW + x + 1;
			local plot = Map.GetPlot(x, y);
			local plotType = plot:GetPlotType()
			if plotType == PlotTypes.PLOT_HILLS or plotType == PlotTypes.PLOT_LAND then -- Could host a city.
				-- Check if plot is two away from salt water.
				if self.plotDataIsNextToCoast[plotIndex] == true then
					table.insert(two_plots_from_ocean, plotIndex);
				elseif self.plotDataIsThreeFromCoast[plotIndex] == true then
					table.insert(three_plots_from_ocean, plotIndex);
				else
					local area_of_plot = plot:GetArea();
					if area_of_plot == iAreaID or iAreaID == -1 then -- This plot is a member, so it goes on at least one candidate list.
						--
						-- Test whether plot is in center bias, middle donut, or outer donut.
						--
						local test_x = region_x + iWestX; -- "Test" coords, ignoring any world wrap and
						local test_y = region_y + iSouthY; -- reaching in to virtual space if necessary.
						if (test_x >= iCenterTestWestX and test_x <= iCenterTestEastX) and 
						   (test_y >= iCenterTestSouthY and test_y <= iCenterTestNorthY) then -- Center Bias.
							
							if NoCoast == true and self.plotDataIsCoastal[plotIndex] == true then
								-- do nothing
							elseif plot:IsRiverSide() then
								table.insert(center_river, plotIndex);
								table.insert(center_candidates, plotIndex);
							elseif plot:IsFreshWater() or self.plotDataIsCoastal[plotIndex] == true then
								table.insert(center_coastal, plotIndex);
								table.insert(center_candidates, plotIndex);
							else
								table.insert(center_inland_dry, plotIndex);
								table.insert(center_candidates, plotIndex);
							end
							
						elseif (test_x >= iMiddleTestWestX and test_x <= iMiddleTestEastX) and 
						       (test_y >= iMiddleTestSouthY and test_y <= iMiddleTestNorthY) then
							
							if NoCoast == true and self.plotDataIsCoastal[plotIndex] == true then
								--do nothing
							elseif plot:IsRiverSide() then
								table.insert(middle_river, plotIndex);
								table.insert(middle_candidates, plotIndex);
							elseif plot:IsFreshWater() or self.plotDataIsCoastal[plotIndex] == true then
								table.insert(middle_coastal, plotIndex);
								table.insert(middle_candidates, plotIndex);
							else
								table.insert(middle_inland_dry, plotIndex);
								table.insert(middle_candidates, plotIndex);
							end
						else
							if NoCoast == true and self.plotDataIsCoastal[plotIndex] == true then
								--do nothing
							else
								table.insert(outer_plots, plotIndex);
							end
						end
					end
				end
			end
		end
	end

	
	-- Check how many plots landed on each list.
	local iNumDisqualified = table.maxn(two_plots_from_ocean) + table.maxn(three_plots_from_ocean);
	local iNumCenter = table.maxn(center_candidates);
	local iNumCenterRiver = table.maxn(center_river);
	local iNumCenterCoastLake = table.maxn(center_coastal);
	local iNumCenterInlandDry = table.maxn(center_inland_dry);
	local iNumMiddle = table.maxn(middle_candidates);
	local iNumMiddleRiver = table.maxn(middle_river);
	local iNumMiddleCoastLake = table.maxn(middle_coastal);
	local iNumMiddleInlandDry = table.maxn(middle_inland_dry);
	local iNumOuter = table.maxn(outer_plots);
	
	-- Debug printout.
	print("-");
	print("--- Number of Candidate Plots in Region #", region_number, " - Region Type:", region_type, " ---");
	print("-");
	print("Center Of Region at: " .. tostring(iCenterWestX) .. "," .. tostring(iCenterSouthY));
	print("-");
	print("Candidates in Center Bias area: ", iNumCenter);
	print("Which are next to river: ", iNumCenterRiver);
	print("Which are next to lake or sea: ", iNumCenterCoastLake);
	print("Which are inland and dry: ", iNumCenterInlandDry);
	print("-");
	print("Candidates in Middle Donut area: ", iNumMiddle);
	print("Which are next to river: ", iNumMiddleRiver);
	print("Which are next to lake or sea: ", iNumMiddleCoastLake);
	print("Which are inland and dry: ", iNumMiddleInlandDry);
	print("-");
	print("Candidate Plots in Outer area: ", iNumOuter);
	print("-");
	print("Disqualified, two or three plots away from salt water: ", iNumDisqualified);
	print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -");
	
	
	-- Process lists of candidate plots.
	if self._lek_flatten_region_start_tiers and (iNumCenter + iNumMiddle + iNumOuter > 0) then
		local seen = {};
		local all_plots = {};
		local merge_lists = {
			center_river, center_coastal, center_inland_dry,
			middle_river, middle_coastal, middle_inland_dry,
			outer_plots,
		};
		for ml = 1, #merge_lists do
			local lst = merge_lists[ml];
			for loop, plotIndex in ipairs(lst) do
				if not seen[plotIndex] then
					seen[plotIndex] = true;
					all_plots[#all_plots + 1] = plotIndex;
				end
			end
		end
		local election_returns = self:IterateThroughCandidatePlotList(all_plots, region_type);
		local found_eligible = election_returns[1];
		if found_eligible then
			local bestPlotScore = election_returns[2];
			local bestPlotIndex = election_returns[3];
			local x = (bestPlotIndex - 1) % iW;
			local y = (bestPlotIndex - x - 1) / iW;
			self.startingPlots[region_number] = {x, y, bestPlotScore};
			self:PlaceImpactAndRipples(x, y);
			return true, false;
		end
		local found_fallback_flat = election_returns[4];
		if found_fallback_flat then
			local bestFallbackScore = election_returns[5];
			local bestFallbackIndex = election_returns[6];
			local x = (bestFallbackIndex - 1) % iW;
			local y = (bestFallbackIndex - x - 1) / iW;
			table.insert(fallback_plots, {x, y, bestFallbackScore});
		end
	elseif iNumCenter + iNumMiddle > 0 then
		if self._lek_prioritize_center then
			print("DEV/SAPHT Using _lek_prioritize_center")
			local candidate_lists = {};
			if iNumCenterRiver > 0 then -- Process center bias river plots.
				table.insert(candidate_lists, center_river);
			end
			if iNumCenterCoastLake > 0 then -- Process center bias lake or coastal plots.
				table.insert(candidate_lists, center_coastal);
			end
			if iNumCenterInlandDry > 0 then -- Process center bias inland dry plots.
				table.insert(candidate_lists, center_inland_dry);
			end
			--
			for loop, plot_list in ipairs(candidate_lists) do -- Up to six plot lists, processed by priority.
				local election_returns = self:IterateThroughCandidatePlotList(plot_list, region_type)
				-- If any candidates are eligible, choose one.
				local found_eligible = election_returns[1];
				if found_eligible then
					local bestPlotScore = election_returns[2]; 
					local bestPlotIndex = election_returns[3];
					local x = (bestPlotIndex - 1) % iW;
					local y = (bestPlotIndex - x - 1) / iW;
					self.startingPlots[region_number] = {x, y, bestPlotScore};
					self:PlaceImpactAndRipples(x, y)
					return true, false
				end
				-- If none eligible, check for fallback plot.
				local found_fallback = election_returns[4];
				if found_fallback then
					local bestFallbackScore = election_returns[5];
					local bestFallbackIndex = election_returns[6];
					local x = (bestFallbackIndex - 1) % iW;
					local y = (bestFallbackIndex - x - 1) / iW;
					table.insert(fallback_plots, {x, y, bestFallbackScore});
				end
			end

			candidate_lists = {}
			if iNumMiddleRiver > 0 then -- Process middle donut river plots.
				table.insert(candidate_lists, middle_river);
			end
			if iNumMiddleCoastLake > 0 then -- Process middle donut lake or coastal plots.
				table.insert(candidate_lists, middle_coastal);
			end
			if iNumMiddleInlandDry > 0 then -- Process middle donut inland dry plots.
				table.insert(candidate_lists, middle_inland_dry);
			end
			--
			for loop, plot_list in ipairs(candidate_lists) do -- Up to six plot lists, processed by priority.
				local election_returns = self:IterateThroughCandidatePlotList(plot_list, region_type)
				-- If any candidates are eligible, choose one.
				local found_eligible = election_returns[1];
				if found_eligible then
					local bestPlotScore = election_returns[2]; 
					local bestPlotIndex = election_returns[3];
					local x = (bestPlotIndex - 1) % iW;
					local y = (bestPlotIndex - x - 1) / iW;
					self.startingPlots[region_number] = {x, y, bestPlotScore};
					self:PlaceImpactAndRipples(x, y)
					return true, false
				end
				-- If none eligible, check for fallback plot.
				local found_fallback = election_returns[4];
				if found_fallback then
					local bestFallbackScore = election_returns[5];
					local bestFallbackIndex = election_returns[6];
					local x = (bestFallbackIndex - 1) % iW;
					local y = (bestFallbackIndex - x - 1) / iW;
					table.insert(fallback_plots, {x, y, bestFallbackScore});
				end
			end
		else
			print("DEV/SAPHT Using default center priority")
			local candidate_lists = {};
			if iNumCenterRiver > 0 then -- Process center bias river plots.
				table.insert(candidate_lists, center_river);
			end
			if iNumCenterCoastLake > 0 then -- Process center bias lake or coastal plots.
				table.insert(candidate_lists, center_coastal);
			end
			if iNumCenterInlandDry > 0 then -- Process center bias inland dry plots.
				table.insert(candidate_lists, center_inland_dry);
			end
			if iNumMiddleRiver > 0 then -- Process middle donut river plots.
				table.insert(candidate_lists, middle_river);
			end
			if iNumMiddleCoastLake > 0 then -- Process middle donut lake or coastal plots.
				table.insert(candidate_lists, middle_coastal);
			end
			if iNumMiddleInlandDry > 0 then -- Process middle donut inland dry plots.
				table.insert(candidate_lists, middle_inland_dry);
			end
			--
			for loop, plot_list in ipairs(candidate_lists) do -- Up to six plot lists, processed by priority.
				local election_returns = self:IterateThroughCandidatePlotList(plot_list, region_type)
				-- If any candidates are eligible, choose one.
				local found_eligible = election_returns[1];
				if found_eligible then
					local bestPlotScore = election_returns[2]; 
					local bestPlotIndex = election_returns[3];
					local x = (bestPlotIndex - 1) % iW;
					local y = (bestPlotIndex - x - 1) / iW;
					self.startingPlots[region_number] = {x, y, bestPlotScore};
					self:PlaceImpactAndRipples(x, y)
					return true, false
				end
				-- If none eligible, check for fallback plot.
				local found_fallback = election_returns[4];
				if found_fallback then
					local bestFallbackScore = election_returns[5];
					local bestFallbackIndex = election_returns[6];
					local x = (bestFallbackIndex - 1) % iW;
					local y = (bestFallbackIndex - x - 1) / iW;
					table.insert(fallback_plots, {x, y, bestFallbackScore});
				end
			end
		end
	end
	-- Reaching this point means no eligible sites in center bias or middle donut subregions!
	
	-- Process candidates from Outer subregion, if any.
	if (not self._lek_flatten_region_start_tiers) and iNumOuter > 0 then
		local outer_eligible_list = {};
		local found_eligible = false;
		local found_fallback = false;
		local bestFallbackScore = -50;
		local bestFallbackIndex;
		-- Process list of candidate plots.
		for loop, plotIndex in ipairs(outer_plots) do
			local score, meets_minimums = self:EvaluateCandidatePlot(plotIndex, region_type)
			-- Test current plot against best known plot.
			if meets_minimums == true then
				found_eligible = true;
				table.insert(outer_eligible_list, plotIndex);
			else
				found_fallback = true;
				if score > bestFallbackScore then
					bestFallbackScore = score;
					bestFallbackIndex = plotIndex;
				end
			end
		end
		if found_eligible then
			local bestOuterPlot;
			local bestOuterScore = -math.huge;
			for loop, plotIndex in ipairs(outer_eligible_list) do
				local score, meets_minimums = self:EvaluateCandidatePlot(plotIndex, region_type);
				if meets_minimums == true and score > bestOuterScore then
					bestOuterScore = score;
					bestOuterPlot = plotIndex;
				end
			end
			if bestOuterPlot then
				local x = (bestOuterPlot - 1) % iW;
				local y = (bestOuterPlot - x - 1) / iW;
				self.startingPlots[region_number] = {x, y, bestOuterScore};
				self:PlaceImpactAndRipples(x, y);
				return true, false;
			end
		end
		-- Add the fallback plot (best scored plot) from the Outer region to the fallback list.
		if found_fallback then
			local x = (bestFallbackIndex - 1) % iW;
			local y = (bestFallbackIndex - x - 1) / iW;
			table.insert(fallback_plots, {x, y, bestFallbackScore});
		end
	end
	-- Reaching here means no plot in the entire region met the minimum standards for selection.
	
	-- The fallback plot contains the best-scored plots from each test area in this region.
	-- We will compare all the fallback plots and choose the best to be the start plot.
	local iNumFallbacks = table.maxn(fallback_plots);
	if iNumFallbacks > 0 then
		local best_fallback_score = -math.huge
		local best_fallback_x;
		local best_fallback_y;
		for loop, plotData in ipairs(fallback_plots) do
			local score = plotData[3];
			if score > best_fallback_score then
				best_fallback_score = score;
				best_fallback_x = plotData[1];
				best_fallback_y = plotData[2];
			end
		end
		-- Assign the start for this region.
		self.startingPlots[region_number] = {best_fallback_x, best_fallback_y, best_fallback_score};
		self:PlaceImpactAndRipples(best_fallback_x, best_fallback_y)
		bSuccessFlag = true;
	else
		self:LekErrorIfLegacyForbidForcedCorner(region_number, "FindStart");
		local forcePlot = Map.GetPlot(iWestX, iSouthY);
		bSuccessFlag = true;
		bForcedPlacementFlag = true;
		forcePlot:SetPlotType(PlotTypes.PLOT_LAND, false, true);
		forcePlot:SetTerrainType(TerrainTypes.TERRAIN_GRASS, false, true);
		forcePlot:SetFeatureType(FeatureTypes.NO_FEATURE, -1);
		self.startingPlots[region_number] = {iWestX, iSouthY, 0};
		self:PlaceImpactAndRipples(iWestX, iSouthY)
	end

	return bSuccessFlag, bForcedPlacementFlag
end
------------------------------------------------------------------------------
function AssignStartingPlots:FindCoastalStart(region_number)
	-- This function attempts to choose a start position (which is along an ocean) for a single region.
	-- This function returns two boolean flags, indicating the success level of the operation.
	local bSuccessFlag = false; -- Returns true when a start is placed, false when process fails.
	local bForcedPlacementFlag = false; -- Returns true if this region had no eligible starts and one was forced to occur.
	local AllowInlandSea = self.AllowInlandSea;

	-- Obtain data needed to process this region.
	local iW, iH = Map.GetGridSize();
	local region_data_table = self.regionData[region_number];
	local iWestX = region_data_table[1];
	local iSouthY = region_data_table[2];
	local iWidth = region_data_table[3];
	local iHeight = region_data_table[4];
	local iAreaID = region_data_table[5];
	local iMembershipEastX = iWestX + iWidth - 1;
	local iMembershipNorthY = iSouthY + iHeight - 1;
	--
	local terrainCounts = self.regionTerrainCounts[region_number];
	local coastalLandCount = terrainCounts[22];
	--
	local region_type = self.regionTypes[region_number];
	-- Done setting up region data.
	-- Set up contingency.
	local fallback_plots = {};
	local function placeBestEffortCoastalInRegion()
		local bestPlotIndex = nil;
		local bestScore = -math.huge;
		for region_y = 0, iHeight - 1 do
			for region_x = 0, iWidth - 1 do
				local x = (region_x + iWestX) % iW;
				local y = (region_y + iSouthY) % iH;
				local plotIndex = y * iW + x + 1;
				if self.plotDataIsCoastal[plotIndex] == true then
					local plot = Map.GetPlot(x, y);
					if plot and plot:GetPlotType() ~= PlotTypes.PLOT_MOUNTAIN and (AllowInlandSea == 1 or plot:IsCoastalLand(300)) then
						local area_of_plot = plot:GetArea();
						if area_of_plot == iAreaID or iAreaID == -1 then
							local score = select(1, self:EvaluateCandidatePlot(plotIndex, region_type));
							if score ~= nil and score > bestScore then
								bestScore = score;
								bestPlotIndex = plotIndex;
							end
						end
					end
				end
			end
		end
		if bestPlotIndex == nil then
			return false;
		end
		local x = (bestPlotIndex - 1) % iW;
		local y = (bestPlotIndex - x - 1) / iW;
		self.startingPlots[region_number] = {x, y, bestScore};
		self:PlaceImpactAndRipples(x, y);
		return true;
	end
	
	-- Check region for AlongOcean eligibility.
	if coastalLandCount < 3 then
		-- Coastal assignment is a hard requirement: do not fall back inland.
		bSuccessFlag = placeBestEffortCoastalInRegion();
		return bSuccessFlag, bForcedPlacementFlag
	end

	-- Establish scope of center bias.
	local fCenterWidth = (self.centerBias / 100) * iWidth;
	local iNonCenterWidth = math.floor((iWidth - fCenterWidth) / 2)
	local iCenterWidth = iWidth - (iNonCenterWidth * 2);
	local iCenterWestX = (iWestX + iNonCenterWidth) % iW; -- Modulo math to synch coordinate to actual map in case of world wrap.
	local iCenterTestWestX = (iWestX + iNonCenterWidth); -- "Test" values ignore world wrap for easier membership testing.
	local iCenterTestEastX = (iCenterWestX + iCenterWidth - 1);

	local fCenterHeight = (self.centerBias / 100) * iHeight;
	local iNonCenterHeight = math.floor((iHeight - fCenterHeight) / 2)
	local iCenterHeight = iHeight - (iNonCenterHeight * 2);
	local iCenterSouthY = (iSouthY + iNonCenterHeight) % iH;
	local iCenterTestSouthY = (iSouthY + iNonCenterHeight);
	local iCenterTestNorthY = (iCenterTestSouthY + iCenterHeight - 1);

	-- Establish scope of "middle donut", outside the center but inside the outer.
	local fMiddleWidth = (self.middleBias / 100) * iWidth;
	local iOuterWidth = math.floor((iWidth - fMiddleWidth) / 2)
	local iMiddleWidth = iWidth - (iOuterWidth * 2);
	--local iMiddleDiameterX = (iMiddleWidth - iCenterWidth) / 2;
	local iMiddleWestX = (iWestX + iOuterWidth) % iW;
	local iMiddleTestWestX = (iWestX + iOuterWidth);
	local iMiddleTestEastX = (iMiddleTestWestX + iMiddleWidth - 1);

	local fMiddleHeight = (self.middleBias / 100) * iHeight;
	local iOuterHeight = math.floor((iHeight - fMiddleHeight) / 2)
	local iMiddleHeight = iHeight - (iOuterHeight * 2);
	--local iMiddleDiameterY = (iMiddleHeight - iCenterHeight) / 2;
	local iMiddleSouthY = (iSouthY + iOuterHeight) % iH;
	local iMiddleTestSouthY = (iSouthY + iOuterHeight);
	local iMiddleTestNorthY = (iMiddleTestSouthY + iMiddleHeight - 1); 

	-- Assemble candidates lists.
	local center_coastal_plots = {};
	local center_plots_on_river = {};
	local center_fresh_plots = {};
	local center_dry_plots = {};
	local middle_coastal_plots = {};
	local middle_plots_on_river = {};
	local middle_fresh_plots = {};
	local middle_dry_plots = {};
	local outer_coastal_plots = {};
	
	-- Identify candidate plots.
	for region_y = 0, iHeight - 1 do -- When handling global plot indices, process Y first.
		for region_x = 0, iWidth - 1 do
			local x = (region_x + iWestX) % iW; -- Actual coords, adjusted for world wrap, if any.
			local y = (region_y + iSouthY) % iH; --
			local plotIndex = y * iW + x + 1;
			if self.plotDataIsCoastal[plotIndex] == true then -- This plot is a land plot next to an ocean.
				local plot = Map.GetPlot(x, y);
				local plotType = plot:GetPlotType()
				if plotType ~= PlotTypes.PLOT_MOUNTAIN and (AllowInlandSea == 1 or plot:IsCoastalLand(300)) then -- Not a mountain plot, nor a plot adjacent to inland sea, or inland sea allowed.
					local area_of_plot = plot:GetArea();
					if area_of_plot == iAreaID or iAreaID == -1 then -- This plot is a member, so it goes on at least one candidate list.
						--
						-- Test whether plot is in center bias, middle donut, or outer donut.
						--
						local test_x = region_x + iWestX; -- "Test" coords, ignoring any world wrap and
						local test_y = region_y + iSouthY; -- reaching in to virtual space if necessary.
						if (test_x >= iCenterTestWestX and test_x <= iCenterTestEastX) and 
						   (test_y >= iCenterTestSouthY and test_y <= iCenterTestNorthY) then
							table.insert(center_coastal_plots, plotIndex);
							if plot:IsRiverSide() then
								table.insert(center_plots_on_river, plotIndex);
							elseif plot:IsFreshWater() then
								table.insert(center_fresh_plots, plotIndex);
							else
								table.insert(center_dry_plots, plotIndex);
							end
						elseif (test_x >= iMiddleTestWestX and test_x <= iMiddleTestEastX) and 
						       (test_y >= iMiddleTestSouthY and test_y <= iMiddleTestNorthY) then
							table.insert(middle_coastal_plots, plotIndex);
							if plot:IsRiverSide() then
								table.insert(middle_plots_on_river, plotIndex);
							elseif plot:IsFreshWater() then
								table.insert(middle_fresh_plots, plotIndex);
							else
								table.insert(middle_dry_plots, plotIndex);
							end
						else
							table.insert(outer_coastal_plots, plotIndex);
						end
					end
				end
			end
		end
	end
	-- Check how many plots landed on each list.
	local iNumCenterCoastal = table.maxn(center_coastal_plots);
	local iNumCenterRiver = table.maxn(center_plots_on_river);
	local iNumCenterFresh = table.maxn(center_fresh_plots);
	local iNumCenterDry = table.maxn(center_dry_plots);
	local iNumMiddleCoastal = table.maxn(middle_coastal_plots);
	local iNumMiddleRiver = table.maxn(middle_plots_on_river);
	local iNumMiddleFresh = table.maxn(middle_fresh_plots);
	local iNumMiddleDry = table.maxn(middle_dry_plots);
	local iNumOuterCoastal = table.maxn(outer_coastal_plots);
	
	-- Debug printout.
	print("-");
	print("--- Number of Candidate Plots next to an ocean in Region #", region_number, " - Region Type:", region_type, " ---");
	print("-");
	print("Center Of Region at: " .. tostring(iCenterWestX) .. "," .. tostring(iCenterSouthY));
	print("-");
	print("Coastal Plots in Center Bias area: ", iNumCenterCoastal);
	print("Which are along rivers: ", iNumCenterRiver);
	print("Which are fresh water: ", iNumCenterFresh);
	print("Which are dry: ", iNumCenterDry);
	print("-");
	print("Coastal Plots in Middle Donut area: ", iNumMiddleCoastal);
	print("Which are along rivers: ", iNumMiddleRiver);
	print("Which are fresh water: ", iNumMiddleFresh);
	print("Which are dry: ", iNumMiddleDry);
	print("-");
	print("Coastal Plots in Outer area: ", iNumOuterCoastal);
	print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -");
	--
	
	-- Process lists of candidate plots.
	if self._lek_flatten_region_start_tiers and (iNumCenterCoastal + iNumMiddleCoastal + iNumOuterCoastal > 0) then
		local seenC = {};
		local all_coastal_plots = {};
		local merge_coast = {
			center_plots_on_river, center_fresh_plots, center_dry_plots,
			middle_plots_on_river, middle_fresh_plots, middle_dry_plots,
			outer_coastal_plots,
		};
		for mc = 1, #merge_coast do
			local lst = merge_coast[mc];
			for loop, plotIndex in ipairs(lst) do
				if not seenC[plotIndex] then
					seenC[plotIndex] = true;
					all_coastal_plots[#all_coastal_plots + 1] = plotIndex;
				end
			end
		end
		local election_returns_c = self:IterateThroughCandidatePlotList(all_coastal_plots, region_type);
		if election_returns_c[1] then
			local bestPlotScore = election_returns_c[2];
			local bestPlotIndex = election_returns_c[3];
			local x = (bestPlotIndex - 1) % iW;
			local y = (bestPlotIndex - x - 1) / iW;
			self.startingPlots[region_number] = {x, y, bestPlotScore};
			self:PlaceImpactAndRipples(x, y);
			return true, false;
		end
		if election_returns_c[4] then
			local bestFallbackScore = election_returns_c[5];
			local bestFallbackIndex = election_returns_c[6];
			local x = (bestFallbackIndex - 1) % iW;
			local y = (bestFallbackIndex - x - 1) / iW;
			table.insert(fallback_plots, {x, y, bestFallbackScore});
		end
	elseif iNumCenterCoastal + iNumMiddleCoastal > 0 then
		local candidate_lists = {};
		if iNumCenterRiver > 0 then -- Process center bias river plots.
			table.insert(candidate_lists, center_plots_on_river);
		end
		if iNumCenterFresh > 0 then -- Process center bias fresh water plots that are not rivers.
			table.insert(candidate_lists, center_fresh_plots);
		end
		if iNumCenterDry > 0 then -- Process center bias dry plots.
			table.insert(candidate_lists, center_dry_plots);
		end
		if iNumMiddleRiver > 0 then -- Process middle bias river plots.
			table.insert(candidate_lists, middle_plots_on_river);
		end
		if iNumMiddleFresh > 0 then -- Process middle bias fresh water plots that are not rivers.
			table.insert(candidate_lists, middle_fresh_plots);
		end
		if iNumMiddleDry > 0 then -- Process middle bias dry plots.
			table.insert(candidate_lists, middle_dry_plots);
		end
		--
		for loop, plot_list in ipairs(candidate_lists) do -- Up to six plot lists, processed by priority.
			local election_returns = self:IterateThroughCandidatePlotList(plot_list, region_type)
			-- If any riverside candidates are eligible, choose one.
			local found_eligible = election_returns[1];
			if found_eligible then
				local bestPlotScore = election_returns[2]; 
				local bestPlotIndex = election_returns[3];
				local x = (bestPlotIndex - 1) % iW;
				local y = (bestPlotIndex - x - 1) / iW;
				self.startingPlots[region_number] = {x, y, bestPlotScore};
				self:PlaceImpactAndRipples(x, y)
				return true, false
			end
			-- If none eligible, check for fallback plot.
			local found_fallback = election_returns[4];
			if found_fallback then
				local bestFallbackScore = election_returns[5];
				local bestFallbackIndex = election_returns[6];
				local x = (bestFallbackIndex - 1) % iW;
				local y = (bestFallbackIndex - x - 1) / iW;
				table.insert(fallback_plots, {x, y, bestFallbackScore});
			end
		end
	end
	-- Reaching this point means no strong coastal sites in center bias or middle donut subregions!
	
	-- Process candidates from Outer subregion, if any.
	if (not self._lek_flatten_region_start_tiers) and iNumOuterCoastal > 0 then
		local outer_eligible_list = {};
		local found_eligible = false;
		local found_fallback = false;
		local bestFallbackScore = -50;
		local bestFallbackIndex;
		-- Process list of candidate plots.
		for loop, plotIndex in ipairs(outer_coastal_plots) do
			local score, meets_minimums = self:EvaluateCandidatePlot(plotIndex, region_type)
			-- Test current plot against best known plot.
			if meets_minimums == true then
				found_eligible = true;
				table.insert(outer_eligible_list, plotIndex);
			else
				found_fallback = true;
				if score > bestFallbackScore then
					bestFallbackScore = score;
					bestFallbackIndex = plotIndex;
				end
			end
		end

		if found_eligible then
			local bestOuterPlot;
			local bestOuterScore = -math.huge;
			for loop, plotIndex in ipairs(outer_eligible_list) do
				local score, meets_minimums = self:EvaluateCandidatePlot(plotIndex, region_type);
				if meets_minimums == true and score > bestOuterScore then
					bestOuterScore = score;
					bestOuterPlot = plotIndex;
				end
			end
			if bestOuterPlot then
				local x = (bestOuterPlot - 1) % iW;
				local y = (bestOuterPlot - x - 1) / iW;
				self.startingPlots[region_number] = {x, y, bestOuterScore};
				self:PlaceImpactAndRipples(x, y);
				return true, false;
			end
		end
		-- Add the fallback plot (best scored plot) from the Outer region to the fallback list.
		if found_fallback then
			local x = (bestFallbackIndex - 1) % iW;
			local y = (bestFallbackIndex - x - 1) / iW;
			table.insert(fallback_plots, {x, y, bestFallbackScore});
		end
	end
	-- Reaching here means no plot in the entire region met the minimum standards for selection.
	
	-- The fallback plot contains the best-scored plots from each test area in this region.
	-- This region must be something awful on food, or had too few coastal plots with none being decent.
	-- We will compare all the fallback plots and choose the best to be the start plot.
	local iNumFallbacks = table.maxn(fallback_plots);
	if iNumFallbacks > 0 then
		local best_fallback_score = -math.huge
		local best_fallback_x;
		local best_fallback_y;
		for loop, plotData in ipairs(fallback_plots) do
			local score = plotData[3];
			if score > best_fallback_score then
				best_fallback_score = score;
				best_fallback_x = plotData[1];
				best_fallback_y = plotData[2];
			end
		end
		-- Assign the start for this region.
		self.startingPlots[region_number] = {best_fallback_x, best_fallback_y, best_fallback_score};
		self:PlaceImpactAndRipples(best_fallback_x, best_fallback_y)
		bSuccessFlag = true;
	else
		-- Coastal assignment is a hard requirement: do not fall back inland.
		bSuccessFlag = placeBestEffortCoastalInRegion();
	end

	return bSuccessFlag, bForcedPlacementFlag
end
------------------------------------------------------------------------------
function AssignStartingPlots:FindStartWithoutRegardToAreaID(region_number, bMustBeCoast)
	-- This function attempts to choose a start position on the best AreaID section within the Region's rectangle.
	-- This function returns two boolean flags, indicating the success level of the operation.
	local bSuccessFlag = false; -- Returns true when a start is placed, false when process fails.
	local bForcedPlacementFlag = false; -- Returns true if this region had no eligible starts and one was forced to occur.
	
	-- Obtain data needed to process this region.
	local iW, iH = Map.GetGridSize();
	local region_data_table = self.regionData[region_number];
	local iWestX = region_data_table[1];
	local iSouthY = region_data_table[2];
	local iWidth = region_data_table[3];
	local iHeight = region_data_table[4];
	local wrapX = Map:IsWrapX();
	local wrapY = Map:IsWrapY();
	local iMembershipEastX = iWestX + iWidth - 1;
	local iMembershipNorthY = iSouthY + iHeight - 1;
	--
	local region_type = self.regionTypes[region_number];
	local fallback_plots = {};
	-- Done setting up region data.

	-- Obtain info on all landmasses wholly or partially within this region, for comparision purposes.
	local regionalFertilityOfLands = {};
	local iRegionalFertilityOfLands = 0;
	local iNumLandPlots = 0;
	local iNumLandAreas = 0;
	local land_area_IDs = {};
	local land_area_plots = {};
	local land_area_fert = {};
	local land_area_plot_lists = {};
	-- Cycle through all plots in the region, checking their Start Placement Fertility and AreaID.
	for region_y = 0, iHeight - 1 do
		for region_x = 0, iWidth - 1 do
			local x = region_x + iWestX;
			local y = region_y + iSouthY;
			local plot = Map.GetPlot(x, y);
			local plotType = plot:GetPlotType()
			if plotType == PlotTypes.PLOT_HILLS or plotType == PlotTypes.PLOT_LAND then -- Land plot, process it.
				iNumLandPlots = iNumLandPlots + 1;
				local iArea = plot:GetArea();
				local plotFertility = self:MeasureStartPlacementFertilityOfPlot(x, y, false); -- Check for coastal land is disabled.
				iRegionalFertilityOfLands = iRegionalFertilityOfLands + plotFertility;
				if TestMembership(land_area_IDs, iArea) == false then -- This plot is the first detected in its AreaID.
					iNumLandAreas = iNumLandAreas + 1;
					table.insert(land_area_IDs, iArea);
					land_area_plots[iArea] = 1;
					land_area_fert[iArea] = plotFertility;
				else -- This AreaID already known.
					land_area_plots[iArea] = land_area_plots[iArea] + 1;
					land_area_fert[iArea] = land_area_fert[iArea] + plotFertility;
				end
			end
		end
	end

	-- Generate empty (non-nil) tables for each Area ID in the plot lists matrix.
	for loop, areaID in ipairs(land_area_IDs) do
		land_area_plot_lists[areaID] = {};
	end
	-- Cycle through all plots in the region again, adding candidates to the applicable AreaID plot list.
	for region_y = 0, iHeight - 1 do
		for region_x = 0, iWidth - 1 do
			local x = region_x + iWestX;
			local y = region_y + iSouthY;
			local i = y * iW + x + 1;
			local plot = Map.GetPlot(x, y);
			local plotType = plot:GetPlotType()
			if plotType == PlotTypes.PLOT_HILLS or plotType == PlotTypes.PLOT_LAND then -- Land plot, process it.
				local iArea = plot:GetArea();
				if self.plotDataIsCoastal[i] == true then
					table.insert(land_area_plot_lists[iArea], i);
				elseif bMustBeCoast == false and self.plotDataIsNextToCoast[i] == false and self.plotDataIsThreeFromCoast[i] == false then
					table.insert(land_area_plot_lists[iArea], i);
				end
			end
		end
	end
	
	local best_areas = {};
	local regionAreaListUnsorted = {};
	local regionAreaListSorted = {}; -- Have to make this a separate table, not merely a pointer to the first table.
	for areaNum, fert in pairs(land_area_fert) do
		table.insert(regionAreaListUnsorted, {areaNum, fert});
		table.insert(regionAreaListSorted, fert);
	end
	table.sort(regionAreaListSorted);
	
	-- Match each sorted fertilty value to the matching unsorted AreaID number and record in sequence.
	local iNumAreas = table.maxn(regionAreaListSorted);
	for area_order = iNumAreas, 1, -1 do -- Best areas are at the end of the list, so run the list backward.
		for loop, data_pair in ipairs(regionAreaListUnsorted) do
			local unsorted_fert = data_pair[2];
			if regionAreaListSorted[area_order] == unsorted_fert then
				local unsorted_area_num = data_pair[1];
				table.insert(best_areas, unsorted_area_num);
				-- HAVE TO remove the entry from the table in case of ties on fert value.
				table.remove(regionAreaListUnsorted, loop);
				break
			end
		end
	end

	--[[ Debug printout.
	print("-");
	print("--- Number of Candidate Plots in each landmass in Region #", region_number, " - Region Type:", region_type, " ---");
	print("-");
	for loop, iAreaID in ipairs(best_areas) do
		local fert_rating = land_area_fert[iAreaID];
		local plotCount = table.maxn(land_area_plot_lists[iAreaID]);
		print("* Area ID#", iAreaID, "has fertility rating of", fert_rating, "and candidate plot count of", plotCount); print("-");
	end
	print("- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -");
	]]--

	-- Now iterate through areas, from best fertility downward, looking for a site good enough to choose.
	for loop, iAreaID in ipairs(best_areas) do
		local plot_list = land_area_plot_lists[iAreaID];
		local election_returns = self:IterateThroughCandidatePlotList(plot_list, region_type)
		-- If any plots in this area are eligible, choose one.
		local found_eligible = election_returns[1];
		if found_eligible then
			local bestPlotScore = election_returns[2]; 
			local bestPlotIndex = election_returns[3];
			local x = (bestPlotIndex - 1) % iW;
			local y = (bestPlotIndex - x - 1) / iW;
			self.startingPlots[region_number] = {x, y, bestPlotScore};
			self:PlaceImpactAndRipples(x, y)
			return true, false
		end
		-- If none eligible, check for fallback plot.
		local found_fallback = election_returns[4];
		if found_fallback then
			local bestFallbackScore = election_returns[5];
			local bestFallbackIndex = election_returns[6];
			local x = (bestFallbackIndex - 1) % iW;
			local y = (bestFallbackIndex - x - 1) / iW;
			table.insert(fallback_plots, {x, y, bestFallbackScore});
		end
	end
	-- Reaching this point means no strong sites far enough away from any already-placed start points.

	-- We will compare all the fallback plots and choose the best to be the start plot.
	local iNumFallbacks = table.maxn(fallback_plots);
	if iNumFallbacks > 0 then
		local best_fallback_score = -math.huge
		local best_fallback_x;
		local best_fallback_y;
		for loop, plotData in ipairs(fallback_plots) do
			local score = plotData[3];
			if score > best_fallback_score then
				best_fallback_score = score;
				best_fallback_x = plotData[1];
				best_fallback_y = plotData[2];
			end
		end
		-- Assign the start for this region.
		self.startingPlots[region_number] = {best_fallback_x, best_fallback_y, best_fallback_score};
		self:PlaceImpactAndRipples(best_fallback_x, best_fallback_y)
		bSuccessFlag = true;
	else
		self:LekErrorIfLegacyForbidForcedCorner(region_number, "FindStartWithoutRegardToAreaID");
		local forcePlot = Map.GetPlot(iWestX, iSouthY);
		bForcedPlacementFlag = true;
		forcePlot:SetPlotType(PlotTypes.PLOT_LAND, false, true);
		forcePlot:SetTerrainType(TerrainTypes.TERRAIN_GRASS, false, true);
		forcePlot:SetFeatureType(FeatureTypes.NO_FEATURE, -1);
		self.startingPlots[region_number] = {iWestX, iSouthY, 0};
		self:PlaceImpactAndRipples(iWestX, iSouthY)
		bSuccessFlag = true;
	end

	return bSuccessFlag, bForcedPlacementFlag
end
------------------------------------------------------------------------------
-- Lekmap v1 virtual six-start pass (deprecated vs SCRATCHPAD-placement-spec-v0.md global OK).
-- Off unless start_plot_database._lek_enable_virtual_six_retries == true and
-- _lek_disable_virtual_six ~= true. Snapshot/restore distance/collision/cityState between tries.
local LEK_VIRTUAL_SIX_ATTEMPTS = 32;

function AssignStartingPlots:LekMinNearestAmongSix()
	local pts = {};
	for r = 1, self.iNumCivs do
		local t = self.startingPlots[r];
		if not t or type(t[1]) ~= "number" or type(t[2]) ~= "number" then
			return -1, -1;
		end
		pts[#pts + 1] = { t[1], t[2] };
	end
	if #pts ~= self.iNumCivs then
		return -1, -1;
	end
	local nearestList = {};
	for i = 1, #pts do
		local best = 9999;
		for j = 1, #pts do
			if i ~= j then
				local d;
				if Map.PlotDistance then
					d = Map.PlotDistance(pts[i][1], pts[i][2], pts[j][1], pts[j][2]);
				elseif PlotDistance then
					d = PlotDistance(pts[i][1], pts[i][2], pts[j][1], pts[j][2]);
				else
					d = 0;
				end
				if d < best then best = d; end
			end
		end
		nearestList[#nearestList + 1] = best;
	end
	table.sort(nearestList);
	return nearestList[1], nearestList[2];
end

function AssignStartingPlots:LekVirtualSixInlandOceanUndesirable()
	local iW, iH = Map.GetGridSize();
	local hexR = 4;
	local maxSaltSea = 4;
	local totalExcess = 0;
	local parts = {};
	for r = 1, self.iNumCivs do
		local t = self.startingPlots[r];
		if t and type(t[1]) == "number" and type(t[2]) == "number" then
			local plot = Map.GetPlot(t[1], t[2]);
			if not plot then
				parts[#parts + 1] = "r" .. tostring(r) .. ":nil_plot";
			elseif plot:IsCoastalLand() then
				parts[#parts + 1] = "r" .. tostring(r) .. ":coastal_skipped";
			else
				local cx, cy = t[1], t[2];
				local nSalt = 0;
				for ny = 0, iH - 1 do
					for nx = 0, iW - 1 do
						local d = nil;
						if Map.PlotDistance then
							d = Map.PlotDistance(cx, cy, nx, ny);
						elseif PlotDistance then
							d = PlotDistance(cx, cy, nx, ny);
						end
						if d ~= nil and d <= hexR then
							local p2 = Map.GetPlot(nx, ny);
							if p2 and p2:IsWater() and not p2:IsLake() then
								nSalt = nSalt + 1;
							end
						end
					end
				end
				local excess = 0;
				if nSalt > maxSaltSea then
					excess = nSalt - maxSaltSea;
					totalExcess = totalExcess + excess;
				end
				parts[#parts + 1] = "r" .. tostring(r) .. ":inland nSaltOcean_dLe" .. tostring(hexR) .. "=" .. tostring(nSalt) .. " excess+" .. tostring(excess);
			end
		end
	end
	local label = "inlandSaltOcean_hexR" .. tostring(hexR) .. "_maxFree" .. tostring(maxSaltSea);
	local breakdown = label .. " totalExcess=" .. tostring(totalExcess);
	if #parts > 0 then
		breakdown = breakdown .. " | perRegion={" .. table.concat(parts, "; ") .. "}";
	else
		breakdown = breakdown .. " | perRegion={}";
	end
	return totalExcess, breakdown;
end

function AssignStartingPlots:LekRunOneStartPlacementPass(regionAssignList, iNumRegions, res_reg, iNumCoastNeeded)
	local coastQuotaStart = iNumCoastNeeded;
	for assignIndex = 1, iNumRegions do
		local currentRegionNumber = regionAssignList[assignIndex];
		local bSuccessFlag = false;
		local bForcedPlacementFlag = false;
		print("Region #" .. currentRegionNumber);
		print("Num coastal still needed " .. tostring(iNumCoastNeeded));
		if res_reg[currentRegionNumber] == false and iNumCoastNeeded > 0 then
			bSuccessFlag, bForcedPlacementFlag = self:FindCoastalStart(currentRegionNumber);
			iNumCoastNeeded = iNumCoastNeeded - 1;
		else
			print("Don't Allow Spawning on Coast: " .. tostring(self.NoCoastInland));
			local noCoastArg = self.NoCoastInland;
			if self.BalancedCoastalExactTwo == true and self.ForceAllInlandPlayerSpawns ~= true then
				noCoastArg = true;
			end
			bSuccessFlag, bForcedPlacementFlag = self:FindStart(currentRegionNumber, noCoastArg);
		end
		print("- - -");
		print("Start Plot for Region #", currentRegionNumber, " was successful: ", bSuccessFlag);
		print("Start Plot for Region #", currentRegionNumber, " was forced: ", bForcedPlacementFlag);
		if not bSuccessFlag then
			return false, iNumCoastNeeded;
		end
	end
	if coastQuotaStart > 0 and iNumCoastNeeded > 0 then
		return false, iNumCoastNeeded;
	end
	return true, iNumCoastNeeded;
end

function AssignStartingPlots:LekGlobalSix_PlotDistance(x1, y1, x2, y2)
	if Map.PlotDistance then
		return Map.PlotDistance(x1, y1, x2, y2);
	end
	if PlotDistance then
		return PlotDistance(x1, y1, x2, y2);
	end
	return nil;
end

-- SCRATCHPAD-placement-spec-v0.11 global-six geometry (§1 annulus, §2 spacing).
local LEK_G6_S1_D_MIN = 9;
local LEK_G6_S1_D_MAX = 18;
local LEK_G6_S1_RELAX_MAX = 19;
local LEK_G6_S1_TARGET_D = 13;
local LEK_G6_S2_SECOND_NEAREST_MAX = 15;
local LEK_G6_MIN_PAIRWISE_PLOTDIST_FALLBACK = 9;

function AssignStartingPlots:LekGlobalSix_NoCoastInlandEnforced()
	if self.NoCoastInland ~= true then
		return false;
	end
	local ok, dsb = pcall(function()
		return Game.GetCustomOption("GAMEOPTION_DISABLE_START_BIAS");
	end);
	if ok and dsb == 1 then
		return false;
	end
	return true;
end

-- Map script "Start Distance" (legacy custom option 6): minimum PlotDistance between any two majors (tuple + post-BA).
function AssignStartingPlots.LekGlobalSix_MapOpt6ToMinPairwisePlotDist(v)
	if v == 1 then
		return 7;
	end
	if v == 2 then
		return 9;
	end
	if v == 3 then
		return 11;
	end
	return nil;
end

function AssignStartingPlots.LekGlobalSix_MinPairwiseDistanceFromStartDistanceOption()
	local ok, v = pcall(function()
		return LekMapGetCustomOption(6);
	end);
	local mapped = nil;
	if ok and type(v) == "number" then
		mapped = AssignStartingPlots.LekGlobalSix_MapOpt6ToMinPairwisePlotDist(v);
	end
	if mapped ~= nil then
		return mapped;
	end
	local h = nil;
	if type(_lek_map_hidden_option_defaults) == "table" then
		h = _lek_map_hidden_option_defaults[6];
	end
	if type(h) == "number" then
		local m2 = AssignStartingPlots.LekGlobalSix_MapOpt6ToMinPairwisePlotDist(h);
		if m2 ~= nil then
			return m2;
		end
	end
	return LEK_G6_MIN_PAIRWISE_PLOTDIST_FALLBACK;
end

function AssignStartingPlots.LekGlobalSix_MinPairRequiredPlotDistForTuple(self, ax, ay, bx, by, baseMin)
	if type(baseMin) ~= "number" or baseMin < 2 then
		return baseMin;
	end
	local mA = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsAtXY(self, ax, ay);
	local mB = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsAtXY(self, bx, by);
	local req = baseMin;
	if mA.alongOcean == true and mB.alongOcean == true and req < 11 then
		req = 11;
	end
	return req;
end

function AssignStartingPlots:LekGlobalSix_OK_Section1_CentreBand()
	local iW, iH = Map.GetGridSize();
	local cx = math.floor(iW / 2);
	local cy = math.floor(iH / 2);
	for r = 1, self.iNumCivs do
		local sp = self.startingPlots[r];
		if not sp or type(sp[1]) ~= "number" or type(sp[2]) ~= "number" then
			return false, "missing_r=" .. tostring(r);
		end
		local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, sp[1], sp[2], cx, cy);
		if d == nil then
			return false, "no_PlotDistance";
		end
		local dLo = self._lek_g6_runtime_s1_min or LEK_G6_S1_D_MIN;
		local dHi = self._lek_g6_runtime_s1_max or LEK_G6_S1_D_MAX;
		if d < dLo or d > dHi then
			return false, string.format("r=%d d=%d xy=%d,%d", r, d, sp[1], sp[2]);
		end
	end
	return true, "";
end

function AssignStartingPlots:LekGlobalSix_OK_Section2_d2()
	for i = 1, self.iNumCivs do
		local ti = self.startingPlots[i];
		if not ti or type(ti[1]) ~= "number" or type(ti[2]) ~= "number" then
			return false, "missing_i=" .. tostring(i);
		end
		local dists = {};
		for j = 1, self.iNumCivs do
			if i ~= j then
				local tj = self.startingPlots[j];
				if not tj or type(tj[1]) ~= "number" or type(tj[2]) ~= "number" then
					return false, "missing_j=" .. tostring(j);
				end
				local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, ti[1], ti[2], tj[1], tj[2]);
				if d == nil then
					return false, "no_PlotDistance";
				end
				dists[#dists + 1] = d;
			end
		end
		table.sort(dists);
		local d2 = dists[2];
		local s2cap = self._lek_g6_runtime_s2_max or LEK_G6_S2_SECOND_NEAREST_MAX;
		if d2 > s2cap then
			return false, string.format("i=%d secondNearest=%d", i, d2);
		end
	end
	local dMinPair = AssignStartingPlots.LekGlobalSix_MinPairwiseDistanceFromStartDistanceOption();
	if type(dMinPair) == "number" and dMinPair >= 2 then
		for i = 1, self.iNumCivs do
			local ti = self.startingPlots[i];
			if not ti or type(ti[1]) ~= "number" or type(ti[2]) ~= "number" then
				return false, "missing_i_pair=" .. tostring(i);
			end
			for j = i + 1, self.iNumCivs do
				local tj = self.startingPlots[j];
				if not tj or type(tj[1]) ~= "number" or type(tj[2]) ~= "number" then
					return false, "missing_j_pair=" .. tostring(j);
				end
				local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, ti[1], ti[2], tj[1], tj[2]);
				if d == nil then
					return false, "no_PlotDistance_pair";
				end
				local req = AssignStartingPlots.LekGlobalSix_MinPairRequiredPlotDistForTuple(self, ti[1], ti[2], tj[1], tj[2], dMinPair);
				if d < req then
					return false, string.format("pair_ij=%d,%d dist=%d minPair=%d opt6", i, j, d, req);
				end
			end
		end
	end
	return true, "";
end

function AssignStartingPlots.LekGlobalSix_SecondNearestD2ForRegion_i(self, i)
	local ti = self.startingPlots[i];
	if not ti or type(ti[1]) ~= "number" or type(ti[2]) ~= "number" then
		return nil;
	end
	local dists = {};
	for j = 1, self.iNumCivs or 0 do
		if i ~= j then
			local tj = self.startingPlots[j];
			if not tj or type(tj[1]) ~= "number" or type(tj[2]) ~= "number" then
				return nil;
			end
			local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, ti[1], ti[2], tj[1], tj[2]);
			if d == nil then
				return nil;
			end
			dists[#dists + 1] = d;
		end
	end
	table.sort(dists);
	return dists[2];
end

function AssignStartingPlots.LekGlobalSix_OK_Section2_MinPairSubclauseOnly(self)
	local dMinPair = AssignStartingPlots.LekGlobalSix_MinPairwiseDistanceFromStartDistanceOption();
	if type(dMinPair) ~= "number" or dMinPair < 2 then
		return true, "";
	end
	for i = 1, self.iNumCivs do
		local ti = self.startingPlots[i];
		if not ti or type(ti[1]) ~= "number" or type(ti[2]) ~= "number" then
			return false, "missing_i_pair=" .. tostring(i);
		end
		for j = i + 1, self.iNumCivs do
			local tj = self.startingPlots[j];
			if not tj or type(tj[1]) ~= "number" or type(tj[2]) ~= "number" then
				return false, "missing_j_pair=" .. tostring(j);
			end
			local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, ti[1], ti[2], tj[1], tj[2]);
			if d == nil then
				return false, "no_PlotDistance_pair";
			end
			local req = AssignStartingPlots.LekGlobalSix_MinPairRequiredPlotDistForTuple(self, ti[1], ti[2], tj[1], tj[2], dMinPair);
			if d < req then
				return false, string.format("pair_ij=%d,%d dist=%d minPair=%d opt6", i, j, d, req);
			end
		end
	end
	return true, "";
end

function AssignStartingPlots.LekGlobalSix_QualifiesMinimalS2Plus1NearMiss(self, s2cap)
	if type(s2cap) ~= "number" then
		return false, nil;
	end
	local maxD2 = -1;
	local nStrict = 0;
	local d2ByR = {};
	for i = 1, 6 do
		local d2 = AssignStartingPlots.LekGlobalSix_SecondNearestD2ForRegion_i(self, i);
		if d2 == nil then
			return false, nil;
		end
		d2ByR[i] = d2;
		if d2 > maxD2 then
			maxD2 = d2;
		end
		if d2 > s2cap then
			nStrict = nStrict + 1;
		end
	end
	if maxD2 ~= s2cap + 1 or nStrict < 1 or nStrict > 2 then
		return false, { maxD2 = maxD2, nOverCap = nStrict, s2cap = s2cap };
	end
	local ok1, _ = AssignStartingPlots.LekGlobalSix_OK_Section1_CentreBand(self);
	if not ok1 then
		return false, nil;
	end
	local okP, _ = AssignStartingPlots.LekGlobalSix_OK_Section2_MinPairSubclauseOnly(self);
	if not okP then
		return false, nil;
	end
	local ok3, _ = AssignStartingPlots.LekGlobalSix_OK_Section3_InlandSalt(self);
	if not ok3 then
		return false, nil;
	end
	local ok5, _ = AssignStartingPlots.LekGlobalSix_OK_Section5_BalanceAndAssignFeasible(self);
	if not ok5 then
		return false, nil;
	end
	local ok6, _ = AssignStartingPlots.LekGlobalSix_OK_Section6_SiteQuality_PostPlacement(self);
	if not ok6 then
		return false, nil;
	end
	return true, { maxD2 = maxD2, nOverCap = nStrict, s2cap = s2cap, d2ByR = d2ByR };
end

function AssignStartingPlots.LekGlobalSix_TupleFailComboS5Heavy(failComboHist)
	if type(failComboHist) ~= "table" or not next(failComboHist) then
		return false;
	end
	local s2pure = failComboHist["s2"];
	if type(s2pure) ~= "number" then
		s2pure = 0;
	end
	local with5 = 0;
	for k, v in pairs(failComboHist) do
		if type(k) == "string" and type(v) == "number" and string.find(k, "s5", 1, true) then
			with5 = with5 + v;
		end
	end
	return with5 > s2pure;
end

function AssignStartingPlots.LekGlobalSix_TupleFailHistPairHeavy(failHist)
	if type(failHist) ~= "table" or not next(failHist) then
		return false;
	end
	local total = 0;
	local pairn = 0;
	for k, v in pairs(failHist) do
		if type(v) == "number" and v > 0 then
			total = total + v;
			if tostring(k) == "pair" then
				pairn = pairn + v;
			end
		end
	end
	if total < 200 then
		return false;
	end
	return (pairn / total) >= 0.85;
end

-- Backward-compatible alias while old option names may still exist in user configs/log scripts.
function AssignStartingPlots.LekGlobalSix_TupleFailHistS4Heavy(failHist)
	return AssignStartingPlots.LekGlobalSix_TupleFailHistPairHeavy(failHist);
end

function AssignStartingPlots.LekGlobalSix_TuplePhaseIsS2OnlyRelaxVsBase(ph, basePh)
	if type(ph) ~= "table" or type(basePh) ~= "table" then
		return false;
	end
	local bs1a = basePh.s1_min;
	local bs1b = basePh.s1_max;
	local bs2 = basePh.s2_max;
	local ps1a = ph.s1_min;
	local ps1b = ph.s1_max;
	local ps2 = ph.s2_max;
	if type(bs1a) ~= "number" then
		bs1a = LEK_G6_S1_D_MIN;
	end
	if type(bs1b) ~= "number" then
		bs1b = LEK_G6_S1_D_MAX;
	end
	if type(bs2) ~= "number" then
		bs2 = LEK_G6_S2_SECOND_NEAREST_MAX;
	end
	if type(ps1a) ~= "number" then
		ps1a = LEK_G6_S1_D_MIN;
	end
	if type(ps1b) ~= "number" then
		ps1b = LEK_G6_S1_D_MAX;
	end
	if type(ps2) ~= "number" then
		ps2 = LEK_G6_S2_SECOND_NEAREST_MAX;
	end
	return ps1a == bs1a and ps1b == bs1b and ps2 > bs2;
end

function AssignStartingPlots.LekGlobalSix_TupleShouldExtendBudgetPureS2(failHist, failComboHist)
	if type(failHist) ~= "table" then
		return false;
	end
	local domK, domN = nil, -1;
	for k, n in pairs(failHist) do
		if type(n) == "number" and n > domN then
			domN = n;
			domK = k;
		end
	end
	if domK ~= "s2" then
		return false;
	end
	return not AssignStartingPlots.LekGlobalSix_TupleFailComboS5Heavy(failComboHist or {});
end

local LEK_G6_S3_INLAND_SALT_HEX_R = 3;
local LEK_G6_S3_INLAND_SALT_MAX_OCEAN = 4;

function AssignStartingPlots.LekGlobalSix_OK_InlandSaltCell(self, plotIndex, rForMsg)
	local iW, iH = Map.GetGridSize();
	local x = (plotIndex - 1) % iW;
	local y = (plotIndex - x - 1) / iW;
	if self.plotDataIsCoastal[plotIndex] == true then
		return true, "";
	end
	local maxR, maxSalt = LEK_G6_S3_INLAND_SALT_HEX_R, LEK_G6_S3_INLAND_SALT_MAX_OCEAN;
	local nSalt = 0;
	for ny = 0, iH - 1 do
		for nx = 0, iW - 1 do
			local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, x, y, nx, ny);
			if d ~= nil and d <= maxR then
				local p2 = Map.GetPlot(nx, ny);
				if p2 and p2:IsWater() and not p2:IsLake() then
					nSalt = nSalt + 1;
				end
			end
		end
	end
	if nSalt > maxSalt then
		if rForMsg ~= nil then
			return false, string.format("r=%d inland nSaltOcean=%d max=%d xy=%d,%d", rForMsg, nSalt, maxSalt, x, y);
		end
		return false, string.format("inland nSaltOcean=%d max=%d plotIndex=%d xy=%d,%d", nSalt, maxSalt, plotIndex, x, y);
	end
	return true, "";
end

function AssignStartingPlots.LekGlobalSix_CoastalCandidatePassesSaltWaterDiskPct(self, plotIndex)
	local pctMax = self._lek_global_six_coastal_disk3_max_salt_water_pct;
	if pctMax == nil or pctMax == false or type(pctMax) ~= "number" or pctMax < 0 or pctMax > 100 then
		return true;
	end
	if self.plotDataIsCoastal[plotIndex] ~= true then
		return true;
	end
	local rad = self._lek_global_six_coastal_salt_water_disk_radius;
	if type(rad) ~= "number" or rad < 1 then
		rad = 3;
	end
	local iW, iH = Map.GetGridSize();
	local x = (plotIndex - 1) % iW;
	local y = (plotIndex - x - 1) / iW;
	local nSalt = 0;
	local tot = 0;
	for ny = 0, iH - 1 do
		for nx = 0, iW - 1 do
			local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, x, y, nx, ny);
			if d ~= nil and d <= rad then
				tot = tot + 1;
				local p2 = Map.GetPlot(nx, ny);
				if p2 and p2:IsWater() and not p2:IsLake() then
					nSalt = nSalt + 1;
				end
			end
		end
	end
	if tot <= 0 then
		return true;
	end
	return (nSalt * 100 <= pctMax * tot);
end

function AssignStartingPlots.LekGlobalSix_CoastalSaltDiskPctFilterActive(self)
	local pctMax = self._lek_global_six_coastal_disk3_max_salt_water_pct;
	return type(pctMax) == "number" and pctMax >= 0 and pctMax <= 100;
end

function AssignStartingPlots:LekGlobalSix_OK_Section3_InlandSalt()
	local iW = select(1, Map.GetGridSize());
	for r = 1, self.iNumCivs do
		local t = self.startingPlots[r];
		if not t or type(t[1]) ~= "number" or type(t[2]) ~= "number" then
			return false, "missing_r=" .. tostring(r);
		end
		local x, y = t[1], t[2];
		local plotIndex = y * iW + x + 1;
		local ok3, det3 = AssignStartingPlots.LekGlobalSix_OK_InlandSaltCell(self, plotIndex, r);
		if not ok3 then
			return false, det3;
		end
	end
	return true, "";
end

function AssignStartingPlots:LekGlobalSix_OK_Section4_TwoCoastalGeoCycle()
	if self.iNumCivs ~= 6 then
		return true, "n/a_iNumCivs_ne_6";
	end
	local iW, iH = Map.GetGridSize();
	local cx = math.floor(iW / 2);
	local cy = math.floor(iH / 2);
	local function isCoastalForCycleRule(x, y)
		local m = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsAtXY(self, x, y);
		return m.alongOcean == true;
	end
	local slots = {};
	for r = 1, 6 do
		local t = self.startingPlots[r];
		if not t or type(t[1]) ~= "number" or type(t[2]) ~= "number" then
			return false, "missing_r=" .. tostring(r);
		end
		local x, y = t[1], t[2];
		local isC = isCoastalForCycleRule(x, y);
		local ang = math.atan2(y - cy, x - cx);
		slots[#slots + 1] = { r = r, ang = ang, coastal = isC };
	end
	table.sort(slots, function(a, b)
		if a.ang ~= b.ang then
			return a.ang < b.ang;
		end
		return a.r < b.r;
	end);
	local coastalPos = {};
	for i = 1, 6 do
		if slots[i].coastal then
			coastalPos[#coastalPos + 1] = i;
		end
	end
	local nC = #coastalPos;
	local forceExactTwo = (self.BalancedCoastalExactTwo == true) and (self.ForceAllInlandPlayerSpawns ~= true);
	if forceExactTwo then
		if nC ~= 2 then
			return false, "force2_need_exactly2_got=" .. tostring(nC) .. "_def=saltOcean";
		end
	else
		if nC ~= 2 then
			return true, "n/a_coastalCount=" .. tostring(nC) .. "_def=saltOcean";
		end
	end
	return true, "geoAngleOrder_twoC";
end

function AssignStartingPlots.LekGlobalSix_OK_EvaluateCandidateEarlyRejectReason(plotIndex)
	if _polar_merge_excluded_plots and _polar_merge_excluded_plots[plotIndex] then
		return "polar_merge_excluded";
	end
	if _fjord_peninsula_excluded_plots and _fjord_peninsula_excluded_plots[plotIndex] then
		return "fjord_peninsula_excluded";
	end
	local iW, iH = Map.GetGridSize();
	local x = (plotIndex - 1) % iW;
	local y = (plotIndex - x - 1) / iW;
	local distFromEdge = math.min(y, iH - 1 - y);
	if distFromEdge < 8 then
		return "edge_lt8";
	end
	local plot = Map.GetPlot(x, y);
	if not plot then
		return "nil_plot";
	end
	if plot:GetTerrainType() == TerrainTypes.TERRAIN_SNOW then
		return "snow";
	end
	return nil;
end

function AssignStartingPlots:LekGlobalSix_OK_Section6_SiteQuality_PostPlacement()
	local iW, iH = Map.GetGridSize();
	for r = 1, self.iNumCivs do
		local t = self.startingPlots[r];
		if not t or type(t[1]) ~= "number" or type(t[2]) ~= "number" then
			return false, "missing_r=" .. tostring(r);
		end
		local x, y = t[1], t[2];
		local plotIndex = y * iW + x + 1;
		local rt = self.regionTypes[r];
		if rt == nil then
			return false, "regionTypes_nil_r=" .. tostring(r);
		end
		local savedDD = self.distanceData[plotIndex];
		self.distanceData[plotIndex] = 0;
		local score, meetsMin = self:EvaluateCandidatePlot(plotIndex, rt);
		self.distanceData[plotIndex] = savedDD;
		if not meetsMin then
			local early = AssignStartingPlots.LekGlobalSix_OK_EvaluateCandidateEarlyRejectReason(plotIndex);
			if early then
				return false, string.format("r=%d plotIndex=%d score=%s early=%s", r, plotIndex, tostring(score), early);
			end
			return false, string.format("r=%d plotIndex=%d score=%s early=ok suspect=rings_junk_or_distancebias", r, plotIndex, tostring(score));
		end
	end
	return true, "mode=postplacement_eval_mask_own_impact_tile";
end

function AssignStartingPlots:LekGlobalSix_MeasureBiasConditionsAtXY(x, y)
	local iW, iH = Map.GetGridSize();
	if type(x) ~= "number" or type(y) ~= "number" or x < 0 or y < 0 or x >= iW or y >= iH then
		return { alongOcean = false, nextToLake = false, isRiver = false, nearRiver = false };
	end
	local plotIndex = y * iW + x + 1;
	local plot = Map.GetPlot(x, y);
	local alongOcean = (self.plotDataIsCoastal and self.plotDataIsCoastal[plotIndex] == true);
	local isRiver = (plot and plot:IsRiver()) or false;
	local nextToLake = false;
	local nearRiver = isRiver;
	local isEvenY = true;
	if y / 2 > math.floor(y / 2) then
		isEvenY = false;
	end
	local function scanRing(search_table)
		for loop, plot_adjustments in ipairs(search_table) do
			local searchX, searchY = self:ApplyHexAdjustment(x, y, plot_adjustments);
			if searchX >= 0 and searchX < iW and searchY >= 0 and searchY < iH then
				local searchPlot = Map.GetPlot(searchX, searchY);
				if searchPlot then
					if searchPlot:IsRiver() then
						nearRiver = true;
					end
					local plotType = searchPlot:GetPlotType();
					local featureType = searchPlot:GetFeatureType();
					if plotType == PlotTypes.PLOT_OCEAN and searchPlot:IsLake() and featureType ~= FeatureTypes.FEATURE_ICE then
						nextToLake = true;
					end
				end
			end
		end
	end
	local st1 = isEvenY and self.firstRingYIsEven or self.firstRingYIsOdd;
	local st2 = isEvenY and self.secondRingYIsEven or self.secondRingYIsOdd;
	if st1 then
		scanRing(st1);
	end
	if st2 then
		scanRing(st2);
	end
	return { alongOcean = alongOcean, nextToLake = nextToLake, isRiver = isRiver, nearRiver = nearRiver };
end

function AssignStartingPlots:LekGlobalSix_MeasureBiasConditionsNoNormalize(region_number)
	local t = self.startingPlots[region_number];
	if not t or type(t[1]) ~= "number" or type(t[2]) ~= "number" then
		return { alongOcean = false, nextToLake = false, isRiver = false, nearRiver = false };
	end
	return AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsAtXY(self, t[1], t[2]);
end

function AssignStartingPlots.LekGlobalSix_BuildEffectiveBiasPolicy(self)
	local policy = {
		coastal_required = {},
		target_coastal = nil,
	};
	if not self or (self.iNumCivs or 0) ~= 6 then
		return policy;
	end
	local pmeta = {};
	for loop = 1, 6 do
		local pid = self.player_ID_list[loop];
		local player = Players[pid];
		local row = player and GameInfo.Civilizations[player:GetCivilizationType()];
		local civType = row and row.Type;
		local natural = false;
		local placeFirst = false;
		if civType then
			natural = CivNeedsCoastalStart(civType) == true;
			placeFirst = CivNeedsPlaceFirstCoastalStart(civType) == true;
			if self.MixedBias and placeFirst then
				natural = false;
			end
		end
		pmeta[#pmeta + 1] = { pid = pid, natural = natural, placeFirst = placeFirst };
		if natural then
			policy.coastal_required[pid] = true;
		end
	end
	if self._lek_ignore_all_start_bias == true or self.ForceAllInlandPlayerSpawns == true then
		policy.target_coastal = 0;
		policy.coastal_required = {};
		return policy;
	end
	if self._lek_tuple_force_two_coastal_majors == true then
		policy.target_coastal = 2;
		local function countReq()
			local n = 0;
			for _, pm in ipairs(pmeta) do
				if policy.coastal_required[pm.pid] == true then
					n = n + 1;
				end
			end
			return n;
		end
		local function tier(pm)
			if pm.natural then
				return 0;
			end
			if pm.placeFirst then
				return 1;
			end
			return 10;
		end
		-- Prefer dropping non-natural coastal first; among same tier, pick at random
		-- (was highest pid — made demotion deterministic).
		while countReq() > 2 do
			local bestTier = -1;
			local cands = {};
			for _, pm in ipairs(pmeta) do
				if policy.coastal_required[pm.pid] == true then
					local t = tier(pm);
					if t > bestTier then
						bestTier = t;
						cands = { pm };
					elseif t == bestTier then
						cands[#cands + 1] = pm;
					end
				end
			end
			if #cands == 0 then
				break;
			end
			local drop = cands[1 + Map.Rand(#cands, "LekForce2 drop coastal pid - Lua")];
			policy.coastal_required[drop.pid] = nil;
		end
		-- Fill to exactly 2: natural coastal first (tier 0), then placeFirst (1), then
		-- plain inland (10). Same tier: random among eligibles (was lowest pid — always
		-- drafted slot 0/1 when an inland civ was needed).
		while countReq() < 2 do
			local bestTier = 999;
			local cands = {};
			for _, pm in ipairs(pmeta) do
				if policy.coastal_required[pm.pid] ~= true then
					local t = tier(pm);
					if t < bestTier then
						bestTier = t;
						cands = { pm };
					elseif t == bestTier then
						cands[#cands + 1] = pm;
					end
				end
			end
			if #cands == 0 then
				break;
			end
			local add = cands[1 + Map.Rand(#cands, "LekForce2 add coastal pid - Lua")];
			policy.coastal_required[add.pid] = true;
		end
	end
	return policy;
end

function AssignStartingPlots:LekGlobalSix_Section5_BuildPlayerBiasPlist()
	local policy = self._lek_g6_bias_policy;
	if type(policy) ~= "table" then
		policy = AssignStartingPlots.LekGlobalSix_BuildEffectiveBiasPolicy(self);
		self._lek_g6_bias_policy = policy;
	end
	local plist = {};
	for loop = 1, 6 do
		local playerNum = self.player_ID_list[loop];
		local player = Players[playerNum];
		if not player then
			return nil, "nil_player_pid=" .. tostring(playerNum);
		end
		local row = GameInfo.Civilizations[player:GetCivilizationType()];
		if not row then
			return nil, "nil_civinfo_pid=" .. tostring(playerNum);
		end
		local civType = row.Type;
		if self._lek_ignore_all_start_bias == true then
			plist[#plist + 1] = { tag = "flex", pid = playerNum };
		else
		local bNeedsCoastalStart = (policy.coastal_required and policy.coastal_required[playerNum] == true);
		if bNeedsCoastalStart then
			plist[#plist + 1] = { tag = "coastal", pid = playerNum };
		else
			local bNeedsRiverStart = CivNeedsRiverStart(civType);
			if bNeedsRiverStart then
				plist[#plist + 1] = { tag = "river", pid = playerNum };
			else
				local iNumRegionPriority = GetNumStartRegionPriorityForCiv(civType);
				if iNumRegionPriority > 0 then
					local pr = GetStartRegionPriorityListForCiv_GetIDs(civType);
					local len = table.maxn(pr) or 0;
					if len == 1 then
						plist[#plist + 1] = { tag = "pri1", pid = playerNum };
					elseif len > 1 then
						plist[#plist + 1] = { tag = "prim", pid = playerNum, pr = pr };
					else
						plist[#plist + 1] = { tag = "flex", pid = playerNum };
					end
				else
					local iNumRegionAvoid = GetNumStartRegionAvoidForCiv(civType);
					if iNumRegionAvoid > 0 then
						local av = GetStartRegionAvoidListForCiv_GetIDs(civType);
						plist[#plist + 1] = { tag = "avoid", pid = playerNum, av = av };
					else
						plist[#plist + 1] = { tag = "flex", pid = playerNum };
					end
				end
			end
		end
		end
	end
	if #plist ~= 6 then
		return nil, "internal_player_count_ne_6";
	end
	return plist, nil;
end

function AssignStartingPlots:LekGlobalSix_TupleBiasFeasibilityFromPools(byRegion)
	local stats = {
		nCoastalPlayers = 0,
		nRiverPlayers = 0,
		nRegionsCoastalCapable = 0,
		nRegionsRiverCapable = 0,
		nRegionsInlandCapable = 0,
		injective = 0,
		skippedOption = 0,
	};
	if self.iNumCivs ~= 6 then
		return true, "n/a_iNumCivs_ne_6", stats;
	end
	local okOpt, dsb = pcall(function()
		return Game.GetCustomOption("GAMEOPTION_DISABLE_START_BIAS");
	end);
	if okOpt and dsb == 1 then
		stats.skippedOption = 1;
		return true, "skipped_GAMEOPTION_DISABLE_START_BIAS", stats;
	end
	local enforceNC = AssignStartingPlots.LekGlobalSix_NoCoastInlandEnforced(self);
	local poolMeta = {};
	for r = 1, 6 do
		local cc, rc = false, false;
		local inl, rivInl = false, false;
		local br = byRegion[r];
		if br then
			for i = 1, #br do
				local c = br[i];
				local coastalM = (c.coastal_ok == true);
				local riverM = (c.river_ok == true);
				if c.coastal_ok == nil or c.river_ok == nil then
					local m = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsAtXY(self, c.x, c.y);
					coastalM = (m.alongOcean == true);
					riverM = (m.isRiver == true or m.nearRiver == true);
				end
				if coastalM then
					cc = true;
				end
				if riverM then
					rc = true;
				end
				if enforceNC then
					if not coastalM then
						inl = true;
						if riverM then
							rivInl = true;
						end
					end
				end
			end
		end
		if not enforceNC then
			inl = true;
			rivInl = rc;
		end
		poolMeta[r] = { canCoastal = cc, canRiver = rc, canInlandPool = inl, canRiverInlandPool = rivInl };
		if cc then
			stats.nRegionsCoastalCapable = stats.nRegionsCoastalCapable + 1;
		end
		if rc then
			stats.nRegionsRiverCapable = stats.nRegionsRiverCapable + 1;
		end
		if inl then
			stats.nRegionsInlandCapable = stats.nRegionsInlandCapable + 1;
		end
	end
	local plist, perr = AssignStartingPlots.LekGlobalSix_Section5_BuildPlayerBiasPlist(self);
	if not plist then
		return true, "gate_open_plist_err=" .. tostring(perr), stats;
	end
	for _, p in ipairs(plist) do
		if p.tag == "coastal" then
			stats.nCoastalPlayers = stats.nCoastalPlayers + 1;
		elseif p.tag == "river" then
			stats.nRiverPlayers = stats.nRiverPlayers + 1;
		end
	end
	if stats.nCoastalPlayers > stats.nRegionsCoastalCapable then
		stats.injective = 0;
		return false, "coastal_quota_pool_infeasible", stats;
	end
	local function okPrim(p, r)
		for _, rtNeed in ipairs(p.pr) do
			if self.regionTypes[r] == rtNeed then
				return true;
			end
		end
		return false;
	end
	local function okAvoid(p, r)
		for _, rtBad in ipairs(p.av) do
			if self.regionTypes[r] == rtBad then
				return false;
			end
		end
		return true;
	end
	local avoidHardF = (self._lek_global_six_s5_avoid_hard ~= false);
	local primHardF = (self._lek_global_six_s5_prim_hard ~= false);
	stats.s5avoidHard = avoidHardF and 1 or 0;
	stats.s5primHard = primHardF and 1 or 0;
	local function pred(p, r)
		local pm = poolMeta[r];
		if p.tag == "coastal" then
			return pm.canCoastal;
		elseif p.tag == "river" then
			if enforceNC then
				return pm.canRiverInlandPool;
			end
			return pm.canRiver;
		elseif p.tag == "pri1" then
			if enforceNC then
				return pm.canInlandPool;
			end
			return true;
		elseif p.tag == "prim" then
			if not primHardF then
				if enforceNC then
					return pm.canInlandPool;
				end
				return true;
			end
			if enforceNC then
				return okPrim(p, r) and pm.canInlandPool;
			end
			return okPrim(p, r);
		elseif p.tag == "avoid" then
			if not avoidHardF then
				if enforceNC then
					return pm.canInlandPool;
				end
				return true;
			end
			if enforceNC then
				return okAvoid(p, r) and pm.canInlandPool;
			end
			return okAvoid(p, r);
		end
		if enforceNC then
			return pm.canInlandPool;
		end
		return true;
	end
	local function countElig(p)
		local n = 0;
		for r = 1, 6 do
			if pred(p, r) then
				n = n + 1;
			end
		end
		return n;
	end
	table.sort(plist, function(a, b)
		local ca, cb = countElig(a), countElig(b);
		if ca ~= cb then
			return ca < cb;
		end
		return a.pid < b.pid;
	end);
	local tagOrd = {};
	local eligOrd = {};
	for _, p in ipairs(plist) do
		tagOrd[#tagOrd + 1] = p.tag;
		eligOrd[#eligOrd + 1] = tostring(countElig(p));
	end
	stats.matchingOrderTags = table.concat(tagOrd, ",");
	stats.matchingOrderEligRegionCount = table.concat(eligOrd, ",");
	stats.minEligRegionsAmongPlayers = 6;
	for i = 1, #eligOrd do
		local n = tonumber(eligOrd[i]);
		if n ~= nil and n < stats.minEligRegionsAmongPlayers then
			stats.minEligRegionsAmongPlayers = n;
		end
	end
	local occ = {};
	local function dfsMatch(k)
		if k > #plist then
			return true;
		end
		local p = plist[k];
		for r = 1, 6 do
			if not occ[r] and pred(p, r) then
				occ[r] = true;
				if dfsMatch(k + 1) then
					return true;
				end
				occ[r] = false;
			end
		end
		return false;
	end
	local ok = dfsMatch(1);
	stats.injective = ok and 1 or 0;
	return ok, ok and "pool_meta_injective_ok" or "no_injective_civ_to_region_with_pool_capabilities", stats;
end

function AssignStartingPlots:LekGlobalSix_OK_Section5_BalanceAndAssignFeasible()
	if self.iNumCivs ~= 6 then
		return true, "n/a_iNumCivs_ne_6";
	end
	local okOpt, dsb = pcall(function()
		return Game.GetCustomOption("GAMEOPTION_DISABLE_START_BIAS");
	end);
	if okOpt and dsb == 1 then
		return true, "skipped_GAMEOPTION_DISABLE_START_BIAS";
	end
	local meta = {};
	for r = 1, 6 do
		meta[r] = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsNoNormalize(self, r);
	end
	local plist, perr = AssignStartingPlots.LekGlobalSix_Section5_BuildPlayerBiasPlist(self);
	if not plist then
		return false, tostring(perr or "plist_nil");
	end
	local function okCoastal(r)
		return meta[r].alongOcean;
	end
	local function okRiver(r)
		return meta[r].isRiver or meta[r].nearRiver;
	end
	local function okPrim(p, r)
		for _, rtNeed in ipairs(p.pr) do
			if self.regionTypes[r] == rtNeed then
				return true;
			end
		end
		return false;
	end
	local function okAvoid(p, r)
		for _, rtBad in ipairs(p.av) do
			if self.regionTypes[r] == rtBad then
				return false;
			end
		end
		return true;
	end
	local avoidHard = (self._lek_global_six_s5_avoid_hard ~= false);
	local primHard = (self._lek_global_six_s5_prim_hard ~= false);
	local enforceNC = AssignStartingPlots.LekGlobalSix_NoCoastInlandEnforced(self);
	local function okNonCoastalLand(r)
		return not okCoastal(r);
	end
	local nCoastalPlayers = 0;
	for _, p in ipairs(plist) do
		if p.tag == "coastal" then
			nCoastalPlayers = nCoastalPlayers + 1;
		end
	end
	local nCoastalRegions = 0;
	for r = 1, 6 do
		if okCoastal(r) then
			nCoastalRegions = nCoastalRegions + 1;
		end
	end
	if nCoastalPlayers > nCoastalRegions then
		return false, "coastal_quota_assignment_infeasible players="
			.. tostring(nCoastalPlayers) .. " regions=" .. tostring(nCoastalRegions);
	end
	local function pred(p, r)
		if p.tag == "coastal" then
			return okCoastal(r);
		elseif p.tag == "river" then
			if enforceNC then
				return okRiver(r) and okNonCoastalLand(r);
			end
			return okRiver(r);
		elseif p.tag == "pri1" then
			if enforceNC then
				return okNonCoastalLand(r);
			end
			return true;
		elseif p.tag == "prim" then
			if not primHard then
				if enforceNC then
					return okNonCoastalLand(r);
				end
				return true;
			end
			if enforceNC then
				return okPrim(p, r) and okNonCoastalLand(r);
			end
			return okPrim(p, r);
		elseif p.tag == "avoid" then
			if not avoidHard then
				if enforceNC then
					return okNonCoastalLand(r);
				end
				return true;
			end
			if enforceNC then
				return okAvoid(p, r) and okNonCoastalLand(r);
			end
			return okAvoid(p, r);
		end
		if enforceNC then
			return okNonCoastalLand(r);
		end
		return true;
	end
	local function countElig(p)
		local n = 0;
		for r = 1, 6 do
			if pred(p, r) then
				n = n + 1;
			end
		end
		return n;
	end
	table.sort(plist, function(a, b)
		local ca, cb = countElig(a), countElig(b);
		if ca ~= cb then
			return ca < cb;
		end
		return a.pid < b.pid;
	end);
	local occ = {};
	local function dfs(k)
		if k > #plist then
			return true;
		end
		local p = plist[k];
		for r = 1, 6 do
			if not occ[r] and pred(p, r) then
				occ[r] = true;
				if dfs(k + 1) then
					return true;
				end
				occ[r] = false;
			end
		end
		return false;
	end
	if not dfs(1) then
		return false, "no_injective_civ_region_matching_coastal_river_priority_avoid";
	end
	local det = "backtrack_mixedBias_coastalClear_if_placeFirst_MeasureNoNormalize";
	if not avoidHard then
		det = det .. " avoidSoft_coastalRiverStillHard";
	end
	if not primHard then
		det = det .. " primSoft_coastalRiverStillHard";
	end
	return true, det;
end

function AssignStartingPlots:LekGlobalSix_OK_RunAll()
	local ok1, det1 = AssignStartingPlots.LekGlobalSix_OK_Section1_CentreBand(self);
	local ok2, det2 = AssignStartingPlots.LekGlobalSix_OK_Section2_d2(self);
	local ok3, det3 = AssignStartingPlots.LekGlobalSix_OK_Section3_InlandSalt(self);
	local ok4, det4 = true, "disabled_pre_solver_coastal_quota_gate";
	local ok5, det5 = AssignStartingPlots.LekGlobalSix_OK_Section5_BalanceAndAssignFeasible(self);
	local ok6, det6 = AssignStartingPlots.LekGlobalSix_OK_Section6_SiteQuality_PostPlacement(self);
	local first_fail, first_det = nil, "";
	if not ok1 then
		first_fail, first_det = "s1", det1;
	elseif not ok2 then
		first_fail, first_det = "s2", det2;
	elseif not ok3 then
		first_fail, first_det = "s3", det3;
	elseif not ok5 then
		first_fail, first_det = "s5", det5;
	elseif not ok6 then
		first_fail, first_det = "s6", det6;
	end
	local all_hard_pass = ok1 and ok2 and ok3 and ok4 and ok5 and ok6;
	local failed_sections = {};
	if not ok1 then
		failed_sections[#failed_sections + 1] = "s1";
	end
	if not ok2 then
		failed_sections[#failed_sections + 1] = "s2";
	end
	if not ok3 then
		failed_sections[#failed_sections + 1] = "s3";
	end
	if not ok5 then
		failed_sections[#failed_sections + 1] = "s5";
	end
	if not ok6 then
		failed_sections[#failed_sections + 1] = "s6";
	end
	local fail_combo_key = (#failed_sections > 0) and table.concat(failed_sections, "+") or "";
	return {
		s1_ok = ok1,
		s1_det = det1,
		s2_ok = ok2,
		s2_det = det2,
		s3_ok = ok3,
		s3_det = det3,
		s4_ok = ok4,
		s4_det = det4,
		s5_ok = ok5,
		s5_det = det5,
		s6_ok = ok6,
		s6_det = det6,
		first_fail = first_fail,
		first_fail_detail = first_det,
		all_hard_pass = all_hard_pass,
		failed_sections = failed_sections,
		fail_combo_key = fail_combo_key,
	};
end

function AssignStartingPlots:LekGlobalSix_OK_LogDiagnostics()
	local rid = tostring(_lek_run_id or "na");
	local R = AssignStartingPlots.LekGlobalSix_OK_RunAll(self);
	local dLo = self._lek_g6_runtime_s1_min or self._lek_ok_diag_last_tuple_phase_s1min or LEK_G6_S1_D_MIN;
	local dHi = self._lek_g6_runtime_s1_max or self._lek_ok_diag_last_tuple_phase_s1max or LEK_G6_S1_D_MAX;
	local s2cap = self._lek_g6_runtime_s2_max or self._lek_ok_diag_last_tuple_phase_s2max or LEK_G6_S2_SECOND_NEAREST_MAX;
	local mp = AssignStartingPlots.LekGlobalSix_MinPairwiseDistanceFromStartDistanceOption();
	local mpStr = "_minPair_ge" .. tostring(mp);
	LekPlacementProbeLog("### LekGlobalSix_OK diag runId=" .. rid ..
		" spec=SCRATCHPAD-placement-spec-v0.11 first_fail=" .. tostring(R.first_fail or "none") ..
		" all_hard_pass=" .. (R.all_hard_pass and "1" or "0") ..
		" s1_centre_" .. tostring(dLo) .. "_" .. tostring(dHi) .. "=" .. (R.s1_ok and "pass" or "fail") .. " " .. tostring(R.s1_det) ..
		" s2_secondNearest_le" .. tostring(s2cap) .. mpStr .. "=" .. (R.s2_ok and "pass" or "fail") .. " " .. tostring(R.s2_det) ..
		" s3_inland_salt_dLe3_max4=" .. (R.s3_ok and "pass" or "fail") .. " " .. tostring(R.s3_det) ..
		" s4_twoCoastal_geoCycle_mesh=disabled " .. tostring(R.s4_det) ..
		" s5_bias_BAndA_feasible=" .. (R.s5_ok and "pass" or "fail") .. " " .. tostring(R.s5_det) ..
		" s6_EvaluateCandidate_meets_minimums=" .. (R.s6_ok and "pass" or "fail") .. " " .. tostring(R.s6_det));
end

function AssignStartingPlots:LekGlobalSix_LogRuleAuditAfterTupleCommit()
	if self.iNumCivs ~= 6 then
		return;
	end
	local rid = tostring(_lek_run_id or "na");
	local minD = nil;
	for i = 1, 6 do
		local ti = self.startingPlots[i];
		if not ti or type(ti[1]) ~= "number" or type(ti[2]) ~= "number" then
			LekPlacementProbeLog("### LekGlobalSix ruleAuditAfterTuple runId=" .. rid .. " status=incomplete_starts", 2);
			return;
		end
		for j = i + 1, 6 do
			local tj = self.startingPlots[j];
			if not tj or type(tj[1]) ~= "number" or type(tj[2]) ~= "number" then
				LekPlacementProbeLog("### LekGlobalSix ruleAuditAfterTuple runId=" .. rid .. " status=incomplete_starts", 2);
				return;
			end
			local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, ti[1], ti[2], tj[1], tj[2]);
			if d == nil then
				LekPlacementProbeLog("### LekGlobalSix ruleAuditAfterTuple runId=" .. rid .. " status=no_PlotDistance", 2);
				return;
			end
			if minD == nil or d < minD then
				minD = d;
			end
		end
	end
	local dReq = AssignStartingPlots.LekGlobalSix_MinPairwiseDistanceFromStartDistanceOption();
	local pairwiseOk = true;
	if type(dReq) == "number" and dReq >= 2 then
		for i = 1, 6 do
			local ti = self.startingPlots[i];
			if not ti or type(ti[1]) ~= "number" or type(ti[2]) ~= "number" then
				pairwiseOk = false;
				break;
			end
			for j = i + 1, 6 do
				local tj = self.startingPlots[j];
				if not tj or type(tj[1]) ~= "number" or type(tj[2]) ~= "number" then
					pairwiseOk = false;
					break;
				end
				local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, ti[1], ti[2], tj[1], tj[2]);
				if d == nil then
					pairwiseOk = false;
					break;
				end
				local req = AssignStartingPlots.LekGlobalSix_MinPairRequiredPlotDistForTuple(self, ti[1], ti[2], tj[1], tj[2], dReq);
				if d < req then
					pairwiseOk = false;
					break;
				end
			end
			if not pairwiseOk then
				break;
			end
		end
	end
	local nCoastR = 0;
	for r = 1, 6 do
		local m = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsNoNormalize(self, r);
		local isC = (m.alongOcean == true);
		if isC then
			nCoastR = nCoastR + 1;
		end
	end
	LekPlacementProbeLog("### LekGlobalSix ruleAuditAfterTuple runId=" .. rid ..
		" scope=region_slots" ..
		" minPlotDist=" .. tostring(minD) ..
		" minRequiredPairwisePlotDist=" .. tostring(dReq) ..
		" pairwiseOk=" .. (pairwiseOk and "1" or "0") ..
		" regionsCoastalLike=" .. tostring(nCoastR) ..
		" noCoastInlandEnforced=" .. (AssignStartingPlots.LekGlobalSix_NoCoastInlandEnforced(self) and "1" or "0"), 2);
end

function AssignStartingPlots:LekGlobalSix_LogRuleAuditAfterPlayers()
	if self.iNumCivs ~= 6 then
		return;
	end
	local rid = tostring(_lek_run_id or "na");
	local dsb = LekSafeGetDisableStartBiasOption();
	if dsb == 1 then
		LekPlacementProbeLog("### LekGlobalSix ruleAuditAfterPlayers runId=" .. rid .. " status=skipped_GAMEOPTION_DISABLE_START_BIAS", 2);
		return;
	end
	local plist, perr = AssignStartingPlots.LekGlobalSix_Section5_BuildPlayerBiasPlist(self);
	if not plist then
		LekPlacementProbeLog("### LekGlobalSix ruleAuditAfterPlayers runId=" .. rid .. " status=plist_err_" .. tostring(perr), 2);
		return;
	end
	local enforceNC = AssignStartingPlots.LekGlobalSix_NoCoastInlandEnforced(self);
	local avoidHard = (self._lek_global_six_s5_avoid_hard ~= false);
	local primHard = (self._lek_global_six_s5_prim_hard ~= false);
	local function okCoastalMeta(m)
		return m.alongOcean == true;
	end
	local function okRiverMeta(m)
		return (m.isRiver or m.nearRiver) == true;
	end
	local function okPrimMeta(p, r)
		if not p.pr then
			return false;
		end
		for _, rtNeed in ipairs(p.pr) do
			if self.regionTypes[r] == rtNeed then
				return true;
			end
		end
		return false;
	end
	local function okAvoidMeta(p, r)
		if not p.av then
			return true;
		end
		for _, rtBad in ipairs(p.av) do
			if self.regionTypes[r] == rtBad then
				return false;
			end
		end
		return true;
	end
	local function regionIndexForStartXY(x, y)
		for r = 1, 6 do
			local t = self.startingPlots[r];
			if t and t[1] == x and t[2] == y then
				return r;
			end
		end
		return nil;
	end
	local viol = 0;
	local parts = {};
	local minD = nil;
	local pairwiseOk = true;
	local dReq = AssignStartingPlots.LekGlobalSix_MinPairwiseDistanceFromStartDistanceOption();
	for i = 1, 6 do
		for j = i + 1, 6 do
			local pi = Players[self.player_ID_list[i]];
			local pj = Players[self.player_ID_list[j]];
			if not pi or not pj then
			else
				local spi, spj = pi:GetStartingPlot(), pj:GetStartingPlot();
				if spi and spj then
					local x1, y1 = spi:GetX(), spi:GetY();
					local x2, y2 = spj:GetX(), spj:GetY();
					local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, x1, y1, x2, y2);
					if d and (minD == nil or d < minD) then
						minD = d;
					end
					if type(dReq) == "number" and dReq >= 2 and d then
						local req = AssignStartingPlots.LekGlobalSix_MinPairRequiredPlotDistForTuple(self, x1, y1, x2, y2, dReq);
						if d < req then
							pairwiseOk = false;
						end
					end
				end
			end
		end
	end
	for _, p in ipairs(plist) do
		local player = Players[p.pid];
		local sp = player and player:GetStartingPlot();
		if not sp then
			viol = viol + 1;
			parts[#parts + 1] = "pid" .. tostring(p.pid) .. "=no_plot";
		else
			local x, y = sp:GetX(), sp:GetY();
			local m = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsAtXY(self, x, y);
			local reg = regionIndexForStartXY(x, y);
			local bad = false;
			local why = {};
			if p.tag == "coastal" then
				if not okCoastalMeta(m) then
					bad = true;
					why[#why + 1] = "need_coastal";
				end
			elseif p.tag == "river" then
				if not okRiverMeta(m) then
					bad = true;
					why[#why + 1] = "need_river";
				end
				if enforceNC and okCoastalMeta(m) then
					bad = true;
					why[#why + 1] = "noCoastInland_violation";
				end
			else
				if enforceNC and okCoastalMeta(m) then
					bad = true;
					why[#why + 1] = "noCoastInland_violation";
				end
				if p.tag == "prim" and primHard and reg and not okPrimMeta(p, reg) then
					bad = true;
					why[#why + 1] = "prim_hard";
				end
				if p.tag == "avoid" and avoidHard and reg and not okAvoidMeta(p, reg) then
					bad = true;
					why[#why + 1] = "avoid_hard";
				end
			end
			if bad then
				viol = viol + 1;
			end
			local w = (#why > 0) and table.concat(why, "+") or "ok";
			parts[#parts + 1] = string.format("pid%d=%s:%s:c%s", p.pid, p.tag, w, okCoastalMeta(m) and "1" or "0");
		end
	end
	LekPlacementProbeLog("### LekGlobalSix ruleAuditAfterPlayers runId=" .. rid ..
		" scope=final_player_plots" ..
		" violations=" .. tostring(viol) ..
		" minPlotDist=" .. tostring(minD) ..
		" minRequiredPairwisePlotDist=" .. tostring(dReq) ..
		" pairwiseOk=" .. (pairwiseOk and "1" or "0") ..
		" noCoastInlandEnforced=" .. (enforceNC and "1" or "0") ..
		" detail=" .. table.concat(parts, ";"), 2);
end

local function LekGlobalSix_CopyBufferFields()
	return {
		"distanceData",
		"playerCollisionData",
		"cityStateData",
		"strategicData",
		"luxuryData",
		"bonusData",
		"fishData",
		"naturalWondersData",
		"marbleData",
		"seaOilData",
		"uraniumData",
		"sheepData",
	};
end

function AssignStartingPlots:LekGlobalSix_SnapshotPlaceImpactState()
	local iW, iH = Map.GetGridSize();
	local n = iW * iH;
	local snap = { n = n, layers = {} };
	for _, name in ipairs(LekGlobalSix_CopyBufferFields()) do
		local src = self[name];
		local cpy = {};
		for i = 1, n do
			cpy[i] = src[i];
		end
		snap.layers[name] = cpy;
	end
	return snap;
end

function AssignStartingPlots:LekGlobalSix_RestorePlaceImpactState(snap)
	if not snap or not snap.layers then
		return;
	end
	local n = snap.n;
	for _, name in ipairs(LekGlobalSix_CopyBufferFields()) do
		local src = snap.layers[name];
		local dst = self[name];
		if src and dst then
			for i = 1, n do
				dst[i] = src[i];
			end
		end
	end
end

function AssignStartingPlots:LekGlobalSix_TiebreakMaxCentrDeviation()
	local iW, iH = Map.GetGridSize();
	local cx = math.floor(iW / 2);
	local cy = math.floor(iH / 2);
	local worst = 0;
	for r = 1, 6 do
		local sp = self.startingPlots[r];
		local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, sp[1], sp[2], cx, cy);
		if not d then
			return math.huge;
		end
		local dev = math.abs(d - LEK_G6_S1_TARGET_D);
		if dev > worst then
			worst = dev;
		end
	end
	return worst;
end

function AssignStartingPlots:LekGlobalSix_CountMaskedMeetsMinOutsideInsideCentreBand(region_r)
	local list = AssignStartingPlots.LekGlobalSix_GatherTupleStyleCandidateIndices(self, region_r, false);
	local rt = self.regionTypes[region_r];
	if not rt then
		return 0, 0, nil, nil;
	end
	local iW, iH = Map.GetGridSize();
	local cx = math.floor(iW / 2);
	local cy = math.floor(iH / 2);
	local maskedAll = 0;
	local inBand = 0;
	local dLo, dHi = nil, nil;
	for idx = 1, #list do
		local plotIndex = list[idx];
		local x = (plotIndex - 1) % iW;
		local y = (plotIndex - x - 1) / iW;
		local savedDD = self.distanceData[plotIndex];
		self.distanceData[plotIndex] = 0;
		local score, meetsMin = self:EvaluateCandidatePlot(plotIndex, rt);
		self.distanceData[plotIndex] = savedDD;
		if meetsMin then
			maskedAll = maskedAll + 1;
			local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, x, y, cx, cy);
			if d then
				if dLo == nil or d < dLo then dLo = d; end
				if dHi == nil or d > dHi then dHi = d; end
				local bandLo = self._lek_g6_runtime_s1_min or LEK_G6_S1_D_MIN;
				local bandHi = self._lek_g6_runtime_s1_max or LEK_G6_S1_D_MAX;
				if d >= bandLo and d <= bandHi then
					inBand = inBand + 1;
				end
			end
		end
	end
	return maskedAll, inBand, dLo, dHi;
end

function AssignStartingPlots:LekGlobalSix_LogTupleProbeLayerSnapshot()
	local rid = tostring(_lek_run_id or "na");
	local iW, iH = Map.GetGridSize();
	local n = iW * iH;
	local ddPos, ddMax = 0, 0;
	local pcPos, csPos = 0, 0;
	for i = 1, n do
		local v = self.distanceData[i];
		if type(v) == "number" and v > 0 then
			ddPos = ddPos + 1;
			if v > ddMax then ddMax = v; end
		end
		if self.playerCollisionData[i] == true then
			pcPos = pcPos + 1;
		end
		local cs = self.cityStateData[i];
		if type(cs) == "number" and cs > 0 then
			csPos = csPos + 1;
		end
	end
	LekPlacementProbeLog("### LekGlobalSix tupleProbeLayer runId=" .. rid ..
		" grid=" .. tostring(iW) .. "x" .. tostring(iH) ..
		" distanceData_gt0=" .. tostring(ddPos) .. " distanceData_max=" .. tostring(ddMax) ..
		" playerCollision_true=" .. tostring(pcPos) ..
		" cityStateData_gt0=" .. tostring(csPos));
end

function AssignStartingPlots:LekGlobalSix_TuplePoolDiagCollect(region_r)
	local list = AssignStartingPlots.LekGlobalSix_GatherTupleStyleCandidateIndices(self, region_r, false);
	local rt = self.regionTypes[region_r];
	local rawN = #list;
	local iW, iH = Map.GetGridSize();
	local cx = math.floor(iW / 2);
	local cy = math.floor(iH / 2);
	local rawCoastal = 0;
	local rawInS1band = 0;
	local rawInBandCoastal = 0;
	local meetsMinAll = 0;
	local meetsMinInS1band = 0;
	local inBandButFailsMeetsMin = 0;
	local dLo, dHi = nil, nil;
	for idx = 1, rawN do
		local plotIndex = list[idx];
		if self.plotDataIsCoastal[plotIndex] == true then
			rawCoastal = rawCoastal + 1;
		end
		local x = (plotIndex - 1) % iW;
		local y = (plotIndex - x - 1) / iW;
		local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, x, y, cx, cy);
		local bandLo = self._lek_g6_runtime_s1_min or LEK_G6_S1_D_MIN;
		local bandHi = self._lek_g6_runtime_s1_max or LEK_G6_S1_D_MAX;
		local inBand = d and d >= bandLo and d <= bandHi;
		if inBand then
			rawInS1band = rawInS1band + 1;
			if self.plotDataIsCoastal[plotIndex] == true then
				rawInBandCoastal = rawInBandCoastal + 1;
			end
		end
		if not rt then
		else
			local savedDD = self.distanceData[plotIndex];
			self.distanceData[plotIndex] = 0;
			local _, meetsMin = self:EvaluateCandidatePlot(plotIndex, rt);
			self.distanceData[plotIndex] = savedDD;
			if meetsMin then
				meetsMinAll = meetsMinAll + 1;
				if d then
					if dLo == nil or d < dLo then dLo = d; end
					if dHi == nil or d > dHi then dHi = d; end
				end
				if inBand then
					meetsMinInS1band = meetsMinInS1band + 1;
				end
			elseif inBand then
				inBandButFailsMeetsMin = inBandButFailsMeetsMin + 1;
			end
		end
	end
	local rangeStr = "na";
	if dLo ~= nil and dHi ~= nil then
		rangeStr = tostring(dLo) .. "-" .. tostring(dHi);
	end
	local cap = self._lek_global_six_max_candidates_per_region;
	if type(cap) ~= "number" or cap < 1 then
		cap = 36;
	end
	return {
		rawN = rawN,
		rawCoastal = rawCoastal,
		rawInS1band = rawInS1band,
		rawInBandCoastal = rawInBandCoastal,
		meetsMinAll = meetsMinAll,
		meetsMinInS1band = meetsMinInS1band,
		inBandButFailsMeetsMin = inBandButFailsMeetsMin,
		meetsMinDRange = rangeStr,
		cap = cap,
	};
end

function AssignStartingPlots:LekGlobalSix_LogTuplePoolDiagLine(region_r, searchOrderedN)
	local rid = tostring(_lek_run_id or "na");
	local D = AssignStartingPlots.LekGlobalSix_TuplePoolDiagCollect(self, region_r);
	local rt = self.regionTypes[region_r];
	LekPlacementProbeAt(3, "### LekGlobalSix tuplePoolDiag runId=" .. rid ..
		" region=" .. tostring(region_r) ..
		" regionType=" .. tostring(rt) ..
		" rawTupleStyleN=" .. tostring(D.rawN) ..
		" rawCoastalN=" .. tostring(D.rawCoastal) ..
		" rawInS1band=" .. tostring(D.rawInS1band) ..
		" rawInBand_coastalN=" .. tostring(D.rawInBandCoastal) ..
		" meetsMin_maskOwnDD=" .. tostring(D.meetsMinAll) ..
		" meetsMin_inS1band=" .. tostring(D.meetsMinInS1band) ..
		" inS1band_butNotMeetsMin=" .. tostring(D.inBandButFailsMeetsMin) ..
		" meetsMin_dCenterRange=" .. D.meetsMinDRange ..
		" searchOrderedN=" .. tostring(searchOrderedN) ..
		" perRegionCap=" .. tostring(D.cap) ..
		" note=tupleUses_NoCoastFalse_coastExcl_nextToCoast_and_threeFromCoast");
end

function AssignStartingPlots:LekGlobalSix_LogTuplePoolSpatial(region_r, pool)
	if not pool or #pool < 1 then
		return;
	end
	local rid = tostring(_lek_run_id or "na");
	local n = #pool;
	local xmin, xmax, ymin, ymax = pool[1].x, pool[1].x, pool[1].y, pool[1].y;
	local xyParts = {};
	for i = 1, n do
		local c = pool[i];
		if c.x < xmin then xmin = c.x; end
		if c.x > xmax then xmax = c.x; end
		if c.y < ymin then ymin = c.y; end
		if c.y > ymax then ymax = c.y; end
		xyParts[#xyParts + 1] = tostring(c.x) .. "," .. tostring(c.y);
	end
	local bboxW = xmax - xmin + 1;
	local bboxH = ymax - ymin + 1;
	local pairSum, pairCnt = 0, 0;
	local pairMin, pairMax = nil, nil;
	local nnSum, nnCnt = 0, 0;
	if n >= 2 then
		for i = 1, n - 1 do
			for j = i + 1, n do
				local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, pool[i].x, pool[i].y, pool[j].x, pool[j].y);
				if type(d) == "number" then
					pairCnt = pairCnt + 1;
					pairSum = pairSum + d;
					if pairMin == nil or d < pairMin then pairMin = d; end
					if pairMax == nil or d > pairMax then pairMax = d; end
				end
			end
		end
		for i = 1, n do
			local best = nil;
			for j = 1, n do
				if i ~= j then
					local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, pool[i].x, pool[i].y, pool[j].x, pool[j].y);
					if type(d) == "number" and (best == nil or d < best) then
						best = d;
					end
				end
			end
			if best ~= nil then
				nnCnt = nnCnt + 1;
				nnSum = nnSum + best;
			end
		end
	end
	local pairMean = (pairCnt > 0) and (pairSum / pairCnt) or nil;
	local nnMean = (nnCnt > 0) and (nnSum / nnCnt) or nil;
	local pm = pairMean and string.format("%.2f", pairMean) or "na";
	local pmi = pairMin and tostring(pairMin) or "na";
	local pma = pairMax and tostring(pairMax) or "na";
	local nnm = nnMean and string.format("%.2f", nnMean) or "na";
	LekPlacementProbeAt(3, "### LekGlobalSix tuplePoolSpatial runId=" .. rid ..
		" region=" .. tostring(region_r) ..
		" n=" .. tostring(n) ..
		" bboxMinMax=" .. tostring(xmin) .. "," .. tostring(ymin) .. ".." .. tostring(xmax) .. "," .. tostring(ymax) ..
		" bboxWH=" .. tostring(bboxW) .. "x" .. tostring(bboxH) ..
		" pairPlotDist_min=" .. pmi .. " mean=" .. pm .. " max=" .. pma ..
		" nnPlotDist_mean=" .. nnm ..
		" hint=low_nnMean_tight_clump_high_spread" ..
		" xy=" .. table.concat(xyParts, ";"));
end

function AssignStartingPlots:LekGlobalSix_CoastalCountInSearchPool(byRegion, region_r)
	local list = byRegion[region_r];
	if not list then
		return 0;
	end
	local c = 0;
	for i = 1, #list do
		local pi = list[i].plotIndex;
		if self.plotDataIsCoastal[pi] == true then
			c = c + 1;
		end
	end
	return c;
end

function AssignStartingPlots:LekGlobalSix_RegionMinCoastalBandDeviationForTuple(byRegion, region_r)
	local list = byRegion[region_r];
	if not list or #list == 0 then
		return 999999;
	end
	local iW, iH = Map.GetGridSize();
	local cx = math.floor(iW / 2);
	local cy = math.floor(iH / 2);
	local dLo = self._lek_g6_runtime_s1_min or LEK_G6_S1_D_MIN;
	local dHi = self._lek_g6_runtime_s1_max or LEK_G6_S1_D_MAX;
	local best = nil;
	for i = 1, #list do
		local c = list[i];
		local isCoast = (c.coastal_ok == true);
		if c.coastal_ok == nil then
			local m = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsAtXY(self, c.x, c.y);
			isCoast = (m.alongOcean == true);
		end
		if isCoast then
			local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, c.x, c.y, cx, cy);
			if d and d >= dLo and d <= dHi then
				local dev = math.abs(d - LEK_G6_S1_TARGET_D);
				if best == nil or dev < best then
					best = dev;
				end
			end
		end
	end
	if best == nil then
		return 999999;
	end
	return best;
end

function AssignStartingPlots.LekGlobalSix_DfsFeasMarginTiebreak(self, a, b)
	local m = self._lek_g6_feas_margin_by_region;
	if type(m) ~= "table" or self._lek_global_six_tuple_dfs_feas_margin == false then
		return nil;
	end
	local ma = m[a];
	local mb = m[b];
	if type(ma) ~= "number" or type(mb) ~= "number" then
		return nil;
	end
	if ma ~= mb then
		return ma < mb;
	end
	return nil;
end

function AssignStartingPlots:LekGlobalSix_BuildTupleDepthOrder(byRegion)
	local depthOrder = { 1, 2, 3, 4, 5, 6 };
	local thinFirst = (self._lek_global_six_dfs_thin_first ~= false);
	local constraintWeighted = (self._lek_global_six_dfs_constraint_weighted ~= false);
	local layoutN = tonumber(_lek_map_layout_attempt);
	if type(layoutN) ~= "number" or layoutN < 1 then
		layoutN = 1;
	end
	local coastalRingFirst = (layoutN <= 5) and (self._lek_global_six_tuple_coastal_ring_first_dfs ~= false);
	local mode;
	if thinFirst and constraintWeighted then
		mode = coastalRingFirst and "coastal_ring_then_thin_then_coastal_tight" or "thin_then_coastal_tight";
		table.sort(depthOrder, function(a, b)
			if coastalRingFirst then
				local qa = AssignStartingPlots.LekGlobalSix_RegionMinCoastalBandDeviationForTuple(self, byRegion, a);
				local qb = AssignStartingPlots.LekGlobalSix_RegionMinCoastalBandDeviationForTuple(self, byRegion, b);
				if qa ~= qb then
					return qa < qb;
				end
			end
			local na, nb = #byRegion[a], #byRegion[b];
			if na ~= nb then
				return na < nb;
			end
			local ca = AssignStartingPlots.LekGlobalSix_CoastalCountInSearchPool(self, byRegion, a);
			local cb = AssignStartingPlots.LekGlobalSix_CoastalCountInSearchPool(self, byRegion, b);
			if ca ~= cb then
				return ca < cb;
			end
			local ft = AssignStartingPlots.LekGlobalSix_DfsFeasMarginTiebreak(self, a, b);
			if ft ~= nil then
				return ft;
			end
			return a < b;
		end);
	elseif thinFirst then
		mode = coastalRingFirst and "coastal_ring_then_thin_only" or "thin_first_only";
		table.sort(depthOrder, function(a, b)
			if coastalRingFirst then
				local qa = AssignStartingPlots.LekGlobalSix_RegionMinCoastalBandDeviationForTuple(self, byRegion, a);
				local qb = AssignStartingPlots.LekGlobalSix_RegionMinCoastalBandDeviationForTuple(self, byRegion, b);
				if qa ~= qb then
					return qa < qb;
				end
			end
			local na, nb = #byRegion[a], #byRegion[b];
			if na ~= nb then
				return na < nb;
			end
			local ft = AssignStartingPlots.LekGlobalSix_DfsFeasMarginTiebreak(self, a, b);
			if ft ~= nil then
				return ft;
			end
			return a < b;
		end);
	else
		if coastalRingFirst then
			mode = "coastal_ring_then_fixed_r";
			table.sort(depthOrder, function(a, b)
				local qa = AssignStartingPlots.LekGlobalSix_RegionMinCoastalBandDeviationForTuple(self, byRegion, a);
				local qb = AssignStartingPlots.LekGlobalSix_RegionMinCoastalBandDeviationForTuple(self, byRegion, b);
				if qa ~= qb then
					return qa < qb;
				end
				local ft = AssignStartingPlots.LekGlobalSix_DfsFeasMarginTiebreak(self, a, b);
				if ft ~= nil then
					return ft;
				end
				return a < b;
			end);
		else
			mode = "fixed_r1_r6";
		end
	end
	if type(self._lek_g6_feas_margin_by_region) == "table" and self._lek_global_six_tuple_dfs_feas_margin ~= false
		and mode ~= "fixed_r1_r6"
	then
		mode = tostring(mode) .. "+feasMarg";
	end
	local keyParts = {};
	for ri = 1, 6 do
		local rr = depthOrder[ri];
		local nc = AssignStartingPlots.LekGlobalSix_CoastalCountInSearchPool(self, byRegion, rr);
		keyParts[#keyParts + 1] = string.format("r%d=n%d/c%d", rr, #byRegion[rr], nc);
	end
	return depthOrder, mode, table.concat(keyParts, ";");
end

function AssignStartingPlots:LekGlobalSix_LogTupleHeadGeometry(byRegion)
	local rid = tostring(_lek_run_id or "na");
	local heads = {};
	local seg = {};
	for r = 1, 6 do
		local list = byRegion[r];
		local c = list and list[1];
		if not c then
			LekPlacementProbeAt(1, "### LekGlobalSix tupleHeadGeom runId=" .. rid .. " error=missing_head r=" .. tostring(r));
			return;
		end
		heads[r] = { x = c.x, y = c.y };
		seg[#seg + 1] = string.format(
			"r%d=x%d,y%d pi=%d dMapC=%s ringDev=%s score=%s",
			r, c.x, c.y, c.plotIndex, tostring(c.dMapCenter), tostring(c.ringDev), tostring(c.score));
	end
	LekPlacementProbeAt(3, "### LekGlobalSix tupleHeadCells runId=" .. rid .. " " .. table.concat(seg, "; "));
	local pw = {};
	for i = 1, 6 do
		for j = i + 1, 6 do
			local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, heads[i].x, heads[i].y, heads[j].x, heads[j].y);
			pw[#pw + 1] = string.format("d%d_%d=%s", i, j, d and tostring(d) or "na");
		end
	end
	LekPlacementProbeAt(3, "### LekGlobalSix tupleHeadPairwise runId=" .. rid .. " " .. table.concat(pw, " "));
	local snParts = {};
	for ri = 1, 6 do
		local dists = {};
		for j = 1, 6 do
			if j ~= ri then
				local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, heads[ri].x, heads[ri].y, heads[j].x, heads[j].y);
				if d then
					dists[#dists + 1] = d;
				end
			end
		end
		table.sort(dists);
		local d2 = dists[2];
		snParts[#snParts + 1] = string.format("r%d=%s", ri, d2 ~= nil and tostring(d2) or "na");
	end
	local s2cap = self._lek_g6_runtime_s2_max or LEK_G6_S2_SECOND_NEAREST_MAX;
	LekPlacementProbeAt(3, "### LekGlobalSix tupleHeadSecondNearest runId=" .. rid ..
		" " .. table.concat(snParts, " ") ..
		" s2_cap=" .. tostring(s2cap));
end

function AssignStartingPlots:LekGlobalSix_Rank1HeadFirstS2Violator(byRegion, s2cap)
	if type(s2cap) ~= "number" then
		return nil, nil;
	end
	local heads = {};
	for r = 1, 6 do
		local list = byRegion[r];
		local c = list and list[1];
		if not c then
			return nil, nil;
		end
		heads[r] = { x = c.x, y = c.y };
	end
	for ri = 1, 6 do
		local dists = {};
		for j = 1, 6 do
			if j ~= ri then
				local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, heads[ri].x, heads[ri].y, heads[j].x, heads[j].y);
				if d then
					dists[#dists + 1] = d;
				end
			end
		end
		table.sort(dists);
		local d2 = dists[2];
		if d2 ~= nil and d2 > s2cap then
			return ri, d2;
		end
	end
	return nil, nil;
end

function AssignStartingPlots:LekGlobalSix_ForceGeometryPackMetrics(pack, targetD)
	local iW, iH = Map.GetGridSize();
	local cx = math.floor(iW / 2);
	local cy = math.floor(iH / 2);
	local per = {};
	local minPair = 999999;
	for i = 1, 6 do
		local a = pack[i];
		if not a or type(a[1]) ~= "number" or type(a[2]) ~= "number" then
			return nil;
		end
		for j = i + 1, 6 do
			local b = pack[j];
			local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, a[1], a[2], b[1], b[2]);
			if d ~= nil and d < minPair then
				minPair = d;
			end
		end
	end
	local maxD2 = -1;
	local minCenter = 999999;
	local maxCenterDev = -1;
	local sumCenterDev = 0;
	for r = 1, 6 do
		local a = pack[r];
		local dCenter = AssignStartingPlots.LekGlobalSix_PlotDistance(self, a[1], a[2], cx, cy);
		local dists = {};
		for j = 1, 6 do
			if j ~= r then
				local b = pack[j];
				local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, a[1], a[2], b[1], b[2]);
				if d ~= nil then
					dists[#dists + 1] = d;
				end
			end
		end
		table.sort(dists);
		local d1 = dists[1] or 999999;
		local d2 = dists[2] or 999999;
		local m = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsAtXY(self, a[1], a[2]);
		local dev = math.abs((dCenter or targetD) - targetD);
		per[r] = {
			x = a[1],
			y = a[2],
			dCenter = dCenter,
			d1 = d1,
			d2 = d2,
			coastal = (m.alongOcean == true),
		};
		if d2 > maxD2 then
			maxD2 = d2;
		end
		if dCenter ~= nil and dCenter < minCenter then
			minCenter = dCenter;
		end
		if dev > maxCenterDev then
			maxCenterDev = dev;
		end
		sumCenterDev = sumCenterDev + dev;
	end
	return {
		per = per,
		maxD2 = maxD2,
		minCenter = minCenter,
		minPair = minPair,
		maxCenterDev = maxCenterDev,
		avgCenterDev = sumCenterDev / 6,
		targetD = targetD,
	};
end

function AssignStartingPlots:LekGlobalSix_ForceGeometryBiasFit(pack)
	if type(pack) ~= "table" then
		return true, 0, 0, "na";
	end
	local plist, perr = AssignStartingPlots.LekGlobalSix_Section5_BuildPlayerBiasPlist(self);
	if not plist then
		return true, 0, 0, "plist_err_" .. tostring(perr or "na");
	end
	local rmeta = {};
	for r = 1, 6 do
		local p = pack[r];
		if p and type(p[1]) == "number" and type(p[2]) == "number" then
			local m = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsAtXY(self, p[1], p[2]);
			rmeta[r] = {
				coastal = (m.alongOcean == true),
				river = (m.isRiver == true or m.nearRiver == true),
				rt = self.regionTypes[r],
			};
		else
			return false, 0, 0, "pack_incomplete";
		end
	end
	local function regionMatchesPrim(p, r)
		local rt = rmeta[r].rt;
		for _, rtNeed in ipairs(p.pr or {}) do
			if rt == rtNeed then
				return true;
			end
		end
		return false;
	end
	local function regionPassesAvoid(p, r)
		local rt = rmeta[r].rt;
		for _, rtBad in ipairs(p.av or {}) do
			if rt == rtBad then
				return false;
			end
		end
		return true;
	end
	local function hardOK(p, r)
		if p.tag == "coastal" then
			return rmeta[r].coastal == true;
		end
		return true;
	end
	local function softScore(p, r)
		if p.tag == "river" then
			return rmeta[r].river and 1 or 0, 1;
		elseif p.tag == "pri1" then
			local ok = regionMatchesPrim(p, r);
			return ok and 2 or 0, 2;
		elseif p.tag == "prim" then
			local ok = regionMatchesPrim(p, r);
			return ok and 1 or 0, 1;
		elseif p.tag == "avoid" then
			local ok = regionPassesAvoid(p, r);
			return ok and 1 or 0, 1;
		end
		return 0, 0;
	end
	local function hardEligCount(p)
		local n = 0;
		for r = 1, 6 do
			if hardOK(p, r) then
				n = n + 1;
			end
		end
		return n;
	end
	table.sort(plist, function(a, b)
		local ca, cb = hardEligCount(a), hardEligCount(b);
		if ca ~= cb then
			return ca < cb;
		end
		return a.pid < b.pid;
	end);
	local occ = {};
	local bestScore = -999999;
	local bestMax = 0;
	local bestAssign = nil;
	local function dfs(k, score, maxScore, assign)
		if k > #plist then
			if score > bestScore then
				bestScore = score;
				bestMax = maxScore;
				bestAssign = {};
				for pid, reg in pairs(assign) do
					bestAssign[pid] = reg;
				end
			end
			return;
		end
		local p = plist[k];
		local moved = false;
		for r = 1, 6 do
			if not occ[r] and hardOK(p, r) then
				moved = true;
				occ[r] = true;
				local s, m = softScore(p, r);
				assign[p.pid] = r;
				dfs(k + 1, score + s, maxScore + m, assign);
				assign[p.pid] = nil;
				occ[r] = false;
			end
		end
		if not moved then
			return;
		end
	end
	dfs(1, 0, 0, {});
	if bestScore < 0 then
		return false, 0, 0, "coastal_hard_no_matching", nil, nil;
	end
	local coastalPids = {};
	for _, p in ipairs(plist) do
		if p.tag == "coastal" then
			coastalPids[#coastalPids + 1] = p.pid;
		end
	end
	table.sort(coastalPids);
	return true, bestScore, bestMax, "ok", bestAssign, coastalPids;
end

function AssignStartingPlots:LekGlobalSix_ForceGeometryPackFromPools(byRegion, depthOrder)
	local function isEngineSafeStartCandidate(c)
		if c == nil or type(c.x) ~= "number" or type(c.y) ~= "number" then
			return false;
		end
		local p = Map.GetPlot(c.x, c.y);
		if not p then
			return false;
		end
		if p:IsWater() then
			return false;
		end
		if p:IsImpassable() then
			return false;
		end
		local a = p:GetArea();
		if not a then
			return false;
		end
		return true;
	end

	local sampleN = tonumber(self._lek_global_six_force_geometry_sample_count);
	if type(sampleN) ~= "number" or sampleN < 1 then
		sampleN = 120;
	end
	local candCap = tonumber(self._lek_global_six_force_geometry_candidate_cap);
	if type(candCap) ~= "number" or candCap < 1 then
		candCap = 36;
	end
	local targetD = tonumber(self._lek_global_six_force_geometry_target_center_d);
	if type(targetD) ~= "number" or targetD < 1 then
		targetD = LEK_G6_S1_TARGET_D;
	end
	local bandMin = tonumber(self._lek_global_six_force_geometry_center_band_min);
	local bandMax = tonumber(self._lek_global_six_force_geometry_center_band_max);
	if type(bandMin) ~= "number" then
		bandMin = 12;
	end
	if type(bandMax) ~= "number" then
		bandMax = 16;
	end
	if bandMin > bandMax then
		local tmp = bandMin;
		bandMin = bandMax;
		bandMax = tmp;
	end
	local dMinPairOpt6 = AssignStartingPlots.LekGlobalSix_MinPairwiseDistanceFromStartDistanceOption();
	if type(dMinPairOpt6) ~= "number" or dMinPairOpt6 < 2 then
		dMinPairOpt6 = LEK_G6_MIN_PAIRWISE_PLOTDIST_FALLBACK;
	end
	local forceExactTwoCoastal = (self.BalancedCoastalExactTwo == true) and (self.ForceAllInlandPlayerSpawns ~= true);
	local function countCoastalInPack(pack)
		local n = 0;
		for _, t in pairs(pack or {}) do
			if t and type(t[1]) == "number" and type(t[2]) == "number" then
				local m = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsAtXY(self, t[1], t[2]);
				if m and m.alongOcean == true then
					n = n + 1;
				end
			end
		end
		return n;
	end
	local function filterPoolForForceTwoCoastal(pool, wantCoastalOnly, wantInlandOnly)
		if not forceExactTwoCoastal then
			return pool;
		end
		if not wantCoastalOnly and not wantInlandOnly then
			return pool;
		end
		local out = {};
		for i = 1, #pool do
			local c = pool[i];
			local m = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsAtXY(self, c.x, c.y);
			local isC = (m and m.alongOcean == true);
			if wantCoastalOnly and isC then
				out[#out + 1] = c;
			elseif wantInlandOnly and not isC then
				out[#out + 1] = c;
			end
		end
		return out;
	end
	local pools = {};
	for r = 1, 6 do
		local src = byRegion[r] or {};
		local lim = math.min(#src, candCap);
		local inBand = {};
		local fallback = {};
		for i = 1, lim do
			local c = src[i];
			if isEngineSafeStartCandidate(c) then
				fallback[#fallback + 1] = c;
				local d = tonumber(c.dMapCenter);
				if d ~= nil and d >= bandMin and d <= bandMax then
					inBand[#inBand + 1] = c;
				end
			end
		end
		if #inBand > 0 then
			pools[r] = inBand;
		elseif #fallback > 0 then
			pools[r] = fallback;
		else
			return nil, nil, sampleN, candCap, bandMin, bandMax;
		end
	end
	local function pickUniqueCompatible(pool, used, pack, depth, coastalSoFar)
		local placed = depth - 1;
		local rem = 6 - placed;
		local needC = 2 - coastalSoFar;
		local needI = 4 - (placed - coastalSoFar);
		local wantCoastalOnly = false;
		local wantInlandOnly = false;
		if forceExactTwoCoastal then
			if needC > rem or needI > rem then
				return nil, nil;
			end
			if needC == rem then
				wantCoastalOnly = true;
			elseif needI == rem then
				wantInlandOnly = true;
			end
		end
		pool = filterPoolForForceTwoCoastal(pool, wantCoastalOnly, wantInlandOnly);
		local n = #pool;
		if n < 1 then
			return nil, nil;
		end
		local start = 1 + Map.Rand(n, "LekForceGeomPickStart");
		for off = 0, n - 1 do
			local idx = ((start + off - 1) % n) + 1;
			local c = pool[idx];
			local ck = tostring(c.plotIndex or (tostring(c.x) .. "," .. tostring(c.y)));
			if not used[ck] then
				local ok = true;
				for r2, t2 in pairs(pack) do
					if t2 and type(t2[1]) == "number" and type(t2[2]) == "number" then
						local dxy = AssignStartingPlots.LekGlobalSix_PlotDistance(self, c.x, c.y, t2[1], t2[2]);
						local req = AssignStartingPlots.LekGlobalSix_MinPairRequiredPlotDistForTuple(self, c.x, c.y, t2[1], t2[2], dMinPairOpt6);
						if dxy ~= nil and req ~= nil and dxy < req then
							ok = false;
							break;
						end
					end
				end
				if ok then
					return c, ck;
				end
			end
		end
		return nil, nil;
	end
	local bestPack = nil;
	local bestMetrics = nil;
	local feasibleSamples = 0;
	for si = 1, sampleN do
		local used = {};
		local pack = {};
		local okPack = true;
		for depth = 1, 6 do
			local r = depthOrder[depth];
			local pool = pools[r];
			local coastalSoFar = countCoastalInPack(pack);
			local c, ck = pickUniqueCompatible(pool, used, pack, depth, coastalSoFar);
			if not c then
				okPack = false;
				break;
			end
			used[ck] = true;
			pack[r] = { c.x, c.y, c.score };
		end
		if okPack and forceExactTwoCoastal and countCoastalInPack(pack) ~= 2 then
			okPack = false;
		end
		if okPack then
			local m = AssignStartingPlots.LekGlobalSix_ForceGeometryPackMetrics(self, pack, targetD);
			if m ~= nil then
				local biasOk, bScore, bMax, bDet, bAssign, bCoastalPids = AssignStartingPlots.LekGlobalSix_ForceGeometryBiasFit(self, pack);
				if biasOk then
					feasibleSamples = feasibleSamples + 1;
					m.biasSoftScore = bScore;
					m.biasSoftMax = bMax;
					m.biasSoftDet = bDet;
					m.biasAssignPidRegion = bAssign;
					m.biasCoastalPids = bCoastalPids;
					m.samplesTried = sampleN;
					m.samplesFeasible = feasibleSamples;
					m.centerBandMin = bandMin;
					m.centerBandMax = bandMax;
				if bestMetrics == nil
					or m.maxD2 < bestMetrics.maxD2
					or (m.maxD2 == bestMetrics.maxD2 and m.minPair > bestMetrics.minPair)
					or (m.maxD2 == bestMetrics.maxD2 and m.minPair == bestMetrics.minPair and m.biasSoftScore > (bestMetrics.biasSoftScore or -999999))
					or (m.maxD2 == bestMetrics.maxD2 and m.minPair == bestMetrics.minPair and m.biasSoftScore == (bestMetrics.biasSoftScore or -999999) and m.maxCenterDev < bestMetrics.maxCenterDev)
				then
					bestMetrics = m;
					bestPack = pack;
				end
				end
			end
		end
	end
	return bestPack, bestMetrics, sampleN, candCap, bandMin, bandMax;
end

function AssignStartingPlots:LekGlobalSix_LogForceGeometryPack(rid, phaseIdx, phaseName, metrics, sampleN, candCap, bandMin, bandMax)
	if type(metrics) ~= "table" or type(metrics.per) ~= "table" then
		return;
	end
	LekPlacementProbeAt(1, "### LekGlobalSix forceGeom runId=" .. tostring(rid) ..
		" phaseIndex=" .. tostring(phaseIdx) ..
		" name=" .. tostring(phaseName) ..
		" samples=" .. tostring(sampleN) ..
		" candCap=" .. tostring(candCap) ..
		" centerBand=" .. tostring(bandMin) .. "-" .. tostring(bandMax) ..
		" targetD=" .. tostring(metrics.targetD) ..
		" maxCenterDev=" .. tostring(metrics.maxCenterDev) ..
		" avgCenterDev=" .. string.format("%.3f", metrics.avgCenterDev or 0) ..
		" minCenter=" .. tostring(metrics.minCenter) ..
		" maxSecondNearest=" .. tostring(metrics.maxD2) ..
		" minPair=" .. tostring(metrics.minPair) ..
		" biasSoftScore=" .. tostring(metrics.biasSoftScore or 0) ..
		" biasSoftMax=" .. tostring(metrics.biasSoftMax or 0) ..
		" samplesFeasible=" .. tostring(metrics.samplesFeasible or 0) ..
		" biasDet=" .. tostring(metrics.biasSoftDet or "na"));
	local dC, d1, d2, coast = {}, {}, {}, {};
	for r = 1, 6 do
		local p = metrics.per[r];
		if p then
			dC[#dC + 1] = "r" .. tostring(r) .. ":" .. tostring(p.dCenter);
			d1[#d1 + 1] = "r" .. tostring(r) .. ":" .. tostring(p.d1);
			d2[#d2 + 1] = "r" .. tostring(r) .. ":" .. tostring(p.d2);
			coast[#coast + 1] = "r" .. tostring(r) .. ":" .. tostring(p.coastal and "true" or "false");
			LekPlacementProbeAt(1, "### LekGlobalSix forceGeomSlot runId=" .. tostring(rid) ..
				" r=" .. tostring(r) ..
				" x=" .. tostring(p.x) ..
				" y=" .. tostring(p.y) ..
				" coastal=" .. tostring(p.coastal and "true" or "false") ..
				" dCenter=" .. tostring(p.dCenter) ..
				" d1=" .. tostring(p.d1) ..
				" d2=" .. tostring(p.d2));
		end
	end
	LekPlacementProbeAt(1, "### LekGlobalSix forceGeomVectors runId=" .. tostring(rid) ..
		" dCenter=[" .. table.concat(dC, ",") .. "]" ..
		" d1=[" .. table.concat(d1, ",") .. "]" ..
		" d2=[" .. table.concat(d2, ",") .. "]" ..
		" coastal=[" .. table.concat(coast, ",") .. "]" ..
		" overallMaxSecondNearest=" .. tostring(metrics.maxD2) ..
		" overallMinCenter=" .. tostring(metrics.minCenter));
end

function AssignStartingPlots:LekGlobalSix_LogForceBiasAssignmentAudit()
	local expected = self._lek_force_expected_pid_region;
	if type(expected) ~= "table" then
		return;
	end
	local expPids = {};
	for pid, _ in pairs(expected) do
		expPids[#expPids + 1] = tonumber(pid) or pid;
	end
	table.sort(expPids);
	local expParts = {};
	for _, pid in ipairs(expPids) do
		expParts[#expParts + 1] = tostring(pid) .. "->r" .. tostring(expected[pid]);
	end
	local actual = {};
	local allPids = {};
	local seenPid = {};
	for _, pid in ipairs(self.player_ID_list or {}) do
		allPids[#allPids + 1] = pid;
		seenPid[pid] = true;
	end
	for pid, _ in pairs(expected) do
		if not seenPid[pid] then
			allPids[#allPids + 1] = pid;
		end
	end
	table.sort(allPids);
	for _, pid in ipairs(allPids) do
		local player = LekSafeMajorPlayer(pid);
		if player then
			local sp = player:GetStartingPlot();
			if sp then
				local sx, sy = sp:GetX(), sp:GetY();
				local hitR = nil;
				for r = 1, 6 do
					local t = self.startingPlots[r];
					if t and type(t[1]) == "number" and type(t[2]) == "number" and t[1] == sx and t[2] == sy then
						hitR = r;
						break;
					end
				end
				actual[pid] = hitR or "na";
			else
				actual[pid] = "none";
			end
		else
			actual[pid] = "nil_player";
		end
	end
	local actParts = {};
	local mismatch = 0;
	for _, pid in ipairs(allPids) do
		actParts[#actParts + 1] = tostring(pid) .. "->r" .. tostring(actual[pid]);
		local ex = expected[pid];
		if ex ~= nil and tostring(ex) ~= tostring(actual[pid]) then
			mismatch = mismatch + 1;
		end
	end
	local coastalPids = self._lek_force_expected_coastal_pids;
	local coastalStr = "na";
	if type(coastalPids) == "table" then
		local cpy = {};
		for i = 1, #coastalPids do
			cpy[#cpy + 1] = tostring(coastalPids[i]);
		end
		coastalStr = table.concat(cpy, ",");
	end
	LekPlacementProbeAt(1, "### LekGlobalSix forceBiasAudit runId=" .. tostring(_lek_run_id or "na") ..
		" expected=[" .. table.concat(expParts, ",") .. "]" ..
		" actual=[" .. table.concat(actParts, ",") .. "]" ..
		" expectedCoastalPids=[" .. coastalStr .. "]" ..
		" mismatch=" .. tostring(mismatch));
end

function AssignStartingPlots:LekGlobalSix_ForceApplyExpectedPlayerStarts()
	if self._lek_global_six_force_geometry_only ~= true then
		return;
	end
	local expected = self._lek_force_expected_pid_region;
	if type(expected) ~= "table" then
		return;
	end
	local applied = 0;
	local miss = 0;
	for pid, region in pairs(expected) do
		local r = tonumber(region);
		local t = (r and self.startingPlots[r]) or nil;
		if t and type(t[1]) == "number" and type(t[2]) == "number" then
			local p = Map.GetPlot(t[1], t[2]);
			local pl = LekSafeMajorPlayer(pid);
			if p and pl then
				pl:SetStartingPlot(p);
				applied = applied + 1;
			else
				miss = miss + 1;
			end
		else
			miss = miss + 1;
		end
	end
	LekPlacementProbeAt(1, "### LekGlobalSix forceBiasApply runId=" .. tostring(_lek_run_id or "na")
		.. " applied=" .. tostring(applied) .. " missing=" .. tostring(miss));
end

function AssignStartingPlots:LekGlobalSix_TuplePoolFeasProbeRun(byRegion, s2cap, phaseIdx, phaseName, rid)
	if self._lek_global_six_tuple_pool_feas_probe == false then
		return;
	end
	if type(s2cap) ~= "number" then
		s2cap = self._lek_g6_runtime_s2_max or LEK_G6_S2_SECOND_NEAREST_MAX;
	end
	local kTop = tonumber(self._lek_global_six_feas_probe_topk);
	if type(kTop) ~= "number" or kTop < 1 then
		kTop = 4;
	end
	local dReq = AssignStartingPlots.LekGlobalSix_MinPairwiseDistanceFromStartDistanceOption();
	if type(dReq) ~= "number" or dReq < 2 then
		dReq = LEK_G6_MIN_PAIRWISE_PLOTDIST_FALLBACK;
	end

	local crossCache = {};
	local function minCrossSlices(r1, r2)
		if r1 > r2 then
			r1, r2 = r2, r1;
		end
		local ck = crossCache[r1];
		if ck and ck[r2] ~= nil then
			return ck[r2];
		end
		local p1 = byRegion[r1];
		local p2 = byRegion[r2];
		if not p1 or not p2 then
			return nil;
		end
		local n1 = math.min(kTop, #p1);
		local n2 = math.min(kTop, #p2);
		if n1 < 1 or n2 < 1 then
			return nil;
		end
		local best = 999999;
		for i = 1, n1 do
			for j = 1, n2 do
				local a = p1[i];
				local b = p2[j];
				local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, a.x, a.y, b.x, b.y);
				if type(d) == "number" and d < best then
					best = d;
				end
			end
		end
		crossCache[r1] = crossCache[r1] or {};
		crossCache[r1][r2] = best;
		return best;
	end

	local poolNs = {};
	local minPool, maxPool = 999999, -1;
	local thinRs = {};
	for r = 1, 6 do
		local n = #(byRegion[r] or {});
		poolNs[r] = n;
		if n < minPool then
			minPool = n;
		end
		if n > maxPool then
			maxPool = n;
		end
		if n <= 1 then
			thinRs[#thinRs + 1] = r;
		end
	end

	local heads = {};
	for r = 1, 6 do
		local c = byRegion[r] and byRegion[r][1];
		if not c then
			_lek_bench_feas_bn = "no_head";
			_lek_bench_feas_xmin = "na";
			_lek_bench_feas_h2max = "na";
			_lek_bench_feas_margmin = "na";
			_lek_bench_feas_k = tostring(kTop);
			LekPlacementProbeLog("### LekGlobalSix tuplePoolFeasProbe runId=" .. rid ..
				" phaseIndex=" .. tostring(phaseIdx) ..
				" name=" .. tostring(phaseName or "?") ..
				" status=abort_missing_head");
			return;
		end
		heads[r] = c;
	end

	local headPairMin = 999999;
	for i = 1, 6 do
		for j = i + 1, 6 do
			local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, heads[i].x, heads[i].y, heads[j].x, heads[j].y);
			if type(d) == "number" and d < headPairMin then
				headPairMin = d;
			end
		end
	end

	local headMinD2, headMaxD2 = 999999, -1;
	local headViolR, headViolD2 = nil, nil;
	for ri = 1, 6 do
		local dists = {};
		for j = 1, 6 do
			if j ~= ri then
				local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, heads[ri].x, heads[ri].y, heads[j].x, heads[j].y);
				if type(d) == "number" then
					dists[#dists + 1] = d;
				end
			end
		end
		table.sort(dists);
		local d2 = dists[2];
		if d2 ~= nil then
			if d2 < headMinD2 then
				headMinD2 = d2;
			end
			if d2 > headMaxD2 then
				headMaxD2 = d2;
			end
			if d2 > s2cap and headViolR == nil then
				headViolR, headViolD2 = ri, d2;
			end
		end
	end
	if headMinD2 > 900000 then
		headMinD2 = -1;
	end
	if headMaxD2 < 0 then
		headMaxD2 = -1;
	end

	local crossGlobal = nil;
	local weakI, weakJ = nil, nil;
	for i = 1, 6 do
		for j = i + 1, 6 do
			local mc = minCrossSlices(i, j);
			if type(mc) == "number" then
				if crossGlobal == nil or mc < crossGlobal then
					crossGlobal = mc;
					weakI, weakJ = i, j;
				end
			end
		end
	end

	local marginByR = {};
	local margMin = 999999;
	for r = 1, 6 do
		local worst = 999999;
		for j = 1, 6 do
			if j ~= r then
				local mc = minCrossSlices(r, j);
				if type(mc) == "number" and mc < worst then
					worst = mc;
				end
			end
		end
		marginByR[r] = worst;
		if worst < margMin then
			margMin = worst;
		end
	end
	self._lek_g6_feas_margin_by_region = marginByR;

	local bottleneck = "none";
	local bnNote = "";
	if #thinRs > 0 then
		bottleneck = "thin_pool";
		local tp = {};
		for _, x in ipairs(thinRs) do
			tp[#tp + 1] = tostring(x);
		end
		bnNote = "one_cell_regions=" .. table.concat(tp, ",");
	elseif headViolR ~= nil then
		bottleneck = "s2_heads";
		bnNote = "violator_r=" .. tostring(headViolR) .. " d2=" .. tostring(headViolD2) .. ">s2max=" .. tostring(s2cap);
	elseif crossGlobal ~= nil and crossGlobal < dReq then
		bottleneck = "minpair_topK";
		bnNote = "weakPair=" .. tostring(weakI) .. "," .. tostring(weakJ) ..
			" crossTopK=" .. tostring(crossGlobal) .. "<minPairReq=" .. tostring(dReq);
	end

	local pn = {};
	for r = 1, 6 do
		pn[#pn + 1] = "r" .. tostring(r) .. "=" .. tostring(poolNs[r]);
	end
	local mg = {};
	for r = 1, 6 do
		mg[#mg + 1] = "r" .. tostring(r) .. "=" .. tostring(marginByR[r]);
	end

	_lek_bench_feas_bn = bottleneck;
	_lek_bench_feas_xmin = (crossGlobal ~= nil) and tostring(crossGlobal) or "na";
	_lek_bench_feas_h2max = (headMaxD2 >= 0) and tostring(headMaxD2) or "na";
	_lek_bench_feas_margmin = (margMin < 900000) and tostring(margMin) or "na";
	_lek_bench_feas_k = tostring(kTop);

	LekPlacementProbeLog("### LekGlobalSix tuplePoolFeasProbe runId=" .. rid ..
		" phaseIndex=" .. tostring(phaseIdx) ..
		" name=" .. tostring(phaseName or "?") ..
		" kTop=" .. tostring(kTop) ..
		" minPairReq=" .. tostring(dReq) ..
		" s2max=" .. tostring(s2cap) ..
		" poolMin=" .. tostring(minPool) ..
		" poolMax=" .. tostring(maxPool) ..
		" pools{" .. table.concat(pn, ";") .. "}" ..
		" headPairMin=" .. tostring(headPairMin) ..
		" headSecondD2{min=" .. tostring(headMinD2) .. ",max=" .. tostring(headMaxD2) .. "}" ..
		" crossMinTopK=" .. ((crossGlobal ~= nil) and tostring(crossGlobal) or "na") ..
		" weakPair=" .. ((weakI ~= nil) and (tostring(weakI) .. "," .. tostring(weakJ)) or "na") ..
		" margMin=" .. tostring(margMin) ..
		" margins{" .. table.concat(mg, ";") .. "}" ..
		" bottleneck=" .. bottleneck ..
		" " .. bnNote ..
		" note=headGeometry_is_rank1_only_crossMinTopK_is_min_over_regionPairs_bestInTopK_slices_dfsTiebreak_uses_margins");
end

function AssignStartingPlots.LekGlobalSix_DefaultTupleRelaxationPhases()
	return {
		{ name = "base", max_fail_complete = 1000, max_leaf_evals = 8000, s1_min = LEK_G6_S1_D_MIN, s1_max = LEK_G6_S1_D_MAX, s2_max = LEK_G6_S2_SECOND_NEAREST_MAX },
		{ name = "s2_plus_1", max_fail_complete = 1000, max_leaf_evals = 8000, s1_min = LEK_G6_S1_D_MIN, s1_max = LEK_G6_S1_D_MAX, s2_max = LEK_G6_S2_SECOND_NEAREST_MAX + 1 },
		{ name = "s2_plus_2", max_fail_complete = 1000, max_leaf_evals = 8000, s1_min = LEK_G6_S1_D_MIN, s1_max = LEK_G6_S1_D_MAX, s2_max = LEK_G6_S2_SECOND_NEAREST_MAX + 2 },
		{ name = "s2_plus_2_s1_relax_max", max_fail_complete = 1000, max_leaf_evals = 8000, s1_min = LEK_G6_S1_D_MIN, s1_max = LEK_G6_S1_RELAX_MAX, s2_max = LEK_G6_S2_SECOND_NEAREST_MAX + 2 },
	};
end

--[[
	Geometry UI — LekMapGetCustomOption(13) in LekmapPangaeaFractal.lua StartPlotSystem:

	1 Legacy: _lek_global_six_skip_tuple_use_legacy = true; tuple skipped; HB legacy placement.
	2 Global six: _lek_global_six_force_geometry_only = true uses sampled force-geometry packs (no tuple DFS). With force off and
	solver on, LekGlobalSix_RunTupleSearch aborts to legacy (tuple DFS removed). _lek_global_six_tuple_regen_on_solver_fail
	controls layout regen on failure when applicable.

	_one_map_placement_mode_: fractal/island outer redraws unchanged; on a fixed land mask, extra tuple phases hunt harder on the
	same geometry and AssignStartingPlots.LekGlobalSix_CanRequestLayoutRegenForPlacementGate suppresses HB layout regen from
	placement/resource asserts (Pangaea max-outer failure in BalanceAndAssign still may request regen).
]]
function AssignStartingPlots.LekGlobalSix_CanRequestLayoutRegenForPlacementGate(startDb)
	local db = startDb;
	if _lek_enable_hb_generatemap_regen_loop ~= true then
		return false;
	end
	if db ~= nil and db._lek_global_six_one_map_placement_mode == true then
		return false;
	end
	return true;
end

function AssignStartingPlots.LekGlobalSix_SlowPaceLayoutGeometryBoost(layoutN)
	if type(layoutN) ~= "number" or layoutN < 6 then
		return 0, 0;
	end
	local b = layoutN - 5;
	return math.min(b, 10), math.min(math.floor(b / 2), 5);
end

function AssignStartingPlots:LekGlobalSix_FallbackSearchCandidateForRegion(region_r)
	local tupleNoCoast = (self.ForceAllInlandPlayerSpawns == true);
	local list = AssignStartingPlots.LekGlobalSix_GatherTupleStyleCandidateIndices(self, region_r, tupleNoCoast);
	local rt = self.regionTypes[region_r];
	if not rt then
		return nil;
	end
	local iW, iH = Map.GetGridSize();
	local cx = math.floor(iW / 2);
	local cy = math.floor(iH / 2);
	local best = nil;
	local bestRank = nil;
	for idx = 1, #list do
		local plotIndex = list[idx];
		local x = (plotIndex - 1) % iW;
		local y = (plotIndex - x - 1) / iW;
		local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, x, y, cx, cy);
		if d then
			local ringDev = math.abs(d - LEK_G6_S1_TARGET_D);
			local savedDD = self.distanceData[plotIndex];
			self.distanceData[plotIndex] = 0;
			local score, meetsMin = self:EvaluateCandidatePlot(plotIndex, rt);
			self.distanceData[plotIndex] = savedDD;
			local okSalt, _ = AssignStartingPlots.LekGlobalSix_OK_InlandSaltCell(self, plotIndex, nil);
			local passDisk = AssignStartingPlots.LekGlobalSix_CoastalCandidatePassesSaltWaterDiskPct(self, plotIndex);
			local rank = ringDev * 1000000 - score;
			if okSalt and passDisk
				and (best == nil or rank < bestRank or (rank == bestRank and plotIndex < best.plotIndex)) then
				bestRank = rank;
				best = {
					plotIndex = plotIndex,
					x = x,
					y = y,
					score = score,
					ringDev = ringDev,
					dMapCenter = d,
					meetsMin = meetsMin,
				};
			end
		end
	end
	return best;
end

function AssignStartingPlots:LekGlobalSix_HexGoalGuidanceActive()
	local g = self._lek_global_six_hex_goal_guidance;
	if g == false then
		return false;
	end
	if g == true then
		return true;
	end
	return self._lek_global_six_one_map_placement_mode == true;
end

function AssignStartingPlots:LekGlobalSix_WalkHexSpoke(cx, cy, dir, R, iW, iH, wrapX, wrapY)
	local x, y = cx, cy;
	if type(GetHexNeighbor) ~= "function" or type(R) ~= "number" or R < 1 then
		return x, y;
	end
	for _ = 1, R do
		x, y = GetHexNeighbor(x, y, dir, iW, iH, wrapX, wrapY);
	end
	return x, y;
end

function AssignStartingPlots:LekGlobalSix_RegionIndexAtPlotXY(x, y, iW, iH)
	if self.regionData == nil then
		return nil;
	end
	for r = 1, 6 do
		local rd = self.regionData[r];
		if type(rd) == "table"
			and type(rd[1]) == "number" and type(rd[2]) == "number"
			and type(rd[3]) == "number" and type(rd[4]) == "number"
			and rd[3] >= 1 and rd[4] >= 1
		then
			if self:LekPlotXYInRegionRectangle(x, y, rd[1], rd[2], rd[3], rd[4], iW, iH) then
				return r;
			end
		end
	end
	return nil;
end

function AssignStartingPlots:LekGlobalSix_BuildHexGoalsForRotation(cx, cy, R, rot, iW, iH, wrapX, wrapY)
	local regByDir = {};
	local posByDir = {};
	for d = 1, 6 do
		local dir = ((d - 1 + rot) % 6) + 1;
		local vx, vy = AssignStartingPlots.LekGlobalSix_WalkHexSpoke(self, cx, cy, dir, R, iW, iH, wrapX, wrapY);
		posByDir[d] = { x = vx, y = vy };
		regByDir[d] = AssignStartingPlots.LekGlobalSix_RegionIndexAtPlotXY(self, vx, vy, iW, iH);
		if regByDir[d] == nil then
			return nil;
		end
	end
	local seen = {};
	for d = 1, 6 do
		local rr = regByDir[d];
		if seen[rr] then
			return nil;
		end
		seen[rr] = true;
	end
	local goals = {};
	for d = 1, 6 do
		local rr = regByDir[d];
		local p = posByDir[d];
		goals[rr] = { x = p.x, y = p.y };
	end
	return goals;
end

function AssignStartingPlots:LekGlobalSix_ScoreHexGoalsForPools(byRegion, goals)
	local s = 0;
	for r = 1, 6 do
		local g = goals[r];
		if not g then
			return nil;
		end
		local minAll = 999999;
		local minC = 999999;
		local hasC = false;
		local list = byRegion[r];
		if not list or #list < 1 then
			return nil;
		end
		for i = 1, #list do
			local c = list[i];
			local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, c.x, c.y, g.x, g.y);
			if type(d) == "number" and d < minAll then
				minAll = d;
			end
			if self.plotDataIsCoastal[c.plotIndex] == true then
				hasC = true;
				if type(d) == "number" and d < minC then
					minC = d;
				end
			end
		end
		s = s + minAll;
		local cc = AssignStartingPlots.LekGlobalSix_CoastalCountInSearchPool(self, byRegion, r);
		if cc > 0 then
			if hasC then
				s = s + 0.28 * minC;
			else
				s = s + 0.28 * 420;
			end
		end
	end
	return s;
end

function AssignStartingPlots:LekGlobalSix_NudgeHexGoalsInlandByPool(byRegion, goals, iW, iH, wrapX, wrapY)
	if goals == nil or self._lek_global_six_hex_inland_goal_nudge == false then
		return;
	end
	local a = tonumber(self._lek_global_six_hex_inland_nudge_alpha);
	if type(a) ~= "number" or a < 0 or a > 1 then
		a = 0.32;
	end
	for r = 1, 6 do
		if AssignStartingPlots.LekGlobalSix_CoastalCountInSearchPool(self, byRegion, r) == 0 then
			local g = goals[r];
			local rd = self.regionData and self.regionData[r];
			if g and type(rd) == "table" and type(rd[1]) == "number" and type(rd[2]) == "number"
				and type(rd[3]) == "number" and type(rd[4]) == "number" and rd[3] >= 1 and rd[4] >= 1
			then
				local rcx = (rd[1] + math.floor((rd[3] - 1) / 2)) % iW;
				local rcy = (rd[2] + math.floor((rd[4] - 1) / 2)) % iH;
				local nx = math.floor(g.x + (rcx - g.x) * a + 0.5);
				local ny = math.floor(g.y + (rcy - g.y) * a + 0.5);
				if type(WrapCoord) == "function" then
					nx = WrapCoord(nx, iW, wrapX);
					ny = WrapCoord(ny, iH, wrapY);
				else
					nx = ((nx % iW) + iW) % iW;
					ny = ((ny % iH) + iH) % iH;
				end
				g.x, g.y = nx, ny;
			end
		end
	end
end

function AssignStartingPlots:LekGlobalSix_ApplyHexGoalSortToRegionPool(byRegion, r, gx, gy)
	local list = byRegion[r];
	if not list or #list < 2 then
		return;
	end
	table.sort(list, function(a, b)
		if a.ringDev ~= b.ringDev then
			return a.ringDev < b.ringDev;
		end
		local da = AssignStartingPlots.LekGlobalSix_PlotDistance(self, a.x, a.y, gx, gy);
		local db = AssignStartingPlots.LekGlobalSix_PlotDistance(self, b.x, b.y, gx, gy);
		if type(da) ~= "number" then
			da = 999999;
		end
		if type(db) ~= "number" then
			db = 999999;
		end
		if da ~= db then
			return da < db;
		end
		if a.score ~= b.score then
			return a.score > b.score;
		end
		return a.plotIndex < b.plotIndex;
	end);
end

function AssignStartingPlots:LekGlobalSix_ApplyHexGoalGuidanceToPools(byRegion)
	local rid = tostring(_lek_run_id or "na");
	self._lek_g6_hex_goals = nil;
	self._lek_g6_hex_rot = nil;
	self._lek_g6_hex_ringR = nil;
	self._lek_g6_hex_pick_score = nil;
	_lek_bench_hex_ok = "0";
	_lek_bench_hex_rot = "na";
	_lek_bench_hex_ringR = "na";
	if self.iNumCivs ~= 6 then
		return;
	end
	if not AssignStartingPlots.LekGlobalSix_HexGoalGuidanceActive(self) then
		_lek_bench_hex_ok = "off";
		return;
	end
	if type(GetHexNeighbor) ~= "function" then
		LekPlacementProbeLog("### LekGlobalSix hexGoalGuidance runId=" .. rid .. " status=skip missing_GetHexNeighbor");
		_lek_bench_hex_ok = "no_api";
		return;
	end
	local iW, iH = Map.GetGridSize();
	local wrapX = Map:IsWrapX();
	local wrapY = Map:IsWrapY();
	local cx = math.floor(iW / 2);
	local cy = math.floor(iH / 2);
	local R = tonumber(self._lek_global_six_hex_goal_radius);
	if type(R) ~= "number" or R < 1 then
		R = 13;
	end
	local bestRot, bestGoals, bestScore = nil, nil, nil;
	for rot = 0, 5 do
		local goals = AssignStartingPlots.LekGlobalSix_BuildHexGoalsForRotation(self, cx, cy, R, rot, iW, iH, wrapX, wrapY);
		if goals then
			local sc = AssignStartingPlots.LekGlobalSix_ScoreHexGoalsForPools(self, byRegion, goals);
			if type(sc) == "number" and (bestScore == nil or sc < bestScore) then
				bestScore = sc;
				bestRot = rot;
				bestGoals = goals;
			end
		end
	end
	if not bestGoals then
		LekPlacementProbeLog("### LekGlobalSix hexGoalGuidance runId=" .. rid ..
			" status=no_injective_rotation" ..
			" cx=" .. tostring(cx) .. " cy=" .. tostring(cy) ..
			" ringR=" .. tostring(R));
		_lek_bench_hex_ok = "0";
		return;
	end
	AssignStartingPlots.LekGlobalSix_NudgeHexGoalsInlandByPool(self, byRegion, bestGoals, iW, iH, wrapX, wrapY);
	self._lek_g6_hex_goals = bestGoals;
	self._lek_g6_hex_rot = bestRot;
	self._lek_g6_hex_ringR = R;
	self._lek_g6_hex_pick_score = bestScore;
	for r = 1, 6 do
		local g = bestGoals[r];
		if g then
			AssignStartingPlots.LekGlobalSix_ApplyHexGoalSortToRegionPool(self, byRegion, r, g.x, g.y);
		end
	end
	_lek_bench_hex_ok = "1";
	_lek_bench_hex_rot = tostring(bestRot);
	_lek_bench_hex_ringR = tostring(R);
	LekPlacementProbeLog("### LekGlobalSix hexGoalGuidance runId=" .. rid ..
		" status=applied" ..
		" rot=" .. tostring(bestRot) ..
		" ringR=" .. tostring(R) ..
		" pickScore=" .. tostring(bestScore));
end

function AssignStartingPlots:LekGlobalSix_GatherSearchCandidatesOrdered(region_r)
	local tupleNoCoast = (self.ForceAllInlandPlayerSpawns == true);
	local list = AssignStartingPlots.LekGlobalSix_GatherTupleStyleCandidateIndices(self, region_r, tupleNoCoast);
	local rt = self.regionTypes[region_r];
	if not rt then
		return {};
	end
	local iW, iH = Map.GetGridSize();
	local cx = math.floor(iW / 2);
	local cy = math.floor(iH / 2);
	local out = {};
	local bandLo = self._lek_g6_runtime_s1_min or LEK_G6_S1_D_MIN;
	local bandHi = self._lek_g6_runtime_s1_max or LEK_G6_S1_D_MAX;
	for idx = 1, #list do
		local plotIndex = list[idx];
		local x = (plotIndex - 1) % iW;
		local y = (plotIndex - x - 1) / iW;
		local d = AssignStartingPlots.LekGlobalSix_PlotDistance(self, x, y, cx, cy);
		if not d then
		elseif d < bandLo or d > bandHi then
		else
			local savedDD = self.distanceData[plotIndex];
			self.distanceData[plotIndex] = 0;
			local score, meetsMin = self:EvaluateCandidatePlot(plotIndex, rt);
			self.distanceData[plotIndex] = savedDD;
			if meetsMin then
				local okSalt, _ = AssignStartingPlots.LekGlobalSix_OK_InlandSaltCell(self, plotIndex, nil);
				local passDisk = AssignStartingPlots.LekGlobalSix_CoastalCandidatePassesSaltWaterDiskPct(self, plotIndex);
				local acc = self._lek_diag_salt_disk_accum;
				if acc and okSalt and self.plotDataIsCoastal[plotIndex] == true then
					acc.coastalMeetsInlandSalt = (acc.coastalMeetsInlandSalt or 0) + 1;
					if not passDisk then
						acc.rejects = (acc.rejects or 0) + 1;
						acc.byR[region_r] = (acc.byR[region_r] or 0) + 1;
					end
				end
				if okSalt and passDisk then
					local ringDev = math.abs(d - LEK_G6_S1_TARGET_D);
					local m = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsAtXY(self, x, y);
					out[#out + 1] = {
						plotIndex = plotIndex,
						x = x,
						y = y,
						score = score,
						ringDev = ringDev,
						dMapCenter = d,
						coastal_ok = (m.alongOcean == true),
						river_ok = ((m.isRiver == true) or (m.nearRiver == true)),
					};
				end
			end
		end
	end
	table.sort(out, function(a, b)
		if a.ringDev ~= b.ringDev then
			return a.ringDev < b.ringDev;
		end
		if a.score ~= b.score then
			return a.score > b.score;
		end
			return a.plotIndex < b.plotIndex;
	end);
	if #out == 0 and self._lek_global_six_tuple_empty_pool_fallback ~= false then
		local fb = AssignStartingPlots.LekGlobalSix_FallbackSearchCandidateForRegion(self, region_r);
		if fb then
			local fbm = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsAtXY(self, fb.x, fb.y);
			local rid = tostring(_lek_run_id or "na");
			LekPlacementProbeAt(3, "### LekGlobalSix tuplePoolFallback runId=" .. rid ..
				" region=" .. tostring(region_r) ..
				" x=" .. tostring(fb.x) .. " y=" .. tostring(fb.y) ..
				" pi=" .. tostring(fb.plotIndex) ..
				" dMapC=" .. tostring(fb.dMapCenter) ..
				" ringDevToTargetD=" .. tostring(fb.ringDev) ..
				" EvaluateCandidate_meetsMin=" .. (fb.meetsMin and "1" or "0") ..
				" note=min_ringDev_then_max_score_over_tupleStylePlots");
			out[1] = {
				plotIndex = fb.plotIndex,
				x = fb.x,
				y = fb.y,
				score = fb.score,
				ringDev = fb.ringDev,
				dMapCenter = fb.dMapCenter,
				coastal_ok = (fbm.alongOcean == true),
				river_ok = ((fbm.isRiver == true) or (fbm.nearRiver == true)),
			};
		end
	end
	local cap = self._lek_global_six_max_candidates_per_region;
	if type(cap) ~= "number" or cap < 1 then
		cap = 36;
	end
	while #out > cap do
		table.remove(out);
	end
	return out;
end

function AssignStartingPlots:LekGlobalSix_CopyStartsTableForBest()
	local t = {};
	for r = 1, 6 do
		local sp = self.startingPlots[r];
		if not sp then
			return nil;
		end
		t[r] = { sp[1], sp[2], sp[3] };
	end
	return t;
end

function AssignStartingPlots:LekGlobalSix_RunTupleSearch()
	local rid = tostring(_lek_run_id or "na");
	if self.iNumCivs ~= 6 then
		return false, 0, 0, 0, nil;
	end
	self._lek_tuple_cause_gate = nil;
	self._lek_tuple_cause_prune = nil;
	self._lek_tuple_cause_leaf = nil;
	self._lek_tuple_cause_combo = nil;
	self._lek_force_expected_pid_region = nil;
	self._lek_force_expected_coastal_pids = nil;
	self._lek_tuple_search_success_phase_name = nil;
	self._lek_tuple_search_success_phase_index = nil;
	self._lek_g6_bias_policy = AssignStartingPlots.LekGlobalSix_BuildEffectiveBiasPolicy(self);

	if self._lek_global_six_force_geometry_only ~= true then
		self._lek_tuple_cause_gate = "tuple_dfs_removed";
		self._lek_tuple_cause_prune = "na";
		self._lek_tuple_cause_leaf = "tuple_dfs_removed";
		self._lek_tuple_cause_combo = "na";
		local mf = self._lek_global_six_max_fail_complete;
		if type(mf) ~= "number" or mf < 1 then
			mf = 1000;
		end
		LekPlacementProbeLog("### LekGlobalSix tupleSearch runId=" .. rid ..
			" status=aborted_non_force tuple_dfs_removed=1");
		return false, 0, 0, mf, "tuple_dfs_removed";
	end

	local layoutN = tonumber(_lek_map_layout_attempt);
	if type(layoutN) ~= "number" or layoutN < 1 then
		layoutN = 1;
	end

	local relaxMinLayout = self._lek_global_six_tuple_relax_min_layout;
	local forceHardOnly = false;
	if relaxMinLayout ~= false then
		if relaxMinLayout == nil then
			relaxMinLayout = 4;
		end
		if type(relaxMinLayout) == "number" and layoutN < relaxMinLayout then
			forceHardOnly = true;
		end
	end

	local phases;
	if self._lek_global_six_tuple_relaxation_phases == false then
		local mf = self._lek_global_six_max_fail_complete;
		if type(mf) ~= "number" or mf < 1 then
			mf = 100;
		end
		local ml = self._lek_global_six_max_leaf_evals;
		if type(ml) ~= "number" or ml < 1 then
			ml = 800;
		end
		phases = {
			{
				name = "single",
				max_fail_complete = mf,
				max_leaf_evals = ml,
				s1_min = LEK_G6_S1_D_MIN,
				s1_max = LEK_G6_S1_D_MAX,
				s2_max = LEK_G6_S2_SECOND_NEAREST_MAX,
			},
		};
	elseif type(self._lek_global_six_tuple_relaxation_phases) == "table" and #self._lek_global_six_tuple_relaxation_phases > 0 then
		phases = self._lek_global_six_tuple_relaxation_phases;
	else
		phases = AssignStartingPlots.LekGlobalSix_DefaultTupleRelaxationPhases();
	end

	if forceHardOnly and type(phases) == "table" and #phases > 1 then
		phases = { phases[1] };
	end

	if self._lek_global_six_one_map_placement_mode == true and type(phases) == "table" then
		local mf0 = self._lek_global_six_max_fail_complete;
		if type(mf0) ~= "number" or mf0 < 1 then
			mf0 = 1000;
		end
		local ml0 = self._lek_global_six_max_leaf_evals;
		if type(ml0) ~= "number" or ml0 < 1 then
			ml0 = 8000;
		end
		phases[#phases + 1] = {
			name = "one_map_finale_s2p6",
			max_fail_complete = math.max(mf0 * 2, 2000),
			max_leaf_evals = math.max(ml0 * 2, 16000),
			s1_min = LEK_G6_S1_D_MIN,
			s1_max = LEK_G6_S1_RELAX_MAX,
			s2_max = LEK_G6_S2_SECOND_NEAREST_MAX + 6,
		};
		phases[#phases + 1] = {
			name = "one_map_finale_ultra",
			max_fail_complete = math.max(mf0 * 4, 4000),
			max_leaf_evals = math.max(ml0 * 4, 32000),
			s1_min = LEK_G6_S1_D_MIN,
			s1_max = math.min(LEK_G6_S1_RELAX_MAX + 3, 22),
			s2_max = LEK_G6_S2_SECOND_NEAREST_MAX + 10,
		};
	end

	if forceHardOnly then
		LekPlacementProbeLog("### LekGlobalSix tupleRelaxGate hard_only runId=" .. rid ..
			" map_layout_attempt=" .. tostring(layoutN) ..
			" relax_min_layout=" .. tostring(relaxMinLayout));
	end

	if LekMapgenLogAtLeast(2) then
		AssignStartingPlots.LekGlobalSix_LogTupleProbeLayerSnapshot(self);
	end

	local lastFailKind = nil;
	local lastFC, lastLE, lastMaxF = 0, 0, 0;
	local doTuplePoolDiag3 = (self._lek_tuple_pool_diag ~= false) and LekMapgenLogAtLeast(3);

	for phaseIdx, ph in ipairs(phases) do
		local phaseName = ph.name or ("phase" .. tostring(phaseIdx));
		local s1a = ph.s1_min;
		local s1b = ph.s1_max;
		local s2m = ph.s2_max;
		if type(s1a) ~= "number" then
			s1a = LEK_G6_S1_D_MIN;
		end
		if type(s1b) ~= "number" then
			s1b = LEK_G6_S1_D_MAX;
		end
		if type(s2m) ~= "number" then
			s2m = LEK_G6_S2_SECOND_NEAREST_MAX;
		end
		local geomNote = "";
		if self._lek_global_six_pace_fast ~= true and self._lek_global_six_fatal_on_exhausted == true then
			local g2, g1 = AssignStartingPlots.LekGlobalSix_SlowPaceLayoutGeometryBoost(layoutN);
			if g2 > 0 or g1 > 0 then
				s2m = s2m + g2;
				s1b = math.min(s1b + g1, LEK_G6_S1_RELAX_MAX + 6);
				geomNote = " slowPace_geom=+" .. tostring(g1) .. "s1_+" .. tostring(g2) .. "s2";
			end
		end
		if self._lek_global_six_pace_fast == true and self._lek_global_six_one_map_placement_mode ~= true then
			local maxL = self._lek_global_six_regen_max_layouts;
			if type(maxL) ~= "number" or maxL < 1 then
				maxL = 3;
			end
			if layoutN == maxL then
				s2m = s2m + 3;
				s1b = math.min(s1b + 4, LEK_G6_S1_RELAX_MAX + 8);
				geomNote = geomNote .. " fastLastLayout=+4s1_+3s2";
			end
		end
		self._lek_g6_runtime_s1_min = s1a;
		self._lek_g6_runtime_s1_max = s1b;
		self._lek_g6_runtime_s2_max = s2m;
		self._lek_ok_diag_last_tuple_phase_s1min = s1a;
		self._lek_ok_diag_last_tuple_phase_s1max = s1b;
		self._lek_ok_diag_last_tuple_phase_s2max = s2m;

		local maxFail = ph.max_fail_complete;
		if type(maxFail) ~= "number" or maxFail < 1 then
			maxFail = self._lek_global_six_max_fail_complete;
		end
		if type(maxFail) ~= "number" or maxFail < 1 then
			maxFail = 100;
		end
		local maxLeaf = ph.max_leaf_evals;
		if type(maxLeaf) ~= "number" or maxLeaf < 1 then
			maxLeaf = self._lek_global_six_max_leaf_evals;
		end
		if type(maxLeaf) ~= "number" or maxLeaf < 1 then
			maxLeaf = 800;
		end

		LekPlacementProbeLog("### LekGlobalSix tuplePhase begin runId=" .. rid ..
			" phaseIndex=" .. tostring(phaseIdx) .. "/" .. tostring(#phases) ..
			" name=" .. phaseName ..
			" s1=" .. tostring(s1a) .. "-" .. tostring(s1b) ..
			" s2max=" .. tostring(s2m) ..
			" maxFail=" .. tostring(maxFail) ..
			" maxLeaf=" .. tostring(maxLeaf) ..
			geomNote ..
			" note=force_geometry_only");

	self._lek_g6_feas_margin_by_region = nil;
	local enforceNCPhase = AssignStartingPlots.LekGlobalSix_NoCoastInlandEnforced(self);
	local nCoastalRequired = 0;
	do
		local plistPhase, _ = AssignStartingPlots.LekGlobalSix_Section5_BuildPlayerBiasPlist(self);
		if plistPhase then
			for _, p in ipairs(plistPhase) do
				if p.tag == "coastal" then
					nCoastalRequired = nCoastalRequired + 1;
				end
			end
		end
	end
	local domainStaticPruned = 0;
	local domainBeforeN = 0;
	local domainAfterN = 0;
	local function candCoastalOK(c)
		if c and c.coastal_ok ~= nil then
			return c.coastal_ok == true;
		end
		if c and type(c.x) == "number" and type(c.y) == "number" then
			local m = AssignStartingPlots.LekGlobalSix_MeasureBiasConditionsAtXY(self, c.x, c.y);
			return m.alongOcean == true;
		end
		return false;
	end

	if LekMapgenLogAtLeast(2) and AssignStartingPlots.LekGlobalSix_CoastalSaltDiskPctFilterActive(self)
		and self._lek_global_six_coastal_disk3_pool_diag ~= false then
		self._lek_diag_salt_disk_accum = { rejects = 0, byR = {}, coastalMeetsInlandSalt = 0 };
	else
		self._lek_diag_salt_disk_accum = nil;
	end

	local byRegion = {};
	local abortRegion = nil;
	for r = 1, 6 do
		byRegion[r] = AssignStartingPlots.LekGlobalSix_GatherSearchCandidatesOrdered(self, r);
		domainBeforeN = domainBeforeN + #byRegion[r];
		if enforceNCPhase and nCoastalRequired == 0 and #byRegion[r] > 0 then
			local keep = {};
			for i = 1, #byRegion[r] do
				local c = byRegion[r][i];
				if not candCoastalOK(c) then
					keep[#keep + 1] = c;
				else
					domainStaticPruned = domainStaticPruned + 1;
				end
			end
			byRegion[r] = keep;
		end
		domainAfterN = domainAfterN + #byRegion[r];
		if doTuplePoolDiag3 then
			AssignStartingPlots.LekGlobalSix_LogTuplePoolDiagLine(self, r, #byRegion[r]);
			AssignStartingPlots.LekGlobalSix_LogTuplePoolSpatial(self, r, byRegion[r]);
		end
		if #byRegion[r] == 0 then
			abortRegion = r;
			break;
		end
	end

	if self._lek_diag_salt_disk_accum and LekMapgenLogAtLeast(2) then
		local acc = self._lek_diag_salt_disk_accum;
		local rad = self._lek_global_six_coastal_salt_water_disk_radius;
		if type(rad) ~= "number" or rad < 1 then
			rad = 3;
		end
		local pctMax = self._lek_global_six_coastal_disk3_max_salt_water_pct;
		local parts = {};
		local sumPool = 0;
		local sumVirt = 0;
		for r = 1, 6 do
			local n = #(byRegion[r] or {});
			local rej = acc.byR[r] or 0;
			sumPool = sumPool + n;
			sumVirt = sumVirt + n + rej;
			parts[#parts + 1] = "r" .. tostring(r) .. ":pool=" .. tostring(n) .. "+diskOff=" .. tostring(rej);
		end
		LekPlacementProbeLog("### LekGlobalSix coastalSaltDiskPoolDiag runId=" .. rid ..
			" phase=" .. phaseName ..
			" saltDisk_pctMax=" .. tostring(pctMax) .. " hexR=" .. tostring(rad) ..
			" coastal_meetsInlandSalt_evaluated=" .. tostring(acc.coastalMeetsInlandSalt or 0) ..
			" rejected_from_pool_by_disk=" .. tostring(acc.rejects or 0) ..
			" poolCells_total=" .. tostring(sumPool) ..
			" virtual_pool_total_if_disk_disabled=" .. tostring(sumVirt) ..
			" " .. table.concat(parts, ";"));
		self._lek_diag_salt_disk_accum = nil;
	end
	if LekMapgenLogAtLeast(2) then
		LekPlacementProbeLog("### LekGlobalSix tupleDomain phase runId=" .. rid ..
			" phaseIndex=" .. tostring(phaseIdx) ..
			" name=" .. phaseName ..
			" nCoastalRequired=" .. tostring(nCoastalRequired) ..
			" noCoastInlandEnforced=" .. (enforceNCPhase and "1" or "0") ..
			" poolBefore=" .. tostring(domainBeforeN) ..
			" poolAfter=" .. tostring(domainAfterN) ..
			" staticPruned=" .. tostring(domainStaticPruned));
	end

	if abortRegion then
		local maskedAll, inBand, dLo, dHi = AssignStartingPlots.LekGlobalSix_CountMaskedMeetsMinOutsideInsideCentreBand(self, abortRegion);
		local dr = "na";
		if dLo ~= nil and dHi ~= nil then
			dr = tostring(dLo) .. "-" .. tostring(dHi);
		end
		LekPlacementProbeLog("### LekGlobalSix tuplePhase no_tupleStyle_land runId=" .. rid ..
			" phaseIndex=" .. tostring(phaseIdx) ..
			" name=" .. phaseName ..
			" region=" .. tostring(abortRegion) ..
			" meetsMin_maskOwnDD_allRaw=" .. tostring(maskedAll) ..
			" meetsMin_inS1band=" .. tostring(inBand) ..
			" meetsMin_dCenterRange=" .. dr ..
			" note=no_plot_passes_GatherTupleStyle_filters");
		lastMaxF = maxFail;
		lastFC, lastLE = 0, 0;
		lastFailKind = "no_candidates_r=" .. tostring(abortRegion);
		self._lek_tuple_cause_gate = "empty_pool_r" .. tostring(abortRegion);
		LekPlacementProbeLog("### LekGlobalSix tuplePhase end runId=" .. rid ..
			" phaseIndex=" .. tostring(phaseIdx) ..
			" name=" .. phaseName ..
			" status=skip_empty_pool");
	else
		AssignStartingPlots.LekGlobalSix_ApplyHexGoalGuidanceToPools(self, byRegion);
		local _okFeas, _errFeas = pcall(function()
			AssignStartingPlots.LekGlobalSix_TuplePoolFeasProbeRun(self, byRegion, s2m, phaseIdx, phaseName, rid);
		end);
		if not _okFeas then
			self._lek_g6_feas_margin_by_region = nil;
			_lek_bench_feas_bn = "probe_err";
			_lek_bench_feas_xmin = "na";
			_lek_bench_feas_h2max = "na";
			_lek_bench_feas_margmin = "na";
			_lek_bench_feas_k = "na";
			LekPlacementProbeLog("### LekGlobalSix tuplePoolFeasProbe pcall_fail runId=" .. rid ..
				" phaseIndex=" .. tostring(phaseIdx) ..
				" name=" .. tostring(phaseName or "?") ..
				" err=" .. tostring(_errFeas));
		end
		if doTuplePoolDiag3 then
			AssignStartingPlots.LekGlobalSix_LogTupleHeadGeometry(self, byRegion);
		end
		local depthOrder, dfsOrderMode, dfsOrderKeys =
			AssignStartingPlots.LekGlobalSix_BuildTupleDepthOrder(self, byRegion);
		if LekMapgenLogAtLeast(2) then
			local parts = {};
			for d = 1, 6 do
				local rg = depthOrder[d];
				local nc = AssignStartingPlots.LekGlobalSix_CoastalCountInSearchPool(self, byRegion, rg);
				parts[#parts + 1] = string.format("d%d=r%d(n=%d,c=%d)", d, rg, #byRegion[rg], nc);
			end
			LekPlacementProbeLog("### LekGlobalSix tupleDfsOrder runId=" .. rid ..
				" phaseIndex=" .. tostring(phaseIdx) ..
				" name=" .. phaseName ..
				" dfsOrderMode=" .. tostring(dfsOrderMode) ..
				" thin_first=" .. tostring((self._lek_global_six_dfs_thin_first ~= false) and 1 or 0) ..
				" constraint_weighted=" .. tostring((self._lek_global_six_dfs_constraint_weighted ~= false) and 1 or 0) ..
				" sortKeys=" .. tostring(dfsOrderKeys) ..
				" " .. table.concat(parts, "; "));
		end

		local forcePack, forceMetrics, forceSampleN, forceCap, forceBandMin, forceBandMax =
			AssignStartingPlots.LekGlobalSix_ForceGeometryPackFromPools(self, byRegion, depthOrder);
		if forcePack ~= nil then
			for r = 1, 6 do
				local p = forcePack[r];
				self.startingPlots[r] = { p[1], p[2], p[3] };
				self:PlaceImpactAndRipples(p[1], p[2]);
			end
			AssignStartingPlots.LekGlobalSix_LogForceGeometryPack(self, rid, phaseIdx, phaseName, forceMetrics, forceSampleN, forceCap, forceBandMin, forceBandMax);
			local _okRuleAudF, _errRuleAudF = pcall(function()
				AssignStartingPlots.LekGlobalSix_LogRuleAuditAfterTupleCommit(self);
			end);
			if not _okRuleAudF then
				LekPlacementProbeAt(1, "### LekGlobalSix ruleAuditAfterTuple pcall_err runId=" .. rid
					.. " err=" .. tostring(_errRuleAudF));
			end
			self._lek_tuple_cause_gate = "force_geometry_only";
			self._lek_tuple_cause_prune = "force_geometry_only";
			self._lek_tuple_cause_leaf = "ok_force_geometry_only";
			self._lek_tuple_cause_combo = "na";
			self._lek_force_expected_pid_region = forceMetrics and forceMetrics.biasAssignPidRegion or nil;
			self._lek_force_expected_coastal_pids = forceMetrics and forceMetrics.biasCoastalPids or nil;
			self._lek_tuple_search_success_phase_name = tostring(phaseName) .. "_force_geometry_only";
			self._lek_tuple_search_success_phase_index = phaseIdx;
			self._lek_g6_runtime_s1_min = nil;
			self._lek_g6_runtime_s1_max = nil;
			self._lek_g6_runtime_s2_max = nil;
			LekPlacementProbeLog("### LekGlobalSix tuplePhase success_force_geometry_only runId=" .. rid ..
				" phaseIndex=" .. tostring(phaseIdx) ..
				" name=" .. phaseName ..
				" failComplete=0 leafEvals=0");
			return true, 0, 0, maxFail, nil;
		else
			lastFC = 0;
			lastLE = 0;
			lastMaxF = maxFail;
			lastFailKind = "force_geometry_no_pack";
			self._lek_tuple_cause_gate = "force_geometry_no_pack";
			LekPlacementProbeLog("### LekGlobalSix tuplePhase end runId=" .. rid ..
				" phaseIndex=" .. tostring(phaseIdx) ..
				" name=" .. phaseName ..
				" status=force_geometry_no_pack");
		end
	end
	end

	self._lek_g6_runtime_s1_min = nil;
	self._lek_g6_runtime_s1_max = nil;
	self._lek_g6_runtime_s2_max = nil;
	if self._lek_tuple_cause_leaf == nil then
		self._lek_tuple_cause_leaf = tostring(lastFailKind or "na");
	end
	if self._lek_tuple_cause_combo == nil then
		self._lek_tuple_cause_combo = "na";
	end
	LekPlacementProbeAt(3, "### LekGlobalSix tupleSearch runId=" .. rid ..
		" status=fail_all_phases last_phase_failComplete=" .. tostring(lastFC) ..
		" leafEvals=" .. tostring(lastLE) ..
		" maxFail=" .. tostring(lastMaxF) ..
		" last_fail=" .. tostring(lastFailKind or "na"));
	return false, lastFC, lastLE, lastMaxF, lastFailKind;
end

function AssignStartingPlots:LekGlobalSixChooseLocations(args)
	local rid = tostring(_lek_run_id or "na");
	local n = self.iNumCivs or 0;
	local elig = (n == 6) and 1 or 0;
	local snap = "";
	if elig == 1 then
		local parts = {};
		local rawParts = {};
		local meetParts = {};
		for r = 1, 6 do
			local rd = self.regionData[r];
			local rt = self.regionTypes[r];
			if rd and rt ~= nil then
				local fert = rd[8] or 0;
				local area = rd[5];
				local rw, rh = rd[3] or 0, rd[4] or 0;
				parts[#parts + 1] = string.format(
					"r%d=t%d avgF=%.2f area=%d w%dxh%d",
					r, rt, fert, area or -1, rw, rh);
				local rawN = AssignStartingPlots.LekGlobalSix_CountRawFindStartStyleCandidates(self, r, false);
				rawParts[#rawParts + 1] = string.format("r%d:%d", r, rawN);
				local okN, rawCheck = AssignStartingPlots.LekGlobalSix_CountEvaluateMeetsMinInRawPool(self, r, false);
				meetParts[#meetParts + 1] = string.format("r%d:%d/%d", r, okN, rawCheck);
			else
				parts[#parts + 1] = "r" .. tostring(r) .. "=?";
				rawParts[#rawParts + 1] = "r" .. tostring(r) .. ":?";
				meetParts[#meetParts + 1] = "r" .. tostring(r) .. ":?/?";
			end
		end
		snap = " regions=" .. table.concat(parts, ";") ..
			" rawFindStartStyleCandidates_NoCoastFalse=" .. table.concat(rawParts, ",") ..
			" evalMeetsMin_maskOwnDD_postReserve=" .. table.concat(meetParts, ",");
	end
	LekPlacementProbeAt(2, "### LekGlobalSixChooseLocations runId=" .. rid ..
		" implementation=force_geometry_pack hook=after_DetermineRegionTypes" ..
		" eligible_iNumCivs_eq_6=" .. tostring(elig) .. snap);
	if elig == 1 and self._lek_global_six_skip_tuple_use_legacy == true then
		self._lek_global_six_tuple_solver_accepted = true;
		self._lek_global_six_placement_tier = "legacy_menu_skip_tuple";
		LekPlacementProbeAt(1, "### LekGlobalSixChooseLocations runId=" .. rid ..
			" path=skip_tuple_use_legacy tuple_not_run=1");
		if LekMapgenTupleBenchmarkMode() then
			_lek_bench_tuple_ok = 0;
			_lek_bench_tuple_why = "menu_skip_tuple";
			_lek_bench_tuple_leaf = 0;
			_lek_bench_tuple_fail_complete = 0;
			_lek_bench_tuple_max_fail = 0;
			_lek_bench_tuple_relax = "";
			_lek_bench_tuple_tier = "legacy_menu_skip_tuple";
		end
		return false;
	end
	if elig == 1 and self._lek_global_six_ripple_dry_run == true then
		local okDry, errDry = pcall(function()
			self:LekGlobalSix_LogRippleOrderedSampleDryRun();
		end);
		if not okDry then
			LekPlacementProbeAt(2, "### LekGlobalSix rippleOrderDryRun runId=" .. rid .. " pcall_err=" .. tostring(errDry));
		end
	end
	if elig ~= 1 then
		self._lek_global_six_tuple_solver_accepted = true;
		self._lek_global_six_placement_tier = "legacy_not_six_civs";
		return false;
	end
	local okSolve, fComplete, leafE, maxF, why = self:LekGlobalSix_RunTupleSearch();
	local whyExtra = "";
	if why ~= nil then
		whyExtra = " why=" .. tostring(why);
	end
	local relaxExtra = "";
	if okSolve and self._lek_tuple_search_success_phase_name then
		relaxExtra = " relax_phase=" .. tostring(self._lek_tuple_search_success_phase_name) ..
			" relax_phaseIndex=" .. tostring(self._lek_tuple_search_success_phase_index or "?");
	end
	local attL = _lek_map_layout_attempt or 1;
	local maxLL = _lek_global_six_regen_max_layouts;
	if type(maxLL) ~= "number" or maxLL < 1 then
		maxLL = 4;
	end
	LekPlacementProbeAt(1, "### LekGlobalSixChooseLocations runId=" .. rid ..
		" layout=" .. tostring(attL) .. "/" .. tostring(maxLL) ..
		" solver_return=" .. (okSolve and "true" or "false") ..
		" failComplete=" .. tostring(fComplete) ..
		" leafEvals=" .. tostring(leafE) ..
		" maxFailComplete=" .. tostring(maxF) .. whyExtra .. relaxExtra);
	LekPlacementProbeAt(1, "### g6|cause runId=" .. rid ..
		" status=" .. (okSolve and "ok" or "fail") ..
		" gate=" .. tostring(self._lek_tuple_cause_gate or "na") ..
		" prune=" .. tostring(self._lek_tuple_cause_prune or "na") ..
		" leaf=" .. tostring(self._lek_tuple_cause_leaf or "na") ..
		" combo=" .. tostring(self._lek_tuple_cause_combo or "na") ..
		" why=" .. tostring(why or "na") ..
		(okSolve and (" relax_phase=" .. tostring(self._lek_tuple_search_success_phase_name or "na")) or ""));
	self._lek_global_six_tuple_solver_accepted = (okSolve == true);
	if okSolve then
		self._lek_global_six_placement_tier = "tuple_ok";
	else
		self._lek_global_six_placement_tier = "legacy_after_tuple_fail";
	end
	if LekMapgenTupleBenchmarkMode() then
		_lek_bench_tuple_ok = okSolve and 1 or 0;
		_lek_bench_tuple_why = tostring(why or "");
		_lek_bench_tuple_leaf = leafE;
		_lek_bench_tuple_fail_complete = fComplete;
		_lek_bench_tuple_max_fail = maxF;
		_lek_bench_tuple_relax = (okSolve == true) and tostring(self._lek_tuple_search_success_phase_name or "") or "";
		_lek_bench_tuple_tier = tostring(self._lek_global_six_placement_tier or "");
	end
	return okSolve == true;
end

function AssignStartingPlots:ChooseLocations(args)
	if not LekMapgenTupleBenchmarkMode() then
		print("Map Generation - Choosing Start Locations for Civilizations");
	end
	local args = args or {};
	self._lek_choose_locations_legacy_start_placement = false;
	self._lek_legacy_forbid_forced_start_placement = false;
	self._lek_global_six_placement_tier = "legacy_pending";
	local iW, iH = Map.GetGridSize();
	local mustBeCoast = args.mustBeCoast or false; -- if true, will force all starts on salt water coast if possible
	
	-- Defaults for evaluating potential start plots are assigned in .Create but args
	-- passed in here can override. If args value for a field is nil (no arg) then
	-- these assignments will keep the default values in place.
	self.centerBias = args.centerBias or self.centerBias; -- % of radius from region center to examine first
	self.middleBias = args.middleBias or self.middleBias; -- % of radius from region center to check second
	if not LekMapgenTupleBenchmarkMode() then
		print(string.format("DEV/SAPHT Center bias %d, %d", self.centerBias, self.middleBias));
	end
	self.minFoodInner = args.minFoodInner or self.minFoodInner;
	self.minProdInner = args.minProdInner or self.minProdInner;
	self.minGoodInner = args.minGoodInner or self.minGoodInner;
	self.minFoodMiddle = args.minFoodMiddle or self.minFoodMiddle;
	self.minProdMiddle = args.minProdMiddle or self.minProdMiddle;
	self.minGoodMiddle = args.minGoodMiddle or self.minGoodMiddle;
	self.minFoodOuter = args.minFoodOuter or self.minFoodOuter;
	self.minProdOuter = args.minProdOuter or self.minProdOuter;
	self.minGoodOuter = args.minGoodOuter or self.minGoodOuter;
	self.maxJunk = args.maxJunk or self.maxJunk;

	local lekProbe = (self._lek_global_six_solver == true);
	local lekSixBiasSkipsGlobalSolver = false;
	if lekProbe then
		local rid = tostring(_lek_run_id or "na");
		local dsbRaw = LekSafeGetDisableStartBiasOption();
		local dsb = (dsbRaw == nil) and "pcall_err" or tostring(dsbRaw);
		LekPlacementProbeAt(1, "### ChooseLocations begin runId=" .. rid ..
			" layout=" .. tostring(_lek_map_layout_attempt or 1) ..
			" skip_tuple_legacy=" .. tostring(self._lek_global_six_skip_tuple_use_legacy == true) ..
			" tuple_regen_on_fail=" .. tostring(self._lek_global_six_tuple_regen_on_solver_fail == true));
		LekPlacementProbeLog("### ChooseLocations begin runId=" .. rid ..
			" iNumCivs=" .. tostring(self.iNumCivs) ..
			" mapLayout=" .. tostring(_lek_map_layout_attempt or 1) ..
			" _lek_global_six_solver=true GAMEOPTION_DISABLE_START_BIAS=" .. dsb ..
			" pace_fast=" .. tostring(self._lek_global_six_pace_fast == true) ..
			" skip_tuple_legacy=" .. tostring(self._lek_global_six_skip_tuple_use_legacy == true) ..
			" tuple_regen_on_fail=" .. tostring(self._lek_global_six_tuple_regen_on_solver_fail == true) ..
			" fatal_on_exhausted=" .. tostring(self._lek_global_six_fatal_on_exhausted == true) ..
			" NoCoastInland=" .. tostring(self.NoCoastInland) ..
			" noCoastInlandEnforcedSix=" .. (AssignStartingPlots.LekGlobalSix_NoCoastInlandEnforced(self) and "1" or "0") ..
			" minPairwisePlotDist=" .. tostring(AssignStartingPlots.LekGlobalSix_MinPairwiseDistanceFromStartDistanceOption()));
		if dsbRaw == 1 then
			LekPlacementProbeLog("### LekGlobalSix runId=" .. rid .. " path=skipped reason=GAMEOPTION_DISABLE_START_BIAS");
			lekSixBiasSkipsGlobalSolver = true;
			self._lek_global_six_tuple_solver_accepted = true;
		end
	end

	-- Lekmap: reserved island feature plots (Solomon's Mines body, geothermal) - pre-fill distanceData ripples so majors avoid stacking on them
	local reserve_plots = {};
	if _solomons_island_mines_plot then reserve_plots[#reserve_plots + 1] = _solomons_island_mines_plot; end
	if _geothermal_island_plot then reserve_plots[#reserve_plots + 1] = _geothermal_island_plot; end
	for _, sp in ipairs(reserve_plots) do
		local solX = (sp - 1) % iW;
		local solY = math.floor((sp - 1 - solX) / iW);
		local wrapX = Map.IsWrapX();
		local wrapY = Map.IsWrapY();
		local odd = self.firstRingYIsOdd;
		local even = self.firstRingYIsEven;
		local ripple_values = {97, 95, 92, 88, 83};
		local impact_value = 99;
		self.distanceData[sp] = impact_value;
		self.playerCollisionData[sp] = true;
		for ripple_radius, ripple_value in ipairs(ripple_values) do
			local currentX = solX - ripple_radius;
			local currentY = solY;
			for direction_index = 1, 6 do
				for plot_to_handle = 1, ripple_radius do
					local plot_adjustments = (currentY % 2 ~= 0) and odd[direction_index] or even[direction_index];
					local nextX = currentX + plot_adjustments[1];
					local nextY = currentY + plot_adjustments[2];
					if not wrapX and (nextX < 0 or nextX >= iW) then
					elseif not wrapY and (nextY < 0 or nextY >= iH) then
					else
						local realX = wrapX and (nextX % iW) or nextX;
						local realY = wrapY and (nextY % iH) or nextY;
						if realX < 0 then realX = realX + iW; end
						if realY < 0 then realY = realY + iH; end
						local ringPlotIndex = realY * iW + realX + 1;
						if self.distanceData[ringPlotIndex] > 0 then
							self.distanceData[ringPlotIndex] = math.min(97, math.max(self.distanceData[ringPlotIndex], ripple_value));
						else
							self.distanceData[ringPlotIndex] = ripple_value;
						end
					end
					currentX, currentY = nextX, nextY;
				end
			end
		end
	end

	-- Measure terrain/plot/feature in regions.
	self:MeasureTerrainInRegions()
	
	-- Determine region type.
	self:DetermineRegionTypes()

	-- Hook A (placement spec): after terrain + region types; bias-disable logged earlier, no solver call then.
	if self._lek_global_six_solver == true and not lekSixBiasSkipsGlobalSolver then
		local rid = tostring(_lek_run_id or "na");
		if self:LekGlobalSixChooseLocations(args) == true then
			local att0 = _lek_map_layout_attempt or 1;
			local maxL0 = _lek_global_six_regen_max_layouts;
			if type(maxL0) ~= "number" or maxL0 < 1 then
				maxL0 = 4;
			end
			LekPlacementProbeAt(1, "### LekGlobalSix runId=" .. rid .. " path=solver_finished ChooseLocations_early_return=1"
				.. " layout=" .. tostring(att0) .. "/" .. tostring(maxL0)
				.. " placement_tier=" .. tostring(self._lek_global_six_placement_tier or "?"));
			self:LekAssertBalancedCoastalExactTwoOrRegen();
			return;
		else
			local maxRegenL = _lek_global_six_regen_max_layouts;
			if type(maxRegenL) ~= "number" or maxRegenL < 1 then
				maxRegenL = 4;
			end
			local att = _lek_map_layout_attempt or 1;
			if _lek_enable_hb_generatemap_regen_loop == true
				and self._lek_global_six_tuple_regen_on_solver_fail == true
				and self.iNumCivs == 6
				and self._lek_global_six_tuple_solver_accepted == false
				and att < maxRegenL then
				_lek_global_six_request_map_regen_reason = "tuple_solver_no_accepted_tuple_skip_legacy";
				_lek_global_six_request_map_regen = true;
				LekPlacementProbeAt(1, "### LekGlobalSix runId=" .. rid ..
					" path=tuple_fail_skip_legacy layout=" .. tostring(att) .. "/" .. tostring(maxRegenL));
				LekPlacementProbeAt(1, "### LekGlobalSix mapRegen request runId=" .. tostring(_lek_run_id or "na") ..
					" layout=" .. tostring(att) .. "/" .. tostring(maxRegenL) ..
					" reason=tuple_solver_no_accepted_tuple skip_legacy=1");
				return;
			end
			if self._lek_global_six_fatal_on_exhausted == true
				and self._lek_global_six_tuple_solver_accepted == false then
				local msg = "### LekGlobalSix FATAL runId=" .. rid ..
					" exhausted_layouts=" .. tostring(att) .. "/" .. tostring(maxRegenL) ..
					" tuple_solver_no_accepted_tuple no_HB_legacy_fallback";
				LekPlacementProbeLog(msg);
				error("LekGlobalSix: no valid six-tuple after " .. tostring(maxRegenL) ..
					" map layouts (Capital Precision Medium or Very Slow). Regenerate or relax start/island rules.");
			end
			LekPlacementProbeAt(2, "### LekGlobalSix runId=" .. rid ..
				" path=fallthrough legacy_ChooseLocations_continues=1 tuple_accepted=" .. tostring(self._lek_global_six_tuple_solver_accepted == true));
			self._lek_legacy_forbid_forced_start_placement = (self._lek_global_six_tuple_solver_accepted == false);
			if self._lek_legacy_forbid_forced_start_placement then
				LekPlacementProbeAt(1, "### LekGlobalSix runId=" .. rid ..
					" legacy_after_tuple_fail=1 HB_SW_corner_force_disabled_if_triggered");
			end
		end
	else
		if lekSixBiasSkipsGlobalSolver then
			self._lek_global_six_placement_tier = "legacy_start_bias_disabled";
		elseif self._lek_global_six_solver ~= true then
			self._lek_global_six_placement_tier = "legacy_no_solver_hook";
		end
	end

	self._lek_choose_locations_legacy_start_placement = true;

	-- Set up list of regions (to be processed in this order).
	--
	-- First, make a list of all average fertility values...
	local regionAssignList = {};
	local averageFertilityListUnsorted = {};
	local averageFertilityListSorted = {}; -- Have to make this a separate table, not merely a pointer to the first table.
	for i, region_data in ipairs(self.regionData) do
		local thisRegionAvgFert = region_data[8];
		table.insert(averageFertilityListUnsorted, {i, thisRegionAvgFert});
		table.insert(averageFertilityListSorted, thisRegionAvgFert);
	end
	-- Now sort the copy low to high.
	table.sort(averageFertilityListSorted);
	-- Finally, match each sorted fertilty value to the matching unsorted region number and record in sequence.
	local iNumRegions = table.maxn(averageFertilityListSorted);
	for region_order = 1, iNumRegions do
		for loop, data_pair in ipairs(averageFertilityListUnsorted) do
			local unsorted_fert = data_pair[2];
			if averageFertilityListSorted[region_order] == unsorted_fert then
				local unsorted_reg_num = data_pair[1];
				table.insert(regionAssignList, unsorted_reg_num);
				-- HAVE TO remove the entry from the table in rare case of ties on fert 
				-- value. Or it will just match this value for a second time, then crash 
				-- when the region it was tied with ends up with nil data.
				table.remove(averageFertilityListUnsorted, loop);
				break
			end
		end
	end

	-- main loop
	-- lets check how many coastal civs are in the game and force that many regions to be coastal
	
	print("<<<<<<<<<<<<<<<<<< START OF REGION MANIPLUATION >>>>>>>>>>>>>>>>>>>>>");
	
	local iNumCoastNeeded = 0;
	local iNumRiverCivs, iNumPriorityCivs = 0, 0;
	local priority_lists = {};
	local res_reg = table.fill(false, self.iNumCivs);
	local reg_still_active = {};
	
	for loop = 1, self.iNumCivs do
		table.insert(reg_still_active, loop);
	end
	
	for loop = 1, self.iNumCivs do
		if not self._lek_ignore_all_start_bias then
			local playerNum = self.player_ID_list[loop]; -- MP games can have gaps between player numbers, so we cannot assume a sequential set of IDs.
			local player = Players[playerNum];
			local civType = GameInfo.Civilizations[player:GetCivilizationType()].Type;
			print("Player", playerNum, "of Civ Type", civType);
			local bNeedsCoastalStart = CivNeedsCoastalStart(civType);
			if self.ForceAllInlandPlayerSpawns == true then
				bNeedsCoastalStart = false;
			end
			-- Roll for coastal start for weak bias civs
			if self.MixedBias and Map.Rand(100, "") >= 60 and CivNeedsPlaceFirstCoastalStart(civType) then
				bNeedsCoastalStart = false;
			end
			if bNeedsCoastalStart == true then
				print("- - - - - - - needs Coastal Start!"); print("-");
				iNumCoastNeeded = iNumCoastNeeded + 1;
			else
				local bNeedsRiverStart = CivNeedsRiverStart(civType)
				if bNeedsRiverStart == true then
					print("- - - - - - - needs River Start!"); print("-");
					iNumRiverCivs = iNumRiverCivs + 1;
				else
					local iNumRegionPriority = GetNumStartRegionPriorityForCiv(civType)
					if iNumRegionPriority > 0 then
						print("- - - - - - - needs Region Priority!"); print("-");
						local table_of_this_civs_priority_needs = GetStartRegionPriorityListForCiv_GetIDs(civType)
						iNumPriorityCivs = iNumPriorityCivs + 1;
						priority_lists[playerNum] = table_of_this_civs_priority_needs;
					end
				end
			end
		end
	end
	
	for regcount = 1, iNumRegions do
		print("Region #", regcount, " Is type: ", self.regionTypes[regcount]);
	end
	
	print("-"); print("-"); print("--- REGION PRIORITY READOUT ---"); print("-");
	local iNumSinglePriority, iNumMultiPriority, iNumNeedFallbackPriority, iNumReserved = 0, 0, 0, 0;
	local single_priority, multi_priority, fallback_priority = {}, {}, {};
	local single_sorted, multi_sorted = {}, {};
	-- Separate priority civs in to two categories: single priority, multiple priority.
	for playerNum, priority_needs in pairs(priority_lists) do
		local len = table.maxn(priority_needs)
		if len == 1 then
			print("Player#", playerNum, "has a single Region Priority of type", priority_needs[1]);
			
			local found_reg = false;
			
			--loop thru all the regions and see if we can find a match
			for regcount = 1, iNumRegions do
				if self.regionTypes[regcount] == priority_needs[1] and found_reg == false then	
					-- this region matches this civ
					
					if res_reg[regcount] == false then
						print("Region match found for player #", playerNum, " Region #:", regcount);
						print("--");
						res_reg[regcount] = true;
						iNumReserved = iNumReserved + 1;
						found_reg = true;
						table.remove(reg_still_active, regcount);
					end
				end
			end
			
			-- if found_reg is still false at this point there are no regions left for this civs type, find the next best
			if found_reg == false then
				local iPriorityType = priority_needs[1];
				local choose_this_region = self:FindFallbackForUnmatchedRegionPriority(iPriorityType, reg_still_active)
				print("Fallback region found for player #", playerNum, " Region #:", choose_this_region);
				res_reg[choose_this_region] = true;
				iNumReserved = iNumReserved + 1;
				table.remove(reg_still_active, choose_this_region);
			end
		else
			print("Player#", playerNum, "has multiple Region Priority, this many types:", len);
			--local priority_data = {playerNum, len};
			--table.insert(multi_priority, priority_data)
			--iNumMultiPriority = iNumMultiPriority + 1;
		end
	end
	-- add extra coastals if balanced coast setting was chosen
	if self.BalancedCoastal and self.BalancedCoastalExactTwo and iNumRegions >= 2 then
		local cap = math.min(2, iNumRegions);
		local iNumCoastStart = iNumCoastNeeded;
		iNumCoastNeeded = math.min(math.max(iNumCoastStart, cap), cap);
	elseif self.BalancedCoastal then
		iRoll = Map.Rand(100, "Roll for extra coast");
		local iNumCoastStart = iNumCoastNeeded;
		if iNumRegions == 6 then
			if iNumCoastStart == 0 then
				iNumCoastNeeded = iNumCoastNeeded + (iRoll >= 20 and 1 or 0) + (iRoll >= 45 and 1 or 0) + (iRoll >= 95 and 1 or 0);
			end
			if iNumCoastStart == 1 then
				iNumCoastNeeded = iNumCoastNeeded + (iRoll >= 15 and 1 or 0) + (iRoll >= 90 and 1 or 0)
			end
			if iNumCoastStart == 2 then
				iNumCoastNeeded = iNumCoastNeeded + (iRoll >= 90 and 1 or 0)
			end
		end
		
		if iNumRegions == 8 then
			if iNumCoastStart == 0 then
				iNumCoastNeeded = iNumCoastNeeded + (iRoll >= 15 and 1 or 0) + (iRoll >= 35 and 1 or 0) + (iRoll >= 65 and 1 or 0) + (iRoll >= 85 and 1 or 0)
			end
			if iNumCoastStart == 1 then
				iNumCoastNeeded = iNumCoastNeeded + (iRoll >= 10 and 1 or 0) + (iRoll >= 55 and 1 or 0) + (iRoll >= 85 and 1 or 0)
			end
			if iNumCoastStart == 2 then
				iNumCoastNeeded = iNumCoastNeeded + (iRoll >= 35 and 1 or 0) + (iRoll >= 80 and 1 or 0)  + (iRoll >= 95 and 1 or 0)
			end
			if iNumCoastStart == 3 then
				iNumCoastNeeded = iNumCoastNeeded + (iRoll >= 60 and 1 or 0)  + (iRoll >= 90 and 1 or 0)
			end
			if iNumCoastStart == 4 then
				iNumCoastNeeded = iNumCoastNeeded + (iRoll >= 75 and 1 or 0)  + (iRoll >= 95 and 1 or 0)
			end
		end
		
		-- clear out reservations randomly
		local i = 1;
		while iNumRegions - iNumReserved > iNumCoastNeeded and i <= 100 do
		iRoll = Map.Rand(iNumRegions, "Roll region number to clear");
			if res_reg[iRoll] then
				res_reg[iRoll] = false;
				iNumReserved = iNumReserved - 1;
			end
			i = i + 1;
		end
	end
	-- now we have reserved the bias region all civ left must be coastal, so give them the remanining regions
	
	local coastBudgetOrig = iNumCoastNeeded;
	local gridCells = iW * iH;
	if self.iNumCivs == 6 and self._lek_enable_virtual_six_retries == true and self._lek_disable_virtual_six ~= true then
		local snapDD = {};
		local snapPC = {};
		local snapCS = {};
		for i = 1, gridCells do
			snapDD[i] = self.distanceData[i];
			snapPC[i] = self.playerCollisionData[i];
			snapCS[i] = self.cityStateData[i];
		end
		local function restoreLayers()
			for i = 1, gridCells do
				self.distanceData[i] = snapDD[i];
				self.playerCollisionData[i] = snapPC[i];
				self.cityStateData[i] = snapCS[i];
			end
			for r = 1, self.iNumCivs do
				self.startingPlots[r] = nil;
			end
		end
		local function copyBestStarts()
			local out = {};
			for r = 1, self.iNumCivs do
				local t = self.startingPlots[r];
				if not t or type(t[1]) ~= "number" or type(t[2]) ~= "number" then
					return nil;
				end
				out[r] = { t[1], t[2], t[3] };
			end
			return out;
		end
		local bestScore = -1;
		local bestUndesirable = math.huge;
		local bestUndesirableDetail = "";
		local bestStarts = nil;
		for attempt = 1, LEK_VIRTUAL_SIX_ATTEMPTS do
			restoreLayers();
			local order;
			if attempt == 1 then
				order = {};
				for i = 1, #regionAssignList do
					order[i] = regionAssignList[i];
				end
			else
				order = GetShuffledCopyOfTable(regionAssignList);
			end
			local ok = self:LekRunOneStartPlacementPass(order, iNumRegions, res_reg, coastBudgetOrig);
			if ok then
				local mnear, m2nd = self:LekMinNearestAmongSix();
				if mnear > 0 then
					local score = mnear * 1000 + m2nd;
					local undesirable, undesirableDetail = self:LekVirtualSixInlandOceanUndesirable();
					if score > bestScore or (score == bestScore and undesirable < bestUndesirable) then
						local cand = copyBestStarts();
						if cand then
							bestScore = score;
							bestUndesirable = undesirable;
							bestUndesirableDetail = undesirableDetail;
							bestStarts = cand;
						end
					end
				end
			end
		end
		restoreLayers();
		if bestStarts then
			for r = 1, self.iNumCivs do
				local t = bestStarts[r];
				if t then
					self.startingPlots[r] = { t[1], t[2], t[3] };
					self:PlaceImpactAndRipples(t[1], t[2]);
				end
			end
			if LekMapgenPrintAndDiagFile then
				LekMapgenPrintAndDiagFile("### LekVirtualSix: picked minNearestCombo=" .. tostring(bestScore) .. " undesirableTotal=" .. tostring(bestUndesirable));
				LekMapgenPrintAndDiagFile("### LekVirtualSix: undesirableDetail " .. tostring(bestUndesirableDetail));
			end
		else
			local order = {};
			for i = 1, #regionAssignList do
				order[i] = regionAssignList[i];
			end
			self:LekRunOneStartPlacementPass(order, iNumRegions, res_reg, coastBudgetOrig);
			if LekMapgenPrint then LekMapgenPrint("### LekVirtualSix: fallback vanilla order (no successful retry set)"); end
		end
	else
		local order = {};
		for i = 1, #regionAssignList do
			order[i] = regionAssignList[i];
		end
		self:LekRunOneStartPlacementPass(order, iNumRegions, res_reg, coastBudgetOrig);
	end
	--

	--[[ Printout of start plots. Debug use only.
	print("-");
	print("--- Table of results, New Start Finder ---");
	for loop, startData in ipairs(self.startingPlots) do
		print("-");
		print("Region#", loop, " has start plot at: ", startData[1], startData[2], "with Fertility Rating of ", startData[3]);
	end
	print("-");
	print("--- Table of results, New Start Finder ---");
	print("-");
	]]--
	
	--[[ Printout of Impact and Ripple data.
	print("--- Impact and Ripple ---");
	PrintContentsOfTable(self.distanceData)
	print("-");  ]]--

	if self._lek_global_six_tuple_solver_accepted == nil then
		self._lek_global_six_tuple_solver_accepted = true;
	end
	local maxRegenL = _lek_global_six_regen_max_layouts;
	if type(maxRegenL) ~= "number" or maxRegenL < 1 then
		maxRegenL = 4;
	end
	local att = _lek_map_layout_attempt or 1;
	if self._lek_global_six_solver == true and not lekSixBiasSkipsGlobalSolver and self.iNumCivs == 6
		and self._lek_global_six_tuple_regen_on_solver_fail == true
		and self._lek_global_six_tuple_solver_accepted == false and att < maxRegenL then
		_lek_global_six_request_map_regen_reason = "tuple_solver_no_accepted_tuple";
		_lek_global_six_request_map_regen = true;
		LekPlacementProbeAt(1, "### LekGlobalSix mapRegen request runId=" .. tostring(_lek_run_id or "na") ..
			" layout=" .. tostring(att) .. "/" .. tostring(maxRegenL) .. " reason=tuple_solver_no_accepted_tuple");
	end

	if _lek_global_six_request_map_regen ~= true then
		self:LekAssertBalancedCoastalExactTwoOrRegen();
	end

	if lekProbe then
		local rid = tostring(_lek_run_id or "na");
		local n = self.iNumCivs or 0;
		local parts = {};
		for r = 1, n do
			local sp = self.startingPlots[r];
			if sp and type(sp[1]) == "number" and type(sp[2]) == "number" then
				parts[#parts + 1] = string.format("r%d=%d,%d", r, sp[1], sp[2]);
			else
				parts[#parts + 1] = string.format("r%d=nil", r);
			end
		end
		LekPlacementProbeAt(1, "### ChooseLocations end runId=" .. rid ..
			" legacy_path=1 starts_placed=" .. tostring(n)
			.. " placement_tier=" .. tostring(self._lek_global_six_placement_tier or "?"));
		LekPlacementProbeLog("### ChooseLocations end runId=" .. rid ..
			" legacy_path_completed=1 starts=" .. table.concat(parts, ";"));
		self:LekGlobalSix_OK_LogDiagnostics();
	end
end
------------------------------------------------------------------------------
-- Start of functions tied to BalanceAndAssign()
------------------------------------------------------------------------------
function AssignStartingPlots:AttemptToPlaceBonusResourceAtPlot(x, y, bAllowOasis, Fish_Count)
	-- Returns two booleans. First is true if something was placed. Second true if Oasis placed.
	-- maxCapitalGoodiesLeft: per-plot branch budget for legacy bonus placements (align with iNumFoodBonusNeeded cap of 3; coastal fish re-balance uses LekPlaceFishNearStart goodies_cap=3 separately).
	--print("-"); print("Attempting to place a Bonus at: ", x, y);
	local plot = Map.GetPlot(x, y);
	local maxCapitalGoodiesLeft = 3
	local maxFishPlace = Fish_Count
	if plot == nil then
		--print("Placement failed, plot was nil.");
		return false
	end
	if plot:GetResourceType(-1) ~= -1 then
		--print("Plot already had a resource.");
		return false
	end
	local terrainType = plot:GetTerrainType()
	if terrainType == TerrainTypes.TERRAIN_SNOW then
		--print("Plot was arctic land buried beneath endless snow.");
		return false
	end
	local featureType = plot:GetFeatureType()
	if featureType == FeatureTypes.FEATURE_OASIS then
		--print("Plot already had an Oasis.");
		return false
	end
	local plotType = plot:GetPlotType()
	--
	
	-- Made by EAP
	-- Note: a lot of this code doesn't do anything, yet, lot of it is for if you increase the iNumFoodBonusNeeded above 3 at the end of the iNumFoodBonusNeeded calculations
	-- Here we place possible fish
	if plotType == PlotTypes.PLOT_OCEAN then
		if maxCapitalGoodiesLeft > 0 and maxFishPlace > 0 then
			if terrainType == TerrainTypes.TERRAIN_COAST and featureType == FeatureTypes.NO_FEATURE then
				if plot:IsLake() == false then -- Place Fish
					plot:SetResourceType(self.fish_ID, 1);
					print("Placed Fish.");
					self.amounts_of_resources_placed[self.fish_ID + 1] = self.amounts_of_resources_placed[self.fish_ID + 1] + 1;
					maxFishPlace = maxFishPlace - 1;
					return true, false, true
				end
			end
		end
	end
	if featureType == FeatureTypes.FEATURE_JUNGLE then -- Place Banana
		if maxCapitalGoodiesLeft > 0 then
		plot:SetResourceType(self.banana_ID, 1);
		print("Placed Banana.");
		self.amounts_of_resources_placed[self.banana_ID + 1] = self.amounts_of_resources_placed[self.banana_ID + 1] + 1;
		maxCapitalGoodiesLeft = maxCapitalGoodiesLeft - 1;
		return true, false, false
		else
		return false
		end
	elseif featureType == FeatureTypes.FEATURE_FOREST then -- Place Deer
		if maxCapitalGoodiesLeft > 0 then
		plot:SetResourceType(self.deer_ID, 1);
		print("Placed Deer.");
		self.amounts_of_resources_placed[self.deer_ID + 1] = self.amounts_of_resources_placed[self.deer_ID + 1] + 1;
		maxCapitalGoodiesLeft = maxCapitalGoodiesLeft - 1;
		return true, false, false
		else
		return false
		end
	elseif featureType == FeatureTypes.FEATURE_FOREST then -- Place Hardwood
		plot:SetResourceType(self.hardwood_ID, 1);
		print("Placed Hardwood.");
		self.amounts_of_resources_placed[self.hardwood_ID + 1] = self.amounts_of_resources_placed[self.hardwood_ID + 1] + 1;
		return true, false, false
	elseif plotType == PlotTypes.PLOT_HILLS and featureType == FeatureTypes.NO_FEATURE and terrainType ~= TerrainTypes.TERRAIN_DESERT then
		-- add a sheep or deer, for deer add forest first
		if maxCapitalGoodiesLeft > 0 then
			local hillsDeerPct = (terrainType == TerrainTypes.TERRAIN_TUNDRA) and 80 or 90;
			if Map.Rand(100, "") < hillsDeerPct then plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1); end
			plot:SetResourceType(self.deer_ID, 1);
			print("Placed Deer xx.");
			self.amounts_of_resources_placed[self.deer_ID + 1] = self.amounts_of_resources_placed[self.deer_ID + 1] + 1;
			maxCapitalGoodiesLeft = maxCapitalGoodiesLeft - 1;
			return true, false, false
		else
			return false
		end
	-- Sheep or Deer on Hills, if not desert	
	elseif plotType == PlotTypes.PLOT_HILLS and featureType == FeatureTypes.NO_FEATURE and terrainType ~= TerrainTypes.TERRAIN_DESERT then
		plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1);
		plot:SetResourceType(self.hardwood_ID, 1);
		print("Placed Hardwood.");
		self.amounts_of_resources_placed[self.hardwood_ID + 1] = self.amounts_of_resources_placed[self.hardwood_ID + 1] + 1;
		return true, false, false
	elseif plotType == PlotTypes.PLOT_HILLS and featureType == FeatureTypes.NO_FEATURE and terrainType ~= TerrainTypes.TERRAIN_DESERT then
		plot:SetResourceType(self.sheep_ID, 1);
		print("Placed Sheep xx.");
		self.amounts_of_resources_placed[self.sheep_ID + 1] = self.amounts_of_resources_placed[self.sheep_ID + 1] + 1;
		return true, false, false
		
	-- Flat grassland Bison, Deer or Cow
	elseif plotType == PlotTypes.PLOT_LAND and featureType == FeatureTypes.NO_FEATURE and terrainType == TerrainTypes.TERRAIN_GRASS then
		local placethis = Map.Rand(100, "");
		if placethis < 50 then
			if maxCapitalGoodiesLeft > 0 then	
				plot:SetResourceType(self.bison_ID, 1);
				print("Placed Bison.");
				self.amounts_of_resources_placed[self.bison_ID + 1] = self.amounts_of_resources_placed[self.bison_ID + 1] + 1;
				maxCapitalGoodiesLeft = maxCapitalGoodiesLeft - 1;
				return true, false, false
			else
				return false
			end
		elseif placethis > 50 and placethis < 90 then
			if maxCapitalGoodiesLeft > 0 then
				plot:SetResourceType(self.sheep_ID, 1);
				AssignStartingPlots.LekMaybePromoteLandToHill(plot, 70, "Lek sheep capital_goodies grass hill pct");
				print("Placed Sheep.");
				self.amounts_of_resources_placed[self.sheep_ID + 1] = self.amounts_of_resources_placed[self.sheep_ID + 1] + 1;
				maxCapitalGoodiesLeft = maxCapitalGoodiesLeft - 1;
				return true, false, false
			else
				return false
			end
		else
			if maxCapitalGoodiesLeft > 0 then	
				plot:SetResourceType(self.stone_ID, 1);
				print("Placed Stone.");
				self.amounts_of_resources_placed[self.stone_ID + 1] = self.amounts_of_resources_placed[self.stone_ID + 1] + 1;
				maxCapitalGoodiesLeft = maxCapitalGoodiesLeft - 1;
				return true, false, false
			else
				return false
			end
		end
	elseif plotType == PlotTypes.PLOT_LAND and featureType == FeatureTypes.NO_FEATURE and terrainType == TerrainTypes.TERRAIN_GRASS then
		local placethis = Map.Rand(100, "");
		if placethis < 67 then
			if maxCapitalGoodiesLeft > 0 then
				if Map.Rand(100, "") < 90 then plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1); end
				plot:SetResourceType(self.deer_ID, 1);
				print("Placed Deer xx.");
				self.amounts_of_resources_placed[self.deer_ID + 1] = self.amounts_of_resources_placed[self.deer_ID + 1] + 1;
				maxCapitalGoodiesLeft = maxCapitalGoodiesLeft - 1;
				return true, false, false
			else
				return false
			end
		else
			if maxCapitalGoodiesLeft > 0 then
				if Map.Rand(100, "") < 90 then plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1); end
				plot:SetResourceType(self.deer_ID, 1);
				plot:SetPlotType(PlotTypes.PLOT_HILLS, false, true); -- make it a hill
				print("Placed Deer xx.");
				self.amounts_of_resources_placed[self.deer_ID + 1] = self.amounts_of_resources_placed[self.deer_ID + 1] + 1;
				maxCapitalGoodiesLeft = maxCapitalGoodiesLeft - 1;
				return true, false, false
			else
				return false
			end
		end
	elseif plotType == PlotTypes.PLOT_LAND and featureType == FeatureTypes.NO_FEATURE and terrainType == TerrainTypes.TERRAIN_GRASS then
			plot:SetResourceType(self.cow_ID, 1);
			print("Placed Cow.");
			self.amounts_of_resources_placed[self.cow_ID + 1] = self.amounts_of_resources_placed[self.cow_ID + 1] + 1;
		return true, false, false
	
	-- Wheat, Bison, Cow or Hardwood on Flat plains
	elseif plotType == PlotTypes.PLOT_LAND and featureType == FeatureTypes.NO_FEATURE and terrainType == TerrainTypes.TERRAIN_PLAINS then
		local placethis = Map.Rand(100, "");
		if placethis < 75 then
			if maxCapitalGoodiesLeft > 0 then
				plot:SetResourceType(self.wheat_ID, 1);
				print("Placed Wheat.");
				self.amounts_of_resources_placed[self.wheat_ID + 1] = self.amounts_of_resources_placed[self.wheat_ID + 1] + 1;
				maxCapitalGoodiesLeft = maxCapitalGoodiesLeft - 1;
				return true, false, false
			else
				return false
			end
		else
			if maxCapitalGoodiesLeft > 0 then
				plot:SetResourceType(self.bison_ID, 1);
				print("Placed Bison.");
				self.amounts_of_resources_placed[self.bison_ID + 1] = self.amounts_of_resources_placed[self.bison_ID + 1] + 1;
				maxCapitalGoodiesLeft = maxCapitalGoodiesLeft - 1;
				return true, false, false
			else
				return false
			end
		end
	elseif plotType == PlotTypes.PLOT_LAND and featureType == FeatureTypes.NO_FEATURE and terrainType == TerrainTypes.TERRAIN_PLAINS then
		if maxCapitalGoodiesLeft > 0 then
			plot:SetResourceType(self.bison_ID, 1);
			print("Placed Bison.");
			self.amounts_of_resources_placed[self.bison_ID + 1] = self.amounts_of_resources_placed[self.bison_ID + 1] + 1;
			maxCapitalGoodiesLeft = maxCapitalGoodiesLeft - 1;
			return true, false, false
		else
			return false
		end
	-- Place Wheat on Floodplains
	elseif terrainType == TerrainTypes.TERRAIN_DESERT and plotType == PlotTypes.PLOT_LAND and featureType == FeatureTypes.FEATURE_FLOOD_PLAINS then
		-- Place Wheat
		local placethis = Map.Rand(100, "");
		if placethis < 25 then
			plot:SetResourceType(self.wheat_ID, 1);
			print("Placed Wheat.");
			self.amounts_of_resources_placed[self.wheat_ID + 1] = self.amounts_of_resources_placed[self.wheat_ID + 1] + 1;
			return true, false, false
		elseif placethis > 25 and placethis < 75 then
			plot:SetResourceType(self.sheep_ID, 1);
			AssignStartingPlots.LekMaybePromoteLandToHill(plot, 100, "Lek sheep capital_goodies flood hill pct");
			plot:SetFeatureType(FeatureTypes.NO_FEATURE, -1);
			print("Placed Sheep.");
			self.amounts_of_resources_placed[self.sheep_ID + 1] = self.amounts_of_resources_placed[self.sheep_ID + 1] + 1;
			maxCapitalGoodiesLeft = maxCapitalGoodiesLeft - 1;
			return true, false, false
		else
			if maxCapitalGoodiesLeft > 0 then	-- we do actually want a limit on stone placed
				plot:SetResourceType(self.stone_ID, 1);
				print("Placed Stone.");
				self.amounts_of_resources_placed[self.stone_ID + 1] = self.amounts_of_resources_placed[self.stone_ID + 1] + 1;
				maxCapitalGoodiesLeft = maxCapitalGoodiesLeft - 1;
				return true, false, false
			else
				return false
			end
		end
		
		
	elseif plotType == PlotTypes.PLOT_LAND and featureType == FeatureTypes.NO_FEATURE and terrainType == TerrainTypes.TERRAIN_PLAINS then
		plot:SetResourceType(self.cow_ID, 1);
		print("Placed Cow.");
		self.amounts_of_resources_placed[self.cow_ID + 1] = self.amounts_of_resources_placed[self.cow_ID + 1] + 1;
		return true, false, false
	elseif plotType == PlotTypes.PLOT_LAND and featureType == FeatureTypes.NO_FEATURE and terrainType == TerrainTypes.TERRAIN_PLAINS then
		plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1);
		plot:SetResourceType(self.hardwood_ID, 1);
		print("Placed Hardwood.");
		self.amounts_of_resources_placed[self.hardwood_ID + 1] = self.amounts_of_resources_placed[self.hardwood_ID + 1] + 1;
		return true, false, false
		
	-- Tundra support, does not use maxCapitalGoodiesLeft (tundra path bypasses that budget for now)
	elseif terrainType == TerrainTypes.TERRAIN_TUNDRA and plotType == PlotTypes.PLOT_LAND and featureType == FeatureTypes.NO_FEATURE then -- Place Deer
				if Map.Rand(100, "") < 80 then plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1); end
				plot:SetResourceType(self.deer_ID, 1);
					print("Placed Deer.");
					self.amounts_of_resources_placed[self.deer_ID + 1] = self.amounts_of_resources_placed[self.deer_ID + 1] + 1;
					return true, false, false
	elseif terrainType == TerrainTypes.TERRAIN_TUNDRA and plotType == PlotTypes.PLOT_LAND and featureType == FeatureTypes.NO_FEATURE then -- Place Hardwood
					--add forest to the location to make it even better
					plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1);
					plot:SetResourceType(self.hardwood_ID, 1);
					print("Placed Hardwood.");
					self.amounts_of_resources_placed[self.hardwood_ID + 1] = self.amounts_of_resources_placed[self.hardwood_ID + 1] + 1;
					return true, false, false
	-- Place Wheat on Desert
	elseif terrainType == TerrainTypes.TERRAIN_DESERT and plotType == PlotTypes.PLOT_LAND and featureType == FeatureTypes.NO_FEATURE then 
		if plot:IsFreshWater() then
			-- Place Wheat
			plot:SetResourceType(self.wheat_ID, 1);
			print("Placed Wheat.");
			self.amounts_of_resources_placed[self.wheat_ID + 1] = self.amounts_of_resources_placed[self.wheat_ID + 1] + 1;
			return true, false, false
		elseif bAllowOasis then -- Place Oasis
					plot:SetFeatureType(FeatureTypes.FEATURE_OASIS, -1);
					print("Placed Oasis.");
					return true, true, false
		else
					print("Not allowed to place any more Oasis help at this site.");
		end
	end
	
	-- Nothing placed.
	return false, false, false
end
------------------------------------------------------------------------------
function AssignStartingPlots:AttemptToPlaceHillsAtPlot(x, y)
	-- This function will add hills at a specified plot, if able.
	--print("-"); print("Attempting to add Hills at: ", x, y);
	local plot = Map.GetPlot(x, y);
	if plot == nil then
		--print("Placement failed, plot was nil.");
		return false
	end
	if plot:GetResourceType(-1) ~= -1 then
		--print("Placement failed, plot had a resource.");
		return false
	end
	local plotType = plot:GetPlotType()
	local featureType = plot:GetFeatureType();
	if plotType == PlotTypes.PLOT_OCEAN then
		--print("Placement failed, plot was water.");
		return false
	elseif plot:IsRiverSide() then
		--print("Placement failed, plot was next to river.");
		return false
	elseif featureType == FeatureTypes.FEATURE_FOREST then
		--print("Placement failed, plot had a forest already.");
		return false
	end	
	-- Change the plot type from flatlands to hills and clear any features.
	plot:SetPlotType(PlotTypes.PLOT_HILLS, false, true);
	plot:SetFeatureType(FeatureTypes.NO_FEATURE, -1);
	return true
end
------------------------------------------------------------------------------
function AssignStartingPlots:AttemptToPlaceSmallStrategicAtPlot(x, y)
	-- This function will add a small horse or iron source to a specified plot, if able.
	--print("-"); print("Attempting to add Small Strategic resource at: ", x, y);
	local plot = Map.GetPlot(x, y);
	if plot == nil then
		--print("Placement failed, plot was nil.");
		return false
	end
	if plot:GetResourceType(-1) ~= -1 then
		--print("Plot already had a resource.");
		return false
	end
	local plotType = plot:GetPlotType()
	local terrainType = plot:GetTerrainType()
	local featureType = plot:GetFeatureType()
	if plotType ~= PlotTypes.PLOT_LAND then
		--print("Placement failed, plot was not flat land.");
		return false
	elseif featureType == FeatureTypes.NO_FEATURE then
		if terrainType == TerrainTypes.TERRAIN_GRASS or terrainType == TerrainTypes.TERRAIN_PLAINS then -- Could be horses.
			local choice = self.horse_ID;
			local diceroll = Map.Rand(5, "Selection of Strategic Resource type - Start Normalization LUA");
			if diceroll > 3 then
				choice = self.iron_ID;
				--print("Placed Iron.");
			else
				--print("Placed Horse.");
			end
			plot:SetResourceType(choice, 2);
			AssignStartingPlots.LekStratAuditRecordHorseIron(self, choice, 2, plot, x, y);
			self.amounts_of_resources_placed[choice + 1] = self.amounts_of_resources_placed[choice + 1] + 2;
		else -- Can't be horses.
			plot:SetResourceType(self.iron_ID, 2);
			AssignStartingPlots.LekStratAuditRecordHorseIron(self, self.iron_ID, 2, plot, x, y);
			self.amounts_of_resources_placed[self.iron_ID + 1] = self.amounts_of_resources_placed[self.iron_ID + 1] + 2;
			--print("Placed Iron.");
		end
		return true
	end
	--print("Placement failed, feature in the way.");
	return false
end
------------------------------------------------------------------------------
function AssignStartingPlots:AddStrategicBalanceResources(region_number)
	-- This function adds the required Strategic Resources to start plots, for
	-- games that have selected to enable Strategic Resource Balance.
	local iW, iH = Map.GetGridSize();
	local start_point_data = self.startingPlots[region_number];
	local x = start_point_data[1];
	local y = start_point_data[2];
	local plot = Map.GetPlot(x, y);
	local plotIndex = y * iW + x + 1;
	local wrapX = Map:IsWrapX();
	local wrapY = Map:IsWrapY();
	local odd = self.firstRingYIsOdd;
	local even = self.firstRingYIsEven;
	local nextX, nextY, plot_adjustments;
	local iron_list, horse_list, oil_list, alum_list, coal_list, uran_list = {}, {}, {}, {}, {}, {};
	local iron_fallback, horse_fallback, oil_fallback, alum_fallback, coal_fallback, uran_fallback = {}, {}, {}, {}, {}, {};
	local radius = 3;
	local OilToPlace = 2;
	local prevStratAuditCtx = self._lek_strat_audit_context;
	if self.resource_setting == 5 then
		self._lek_strat_audit_context = "strat_balance_region=" .. tostring(region_number);
	end
	
	--print("- Adding Strategic Balance Resources for start location in Region#", region_number);
	
	for ripple_radius = 1, radius do
		local ripple_value = radius - ripple_radius + 1;
		local currentX = x - ripple_radius;
		local currentY = y;
		for direction_index = 1, 6 do
			for plot_to_handle = 1, ripple_radius do
			 	if currentY / 2 > math.floor(currentY / 2) then
					plot_adjustments = odd[direction_index];
				else
					plot_adjustments = even[direction_index];
				end
				nextX = currentX + plot_adjustments[1];
				nextY = currentY + plot_adjustments[2];
				if wrapX == false and (nextX < 0 or nextX >= iW) then
					-- X is out of bounds.
				elseif wrapY == false and (nextY < 0 or nextY >= iH) then
					-- Y is out of bounds.
				else
					local realX = nextX;
					local realY = nextY;
					if wrapX then
						realX = realX % iW;
					end
					if wrapY then
						realY = realY % iH;
					end
					-- We've arrived at the correct x and y for the current plot.
					local plot = Map.GetPlot(realX, realY);
					local plotType = plot:GetPlotType()
					local terrainType = plot:GetTerrainType()
					local featureType = plot:GetFeatureType()
					local plotIndex = realY * iW + realX + 1;
					-- Check this plot for resource placement eligibility.
					if plotType == PlotTypes.PLOT_HILLS then
						if ripple_radius < 3 then
							table.insert(iron_list, plotIndex)

						else
							table.insert(iron_fallback, plotIndex)

						end
						if terrainType ~= TerrainTypes.TERRAIN_SNOW and featureType == FeatureTypes.NO_FEATURE then
							table.insert(horse_fallback, plotIndex)
						end
					elseif plotType == PlotTypes.PLOT_LAND then
						if featureType == FeatureTypes.NO_FEATURE then
							if terrainType == TerrainTypes.TERRAIN_TUNDRA or terrainType == TerrainTypes.TERRAIN_DESERT then
								if ripple_radius < 3 then
									table.insert(oil_list, plotIndex)
								else
									table.insert(oil_fallback, plotIndex)
								end
								table.insert(iron_fallback, plotIndex)
								table.insert(horse_fallback, plotIndex)
							elseif terrainType == TerrainTypes.TERRAIN_PLAINS or terrainType == TerrainTypes.TERRAIN_GRASS then
								if ripple_radius < 3 then
									table.insert(horse_list, plotIndex)
								else
									table.insert(horse_fallback, plotIndex)
								end
								table.insert(iron_fallback, plotIndex)
								table.insert(oil_fallback, plotIndex)
							elseif terrainType == TerrainTypes.TERRAIN_SNOW then
								if ripple_radius < 3 then
									table.insert(oil_list, plotIndex)
								else
									table.insert(oil_fallback, plotIndex)
								end
							end
						elseif featureType == FeatureTypes.FEATURE_MARSH then		
							if ripple_radius < 3 then
								table.insert(oil_list, plotIndex)
							else
								table.insert(oil_fallback, plotIndex)
							end
							table.insert(iron_fallback, plotIndex)
						elseif featureType == FeatureTypes.FEATURE_FLOOD_PLAINS then		
							table.insert(horse_fallback, plotIndex)
							table.insert(oil_fallback, plotIndex)
						elseif featureType == FeatureTypes.FEATURE_JUNGLE or featureType == FeatureTypes.FEATURE_FOREST then		
							table.insert(iron_fallback, plotIndex)
							table.insert(oil_fallback, plotIndex)
						end
					end
					currentX, currentY = nextX, nextY;
				end
			end
		end
	end


	local radius = 4;
	for ripple_radius = 1, radius do
		local ripple_value = radius - ripple_radius + 1;
		local currentX = x - ripple_radius;
		local currentY = y;
		for direction_index = 1, 6 do
			for plot_to_handle = 1, ripple_radius do
			 	if currentY / 2 > math.floor(currentY / 2) then
					plot_adjustments = odd[direction_index];
				else
					plot_adjustments = even[direction_index];
				end
				nextX = currentX + plot_adjustments[1];
				nextY = currentY + plot_adjustments[2];
				if wrapX == false and (nextX < 0 or nextX >= iW) then
					-- X is out of bounds.
				elseif wrapY == false and (nextY < 0 or nextY >= iH) then
					-- Y is out of bounds.
				else
					local realX = nextX;
					local realY = nextY;
					if wrapX then
						realX = realX % iW;
					end
					if wrapY then
						realY = realY % iH;
					end
					-- We've arrived at the correct x and y for the current plot.
					local plot = Map.GetPlot(realX, realY);
					local plotType = plot:GetPlotType()
					local terrainType = plot:GetTerrainType()
					local featureType = plot:GetFeatureType()
					local plotIndex = realY * iW + realX + 1;
					-- Check this plot for resource placement eligibility.
					if plotType == PlotTypes.PLOT_HILLS then
						if ripple_radius < 4 then
							table.insert(alum_list, plotIndex)
							table.insert(coal_list, plotIndex)
						else
							table.insert(alum_fallback, plotIndex)
							table.insert(coal_fallback, plotIndex)
						end
						if terrainType ~= TerrainTypes.TERRAIN_SNOW and featureType == FeatureTypes.NO_FEATURE then
							table.insert(horse_fallback, plotIndex)
						end
					elseif plotType == PlotTypes.PLOT_LAND then
						if featureType == FeatureTypes.NO_FEATURE then
							if terrainType == TerrainTypes.TERRAIN_TUNDRA or terrainType == TerrainTypes.TERRAIN_DESERT then
								if ripple_radius < 4 then
									table.insert(coal_list, plotIndex)
									table.insert(alum_list, plotIndex)
									table.insert(oil_fallback, plotIndex)
								else
									table.insert(coal_fallback, plotIndex)
									table.insert(alum_fallback, plotIndex)
								end
							elseif terrainType == TerrainTypes.TERRAIN_PLAINS or terrainType == TerrainTypes.TERRAIN_GRASS then
								if ripple_radius < 4 then
									table.insert(coal_list, plotIndex)
									table.insert(alum_list, plotIndex)
									table.insert(oil_fallback, plotIndex)
								else
									table.insert(alum_fallback, plotIndex)
									table.insert(coal_fallback, plotIndex)
								end
							elseif terrainType == TerrainTypes.TERRAIN_SNOW then
								if ripple_radius < 4 then
									table.insert(coal_list, plotIndex)
									table.insert(alum_list, plotIndex)
									table.insert(oil_fallback, plotIndex)
								else
									table.insert(alum_fallback, plotIndex)
									table.insert(coal_fallback, plotIndex)
								end
							end
						elseif featureType == FeatureTypes.FEATURE_MARSH then		
							if ripple_radius < 4 then
								table.insert(coal_list, plotIndex)
								table.insert(alum_list, plotIndex)
								table.insert(oil_fallback, plotIndex)
							else
								table.insert(alum_fallback, plotIndex)
								table.insert(coal_fallback, plotIndex)
							end
						elseif featureType == FeatureTypes.FEATURE_FLOOD_PLAINS then		
							table.insert(alum_fallback, plotIndex)
							table.insert(coal_fallback, plotIndex)
						elseif featureType == FeatureTypes.FEATURE_JUNGLE or featureType == FeatureTypes.FEATURE_FOREST then		
							table.insert(alum_fallback, plotIndex)
							table.insert(coal_fallback, plotIndex)
							table.insert(oil_fallback, plotIndex)
						end
					end
					currentX, currentY = nextX, nextY;
				end
			end
		end
	end

	local radius = 6;
	for ripple_radius = 4, radius do
		local ripple_value = radius - ripple_radius + 1;
		local currentX = x - ripple_radius;
		local currentY = y;
		for direction_index = 1, 6 do
			for plot_to_handle = 1, ripple_radius do
			 	if currentY / 2 > math.floor(currentY / 2) then
					plot_adjustments = odd[direction_index];
				else
					plot_adjustments = even[direction_index];
				end
				nextX = currentX + plot_adjustments[1];
				nextY = currentY + plot_adjustments[2];
				if wrapX == false and (nextX < 0 or nextX >= iW) then
					-- X is out of bounds.
				elseif wrapY == false and (nextY < 0 or nextY >= iH) then
					-- Y is out of bounds.
				else
					local realX = nextX;
					local realY = nextY;
					if wrapX then
						realX = realX % iW;
					end
					if wrapY then
						realY = realY % iH;
					end
					-- We've arrived at the correct x and y for the current plot.
					local plot = Map.GetPlot(realX, realY);
					local plotType = plot:GetPlotType()
					local terrainType = plot:GetTerrainType()
					local featureType = plot:GetFeatureType()
					local plotIndex = realY * iW + realX + 1;
					-- Check this plot for resource placement eligibility.
					if plotType == PlotTypes.PLOT_LAND then
						if featureType ~= FeatureTypes.FEATURE_FLOOD_PLAINS then
							if featureType ~= FeatureTypes.FEATURE_OASIS then
								if terrainType == TerrainTypes.TERRAIN_TUNDRA or terrainType == TerrainTypes.TERRAIN_DESERT or terrainType == TerrainTypes.TERRAIN_PLAINS or terrainType == TerrainTypes.TERRAIN_GRASS or terrainType == TerrainTypes.TERRAIN_SNOW then
									table.insert(uran_list, plotIndex)
									table.insert(uran_fallback, plotIndex)
								end
							end
						end
					end
					currentX, currentY = nextX, nextY;
				end
			end
		end
	end

	local uran_amt, horse_amt, oil_amt, iron_amt, coal_amt, alum_amt = self:GetMajorStrategicResourceQuantityValues()
	local shuf_list;
	local placed_iron, placed_horse, placed_oil, placed_alum, placed_coal, placed_uran = false, false, false, false, false, false;
	-- RS5 oil/uranium recipe is band guarantees (replaces OG 2×oil + 2×uran-qty1 below).
	local useOuBands = (self.resource_setting or 0) == 5 and AssignStartingPlots.LekStratOuBandsEnabled();

	-- OG balance path only: uranium deposits were qty=1.
	if not useOuBands then
		uran_amt = 1;
	end

	if table.maxn(iron_list) > 0 then
		if self.resource_setting == 5 then
			self._lek_strat_audit_context = "strat_balance_iron_primary:region=" .. tostring(region_number)
				.. " primaryN=" .. tostring(table.maxn(iron_list));
		end
		shuf_list = GetShuffledCopyOfTable(iron_list)
		iNumLeftToPlace = self:PlaceSpecificNumberOfResources(self.iron_ID, iron_amt, 1, 1, -1, 0, 0, shuf_list);
		if iNumLeftToPlace == 0 then
			placed_iron = true;
		end
	end
	if table.maxn(horse_list) > 0 then
		if self.resource_setting == 5 then
			self._lek_strat_audit_context = "strat_balance_horse_primary:region=" .. tostring(region_number)
				.. " primaryN=" .. tostring(table.maxn(horse_list));
		end
		shuf_list = GetShuffledCopyOfTable(horse_list)
		iNumLeftToPlace = self:PlaceSpecificNumberOfResources(self.horse_ID, horse_amt, 1, 1, -1, 0, 0, shuf_list);
		if iNumLeftToPlace == 0 then
			placed_horse = true;
		end
	end

	if useOuBands then
		self:LekStratPlaceOuBandsForRegion(region_number);
		placed_oil = true;
		placed_uran = true;
	else
		if table.maxn(oil_list) > 0 then
			if self.resource_setting == 5 then
				self._lek_strat_audit_context = "strat_balance_oil_primary:region=" .. tostring(region_number)
					.. " primaryN=" .. tostring(table.maxn(oil_list));
			end
			shuf_list = GetShuffledCopyOfTable(oil_list)
			iNumLeftToPlace = self:PlaceSpecificNumberOfResources(self.oil_ID, oil_amt, 2, 1, -1, 0, 0, shuf_list);
			if iNumLeftToPlace == 0 then
				print("All Oil Placed First Attempt");
				placed_oil = true;
				OilToPlace = 0;
			else
				OilToPlace = 1;
			end
		end
		if self.start_locations == 2 then
			if table.maxn(uran_list) > 0 then
				if self.resource_setting == 5 then
					self._lek_strat_audit_context = "strat_balance_uran_primary:region=" .. tostring(region_number)
						.. " primaryN=" .. tostring(table.maxn(uran_list));
				end
				shuf_list = GetShuffledCopyOfTable(uran_list)
				iNumLeftToPlace = self:PlaceSpecificNumberOfResources(self.uranium_ID, uran_amt, 2, 1, 9, 0, 0, shuf_list);
				if iNumLeftToPlace == 0 then
					placed_uran = true;
				end
			end
		end
	end
	
	if self.start_locations == 5 or self.start_locations == 6 or self.start_locations == 1 or self.start_locations == 2 then
		if table.maxn(alum_list) > 0 then
			shuf_list = GetShuffledCopyOfTable(alum_list)
			iNumLeftToPlace = self:PlaceSpecificNumberOfResources(self.aluminum_ID, alum_amt, 1, 1, -1, 0, 0, shuf_list);
			if iNumLeftToPlace == 0 then
				placed_alum = true;
			end
		end
	end
	
	if self.start_locations == 4 or self.start_locations == 6 or self.start_locations == 1  or self.start_locations == 2 then
		if table.maxn(coal_list) > 0 then
			shuf_list = GetShuffledCopyOfTable(coal_list)
			iNumLeftToPlace = self:PlaceSpecificNumberOfResources(self.coal_ID, coal_amt, 1, 1, -1, 0, 0, shuf_list);
			if iNumLeftToPlace == 0 then
				placed_coal = true;
			end
		end
	end

	if placed_iron == false and table.maxn(iron_fallback) > 0 then
		if self.resource_setting == 5 then
			self._lek_strat_audit_context = "strat_balance_iron_fallback:region=" .. tostring(region_number)
				.. " fallbackN=" .. tostring(table.maxn(iron_fallback));
		end
		shuf_list = GetShuffledCopyOfTable(iron_fallback)
		iNumLeftToPlace = self:PlaceSpecificNumberOfResources(self.iron_ID, iron_amt, 1, 1, -1, 0, 0, shuf_list);
		if iNumLeftToPlace == 0 then
			placed_iron = true;
		end
	end
	if placed_horse == false and table.maxn(horse_fallback) > 0 then
		if self.resource_setting == 5 then
			self._lek_strat_audit_context = "strat_balance_horse_fallback:region=" .. tostring(region_number)
				.. " fallbackN=" .. tostring(table.maxn(horse_fallback));
		end
		shuf_list = GetShuffledCopyOfTable(horse_fallback)
		iNumLeftToPlace = self:PlaceSpecificNumberOfResources(self.horse_ID, horse_amt, 1, 1, -1, 0, 0, shuf_list);
		if iNumLeftToPlace == 0 then
			placed_horse = true;
		end
	end
	if self.resource_setting == 5 then
		LekMapgenPrintAndDiagFile("### LEK_STRAT_BALANCE region_done runId=" .. tostring(_lek_run_id or "na")
			.. " region=" .. tostring(region_number)
			.. " iron_ok=" .. tostring(placed_iron)
			.. " horse_ok=" .. tostring(placed_horse)
			.. " oil_ok=" .. tostring(placed_oil)
			.. " uran_ok=" .. tostring(placed_uran)
			.. " ou_bands=" .. tostring(useOuBands)
			.. " iron_primaryN=" .. tostring(table.maxn(iron_list))
			.. " iron_fallbackN=" .. tostring(table.maxn(iron_fallback))
			.. " horse_primaryN=" .. tostring(table.maxn(horse_list))
			.. " horse_fallbackN=" .. tostring(table.maxn(horse_fallback))
			.. " oil_primaryN=" .. tostring(table.maxn(oil_list))
			.. " oil_fallbackN=" .. tostring(table.maxn(oil_fallback))
			.. " uran_primaryN=" .. tostring(table.maxn(uran_list))
			.. " uran_fallbackN=" .. tostring(table.maxn(uran_fallback)));
	end
	if not useOuBands and placed_oil == false and table.maxn(oil_fallback) > 0 then
		if self.resource_setting == 5 then
			self._lek_strat_audit_context = "strat_balance_oil_fallback:region=" .. tostring(region_number)
				.. " fallbackN=" .. tostring(table.maxn(oil_fallback));
		end
		shuf_list = GetShuffledCopyOfTable(oil_fallback)
		if OilToPlace == 1 then
			iNumLeftToPlace = self:PlaceSpecificNumberOfResources(self.oil_ID, oil_amt, 1, 1, -1, 0, 0, shuf_list);
		else
			iNumLeftToPlace = self:PlaceSpecificNumberOfResources(self.oil_ID, oil_amt, 2, 1, -1, 0, 0, shuf_list);
		end
		print("Fallback Used");
		if iNumLeftToPlace == 0 then
			print("All Oil Placed 2nd Attempt");
			placed_oil = true;
		else
			--print("Not All Oil Placed");
		end
	end
	if self.start_locations == 5 or self.start_locations == 6 or self.start_locations == 1 or self.start_locations == 2 then
		if placed_alum == false and table.maxn(alum_fallback) > 0 then
			shuf_list = GetShuffledCopyOfTable(alum_fallback)
			iNumLeftToPlace = self:PlaceSpecificNumberOfResources(self.aluminum_ID, alum_amt, 1, 1, -1, 0, 0, shuf_list);
		end
	end
	if self.start_locations == 4 or self.start_locations == 6 or self.start_locations == 1 or self.start_locations == 2 then
		if placed_coal == false and table.maxn(coal_fallback) > 0 then
			shuf_list = GetShuffledCopyOfTable(coal_fallback)
			iNumLeftToPlace = self:PlaceSpecificNumberOfResources(self.coal_ID, coal_amt, 1, 1, -1, 0, 0, shuf_list);
		end
	end
	if not useOuBands and self.start_locations == 2 then
		if placed_uran == false and table.maxn(uran_fallback) > 0 then
			if self.resource_setting == 5 then
				self._lek_strat_audit_context = "strat_balance_uran_fallback:region=" .. tostring(region_number)
					.. " fallbackN=" .. tostring(table.maxn(uran_fallback));
			end
			shuf_list = GetShuffledCopyOfTable(uran_fallback)
			iNumLeftToPlace = self:PlaceSpecificNumberOfResources(self.uranium_ID, uran_amt, 2, 1, 9, 0, 0, shuf_list);
			if iNumLeftToPlace == 0 then
				placed_uran = true;
			end
		end
	end
	self._lek_strat_audit_context = prevStratAuditCtx;
end
