------------------------------------------------------------------------------
function AssignStartingPlots:PlaceSexyBonusAtCivStarts()
	-- This function will place a Bonus resource in the third ring around a Civ's start.
	-- The added Bonus is meant to make the start look more sexy, so to speak.
	-- Third-ring resources will take a long time to bring online, but will assist the site in the late game.
	-- Alternatively, it may assist a different city if another city is settled close enough to the capital and takes control of this tile.
	local iW, iH = Map.GetGridSize();
	local wrapX = Map:IsWrapX();
	local wrapY = Map:IsWrapY();
	local odd = self.firstRingYIsOdd;
	local even = self.firstRingYIsEven;
	local nextX, nextY, plot_adjustments;
	
	local bonus_type_associated_with_region_type = {self.deer_ID, self.banana_ID, 
	self.deer_ID, self.wheat_ID, self.maize_ID, self.sheep_ID, self.wheat_ID, self.cow_ID, self.cow_ID, self.wheat_ID, self.hardwood_ID, self.maize_ID,};
	
	if not odd or not even then
		return;
	end
	for region_number = 1, self.iNumCivs do
		local spSb = self.startingPlots[region_number];
		if not (spSb and type(spSb[1]) == "number" and type(spSb[2]) == "number") then
		else
		local x, y = spSb[1], spSb[2];
		local region_type = self.regionTypes[region_number];
		if type(region_type) ~= "number" or region_type < 1 or region_type > #bonus_type_associated_with_region_type then
		else
		local use_this_ID = bonus_type_associated_with_region_type[region_type];
		if use_this_ID == nil then
		else
		local plot_list, fish_list = {}, {};
		local ripple_radius = 2;
		local currentX = x - ripple_radius;
		local currentY = y;
		for direction_index = 1, 6 do
			for plot_to_handle = 1, ripple_radius do
			 	if currentY / 2 > math.floor(currentY / 2) then
					plot_adjustments = odd[direction_index];
				else
					plot_adjustments = even[direction_index];
				end
				nextX = currentX + plot_adjustments[1];
				nextY = currentY + plot_adjustments[2];
				if wrapX == false and (nextX < 0 or nextX >= iW) then
					-- X is out of bounds.
				elseif wrapY == false and (nextY < 0 or nextY >= iH) then
					-- Y is out of bounds.
				else
					local realX = nextX;
					local realY = nextY;
					if wrapX then
						realX = realX % iW;
					end
					if wrapY then
						realY = realY % iH;
					end
					local plot = Map.GetPlot(realX, realY);
					if not plot then
					else
					local featureType = plot:GetFeatureType()
					if plot:GetResourceType(-1) == -1 and featureType ~= FeatureTypes.FEATURE_OASIS then
						local plotType = plot:GetPlotType()
						local terrainType = plot:GetTerrainType()
						local plotIndex = realY * iW + realX + 1;
						-- Now check this plot for eligibility for the applicable Bonus type for this region.
						if use_this_ID == self.deer_ID then
							if featureType == FeatureTypes.FEATURE_FOREST then
								table.insert(plot_list, plotIndex);
							elseif terrainType == TerrainTypes.TERRAIN_TUNDRA and plotType == PlotTypes.PLOT_LAND then
								table.insert(plot_list, plotIndex);
							end
						elseif use_this_ID == self.hardwood_ID then
							if featureType == FeatureTypes.FEATURE_FOREST then
								table.insert(plot_list, plotIndex);
							elseif terrainType == TerrainTypes.TERRAIN_TUNDRA and plotType == PlotTypes.PLOT_LAND then
								table.insert(plot_list, plotIndex);
							end
						elseif use_this_ID == self.banana_ID then
							if featureType == FeatureTypes.FEATURE_JUNGLE then
								table.insert(plot_list, plotIndex);
							end
						elseif use_this_ID == self.wheat_ID then
							if plotType == PlotTypes.PLOT_LAND then
								if terrainType == TerrainTypes.TERRAIN_PLAINS and featureType == FeatureTypes.NO_FEATURE then
									table.insert(plot_list, plotIndex);
								elseif featureType == FeatureTypes.FEATURE_FLOOD_PLAINS then
									table.insert(plot_list, plotIndex);
								elseif terrainType == TerrainTypes.TERRAIN_DESERT and plot:IsFreshWater() then
									table.insert(plot_list, plotIndex);
								end
							end
						elseif use_this_ID == self.maize_ID then
							if (plotType == PlotTypes.PLOT_LAND or plotType == PlotTypes.PLOT_HILLS) and terrainType == TerrainTypes.TERRAIN_PLAINS and featureType == FeatureTypes.NO_FEATURE then
								table.insert(plot_list, plotIndex);
							end
						elseif use_this_ID == self.sheep_ID then
							if featureType == FeatureTypes.NO_FEATURE and plotType == PlotTypes.PLOT_HILLS then
								if terrainType == TerrainTypes.TERRAIN_PLAINS or terrainType == TerrainTypes.TERRAIN_GRASS or terrainType == TerrainTypes.TERRAIN_TUNDRA then
									table.insert(plot_list, plotIndex);
								end
							end
						elseif use_this_ID == self.cow_ID then
							if plotType == PlotTypes.PLOT_LAND then
								if terrainType == TerrainTypes.TERRAIN_GRASS or terrainType == TerrainTypes.TERRAIN_PLAINS then
									if featureType == FeatureTypes.NO_FEATURE then
										table.insert(plot_list, plotIndex);
									end
								end
							end
						end
						if plotType == PlotTypes.PLOT_OCEAN then
							if featureType ~= self.feature_atoll and featureType ~= FeatureTypes.FEATURE_ICE then
								if terrainType == TerrainTypes.TERRAIN_COAST and not plot:IsLake() then
									table.insert(fish_list, plotIndex);
								end
							end
						end
					end
					end
				end
				currentX, currentY = nextX, nextY;
			end
		end
		local iNumCandidates = table.maxn(plot_list);
		if iNumCandidates > 0 then
			--print("Placing 'sexy Bonus' in third ring of start location in Region#", region_number);
			local shuf_list = GetShuffledCopyOfTable(plot_list)
			local iNumLeftToPlace = self:PlaceSpecificNumberOfResources(use_this_ID, 1, 1, 1, -1, 0, 0, shuf_list);
			if iNumCandidates > 1 and use_this_ID == self.sheep_ID then
				-- Hills region, attempt to give them a second Sexy Sheep.
				--print("Placing a second 'sexy Sheep' in third ring of start location in Hills Region#", region_number);
				iNumLeftToPlace = self:PlaceSpecificNumberOfResources(use_this_ID, 1, 1, 1, -1, 0, 0, shuf_list);
			end
		else
			local iFishCandidates = table.maxn(fish_list);
			if iFishCandidates > 0 then
				local shuf_list = GetShuffledCopyOfTable(self:LekFilterLakeFishIndicesAwayFromMajorStarts(fish_list, 4))
				local iNumLeftToPlace = self:PlaceSpecificNumberOfResources(self.fish_ID, 1, 1, 1, -1, 0, 0, shuf_list);
			end
		end
		end
		end
		end
	end
end
------------------------------------------------------------------------------
function AssignStartingPlots:PlaceCoastalBonusIslands()
	local iW, iH = Map.GetGridSize();
	local wrapX = Map:IsWrapX();
	local wrapY = Map:IsWrapY();
	local odd = self.firstRingYIsOdd;
	local even = self.firstRingYIsEven;
	local forestID = -1;
	for f in GameInfo.Features() do
		if f.Type == "FEATURE_FOREST" then
			forestID = f.ID;
			break;
		end
	end

	local function plotIndex(x, y) return y * iW + x + 1; end
	local function inBounds(x, y) return x >= 0 and x < iW and y >= 0 and y < iH; end
	local function getNeighbor(x, y, d)
		local adj = (y % 2 ~= 0) and odd[d] or even[d];
		local nx = x + adj[1];
		local ny = y + adj[2];
		if wrapX then nx = nx % iW; end
		if wrapY then ny = ny % iH; end
		return nx, ny;
	end
	local function countAdjacentLand(x, y, placedSet)
		local n = 0;
		for d = 1, 6 do
			local nx, ny = getNeighbor(x, y, d);
			if inBounds(nx, ny) then
				if placedSet and placedSet[plotIndex(nx, ny)] then
					n = n + 1;
				else
				local p = Map.GetPlot(nx, ny);
				if p and not p:IsWater() then n = n + 1; end
				end
			end
		end
		return n;
	end
	local function hasLandAtRing2(x, y)
		for d = 1, 6 do
			local sx, sy = getNeighbor(x, y, d);
			if inBounds(sx, sy) then
				for dd = 1, 6 do
					local rx, ry = getNeighbor(sx, sy, dd);
					if inBounds(rx, ry) and not (rx == x and ry == y) then
						local p = Map.GetPlot(rx, ry);
						if p and not p:IsWater() then return true; end
					end
				end
			end
		end
		return false;
	end
	local function capitalReachesSaltWater(sx, sy, placedSet)
		local visited = {};
		local queue = {};
		local maxVisit = math.min(iW * iH, 12000);
		local visitCount = 0;
		local function enqueue(nx, ny)
			if visitCount >= maxVisit then return; end
			if not inBounds(nx, ny) then return; end
			local ii = plotIndex(nx, ny);
			if placedSet and placedSet[ii] then return; end
			local k = nx .. "," .. ny;
			if visited[k] then return; end
			local p = Map.GetPlot(nx, ny);
			if not p or not p:IsWater() or p:IsLake() then return; end
			visited[k] = true;
			visitCount = visitCount + 1;
			queue[#queue + 1] = { nx, ny };
		end
		for d = 1, 6 do
			local nx, ny = getNeighbor(sx, sy, d);
			enqueue(nx, ny);
		end
		if #queue == 0 then return false; end
		local qi = 1;
		while qi <= #queue do
			local x, y = queue[qi][1], queue[qi][2];
			qi = qi + 1;
			local p = Map.GetPlot(x, y);
			if p then
				if p:GetTerrainType() == TerrainTypes.TERRAIN_OCEAN then return true; end
				for d = 1, 6 do
					local nx, ny = getNeighbor(x, y, d);
					if inBounds(nx, ny) then
						local np = Map.GetPlot(nx, ny);
						if np and np:GetTerrainType() == TerrainTypes.TERRAIN_OCEAN then return true; end
					end
				end
			end
			for d = 1, 6 do
				local nx, ny = getNeighbor(x, y, d);
				enqueue(nx, ny);
			end
		end
		return false;
	end
	local function hexStepsToNearestLand(wx, wy)
		local visited = {};
		local q = { { wx, wy, 0 } };
		local qi = 1;
		while qi <= #q do
			local x, y, dist = q[qi][1], q[qi][2], q[qi][3];
			qi = qi + 1;
			local k = x .. "," .. y;
			if not visited[k] then
				visited[k] = true;
				local p = Map.GetPlot(x, y);
				if p and not p:IsWater() then
					return dist;
				end
				if dist < 6 then
					for d = 1, 6 do
						local nx, ny = getNeighbor(x, y, d);
						if inBounds(nx, ny) then
							q[#q + 1] = { nx, ny, dist + 1 };
						end
					end
				end
			end
		end
		return 99;
	end
	local function rotDirIsland(d, delta)
		return ((d - 1 + delta) % 6 + 6) % 6 + 1;
	end
	local function hexDirDistIsland(a, b)
		if type(a) ~= "number" or type(b) ~= "number" then
			return 3;
		end
		local d = math.abs(a - b);
		return math.min(d, 6 - d);
	end
	local function dirTowardNearestLand(wx, wy)
		local bestD, bestDist = 1, 999;
		for d = 1, 6 do
			local nx, ny = getNeighbor(wx, wy, d);
			if inBounds(nx, ny) then
				local p = Map.GetPlot(nx, ny);
				if p and not p:IsWater() then
					return d;
				end
				local dist = hexStepsToNearestLand(nx, ny);
				if dist < 99 and dist + 1 < bestDist then
					bestDist = dist + 1;
					bestD = d;
				end
			end
		end
		return bestD;
	end
	local function placeOneIslandForStart(sx, sy, minRing, maxRing)
		local candidates = {};
		for ripple_radius = minRing, maxRing do
			local currentX = sx - ripple_radius;
			local currentY = sy;
			for direction_index = 1, 6 do
				for _ = 1, ripple_radius do
					local plot_adjustments = (currentY / 2 > math.floor(currentY / 2)) and odd[direction_index] or even[direction_index];
					local nextX = currentX + plot_adjustments[1];
					local nextY = currentY + plot_adjustments[2];
					if wrapX == false and (nextX < 0 or nextX >= iW) then
					elseif wrapY == false and (nextY < 0 or nextY >= iH) then
					else
						local realX = nextX;
						local realY = nextY;
						if wrapX then realX = realX % iW; end
						if wrapY then realY = realY % iH; end
						local p = Map.GetPlot(realX, realY);
						if p and p:IsWater()
							and not p:IsLake()
							and countAdjacentLand(realX, realY) == 0
							and hasLandAtRing2(realX, realY)
						then
							candidates[#candidates + 1] = { realX, realY };
						end
					end
					currentX, currentY = nextX, nextY;
				end
			end
		end
		if #candidates == 0 then return nil; end

		local seedPool = math.min(8, #candidates);
		local seed = candidates[1 + Map.Rand(seedPool, "")];
		local toward = dirTowardNearestLand(seed[1], seed[2]);
		local tan1 = rotDirIsland(toward, 1);
		local tan2 = rotDirIsland(toward, 5);
		local dirOrder = { 1, 2, 3, 4, 5, 6 };
		table.sort(dirOrder, function(a, b)
			local sa = math.min(hexDirDistIsland(a, tan1), hexDirDistIsland(a, tan2));
			local sb = math.min(hexDirDistIsland(b, tan1), hexDirDistIsland(b, tan2));
			if sa ~= sb then return sa < sb; end
			return a < b;
		end);
		local islandTiles = { {seed[1], seed[2]} };
		local used = {};
		used[plotIndex(seed[1], seed[2])] = true;
		local target = 2 + Map.Rand(4, "");
		if Map.Rand(100, "") < 6 then
			target = 6 + Map.Rand(2, "");
		end
		local fi = 1;
		while #islandTiles < target and fi <= #islandTiles do
			local fx = islandTiles[fi][1];
			local fy = islandTiles[fi][2];
			local d0 = 1 + Map.Rand(6, "");
			local added = false;
			for j = 0, 5 do
				local d = dirOrder[((d0 + j - 1) % 6) + 1];
				local nx, ny = getNeighbor(fx, fy, d);
				if inBounds(nx, ny) then
					local ii = plotIndex(nx, ny);
					local p = Map.GetPlot(nx, ny);
					if not used[ii] and p and p:IsWater() and not p:IsLake() then
						local dCap = nil;
						if Map.PlotDistance then
							dCap = Map.PlotDistance(sx, sy, nx, ny);
						elseif PlotDistance then
							dCap = PlotDistance(sx, sy, nx, ny);
						end
						if dCap and dCap > 4 then
						else
							local adjLand = countAdjacentLand(nx, ny, used);
							local nextTileNumber = #islandTiles + 1;
							local ok = false;
							if nextTileNumber == 2 then
								ok = (adjLand == 1);
							else
								ok = (adjLand == 1 or adjLand == 2);
								-- Add shape noise: occasionally allow slightly looser adjacency.
								if not ok and Map.Rand(100, "") < 36 then
									ok = (adjLand >= 0 and adjLand <= 3);
								end
							end
							if ok then
								used[ii] = true;
								islandTiles[#islandTiles + 1] = { nx, ny };
								added = true;
								break;
							end
						end
					end
				end
			end
			if not added then fi = fi + 1; end
		end
		if #islandTiles < 2 then return nil; end

		local backup = {};
		local placedSet = {};
		for _, t in ipairs(islandTiles) do
			local p = Map.GetPlot(t[1], t[2]);
			if p and p:IsWater() then
				placedSet[plotIndex(t[1], t[2])] = true;
				backup[#backup + 1] = {
					x = t[1], y = t[2],
					pt = p:GetPlotType(),
					tt = p:GetTerrainType(),
					ft = p:GetFeatureType()
				};
				p:SetPlotType((Map.Rand(100, "") < 70) and PlotTypes.PLOT_HILLS or PlotTypes.PLOT_LAND, false, false);
				local tg = _lekmap_terrain_generator;
				local tt;
				if tg and tg.GenerateTerrainAtPlot then
					tt = tg:GenerateTerrainAtPlot(t[1], t[2]);
				end
				if tt and tt ~= TerrainTypes.NO_TERRAIN then
					p:SetTerrainType(tt, false, false);
				else
					p:SetTerrainType((Map.Rand(100, "") < 62) and TerrainTypes.TERRAIN_GRASS or TerrainTypes.TERRAIN_PLAINS, false, false);
				end
			end
		end
		-- Forest after terrain brush: 60% default (−5 vs legacy); desert tiles 3%.
		if forestID ~= -1 then
			for _, t in ipairs(islandTiles) do
				local p = Map.GetPlot(t[1], t[2]);
				if p and not p:IsWater() and p:GetFeatureType() == FeatureTypes.NO_FEATURE then
					local fpct = 60;
					if p:GetTerrainType() == TerrainTypes.TERRAIN_DESERT then
						fpct = 3;
					end
					if Map.Rand(100, "Lek cap island forest") < fpct then
						p:SetFeatureType(forestID, -1);
					end
				end
			end
		end
		local checkStart = Map.GetPlot(sx, sy);
		if not (checkStart and checkStart:IsCoastalLand(300) and capitalReachesSaltWater(sx, sy, nil)) then
			for _, b in ipairs(backup) do
				local p = Map.GetPlot(b.x, b.y);
				if p then
					p:SetPlotType(b.pt, false, false);
					p:SetTerrainType(b.tt, false, false);
					p:SetFeatureType(b.ft, -1);
				end
			end
			return nil;
		end
		return backup;
	end

	local function plotDistXY(ax, ay, bx, by)
		if Map.PlotDistance then
			return Map.PlotDistance(ax, ay, bx, by);
		end
		if PlotDistance then
			return PlotDistance(ax, ay, bx, by);
		end
		return math.abs(ax - bx) + math.abs(ay - by);
	end
	-- Bonus islands 2+3: prioritize surf zone (hex distance 2–7 to mainland, no adjacency to land while building);
	-- weak tie-break closer to capital. Keeps a 1-tile water buffer to pangaea.
	local function placeShoreProximalBonusIsland(sx, sy, minRing, maxRing)
		local function anyForeignLandNeighbor(x, y, used2)
			for d = 1, 6 do
				local nx, ny = getNeighbor(x, y, d);
				if inBounds(nx, ny) then
					local ii = plotIndex(nx, ny);
					if used2[ii] then
					else
						local np = Map.GetPlot(nx, ny);
						if np and not np:IsWater() then return true; end
					end
				end
			end
			return false;
		end
		local function countOurNeighbors(x, y, used2)
			local n = 0;
			for d = 1, 6 do
				local nx, ny = getNeighbor(x, y, d);
				if inBounds(nx, ny) and used2[plotIndex(nx, ny)] then
					n = n + 1;
				end
			end
			return n;
		end
		local function collectNearShoreSeeds(r0, r1)
			local cand = {};
			for ripple_radius = r0, r1 do
				local currentX = sx - ripple_radius;
				local currentY = sy;
				for direction_index = 1, 6 do
					for _ = 1, ripple_radius do
						local plot_adjustments = (currentY / 2 > math.floor(currentY / 2)) and odd[direction_index] or even[direction_index];
						local nextX = currentX + plot_adjustments[1];
						local nextY = currentY + plot_adjustments[2];
						if wrapX == false and (nextX < 0 or nextX >= iW) then
						elseif wrapY == false and (nextY < 0 or nextY >= iH) then
						else
							local realX = nextX;
							local realY = nextY;
							if wrapX then realX = realX % iW; end
							if wrapY then realY = realY % iH; end
							local p = Map.GetPlot(realX, realY);
							local emptyUsed = {};
							if p and p:IsWater()
								and not p:IsLake()
								and not anyForeignLandNeighbor(realX, realY, emptyUsed)
								and hasLandAtRing2(realX, realY)
							then
								local dLand = hexStepsToNearestLand(realX, realY);
								if dLand == 2 or dLand == 3 then
									cand[#cand + 1] = { realX, realY, dLand };
								end
							end
						end
						currentX, currentY = nextX, nextY;
					end
				end
			end
			return cand;
		end
		local attempt = function(rLo, rHi)
			local candidates = collectNearShoreSeeds(rLo, rHi);
			if #candidates == 0 then return nil; end
			table.sort(candidates, function(a, b)
				if a[3] ~= b[3] then return a[3] < b[3]; end
				return plotDistXY(a[1], a[2], sx, sy) < plotDistXY(b[1], b[2], sx, sy);
			end);
			local seedPool = math.min(12, #candidates);
			local pickRow = candidates[1 + Map.Rand(seedPool, "Lek shore isle seed")];
			local seed = { pickRow[1], pickRow[2] };
			local towardSh = dirTowardNearestLand(seed[1], seed[2]);
			local tan1sh = rotDirIsland(towardSh, 1);
			local tan2sh = rotDirIsland(towardSh, 5);
			local islandTiles = { { seed[1], seed[2] } };
			local used = {};
			used[plotIndex(seed[1], seed[2])] = true;
			local target = 2 + Map.Rand(3, "Lek shore isle size");
			if Map.Rand(100, "Lek shore isle rare") < 8 then
				target = 5 + Map.Rand(2, "Lek shore isle rare sz");
			end
			local fi = 1;
			while #islandTiles < target and fi <= #islandTiles do
				local fx = islandTiles[fi][1];
				local fy = islandTiles[fi][2];
				local neigh = {};
				for d = 1, 6 do
					local nx, ny = getNeighbor(fx, fy, d);
					if inBounds(nx, ny) then
						local p = Map.GetPlot(nx, ny);
						if not used[plotIndex(nx, ny)] and p and p:IsWater() and not p:IsLake()
							and not anyForeignLandNeighbor(nx, ny, used)
						then
							local shoreD = hexStepsToNearestLand(nx, ny);
							neigh[#neigh + 1] = { nx, ny, shoreD, d };
						end
					end
				end
				table.sort(neigh, function(u, v)
					if u[3] ~= v[3] then return u[3] < v[3]; end
					local ua = math.min(hexDirDistIsland(u[4], tan1sh), hexDirDistIsland(u[4], tan2sh));
					local va = math.min(hexDirDistIsland(v[4], tan1sh), hexDirDistIsland(v[4], tan2sh));
					if ua ~= va then return ua < va; end
					return plotDistXY(u[1], u[2], sx, sy) < plotDistXY(v[1], v[2], sx, sy);
				end);
				local added = false;
				local d0 = (#neigh > 0) and (1 + Map.Rand(#neigh, "Lek shore isle dir")) or 1;
				for j = 0, #neigh - 1 do
					local pick = ((d0 - 1 + j) % #neigh) + 1;
					local nx, ny = neigh[pick][1], neigh[pick][2];
					local ii = plotIndex(nx, ny);
					local shorePick = neigh[pick][3];
					local dCap = plotDistXY(nx, ny, sx, sy);
					if dCap > 5 or shorePick > 4 then
					else
						local our = countOurNeighbors(nx, ny, used);
						local nextTileNumber = #islandTiles + 1;
						local ok = false;
						if nextTileNumber == 2 then
							ok = (our == 1);
						else
							ok = (our == 1 or our == 2);
							if not ok and Map.Rand(100, "Lek shore isle noise") < 28 then
								ok = (our >= 1 and our <= 3);
							end
						end
						if ok then
							used[ii] = true;
							islandTiles[#islandTiles + 1] = { nx, ny };
							added = true;
							break;
						end
					end
				end
				if not added then fi = fi + 1; end
			end
			if #islandTiles < 2 then return nil; end
			local backup = {};
			local placedSet = {};
			for _, t in ipairs(islandTiles) do
				local p = Map.GetPlot(t[1], t[2]);
				if p and p:IsWater() then
					placedSet[plotIndex(t[1], t[2])] = true;
					backup[#backup + 1] = {
						x = t[1], y = t[2],
						pt = p:GetPlotType(),
						tt = p:GetTerrainType(),
						ft = p:GetFeatureType()
					};
					p:SetPlotType((Map.Rand(100, "") < 70) and PlotTypes.PLOT_HILLS or PlotTypes.PLOT_LAND, false, false);
					local tg = _lekmap_terrain_generator;
					local tt;
					if tg and tg.GenerateTerrainAtPlot then
						tt = tg:GenerateTerrainAtPlot(t[1], t[2]);
					end
					if tt and tt ~= TerrainTypes.NO_TERRAIN then
						p:SetTerrainType(tt, false, false);
					else
						p:SetTerrainType((Map.Rand(100, "") < 62) and TerrainTypes.TERRAIN_GRASS or TerrainTypes.TERRAIN_PLAINS, false, false);
					end
				end
			end
			if forestID ~= -1 then
				for _, t in ipairs(islandTiles) do
					local p = Map.GetPlot(t[1], t[2]);
					if p and not p:IsWater() and p:GetFeatureType() == FeatureTypes.NO_FEATURE then
						local fpct = 60;
						if p:GetTerrainType() == TerrainTypes.TERRAIN_DESERT then
							fpct = 3;
						end
						if Map.Rand(100, "Lek cap shore isle forest") < fpct then
							p:SetFeatureType(forestID, -1);
						end
					end
				end
			end
			local checkStart = Map.GetPlot(sx, sy);
			if not (checkStart and checkStart:IsCoastalLand(300) and capitalReachesSaltWater(sx, sy, nil)) then
				for _, b in ipairs(backup) do
					local p = Map.GetPlot(b.x, b.y);
					if p then
						p:SetPlotType(b.pt, false, false);
						p:SetTerrainType(b.tt, false, false);
						p:SetFeatureType(b.ft, -1);
					end
				end
				return nil;
			end
			return backup;
		end
		local b = attempt(minRing, maxRing);
		if b then return b; end
		b = attempt(2, 6);
		if b then return b; end
		return attempt(2, 7);
	end

	for region_number = 1, self.iNumCivs do
		local spC = self.startingPlots[region_number];
		if not (spC and type(spC[1]) == "number" and type(spC[2]) == "number") then
		else
		local sx, sy = spC[1], spC[2];
		local startPlot = Map.GetPlot(sx, sy);
		if startPlot and startPlot:IsCoastalLand() then
			local sessionRestore = {};
			local b1 = placeOneIslandForStart(sx, sy, 2, 5);
			if b1 then
				for _, row in ipairs(b1) do
					sessionRestore[#sessionRestore + 1] = row;
				end
			end
			LekMapgenFileTrace("-", "LEK bonusIsland Region#", region_number, "kind=deepWater2to5", "tiles=", b1 and #b1 or 0, "plot", sx, sy);
			local b2 = nil;
			if b1 then
				b2 = placeShoreProximalBonusIsland(sx, sy, 2, 5);
				if b2 then
					for _, row in ipairs(b2) do
						sessionRestore[#sessionRestore + 1] = row;
					end
				end
			end
			LekMapgenFileTrace("-", "LEK bonusIsland Region#", region_number, "kind=shoreProximal_primary", "tiles=", b2 and #b2 or 0);
			local b3 = nil;
			if Map.Rand(100, "") < 20 then
				b3 = placeShoreProximalBonusIsland(sx, sy, 2, 5);
				if b3 then
					for _, row in ipairs(b3) do
						sessionRestore[#sessionRestore + 1] = row;
					end
				end
			end
			LekMapgenFileTrace("-", "LEK bonusIsland Region#", region_number, "kind=shoreProximal_roll20pct", "tiles=", b3 and #b3 or 0);
			local verify = Map.GetPlot(sx, sy);
			if verify and verify:IsCoastalLand() and #sessionRestore > 0 then
				if not (verify:IsCoastalLand(300) and capitalReachesSaltWater(sx, sy, nil)) then
					LekMapgenFileTrace("-", "LEK PlaceCoastalBonusIslands: revert; capital lost main ocean link Region#", region_number);
					for _, b in ipairs(sessionRestore) do
						local p = Map.GetPlot(b.x, b.y);
						if p then
							p:SetPlotType(b.pt, false, false);
							p:SetTerrainType(b.tt, false, false);
							p:SetFeatureType(b.ft, -1);
						end
					end
				end
			end
		end
		end
	end
end
------------------------------------------------------------------------------
function AssignStartingPlots:AddExtraBonusesToHillsRegions()
	-- Hills regions are very low on food, yet not deemed by the fertility measurements to be so.
	-- Spreading some food bonus around in these regions will help bring them up closer to par.
	local iW, iH = Map.GetGridSize();
	local wrapX = Map:IsWrapX();
	local wrapY = Map:IsWrapY();
	-- Identify Hills Regions, if any.
	local hills_regions, iNumHillsRegions = {}, 0;
	for region_number = 1, self.iNumCivs do
		if self.regionTypes[region_number] == 5 then
			iNumHillsRegions = iNumHillsRegions + 1;
			table.insert(hills_regions, region_number);
		end
	end
	if iNumHillsRegions == 0 then -- We're done.
		return
	end
	-- Process Hills Regions
	local shuffled_hills_regions = GetShuffledCopyOfTable(hills_regions)
	for loop, region_number in ipairs(shuffled_hills_regions) do
		local iWestX = self.regionData[region_number][1];
		local iSouthY = self.regionData[region_number][2];
		local iWidth = self.regionData[region_number][3];
		local iHeight = self.regionData[region_number][4];
		local iAreaID = self.regionData[region_number][5];
		--
		local terrainCounts = self.regionTerrainCounts[region_number];
		--local totalPlots = terrainCounts[1];
		local areaPlots = terrainCounts[2];
		--local waterCount = terrainCounts[3];
		local flatlandsCount = terrainCounts[4];
		local hillsCount = terrainCounts[5];
		local peaksCount = terrainCounts[6];
		--local lakeCount = terrainCounts[7];
		--local coastCount = terrainCounts[8];
		--local oceanCount = terrainCounts[9];
		--local iceCount = terrainCounts[10];
		local grassCount = terrainCounts[11];
		local plainsCount = terrainCounts[12];
		--local desertCount = terrainCounts[13];
		--local tundraCount = terrainCounts[14];
		--local snowCount = terrainCounts[15];
		--local forestCount = terrainCounts[16];
		--local jungleCount = terrainCounts[17];
		--local marshCount = terrainCounts[18];
		--local riverCount = terrainCounts[19];
		--local floodplainCount = terrainCounts[20];
		--local oasisCount = terrainCounts[21];
		--local coastalLandCount = terrainCounts[22];
		--local nextToCoastCount = terrainCounts[23];
		--
		-- Check how badly infertile the region is by comparing hills and mountains to flat farmlands.
		local hills_ratio = (hillsCount + peaksCount) / areaPlots;
		local farm_ratio = (grassCount + plainsCount) / areaPlots;
		if self.method == 3 then -- Need to ignore water tiles, which are included in areaPlots with this regional division method.
			hills_ratio = (hillsCount + peaksCount) / (hillsCount + peaksCount + flatlandsCount);
			farm_ratio = (grassCount + plainsCount) / (hillsCount + peaksCount + flatlandsCount);
		end
		-- If the infertility quotient is greater than 1, this will increase how
		-- many Bonus get placed, up to a max of double the normal ratio.
		local infertility_quotient = 1 + math.max(0, hills_ratio - farm_ratio);
		
		--print("Infertility Quotient for Hills Region#", region_number, " is:", infertility_quotient);
		
		--
		-- Generate plot lists for the extra Bonus placements.
		local dry_hills, flat_plains, flat_grass, flat_tundra, jungles, forests = {}, {}, {}, {}, {}, {};
		for region_loop_y = 0, iHeight - 1 do
			for region_loop_x = 0, iWidth - 1 do
				local x = (region_loop_x + iWestX) % iW;
				local y = (region_loop_y + iSouthY) % iH;
				local plot = Map.GetPlot(x, y);
				local plotIndex = y * iW + x + 1;
				local area_of_plot = plot:GetArea();
				local plotType = plot:GetPlotType()
				local terrainType = plot:GetTerrainType()
				local featureType = plot:GetFeatureType()
				if plotType == PlotTypes.PLOT_LAND or plotType == PlotTypes.PLOT_HILLS then
					-- Check plot for region membership. Only process this plot if it is a member.
					if (area_of_plot == iAreaID) or (iAreaID == -1) then
						if plot:GetResourceType(-1) == -1 then
							if featureType == FeatureTypes.FEATURE_JUNGLE then
								table.insert(jungles, plotIndex);
							elseif featureType == FeatureTypes.FEATURE_FOREST then
								table.insert(forests, plotIndex);
							elseif featureType == FeatureTypes.FEATURE_FLOOD_PLAINS then
								table.insert(flat_plains, plotIndex);
							elseif featureType == FeatureTypes.NO_FEATURE then
								if plotType == PlotTypes.PLOT_HILLS then
									if (terrainType == TerrainTypes.TERRAIN_GRASS or terrainType == TerrainTypes.TERRAIN_PLAINS or terrainType == TerrainTypes.TERRAIN_TUNDRA) then
										if plot:IsFreshWater() == false then
											table.insert(dry_hills, plotIndex);
										end
									end
								elseif plotType == PlotTypes.PLOT_LAND then
									if terrainType == TerrainTypes.TERRAIN_PLAINS then
										table.insert(flat_plains, plotIndex);
									elseif terrainType == TerrainTypes.TERRAIN_DESERT and plot:IsFreshWater() then
										table.insert(flat_plains, plotIndex);
									elseif terrainType == TerrainTypes.TERRAIN_GRASS then
										table.insert(flat_grass, plotIndex);
									elseif terrainType == TerrainTypes.TERRAIN_TUNDRA then
										table.insert(flat_tundra, plotIndex);
									end
								end
							end
						end
					end
				end
			end
		end
		
		--[[
		print("-"); print("--- Extra-Bonus Plot Counts for Hills Region#", region_number, "---");
		print("- Jungles:", table.maxn(jungles));
		print("- Forests:", table.maxn(forests));
		print("- Tundra:", table.maxn(flat_tundra));
		print("- Plains:", table.maxn(flat_plains));
		print("- Grass:", table.maxn(flat_grass));
		print("- Dry Hills:", table.maxn(dry_hills));
		]]--
		
		-- Now that the plot lists are ready, place the Bonuses.
		if table.maxn(dry_hills) > 0 then
			local resources_to_place = {
			{self.sheep_ID, 1, 100, 1, 1} };
			self:ProcessResourceList(9 / infertility_quotient, 3, dry_hills, resources_to_place)
		end
		if table.maxn(jungles) > 0 then
			local resources_to_place = {
			{self.banana_ID, 1, 100, 1, 2} };
			self:ProcessResourceList(14 / infertility_quotient, 3, jungles, resources_to_place)
		end
		if table.maxn(flat_tundra) > 0 then
			local resources_to_place = {
			{self.deer_ID, 1, 100, 0, 1} };
			self:ProcessResourceList(14 / infertility_quotient, 3, flat_tundra, resources_to_place)
		end
		if table.maxn(flat_tundra) > 0 then
			local resources_to_place = {
			{self.hardwood_ID, 1, 100, 0, 1} };
			self:ProcessResourceList(14 / infertility_quotient, 3, flat_tundra, resources_to_place)
		end
		if table.maxn(flat_plains) > 0 then
			local resources_to_place = {
			{self.wheat_ID, 1, 100, 0, 2} };
			self:ProcessResourceList(18 / infertility_quotient, 3, flat_plains, resources_to_place)
		end
		if table.maxn(flat_plains) > 0 then
			local resources_to_place = {
			{self.maize_ID, 1, 100, 0, 2} };
			self:ProcessResourceList(18 / infertility_quotient, 3, flat_plains, resources_to_place)
		end
		if table.maxn(flat_grass) > 0 then
			local resources_to_place = {
			{self.cow_ID, 1, 100, 1, 2} };
			self:ProcessResourceList(20 / infertility_quotient, 3, flat_grass, resources_to_place)
		end
		if table.maxn(forests) > 0 then
			local resources_to_place = {
			{self.deer_ID, 1, 100, 1, 2} };
			self:ProcessResourceList(24 / infertility_quotient, 3, forests, resources_to_place)
		end
		if table.maxn(forests) > 0 then
			local resources_to_place = {
			{self.hardwood_ID, 1, 100, 1, 2} };
			self:ProcessResourceList(24 / infertility_quotient, 3, forests, resources_to_place)
		end
		
		--
		--print("-"); print("Added extra Bonus resources to Hills Region#", region_number);
		--
	end
end
