function AssignStartingPlots.LekFlattenHillForOpenResource(plot, hill_flatten_percent, map_rand_key)
	if plot == nil then
		return;
	end
	local pct = hill_flatten_percent;
	if type(pct) ~= "number" then
		pct = 100;
	end
	if pct < 0 then
		pct = 0;
	elseif pct > 100 then
		pct = 100;
	end
	local pt = plot:GetPlotType();
	if pt == PlotTypes.PLOT_HILLS then
		if pct >= 100 or Map.Rand(100, map_rand_key or "Lek hill flat") < pct then
			plot:SetPlotType(PlotTypes.PLOT_LAND, false, true)
		end
	else
		plot:SetPlotType(PlotTypes.PLOT_LAND, false, true)
	end
end

function AssignStartingPlots.LekMaybePromoteLandToHill(plot, promote_percent, map_rand_key)
	if plot == nil then
		return;
	end
	local pct = promote_percent;
	if type(pct) ~= "number" then
		pct = 100;
	end
	if pct < 0 then
		pct = 0;
	elseif pct > 100 then
		pct = 100;
	end
	if plot:GetPlotType() ~= PlotTypes.PLOT_LAND then
		return;
	end
	if pct >= 100 or Map.Rand(100, map_rand_key or "Lek land hill") < pct then
		plot:SetPlotType(PlotTypes.PLOT_HILLS, false, true)
	end
end

function AssignStartingPlots.LekMergePlotIndexLists(...)
	local out = {};
	for li = 1, select("#", ...) do
		local list = select(li, ...);
		if list ~= nil then
			for i = 1, #list do
				out[#out + 1] = list[i];
			end
		end
	end
	return out;
end

function AssignStartingPlots:LekFilterLakeFishIndicesAwayFromMajorStarts(plot_indices, min_plot_distance)
	if plot_indices == nil or #plot_indices == 0 or self.startingPlots == nil then
		return plot_indices or {};
	end
	local dlim = min_plot_distance;
	if type(dlim) ~= "number" or dlim < 0 then
		dlim = 4;
	end
	local iW, iH = Map.GetGridSize();
	local out = {};
	for li = 1, #plot_indices do
		local plotIndex = plot_indices[li];
		local x = (plotIndex - 1) % iW;
		local y = math.floor((plotIndex - x - 1) / iW);
		local p = Map.GetPlot(x, y);
		local drop = false;
		if p and p:IsLake() then
			for r = 1, self.iNumCivs or 0 do
				local sp = self.startingPlots[r];
				if sp and type(sp[1]) == "number" and type(sp[2]) == "number" then
					local d = nil;
					if Map.PlotDistance then
						d = Map.PlotDistance(x, y, sp[1], sp[2]);
					elseif PlotDistance then
						d = PlotDistance(x, y, sp[1], sp[2]);
					end
					if d == nil and AssignStartingPlots.LekGlobalSix_PlotDistance then
						d = self:LekGlobalSix_PlotDistance(x, y, sp[1], sp[2]);
					end
					if type(d) ~= "number" or d <= dlim then
						drop = true;
						break;
					end
				end
			end
		end
		if not drop then
			out[#out + 1] = plotIndex;
		end
	end
	return out;
end

function AssignStartingPlots:LekFilterFishIndicesExcludingLakeAdjacent(plot_indices)
	if plot_indices == nil or #plot_indices == 0 then
		return plot_indices or {};
	end
	local iW, iH = Map.GetGridSize();
	local wrapX = Map:IsWrapX();
	local wrapY = Map:IsWrapY();
	local odd = self.firstRingYIsOdd;
	local even = self.firstRingYIsEven;
	if not odd or not even then
		return plot_indices;
	end
	local out = {};
	for li = 1, #plot_indices do
		local plotIndex = plot_indices[li];
		local x = (plotIndex - 1) % iW;
		local y = math.floor((plotIndex - x - 1) / iW);
		local p = Map.GetPlot(x, y);
		if not p or p:IsLake() then
		else
			local skip = false;
			for direction_index = 1, 6 do
				local plot_adjustments = (y % 2 ~= 0) and odd[direction_index] or even[direction_index];
				local nx = x + plot_adjustments[1];
				local ny = y + plot_adjustments[2];
				if wrapX then nx = nx % iW; if nx < 0 then nx = nx + iW; end; end
				if wrapY then ny = ny % iH; if ny < 0 then ny = ny + iH; end; end
				if nx >= 0 and nx < iW and ny >= 0 and ny < iH then
					local np = Map.GetPlot(nx, ny);
					if np and np:IsLake() then
						skip = true;
						break;
					end
				end
			end
			if not skip then
				out[#out + 1] = plotIndex;
			end
		end
	end
	return out;
end

function AssignStartingPlots.LekPlotEligibleForNeighborForest(p)
	if p == nil or p:IsWater() then
		return false;
	end
	local pt = p:GetPlotType();
	if pt ~= PlotTypes.PLOT_LAND and pt ~= PlotTypes.PLOT_HILLS then
		return false;
	end
	local t = p:GetTerrainType();
	if t == TerrainTypes.TERRAIN_SNOW then
		return false;
	end
	if t == TerrainTypes.TERRAIN_DESERT and p:GetFeatureType() ~= FeatureTypes.FEATURE_FLOOD_PLAINS then
		return false;
	end
	return true;
end

function AssignStartingPlots.LekFurDeerEnsureForestAdjacency(plot, x, y)
	if plot == nil then
		return;
	end
	local ft = plot:GetFeatureType();
	if ft == FeatureTypes.FEATURE_FOREST or ft == FeatureTypes.FEATURE_JUNGLE then
		return;
	end
	local dirs = {
		DirectionTypes.DIRECTION_NORTHEAST,
		DirectionTypes.DIRECTION_EAST,
		DirectionTypes.DIRECTION_SOUTHEAST,
		DirectionTypes.DIRECTION_SOUTHWEST,
		DirectionTypes.DIRECTION_WEST,
		DirectionTypes.DIRECTION_NORTHWEST,
	};
	for i = 1, #dirs do
		local np = Map.PlotDirection(x, y, dirs[i]);
		if np ~= nil then
			local nft = np:GetFeatureType();
			if nft == FeatureTypes.FEATURE_FOREST or nft == FeatureTypes.FEATURE_JUNGLE then
				return;
			end
		end
	end
	local candidates = {};
	for i = 1, #dirs do
		local np = Map.PlotDirection(x, y, dirs[i]);
		if np ~= nil and AssignStartingPlots.LekPlotEligibleForNeighborForest(np) then
			candidates[#candidates + 1] = np;
		end
	end
	if #candidates > 0 then
		candidates[Map.Rand(#candidates, "Lek fur deer forest neighbor") + 1]:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1);
	elseif AssignStartingPlots.LekPlotEligibleForNeighborForest(plot) then
		plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1);
	end
end
------------------------------------------------------------------------------
function AssignStartingPlots:FixResourceGraphics()

	--[[ MOD.Barathor: 
	
		 Hijacked this function and it now fixes many resource types.  Formerly, this function was FixSugarJungles.
		 This function does not adjust terrain types (except when under jungle), so that terrain bands stay intact.
	
		 This allows much greater flexibility when assigning resources to the map. ]]
		 
	local iW, iH = Map.GetGridSize()
	for y = 0, iH - 1 do
		for x = 0, iW - 1 do
			
		local plot = Map.GetPlot(x, y)
		if plot and not plot:IsWater() then
		local res_ID = plot:GetResourceType(-1)
		local featureType = plot:GetFeatureType()
		local terrainType = plot:GetTerrainType()
			
			-- Mined/Quarried Resources
			if res_ID == self.marble_ID or 
			   res_ID == self.gold_ID or 
			   res_ID == self.silver_ID or 
			   res_ID == self.copper_ID or 
			   res_ID == self.gems_ID or 
			   res_ID == self.salt_ID or 
			   res_ID == self.lapis_ID or 
			   res_ID == self.jade_ID or 
			   res_ID == self.obsidian_ID or
			   res_ID == self.amber_ID then 
			   
				-- If a forest or jungle is present, keep it.  Remove anything else.
				if (featureType ~= FeatureTypes.FEATURE_FOREST) and (featureType ~= FeatureTypes.FEATURE_JUNGLE) then
					plot:SetFeatureType(FeatureTypes.NO_FEATURE, -1)
				end
				-- Always want hills.
				-- plot:SetPlotType(PlotTypes.PLOT_HILLS, false, true)		-- MOD.Barathor: Keep flat mined resources as well.
				
			-- Tree Resources
			elseif res_ID == self.cocoa_ID or 
			       res_ID == self.citrus_ID or 
				   res_ID == self.spices_ID or 
				   res_ID == self.sugar_ID or 
				   res_ID == self.truffles_ID or 
				   res_ID == self.silk_ID or 
				   res_ID == self.dye_ID or 
				   res_ID == self.fur_ID or
				   res_ID == self.coconut_ID or
				   res_ID == self.rubber_ID or
			res_ID == self.hardwood_ID or
			   res_ID == self.deer_ID then

			local deerForestPct = (res_ID == self.deer_ID or res_ID == self.fur_ID)
				and ((terrainType == TerrainTypes.TERRAIN_TUNDRA) and 80 or 90)
				or 100;
			if Map.Rand(100, "") < deerForestPct then
				if featureType ~= FeatureTypes.FEATURE_FOREST and featureType ~= FeatureTypes.FEATURE_JUNGLE then
					plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1)
				end
			end
				
				if res_ID == self.fur_ID then
					AssignStartingPlots.LekFlattenHillForOpenResource(plot, 70, "Lek fur hill flat");
				end
				
				-- MOD.Barathor: Gets the latitude of the tile to determine jungle eligibility.  Note: I like to use symmetrical latitudes, with an equator the width of two rows, which my map script utilizes.
				local lat = 0
				if (y >= (iH/2)) then
					lat = math.abs((iH/2) - y)/(iH/2)
				else
					lat = math.abs((iH/2) - (y + 1))/(iH/2)
				end
				local AvgJungleRange = 0
				--[[ MOD.Barathor: 
					 Get Rainfall setting to determine appropriate jungle range.
					 Assumed Formula: (jungle percent) / ((jungle percent) * (jungle factor)) = X; Jungle will form from 0.0 to X, decreasing as it gets further.
					 Example: Normal Rainfall: 65 / (65 * 5) = 0.2; Divide by 2 to get the mid range, which we'll use to blend it in.  ]]
				local rain = LekMapGetCustomOption(2)	
				if rain == 1 then		
					-- Arid
					AvgJungleRange = 0.08
				elseif rain == 3 then	
					-- Wet
					AvgJungleRange = 0.25
				else					
					-- Normal or Random (Note: I'm currently not sure how to retrieve random, so we'll just use normal for now.)
					AvgJungleRange = 0.12
				end
				
			-- Always want it covered for most tree resources.
			if (featureType == FeatureTypes.FEATURE_MARSH) then
				if res_ID == self.sugar_ID or res_ID == self.spices_ID or res_ID == self.dye_ID or res_ID == self.rubber_ID or res_ID == self.coconut_ID then
					-- Keep it marsh for these resources.
				else
					-- Add some jungle or forest.
					if lat <= AvgJungleRange then
						if res_ID ~= self.deer_ID and res_ID ~= self.fur_ID then
							plot:SetFeatureType(FeatureTypes.FEATURE_JUNGLE, -1)
							plot:SetTerrainType(TerrainTypes.TERRAIN_PLAINS, false, true)
						else
							plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1)
						end
					else
						plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1)
					end	
				end
			else
				-- Add some jungle or forest.
				if lat <= AvgJungleRange then
					if res_ID ~= self.deer_ID and res_ID ~= self.fur_ID then
						plot:SetFeatureType(FeatureTypes.FEATURE_JUNGLE, -1)
						plot:SetTerrainType(TerrainTypes.TERRAIN_PLAINS, false, true)
					else
						plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1)
					end
				else
					plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1)
				end		
			end
			if res_ID == self.deer_ID or res_ID == self.fur_ID then
				AssignStartingPlots.LekFurDeerEnsureForestAdjacency(plot, x, y);
			end

			elseif res_ID == self.stone_ID then
				local ttStone = plot:GetTerrainType();
				if ttStone == TerrainTypes.TERRAIN_GRASS or ttStone == TerrainTypes.TERRAIN_PLAINS then
					AssignStartingPlots.LekFlattenHillForOpenResource(plot, 12, "Lek res stone hill flat grassplains");
				else
					AssignStartingPlots.LekFlattenHillForOpenResource(plot, 12, "Lek res stone hill flat arid");
				end
				if featureType ~= FeatureTypes.FEATURE_FLOOD_PLAINS then
					plot:SetFeatureType(FeatureTypes.NO_FEATURE, -1)
				end

			elseif res_ID == self.incense_ID or 
			       res_ID == self.ivory_ID or 
				   res_ID == self.wine_ID or 
				   res_ID == self.olives_ID or 
				   res_ID == self.coffee_ID or
				   res_ID == self.tobacco_ID or 
				   res_ID == self.tea_ID or 
				   res_ID == self.perfume_ID or 
				   res_ID == self.cotton_ID then 

				if res_ID == self.incense_ID or res_ID == self.perfume_ID or res_ID == self.wine_ID then
					AssignStartingPlots.LekFlattenHillForOpenResource(plot, 70, "Lek res open lux hill pct");
				else
					AssignStartingPlots.LekFlattenHillForOpenResource(plot, 100, "Lek res open lux hill flat");
				end
				
				if (featureType ~= FeatureTypes.FEATURE_FLOOD_PLAINS) and not (res_ID == self.ivory_ID and featureType == FeatureTypes.FEATURE_JUNGLE) then
					plot:SetFeatureType(FeatureTypes.NO_FEATURE, -1)
				end
				
				if res_ID == self.incense_ID then
					if plot:GetTerrainType() == TerrainTypes.TERRAIN_GRASS then
						plot:SetTerrainType(TerrainTypes.TERRAIN_PLAINS, false, true)
					end
				end
			end

			-- Any luxury left on featureless flat desert → hills (covers mined + open, e.g. silver/gold/incense).
			if res_ID ~= nil and res_ID >= 0 and self:LekResourceIsLuxury(res_ID) then
				local ttD = plot:GetTerrainType();
				local ftD = plot:GetFeatureType();
				local ptD = plot:GetPlotType();
				if ttD == TerrainTypes.TERRAIN_DESERT
					and ftD == FeatureTypes.NO_FEATURE
					and ptD == PlotTypes.PLOT_LAND then
					plot:SetPlotType(PlotTypes.PLOT_HILLS, false, true);
				end
			end
		end
		end
	end
	--[[
	-- Sugar could not be made to look good in both jungle and open/marsh at the same time.
	-- Jon and I decided the best workaround would be to turn any Sugar/Jungle in to Marsh.
	local iW, iH = Map.GetGridSize()
	for y = 0, iH - 1 do
		for x = 0, iW - 1 do
			local plot = Map.GetPlot(x, y)
			if plot:GetResourceType(-1) == self.sugar_ID then
				local featureType = plot:GetFeatureType();
				if featureType == FeatureTypes.FEATURE_JUNGLE then
					local plotType = plot:GetPlotType()
					if plotType ~= PlotTypes.PLOT_LAND then
						plot:SetPlotType(PlotTypes.PLOT_LAND, false, true)
					end
					plot:SetFeatureType(FeatureTypes.FEATURE_MARSH, -1)
					plot:SetTerrainType(TerrainTypes.TERRAIN_GRASS, false, true)
					--
					--print("-"); print("Fixed a Sugar/Jungle at plot", x, y);
				end
			end
		end
	end
	--]]
end
