------------------------------------------------------------------------------
function AssignStartingPlots:GetMajorStrategicResourceQuantityValues()
	-- This function determines quantity per tile for each strategic resource's major deposit size.
	-- Note: scripts that cannot place Oil in the sea need to increase amounts on land to compensate.
	local uran_amt, horse_amt, oil_amt, iron_amt, coal_amt, alum_amt = 2, 4, 7, 6, 7, 8;
	-- Check the resource setting.
	if self.resource_setting == 1 or self.resource_setting == 2 then -- Sparse
		uran_amt, horse_amt, oil_amt, iron_amt, coal_amt, alum_amt = 2, 2, 5, 4, 5, 6;
	elseif self.resource_setting == 3 then -- mediocre
		uran_amt, horse_amt, oil_amt, iron_amt, coal_amt, alum_amt = 2, 3, 6, 5, 6, 7;
	elseif self.resource_setting == 7 then -- plenty
		uran_amt, horse_amt, oil_amt, iron_amt, coal_amt, alum_amt = 2, 5, 8, 7, 8, 9;
	elseif self.resource_setting == 8 or self.resource_setting == 9 or self.resource_setting == 10 then -- Abundant
		uran_amt, horse_amt, oil_amt, iron_amt, coal_amt, alum_amt = 2, 6, 9, 8, 9, 10;
	end
	return uran_amt, horse_amt, oil_amt, iron_amt, coal_amt, alum_amt
end
------------------------------------------------------------------------------
function AssignStartingPlots:GetSmallStrategicResourceQuantityValues()
	-- This function determines quantity per tile for each strategic resource's small deposit size.
	local uran_amt, horse_amt, oil_amt, iron_amt, coal_amt, alum_amt = 2, 2, 4, 2, 3, 3;
	-- Check the resource setting.
	if self.resource_setting == 1 or self.resource_setting == 2 or self.resource_setting == 3 then -- Sparse / Mediocre
		uran_amt, horse_amt, oil_amt, iron_amt, coal_amt, alum_amt = 1, 1, 2, 1, 2, 2;
	elseif self.resource_setting == 7 or self.resource_setting == 8 or self.resource_setting == 9 or self.resource_setting == 10 then -- Plenty / Abundant
		uran_amt, horse_amt, oil_amt, iron_amt, coal_amt, alum_amt = 2, 3, 3, 3, 3, 3;
	end
	return uran_amt, horse_amt, oil_amt, iron_amt, coal_amt, alum_amt
end
------------------------------------------------------------------------------
function AssignStartingPlots:PlaceStrategicAndBonusResources()
	-- KEY: {Resource ID, Quantity (0 = unquantified), weighting, minimum radius, maximum radius}
	-- KEY: (frequency (1 per n plots in the list), impact list number, plot list, resource data)
	--
	-- The radius creates a zone around the plot that other resources of that
	-- type will avoid if possible. See ProcessResourceList for impact numbers.
	--
	-- Order of placement matters, so changing the order may affect a later dependency.
	
	-- Adjust amounts, if applicable, based on Resource Setting.
	local uran_amt, horse_amt, oil_amt, iron_amt, coal_amt, alum_amt = self:GetMajorStrategicResourceQuantityValues()
	
	-- Adjust appearance rate per Resource Setting chosen by user.
	local bonus_multiplier = 0.65;

	if self.resource_setting == 1 then -- Near to nothing
		bonus_multiplier = 1;
	elseif self.resource_setting == 2 then -- 
		bonus_multiplier = 0.90;
	elseif self.resource_setting == 3 then -- 
		bonus_multiplier = 0.80;
	elseif self.resource_setting == 4 then -- 
		bonus_multiplier = 0.75;
	elseif self.resource_setting == 6 then -- 
		bonus_multiplier = 0.55;
	elseif self.resource_setting == 7 then -- 
		bonus_multiplier = 0.45;
	elseif self.resource_setting == 8 then -- 
		bonus_multiplier = 0.35;
	elseif self.resource_setting == 9 then -- 
		bonus_multiplier = 0.25;
	elseif self.resource_setting == 10 then -- filled the map full
		bonus_multiplier = 0.15;
	end

	local rs5_fq_horse_dgf, rs5_fq_horse_pln, rs5_fq_horse_tdf = 10, 10, 100;
	local rs5_fq_iron_tdf, rs5_fq_iron_snf, rs5_fq_iron_ddf, rs5_fq_iron_hl = 16, 15, 11, 22;
	-- Coal/alum keep OG-ish freqs even when RS5 thins iron (do not inherit rs5_fq_iron_*).
	local rs5_fq_alum_tdf, rs5_fq_alum_snf, rs5_fq_coal_alum_hl = 16, 15, 22;
	local rs5_fq_coal_jungle, rs5_fq_coal_forest = 33, 39;
	local rs5_small_freq_base = 23;
	local rs5_fq_marsh = 7;
	local rs5_fq_uran_marsh, rs5_fq_uran_jungle, rs5_fq_uran_forest = 7, 33, 39;
	local rs5_oil_w_marsh, rs5_oil_w_tundra, rs5_oil_w_snow, rs5_oil_w_desert, rs5_oil_w_forest = 65, 55, 65, 70, 25;
	local rs5_uran_w_marsh, rs5_uran_w_jungle, rs5_uran_w_forest = 35, 70, 50;
	local rs5_uran_impact_min, rs5_uran_impact_max = 1, 4;
	local skipGlobalHorseIron = (self.resource_setting or 0) == 5 and AssignStartingPlots.LekStratSkipGlobalHorseIronEnabled();
	local ouBands = (self.resource_setting or 0) == 5 and AssignStartingPlots.LekStratOuBandsEnabled();
	if self.resource_setting == 5 then
		-- v5: n=5 batch mean total ~52 (global ~15.6); target ~49 → thin ~20% more.
		-- Higher freq = fewer sites. Horse plains was the main global overshoot.
		rs5_fq_horse_dgf, rs5_fq_horse_pln, rs5_fq_horse_tdf = 67, 67, 670;
		rs5_fq_iron_tdf, rs5_fq_iron_snf, rs5_fq_iron_ddf, rs5_fq_iron_hl = 96, 91, 67, 132;
		rs5_small_freq_base = 125;
	end
	if ouBands then
		-- Land oil target ≈ OG (~17 nodes): player bands = 18, so omit global land oil majors.
		-- Uran band qty=1 (OG); keep spaced majors + backfill toward ~21 nodes / 30 units.
		-- Thin uran-only freqs; coal/alum freqs stay at OG defaults above.
		rs5_fq_marsh = 18;
		rs5_fq_uran_marsh, rs5_fq_uran_jungle, rs5_fq_uran_forest = 18, 55, 70;
		rs5_oil_w_marsh, rs5_oil_w_tundra, rs5_oil_w_snow, rs5_oil_w_desert, rs5_oil_w_forest = 0, 0, 0, 0, 0;
		rs5_uran_w_marsh, rs5_uran_w_jungle, rs5_uran_w_forest = 20, 35, 25;
		-- Slightly wider than band impact so interstitial globals/backfill favor sparse land.
		rs5_uran_impact_min, rs5_uran_impact_max = 5, 7;
		rs5_fq_iron_tdf = math.max(rs5_fq_iron_tdf, 140);
		rs5_fq_iron_snf = math.max(rs5_fq_iron_snf, 130);
		rs5_fq_iron_ddf = math.max(rs5_fq_iron_ddf, 100);
	end

	-- Place Strategic resources.
	print("Map Generation - Placing Strategics");
	if self.resource_setting == 5 then
		LekMapgenPrintAndDiagFile("### LEK_STRAT_AUDIT strat_pass_begin runId=" .. tostring(_lek_run_id or "na")
			.. " resource_setting=5 start_locations=" .. tostring(self.start_locations)
			.. " iNumCivs=" .. tostring(self.iNumCivs)
			.. " bonus_mult=" .. tostring(bonus_multiplier)
			.. " extra_balance_smalls=" .. tostring(AssignStartingPlots.LekStratExtraBalanceSmallsEnabled())
			.. " skip_global_horse_iron=" .. tostring(skipGlobalHorseIron)
			.. " ou_bands=" .. tostring(ouBands));
	end

	-- Marsh: oil on strategic layer; uranium on uranium-only layer 9.
	if not ouBands then
		local resources_to_place = {
		{self.oil_ID, oil_amt, rs5_oil_w_marsh, 1, 4} };
		self._lek_strat_audit_context = "major:marsh_list_oil";
		self:ProcessResourceList(rs5_fq_marsh, 1, self.marsh_list, resources_to_place)
	end
	do
		local resources_to_place = {
		{self.uranium_ID, uran_amt, rs5_uran_w_marsh, rs5_uran_impact_min, rs5_uran_impact_max} };
		self._lek_strat_audit_context = "major:marsh_list_uran_L9";
		self:ProcessResourceList(rs5_fq_uran_marsh, 9, self.marsh_list, resources_to_place)
	end

	-- Tundra: alum (+oil) at alum freq; iron separately at iron freq.
	do
		local resources_to_place = {
		{self.aluminum_ID, alum_amt, 15, 1, 2} };
		if not ouBands then
			table.insert(resources_to_place, 1, {self.oil_ID, oil_amt, rs5_oil_w_tundra, 1, 5});
		end
		self._lek_strat_audit_context = ouBands and "major:tundra_flat_alum" or "major:tundra_flat_oil+alum";
		self:ProcessResourceList(rs5_fq_alum_tdf, 1, self.tundra_flat_no_feature, resources_to_place)
	end
	if not skipGlobalHorseIron then
		local resources_to_place = {
		{self.iron_ID, iron_amt, 35, 1, 2} };
		self._lek_strat_audit_context = "major:tundra_flat_iron";
		self:ProcessResourceList(rs5_fq_iron_tdf, 1, self.tundra_flat_no_feature, resources_to_place)
	end

	-- Snow: alum (+oil) then iron.
	do
		local resources_to_place = {
		{self.aluminum_ID, alum_amt, 15, 1, 2} };
		if not ouBands then
			table.insert(resources_to_place, 1, {self.oil_ID, oil_amt, rs5_oil_w_snow, 1, 5});
		end
		self._lek_strat_audit_context = ouBands and "major:snow_flat_alum" or "major:snow_flat_oil+alum";
		self:ProcessResourceList(rs5_fq_alum_snf, 1, self.snow_flat_list, resources_to_place)
	end
	if not skipGlobalHorseIron then
		local resources_to_place = {
		{self.iron_ID, iron_amt, 20, 1, 2} };
		self._lek_strat_audit_context = "major:snow_flat_iron";
		self:ProcessResourceList(rs5_fq_iron_snf, 1, self.snow_flat_list, resources_to_place)
	end

	do
		local resources_to_place = {};
		if not ouBands then
			table.insert(resources_to_place, {self.oil_ID, oil_amt, rs5_oil_w_desert, 1, 2});
		end
		if not skipGlobalHorseIron then
			table.insert(resources_to_place, {self.iron_ID, iron_amt, 30, 1, 2});
		end
		if table.maxn(resources_to_place) > 0 then
			self._lek_strat_audit_context = ouBands and "major:desert_flat_iron" or (skipGlobalHorseIron and "major:desert_flat_oil" or "major:desert_flat_oil+iron");
			self:ProcessResourceList(rs5_fq_iron_ddf, 1, self.desert_flat_no_feature, resources_to_place)
		end
	end

	-- Hills: coal+alum at OG-ish freq; iron separately when globals on.
	do
		local resources_to_place = {
		{self.coal_ID, coal_amt, 35, 1, 3},
		{self.aluminum_ID, alum_amt, 39, 1, 3} };
		self._lek_strat_audit_context = "major:hills_list_coal+alum";
		self:ProcessResourceList(rs5_fq_coal_alum_hl, 1, self.hills_list, resources_to_place)
	end
	if not skipGlobalHorseIron then
		local resources_to_place = {
		{self.iron_ID, iron_amt, 26, 1, 3} };
		self._lek_strat_audit_context = "major:hills_list_iron";
		self:ProcessResourceList(rs5_fq_iron_hl, 1, self.hills_list, resources_to_place)
	end

	-- Jungle/forest: coal on strategic layer; uranium on layer 9 (split so freq thinning does not starve coal).
	do
		local resources_to_place = {
		{self.coal_ID, coal_amt, 30, 1, 2} };
		self._lek_strat_audit_context = "major:jungle_flat_coal";
		self:ProcessResourceList(rs5_fq_coal_jungle, 1, self.jungle_flat_list, resources_to_place)
	end
	do
		local resources_to_place = {
		{self.uranium_ID, uran_amt, rs5_uran_w_jungle, rs5_uran_impact_min, rs5_uran_impact_max} };
		self._lek_strat_audit_context = "major:jungle_flat_uran_L9";
		self:ProcessResourceList(rs5_fq_uran_jungle, 9, self.jungle_flat_list, resources_to_place)
	end
	do
		local resources_to_place = {
		{self.coal_ID, coal_amt, 25, 1, 2} };
		if not ouBands then
			table.insert(resources_to_place, {self.oil_ID, oil_amt, rs5_oil_w_forest, 1, 5});
		end
		self._lek_strat_audit_context = ouBands and "major:forest_flat_coal" or "major:forest_flat_coal+oil";
		self:ProcessResourceList(rs5_fq_coal_forest, 1, self.forest_flat_list, resources_to_place)
	end
	do
		local resources_to_place = {
		{self.uranium_ID, uran_amt, rs5_uran_w_forest, rs5_uran_impact_min, rs5_uran_impact_max} };
		self._lek_strat_audit_context = "major:forest_flat_uran_L9";
		self:ProcessResourceList(rs5_fq_uran_forest, 9, self.forest_flat_list, resources_to_place)
	end

	if not skipGlobalHorseIron then
		local resources_to_place = {
		{self.horse_ID, horse_amt, 100, 1, 5} };
		self._lek_strat_audit_context = "major:dry_grass_flat_f10_horse";
		self:ProcessResourceList(rs5_fq_horse_dgf, 1, self.dry_grass_flat_no_feature, resources_to_place)
		local resources_to_place = {
		{self.horse_ID, horse_amt, 100, 1, 5} };
		self._lek_strat_audit_context = "major:plains_flat_f10_horse";
		self:ProcessResourceList(rs5_fq_horse_pln, 1, self.plains_flat_no_feature, resources_to_place)
		local resources_to_place = {
		{self.horse_ID, horse_amt, 100, 1, 5} };
		self._lek_strat_audit_context = "major:tundra_flat_f100_horse";
		self:ProcessResourceList(rs5_fq_horse_tdf, 1, self.tundra_flat_no_feature, resources_to_place)
	end

	self:AddModernMinorStrategicsToCityStates() -- Added spring 2011
	
	if not skipGlobalHorseIron then
		self._lek_strat_audit_context = "small_strat:land_list_freq=" .. string.format("%.4f", rs5_small_freq_base * bonus_multiplier);
		self:PlaceSmallQuantitiesOfStrategics(rs5_small_freq_base * bonus_multiplier, self.land_list);
	end

	
	-- Check for low or missing Strategic resources
	if not skipGlobalHorseIron and self.amounts_of_resources_placed[self.iron_ID + 1] < 8 then
		--print("Map has very low iron, adding another.");
		local resources_to_place = { {self.iron_ID, iron_amt, 100, 0, 0} };
		self._lek_strat_audit_context = "backfill:iron_total_lt8_hills_once";
		self:ProcessResourceList(99999, 1, self.hills_list, resources_to_place) -- 99999 means one per that many tiles: a single instance.
	end
	if not skipGlobalHorseIron and self.amounts_of_resources_placed[self.iron_ID + 1] < 4 * self.iNumCivs then
		--print("Map has very low iron, adding another.");
		local resources_to_place = { {self.iron_ID, iron_amt, 100, 0, 0} };
		self._lek_strat_audit_context = "backfill:iron_total_lt_4xcivs_land_once";
		self:ProcessResourceList(99999, 1, self.land_list, resources_to_place)
	end
	if not skipGlobalHorseIron and self.amounts_of_resources_placed[self.horse_ID + 1] < 4 * self.iNumCivs then
		print("Map has very low horse, adding another.");
		local resources_to_place = { {self.horse_ID, horse_amt, 100, 0, 0} };
		self._lek_strat_audit_context = "backfill:horse_total_lt_4xcivs_plains_once";
		self:ProcessResourceList(99999, 1, self.plains_flat_no_feature, resources_to_place)
		
		--print("Map has very low horse, adding another.");
		local resources_to_place = { {self.horse_ID, horse_amt, 100, 0, 0} };
		self._lek_strat_audit_context = "backfill:horse_total_lt_4xcivs_dry_grass_once";
		self:ProcessResourceList(99999, 1, self.dry_grass_flat_no_feature, resources_to_place)
	end
	if self.amounts_of_resources_placed[self.coal_ID + 1] < 8 then
		--print("Map has very low coal, adding another.");
		local resources_to_place = { {self.coal_ID, coal_amt, 100, 0, 0} };
		self:ProcessResourceList(99999, 1, self.hills_list, resources_to_place)
	end
	if self.amounts_of_resources_placed[self.coal_ID + 1] < 4 * self.iNumCivs then
		--print("Map has very low coal, adding another.");
		local resources_to_place = { {self.coal_ID, coal_amt, 100, 0, 0} };
		self:ProcessResourceList(99999, 1, self.land_list, resources_to_place)
	end
	-- OU bands already place ~3 oil/start; keep OG oil backfill only when bands off.
	if not ouBands and self.amounts_of_resources_placed[self.oil_ID + 1] < 4 * self.iNumCivs then
		print("Map has very low oil, adding another.");
		local resources_to_place = { {self.oil_ID, oil_amt, 100, 0, 0} };
		self._lek_strat_audit_context = "backfill:oil_total_lt_4xcivs_land_once";
		self:ProcessResourceList(99999, 1, self.land_list, resources_to_place)
	end
	if self.amounts_of_resources_placed[self.aluminum_ID + 1] < 4 * self.iNumCivs then
		--print("Map has very low aluminum, adding another.");
		local resources_to_place = { {self.aluminum_ID, alum_amt, 100, 0, 0} };
		self:ProcessResourceList(99999, 1, self.hills_list, resources_to_place)
	end
	
	do
		-- OU bands use qty=1 like OG balance; unit floor + spaced impact restore ~21 nodes.
		local urTarget = 5 * self.iNumCivs;
		local urIter = 0;
		local urMinR = ouBands and rs5_uran_impact_min or 0;
		local urMaxR = ouBands and rs5_uran_impact_max or 0;
		while self.amounts_of_resources_placed[self.uranium_ID + 1] < urTarget and urIter < 64 do
			urIter = urIter + 1;
			print("Map has very low uranium, adding another.");
			local beforeU = self.amounts_of_resources_placed[self.uranium_ID + 1];
			local resources_to_place = { {self.uranium_ID, uran_amt, 100, urMinR, urMaxR} };
			self._lek_strat_audit_context = "backfill:uran_lt_" .. tostring(urTarget) .. "_land_i" .. tostring(urIter);
			self:ProcessResourceList(99999, 9, self.land_list, resources_to_place);
			if self.amounts_of_resources_placed[self.uranium_ID + 1] == beforeU then
				self._lek_strat_audit_context = "backfill:uran_lt_" .. tostring(urTarget) .. "_hills_i" .. tostring(urIter);
				self:ProcessResourceList(99999, 9, self.hills_list, resources_to_place);
			end
			if self.amounts_of_resources_placed[self.uranium_ID + 1] == beforeU then
				self._lek_strat_audit_context = "backfill:uran_lt_" .. tostring(urTarget) .. "_forest_i" .. tostring(urIter);
				self:ProcessResourceList(99999, 9, self.forest_flat_list, resources_to_place);
			end
			if self.amounts_of_resources_placed[self.uranium_ID + 1] == beforeU then
				break;
			end
		end
	end

	self._lek_strat_audit_context = nil;
	if self.resource_setting == 5 then
		-- Labeled land passes (horse/iron/oil/uran) before rescan collapses labels.
		AssignStartingPlots.LekStratAuditPrintSummary(self, "after_strategics_pre_rs5_post");
		self:LekStratPostProcessForResourceSettingFive();
		AssignStartingPlots.LekStratAuditPrintSummary(self, "after_rs5_rescan_pre_sea");
	end
	if self.resource_setting == 5 then
		self._lek_strat_audit_context = "sea_oil:coast_list";
	end
	self:PlaceOilInTheSea();
	self._lek_strat_audit_context = nil;
	if self.resource_setting == 5 then
		-- Final oil includes sea; uranium unchanged. Prefer this stage for OU baseline totals.
		AssignStartingPlots.LekStratAuditPrintSummary(self, "after_PlaceOilInTheSea");
	end
	-- Extra center-CS strategics after all other strategic placement (does not interfere with prior passes).
	self:LekAddCenterCityStateStrategics();
	if self.resource_setting == 5 then
		AssignStartingPlots.LekStratAuditPrintSummary(self, "after_cs_center_strat");
	end
	print("Map Generation - Placing Bonuses");
	local lake_fish_full = GetShuffledCopyOfTable(
		self:LekFilterLakeFishIndicesAwayFromMajorStarts(self.lake_coast_fish_list or {}, 4));
	local nLakeFull = #lake_fish_full;
	local lekLakeFishFrac = self._lek_fish_lake_coast_pool_fraction;
	if type(lekLakeFishFrac) ~= "number" or lekLakeFishFrac > 1 then
		lekLakeFishFrac = 0.5;
	end
	if lekLakeFishFrac < 0 then
		lekLakeFishFrac = 0;
	end
	local nLakeKept = nLakeFull;
	local lake_fish = lake_fish_full;
	if lekLakeFishFrac < 1 - 1e-9 and nLakeFull > 0 then
		nLakeKept = math.floor(nLakeFull * lekLakeFishFrac + 1e-9);
		lake_fish = {};
		for i = 1, nLakeKept do
			lake_fish[i] = lake_fish_full[i];
		end
	end
	local function lek_fish_freq_keep_total(baseFreq, nCoast, nLakeK, nLakeF)
		if type(baseFreq) ~= "number" or baseFreq < 1 then
			return baseFreq;
		end
		if type(nCoast) ~= "number" or type(nLakeK) ~= "number" or type(nLakeF) ~= "number" then
			return baseFreq;
		end
		if nLakeF <= nLakeK then
			return baseFreq;
		end
		local poolOld = nCoast + nLakeF;
		local poolNew = nCoast + nLakeK;
		local nTarget = math.ceil(poolOld / baseFreq);
		if nTarget < 1 then
			return baseFreq;
		end
		if poolNew < 1 then
			return baseFreq;
		end
		for f = 1, poolNew do
			if math.ceil(poolNew / f) == nTarget then
				return f;
			end
		end
		return math.max(1, math.floor(baseFreq * poolNew / poolOld + 0.5));
	end
	local function Lek_FishPoolAwayFromStarts(pool)
		return self:LekFilterLakeFishIndicesAwayFromMajorStarts(pool or {}, 4);
	end
	
	if self._lek_coastal_refish then
		local iW, iH = Map.GetGridSize()
		local plotDataImmediateCoast = {};
		local plotDataNextToImmediateCoast ={};
		local plotDataIsThreeFromMainland = {};

		plotDataImmediateCoast, plotDataNextToImmediateCoast = GenerateMainlandExpandedCoastData();
		plotDataIsThreeFromMainland = GenerateThreeFromMainlandCoast(plotDataImmediateCoast, plotDataNextToImmediateCoast);

		table.fill(self.mainland_coast_list, false, iW * iH);
		table.fill(self.mainland_coast_list_inner, false, iW * iH);
		table.fill(self.mainland_coast_list_second, false, iW * iH);
		table.fill(self.mainland_coast_list_outer, false, iW * iH);

		local temp_list_pangaea = {};
		local temp_list_pangaea_inner = {};
		local temp_list_pangaea_second = {};
		local temp_list_pangaea_outer = {};

		-- create a single combined mainland coast list *and* separate
		for x = 0, iW - 1 do
			for y = 0, iH - 1 do
				local i = iW * y + x + 1;
				if plotDataImmediateCoast[i] == true then
					self.mainland_coast_list[i] = true;
					self.mainland_coast_list_inner[i] = true;
					local test_plot = Map.GetPlot(x, y);
					table.insert(temp_list_pangaea, i);
					table.insert(temp_list_pangaea_inner, i);
				elseif plotDataNextToImmediateCoast[i] == true then
					self.mainland_coast_list[i] = true;
					self.mainland_coast_list_second[i] = true;
					local test_plot = Map.GetPlot(x, y);
					table.insert(temp_list_pangaea, i);
					table.insert(temp_list_pangaea_second, i);
				elseif plotDataIsThreeFromMainland[i] == true then
					self.mainland_coast_list[i] = true;
					self.mainland_coast_list_outer[i] = true;
					local test_plot = Map.GetPlot(x, y);
					table.insert(temp_list_pangaea, i);
					table.insert(temp_list_pangaea_outer, i);
				end
			end
		end

		local fish_coast_inner = GetShuffledCopyOfTable(temp_list_pangaea_inner)
		local fish_coast_second = GetShuffledCopyOfTable(temp_list_pangaea_second)
		local fish_coast_outer = GetShuffledCopyOfTable(temp_list_pangaea_outer)

		self:PlaceFishMainland(lek_fish_freq_keep_total(3 * bonus_multiplier, #fish_coast_inner, nLakeKept, nLakeFull),
			Lek_FishPoolAwayFromStarts(AssignStartingPlots.LekMergePlotIndexLists(fish_coast_inner, lake_fish)));
		self:PlaceFishMainland(lek_fish_freq_keep_total(8 * bonus_multiplier, #fish_coast_second, nLakeKept, nLakeFull),
			Lek_FishPoolAwayFromStarts(AssignStartingPlots.LekMergePlotIndexLists(fish_coast_second, lake_fish)));
		self:PlaceFishMainland(lek_fish_freq_keep_total(15 * bonus_multiplier, #fish_coast_outer, nLakeKept, nLakeFull),
			Lek_FishPoolAwayFromStarts(AssignStartingPlots.LekMergePlotIndexLists(fish_coast_outer, lake_fish)));

	elseif self.method == 1 then
		local iW, iH = Map.GetGridSize()
		local plotDataImmediateCoast = {};
		local plotDataNextToImmediateCoast ={};
		local plotDataIsThreeFromMainland = {};

		plotDataImmediateCoast, plotDataNextToImmediateCoast = GenerateMainlandExpandedCoastData();
		plotDataIsThreeFromMainland = GenerateThreeFromMainlandCoast(plotDataImmediateCoast, plotDataNextToImmediateCoast);

		table.fill(self.mainland_coast_list, false, iW * iH);

		-- create a single combined maniland coast list
		for x = 0, iW - 1 do
			for y = 0, iH - 1 do
				local i = iW * y + x + 1;
				if plotDataImmediateCoast[i] == true or plotDataNextToImmediateCoast[i] == true or plotDataIsThreeFromMainland[i] == true then
					self.mainland_coast_list[i] = true;
				end
			end
		end

		local temp_list_panagaea = {};

		for x = 0, iW - 1 do
			for y = 0, iH - 1 do
				local i = iW * y + x + 1;
				if self.mainland_coast_list[i] == true then
					local test_plot = Map.GetPlot(x, y);
					table.insert(temp_list_panagaea, i);
				end
			end
		end

		self.coast_list_panagaea = GetShuffledCopyOfTable(temp_list_panagaea)

		self:PlaceFishMainland(lek_fish_freq_keep_total(10 * bonus_multiplier, #self.coast_list_panagaea, nLakeKept, nLakeFull),
			Lek_FishPoolAwayFromStarts(AssignStartingPlots.LekMergePlotIndexLists(self.coast_list_panagaea, lake_fish)));
	end

	local coast_and_lake_fish = Lek_FishPoolAwayFromStarts(AssignStartingPlots.LekMergePlotIndexLists(self.coast_list, lake_fish));
	if self._lek_coastal_refish then
		self:PlaceFish(lek_fish_freq_keep_total(16 * bonus_multiplier, #(self.coast_list or {}), nLakeKept, nLakeFull), coast_and_lake_fish);
	else
		self:PlaceFish(lek_fish_freq_keep_total(8 * bonus_multiplier, #(self.coast_list or {}), nLakeKept, nLakeFull), coast_and_lake_fish);
	end


	self:PlaceSexyBonusAtCivStarts()
	self:AddExtraBonusesToHillsRegions()
	
	local resources_to_place = {
	{self.deer_ID, 1, 100, 1, 2} };
	self:ProcessResourceList(6 * bonus_multiplier, 3, self.extra_deer_list, resources_to_place)

	local resources_to_place = {
	{self.wheat_ID, 1, 100, 1, 2} };
	self:ProcessResourceList(6 * bonus_multiplier, 3, self.desert_wheat_list, resources_to_place)

	local resources_to_place = {
	{self.deer_ID, 1, 100, 1, 2} };
	self:ProcessResourceList(8 * bonus_multiplier, 3, self.tundra_flat_no_feature, resources_to_place)

	local resources_to_place = {
	{self.banana_ID, 1, 100, 1, 2} };
	self:ProcessResourceList(10 * bonus_multiplier, 3, self.banana_list, resources_to_place)

	local resources_to_place = {
	{self.wheat_ID, 1, 100, 1, 3} };
	self:ProcessResourceList(30 * bonus_multiplier, 3, self.plains_flat_no_feature, resources_to_place)

	local resources_to_place = {
	{self.bison_ID, 1, 100, 2, 3} };
	self:ProcessResourceList(15 * bonus_multiplier, 3, self.plains_flat_no_feature, resources_to_place)

	local resources_to_place = {
	{self.cow_ID, 1, 100, 2, 3} };
	self:ProcessResourceList(22 * bonus_multiplier, 3, self.plains_flat_no_feature, resources_to_place)

	local resources_to_place = {
	{self.cow_ID, 1, 100, 2, 3} };
	self:ProcessResourceList(22 * bonus_multiplier, 3, self.grass_flat_no_feature, resources_to_place)

	local resources_to_place = {
	{self.stone_ID, 1, 100, 1, 1} };
	self:ProcessResourceList(27 * bonus_multiplier, 3, self.dry_grass_flat_no_feature, resources_to_place)

	local resources_to_place = {
	{self.bison_ID, 1, 100, 1, 1} };
	self:ProcessResourceList(20 * bonus_multiplier, 3, self.dry_grass_flat_no_feature, resources_to_place)

	local resources_to_place = {
	{self.sheep_ID, 1, 100, 1, 1} };
	self:ProcessResourceList(20 * bonus_multiplier, 3, self.hills_open_list, resources_to_place)

	local resources_to_place = {
	{self.sheep_ID, 1, 100, 1, 1} };
	self:ProcessResourceList(92 * bonus_multiplier, 3, self.grass_flat_no_feature, resources_to_place)
	self:ProcessResourceList(100 * bonus_multiplier, 3, self.plains_flat_no_feature, resources_to_place)
	self:ProcessResourceList(125 * bonus_multiplier, 3, self.flood_plains_list, resources_to_place)

	local resources_to_place = {
	{self.stone_ID, 1, 100, 1, 2} };
	self:ProcessResourceList(14 * bonus_multiplier, 3, self.tundra_flat_no_feature, resources_to_place)

	local resources_to_place = {
	{self.stone_ID, 1, 100, 1, 2} };
	self:ProcessResourceList(14 * 0.8 * bonus_multiplier, 3, self.snow_flat_list, resources_to_place)

	local resources_to_place = {
	{self.stone_ID, 1, 100, 1, 2} };
	self:ProcessResourceList(22 * bonus_multiplier, 3, self.desert_flat_no_feature, resources_to_place)

	local resources_to_place = {
	{self.stone_ID, 1, 100, 1, 2} };
	self:ProcessResourceList(40 * bonus_multiplier, 3, self.hills_open_no_grass_no_plains or {}, resources_to_place)
	local resources_to_place = {
	{self.stone_ID, 1, 100, 1, 2} };
	self:ProcessResourceList(40 * 0.8 * bonus_multiplier, 3, self.snow_hills_open_list or {}, resources_to_place)

	local resources_to_place = {
	{self.deer_ID, 1, 100, 3, 4} };
	self:ProcessResourceList(22 * bonus_multiplier, 3, self.forest_flat_that_are_not_tundra, resources_to_place)
	
	local resources_to_place = {
	{self.hardwood_ID, 1, 100, 1, 2} };
	self:ProcessResourceList(22 * bonus_multiplier, 3, self.hills_covered_list, resources_to_place)

	local resources_to_place = {
	{self.hardwood_ID, 1, 100, 1, 2} };
	self:ProcessResourceList(22 * bonus_multiplier, 3, self.flat_covered, resources_to_place)

	local resources_to_place = {
	{self.hardwood_ID, 1, 100, 1, 2} };
	self:ProcessResourceList(22 * bonus_multiplier, 3, self.tundra_flat_forest, resources_to_place)
	
	local resources_to_place = {
	{self.maize_ID, 1, 100, 1, 2} };
	local maize_plots = GetShuffledCopyOfTable(AssignStartingPlots.LekMergePlotIndexLists(self.plains_flat_no_feature, self.plains_hills_open_list));
	self:ProcessResourceList(35 * bonus_multiplier, 3, maize_plots, resources_to_place)
	
	
end
