function AssignStartingPlots:LekTestCopperOnAllWater()
	if _lek_test_copper_on_all_water ~= true then
		return;
	end
	local iW, iH = Map.GetGridSize();
	local rid = self.copper_ID;
	if rid == nil then
		LekMapgenDiagLogAppend("### _lek_test_copper_on_all_water skip copper_ID=nil");
		return;
	end
	local attempts, matched = 0, 0;
	for y = 0, iH - 1 do
		for x = 0, iW - 1 do
			local plot = Map.GetPlot(x, y);
			local pt = plot:GetPlotType();
			if pt == PlotTypes.PLOT_OCEAN or pt == PlotTypes.PLOT_LAKE then
				attempts = attempts + 1;
				pcall(function()
					plot:SetResourceType(rid, 2);
				end);
				if plot:GetResourceType(-1) == rid then
					matched = matched + 1;
				end
			end
		end
	end
	LekMapgenDiagLogAppend("### _lek_test_copper_on_all_water attempts=" .. tostring(attempts) .. " matched=" .. tostring(matched) .. " copper_ID=" .. tostring(rid));
end

function AssignStartingPlots:PlaceResourcesAndCityStates()
	-- This function controls nearly all resource placement. Only resources
	-- placed during Normalization operations are handled elsewhere.
	--
	-- Luxury resources are placed in relationship to Regions, adapting to the
	-- details of the given map instance, including number of civs and city 
	-- states present. At Jon's direction, Luxuries have been implemented to
	-- be diplomatic widgets for trading, in addition to sources of Happiness.
	--
	-- Strategic and Bonus resources are terrain-adjusted. They will customize
	-- to each map instance. Each terrain type has been measured and has certain 
	-- resource types assigned to it. You can customize resource placement to 
	-- any degree desired by controlling generation of plot groups to feed in
	-- to the process. The default plot groups are terrain-based, but any
	-- criteria you desire could be used to determine plot group membership.
	-- 
	-- If any default methods fail to meet a specific need, don't hesitate to 
	-- replace them with custom methods. I have labored to make this new 
	-- system as accessible and powerful as any ever before offered.

	LekMapgenFileTrace("Map Generation - Assigning Luxury Resource Distribution");
	self:LekSyncStartingPlotsFromMajorPlayersByRegionRect();
	do
		local ok, err = pcall(function() self:PlaceCoastalBonusIslands() end);
		if not ok then
			local msg = "### PRE-CS CRASH: runId=" .. tostring(_lek_run_id or "na") .. " stage=PlaceCoastalBonusIslands err=" .. tostring(err);
			print(msg);
			LekMapgenDiagLogAppend(msg);
		end
	end
	do
		local ok, err = pcall(function() self:AssignLuxuryRoles() end);
		if not ok then
			local msg = "### PRE-CS CRASH: runId=" .. tostring(_lek_run_id or "na") .. " stage=AssignLuxuryRoles err=" .. tostring(err);
			print(msg);
			LekMapgenDiagLogAppend(msg);
		end
	end
	do
		local ok, err = pcall(function() self:PlaceCityStates() end);
		if not ok then
			local msg = "### CS CRASH: runId=" .. tostring(_lek_run_id or "na") .. " err=" .. tostring(err);
			print(msg);
			LekMapgenDiagLogAppend(msg);
		end
	end
	local ridRes = tostring(_lek_run_id or "na");
	-- LekMapgenDiagLogAppend("### LekBuildPing PlaceResources_post_PlaceCityStates runId=" .. ridRes);
	-- Generate global plot lists for resource distribution.
	self:GenerateGlobalResourcePlotLists()
	-- LekMapgenDiagLogAppend("### LekBuildPing PlaceResources_after_GlobalLists runId=" .. ridRes);

	-- LekMapgenDiagLogAppend("### LekBuildPing PlaceResources_before_PlaceLuxuries runId=" .. ridRes);
	LekMapgenFileTrace("Map Generation - Placing Luxuries");
	do
		local ok, err = pcall(function() self:PlaceLuxuries() end);
		if not ok then
			local msg = "### PlaceResources_err runId=" .. ridRes .. " stage=PlaceLuxuries err=" .. tostring(err);
			print(msg);
			LekMapgenDiagLogAppend(msg);
			error(err);
		end
	end
	self:GenerateGlobalResourcePlotLists()

	-- LekMapgenDiagLogAppend("### LekBuildPing PlaceResources_after_PlaceLuxuries runId=" .. ridRes);

	-- LekMapgenDiagLogAppend("### LekBuildPing PlaceResources_before_StrategicBonus runId=" .. ridRes);
	do
		local ok, err = pcall(function() self:PlaceStrategicAndBonusResources() end);
		if not ok then
			local msg = "### PlaceResources_err runId=" .. ridRes .. " stage=PlaceStrategicAndBonus err=" .. tostring(err);
			print(msg);
			LekMapgenDiagLogAppend(msg);
			error(err);
		end
	end
	-- LekMapgenDiagLogAppend("### LekBuildPing PlaceResources_after_StrategicBonus runId=" .. ridRes);
	-- LekMapgenDiagLogAppend("### LekBuildPing PlaceResources_before_NormalizeCS runId=" .. ridRes);
	do
		local ok, err = pcall(function() self:NormalizeCityStateLocations() end);
		if not ok then
			local msg = "### PlaceResources_err runId=" .. ridRes .. " stage=NormalizeCityStateLocations err=" .. tostring(err);
			print(msg);
			LekMapgenDiagLogAppend(msg);
			error(err);
		end
	end
	-- LekMapgenDiagLogAppend("### LekBuildPing PlaceResources_after_NormalizeCS runId=" .. ridRes);
	-- LekMapgenDiagLogAppend("### LekBuildPing PlaceResources_before_FixGraphics runId=" .. ridRes);
	do
		local ok, err = pcall(function() self:FixResourceGraphics() end);
		if not ok then
			local msg = "### PlaceResources_err runId=" .. ridRes .. " stage=FixResourceGraphics err=" .. tostring(err);
			print(msg);
			LekMapgenDiagLogAppend(msg);
			error(err);
		end
	end
	-- LekMapgenDiagLogAppend("### LekBuildPing PlaceResources_after_FixGraphics runId=" .. ridRes);

	do
		local iW, iH = Map.GetGridSize();
		for y = 0, iH - 1 do
			for x = 0, iW - 1 do
				local plot = Map.GetPlot(x, y);
				if plot and not plot:IsWater()
					and plot:GetTerrainType() == TerrainTypes.TERRAIN_DESERT
					and plot:GetPlotType() == PlotTypes.PLOT_HILLS
					and plot:IsFreshWater()
					and plot:GetFeatureType() == FeatureTypes.NO_FEATURE
				then
					if Map.Rand(100, "Lek desert freshwater hill forest") < 3 then
						plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1);
					end
				end
			end
		end
	end

	-- LekMapgenDiagLogAppend("### LekBuildPing PlaceResources_before_snowDeer runId=" .. ridRes);
	-- Sparse deer or fur on snow (bonus/lux both use same tile rules): only if forest on tile or adjacent;
	-- empty snow: random tie-break — add forest here, or require neighbor forest and stay clear.
	do
		local iW, iH = Map.GetGridSize();
		local function trySnowDeerOrFur(plot, x, y)
			if plot == nil or plot:IsWater() then
				return;
			end
			local pt = plot:GetPlotType();
			if pt ~= PlotTypes.PLOT_LAND and pt ~= PlotTypes.PLOT_HILLS then
				return;
			end
			if plot:GetTerrainType() ~= TerrainTypes.TERRAIN_SNOW then
				return;
			end
			if plot:GetResourceType(-1) ~= -1 then
				return;
			end
			local ft = plot:GetFeatureType();
			local onForest = (ft == FeatureTypes.FEATURE_FOREST);
			local hasForestNeighbor = false;
			for d = 0, 5 do
				local nb = Map.PlotDirection(x, y, d);
				if nb and nb:GetFeatureType() == FeatureTypes.FEATURE_FOREST then
					hasForestNeighbor = true;
					break;
				end
			end
			if not onForest and not hasForestNeighbor then
				return;
			end
			if Map.Rand(100, "Lek snow deer fur master") >= 4 then
				return;
			end
			local resId = self.deer_ID;
			if self.fur_ID ~= nil and Map.Rand(2, "Lek snow deer v fur") == 0 then
				resId = self.fur_ID;
			end
			local function commitRes()
				plot:SetResourceType(resId, 1);
				self.amounts_of_resources_placed[resId + 1] = self.amounts_of_resources_placed[resId + 1] + 1;
				if Game.GetResourceUsageType(resId) == ResourceUsageTypes.RESOURCEUSAGE_LUXURY then
					self.totalLuxPlacedSoFar = self.totalLuxPlacedSoFar + 1;
				end
			end
			if onForest then
				commitRes();
				return;
			end
			if ft ~= FeatureTypes.NO_FEATURE then
				return;
			end
			if Map.Rand(2, "Lek snow forest on tile v neighbor") == 0 then
				plot:SetFeatureType(FeatureTypes.FEATURE_FOREST, -1);
				commitRes();
			elseif hasForestNeighbor then
				commitRes();
			end
		end
		for y = 0, iH - 1 do
			for x = 0, iW - 1 do
				local i = y * iW + x + 1;
				if self.playerCollisionData[i] ~= true then
					trySnowDeerOrFur(Map.GetPlot(x, y), x, y);
				end
			end
		end
	end
	-- LekMapgenDiagLogAppend("### LekBuildPing PlaceResources_after_snowDeer runId=" .. ridRes);

	do
		local ok, err = pcall(function() self:LekTestCopperOnAllWater(); end);
		if not ok then
			LekMapgenDiagLogAppend("### LekTestCopperOnAllWater err=" .. tostring(err));
		end
	end

	self:LekSanitizeFishNearMajorLakeCells(4);

	if _lek_global_six_request_map_regen ~= true then
		self:LekAssertCapitalLuxuryTilesMinimumOrRegen(4, 3);
	end

	-- Necessary to implement placement of Natural Wonders, and possibly other plot-type changes.
	-- This operation must be saved for last, as it invalidates all regional data by resetting Area IDs.
	Map.RecalculateAreas();
	-- LekMapgenDiagLogAppend("### LekBuildPing PlaceResources_end runId=" .. tostring(_lek_run_id or "na"));

	do
		local ok, err = pcall(function() self:LekPlaceRegionalLuxuryShortfallFallback() end);
		if not ok then
			local msg = "### PlaceResources_err runId=" .. tostring(_lek_run_id or "na") .. " stage=LekPlaceRegionalLuxuryShortfallFallback err=" .. tostring(err);
			print(msg);
			LekMapgenDiagLogAppend(msg);
		end
	end
	self:LekSanitizeFishNearMajorLakeCells(4);
	self:LekSanitizeSeaLuxuriesOnLakeTiles();
	if _lek_global_six_request_map_regen ~= true then
		self:LekAssertRegionalLuxuryNoShortfallAfterFallbackOrRegen();
	end

	do
		local ok, err = pcall(function() self:PrintFinalResourceTotalsToLog(); end);
		if not ok then
			local msg = "### PrintFinalResourceTotalsToLog_err runId=" .. tostring(_lek_run_id or "na") .. " err=" .. tostring(err);
			print(msg);
			LekMapgenDiagLogAppend(msg);
		end
	end
end
